window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[3]=[{"i":12492,"n":"דאבי, יצחק מעתוק מאלכסנדיה","b":"רב באלכסנדריה, נזכר ב\"יביע אומר\"-תשח. עלה לארץ."},{"i":12493,"n":"דאברזינסקי, אהרן מארה\"ב","k":"בעל פרחי אהרן","b":"רב בניו יורק. בניו - ר ישראל צבי מברמינגהם-אלבמה, ר שמעון, ר יעקב ממרשפילד-אורגון, ר עמנואל, ר אברהם מסן פרנציסקו."},{"i":12494,"n":"דאברין, אברהם אליהו מארה\"ב","f":"אהרן דאברזינסקי-פרחי","b":"רב בסן פרנציסקו."},{"i":12495,"n":"דאברר, ליב מפלאצק","b":"רב בפלאצק-ת\"כ"},{"i":12496,"n":"דאדה, יצחק מאלגיר","b":"רב במזאב(=מקאב, גרדאייא). שאלה ממנו לר אברהם ן טוואה."},{"i":12497,"n":"דאדס, סעדיה ממרוקו","dp":"שריעה-מרוקו","b":"מצדיקי מרוקו. הגיע מספרד בזמן הרדיפות."},{"i":12498,"n":"דאואד סעדי לוי משלוניקי","b":"מנהל הקהלה בשלוניקי-תרפא."},{"i":12499,"n":"דאוד (דוד) הרופא ממצרים","f":"שולימן (שלמה)","k":"אבואלפהדאל דאוד","bt":"ד'תתקכא","bp":"קהיר","b":"רופא במצרים. חיבר ספר רפואה בערבית."},{"i":12500,"n":"דאווד ן, חכמון מטריפולי וצפת","f":"דוד","bt":"תר","dt":"תרסח","dp":"צפת","b":"רב מקובל בטריפולי ועסק גם בקבלה מעשית, עלה לארץ-תרם, והיה ממקובלי צפת. הניח חבור בקבלה - ואבד."},{"i":12501,"n":"דאוודי, מכלוף ממראקש","bt":"תקפה","bp":"מרוקו","dt":"תרע - ד אלול","dp":"ירושלים","b":"מצאצאי ר חיים דאוודי. מחכמי מראקש. עלה לירושלים."},{"i":12502,"n":"דאט, אהרן זלמן מליטא","f":"דב","k":"בעל תולדות אהרן","bt":"תריט","bp":"קידאן","dt":"תרעו-ח","dp":"פושאלאט","b":"תלמיד ישיבות ראגולה ואיישישוק. חתן ר משה יונה מסמילג. רב בפושאלאט-ליטא, סמילג על מקום חותנו, והתפרנס מחנות שניהלו בניו. פרסם מאמרים ב\"המליץ\" ועוד. ?? לא באוצר ??"},{"i":12503,"n":"דאטו, מרדכי מאיטליה וצפת","f":"יהודה","k":"בעל שמן ערב","bt":"רפה","bp":"איטליה","dt":"שן","b":"מקובל ופייטן מחכמי איטליה, עלה לצפת-ש, תלמיד ר משה קורדובירו. חיבר עם חברו ר שמואל גאליקו \"עסיס רמונים\". חיבר גם \"מגדל דוד\", \"שמן ערב\" ועוד. פיוטים שלו מובאים במחזור נוסח איטליה. ?? לא באוצר ??"},{"i":12504,"n":"דאיינה, אליהו","b":"מגדולי איטליה-שט\"ו"},{"i":12505,"n":"דאיינה, עזריאל מאיטליה","f":"שלמה","dt":"רצו","b":"רב בסביוניטה-איטליה - המאה ה-16, פיימונט-איטליה. ממשפחה מצרפת שהתישבה באיטליה. ארבעה מבניו היו רבנים באיטליה. ממתנגדי דוד הראובני, ומתומכי שלמה מולכו."},{"i":12506,"n":"דאיינה, עזריאל מאיטליה וקושטא","f":"שלמה","k":"בעל שו\"ת","b":"רב באיטליה, רב בסביונה-רצב, קושטא."},{"i":12507,"n":"דאישטיליא, דוד","k":"בעל קרית ספר","b":"רב בגבארה(ספרד), חיבר \"קרית ספר\". ?? לא באוצר ??"},{"i":12508,"n":"דאלב\"ה, אברהם משלוניקי","f":"יהודה","dt":"שעז - יד אלול","dp":"שלוניקי","b":"מהרוגי דולייא."},{"i":12509,"n":"דאלגאנעס, אברהם מארה\"ב","b":"רב ומטיף בקהלת \"אהבת חסד\" בניו יורק."},{"i":12510,"n":"דאן, ליב מפפד\"מ","f":"פער","dt":"תקפד - טז ניסן","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":12511,"n":"דאן, פער מפפד\"מ","f":"זנויל","dt":"תקלח - כז אב","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":12512,"n":"דאנדא, דוד ממרוקו","b":"מקובל, מחכמי מרוקו-תקס, ישב בכפר קאקאווי-נוף סוס שבמרוקו."},{"i":12513,"n":"דאנה, שלמה מתונס","k":"בעל שלמי תודה","bt":"תרי","bp":"תונס","dt":"תרעג - כט סיון","dp":"תונס","b":"רב בתונס. תלמיד ר אברהם יצחקי בעל \"משמרות כהונה\", ור משה ברבי מתונס. יסד את ישיבת \"חכמת התלמוד\" ומתלמידיו ר שמואל טייב, ועוד.","bk":[["שלמי תודה",""]]},{"i":12514,"n":"דאנצקר, חיים מזולקוא","dt":"תקמב - ח שבט","dp":"זולקוא","b":"גביר מחכמי זולקוא, מראשי הקהלה-תקלד."},{"i":12515,"n":"דאנקיל, מאיר מרישא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":12516,"n":"דאנר, יהושע השל","b":"פרסם מאמרים ב\"תצא תורה\" - קריניצה תרצא."},{"i":12517,"n":"דאנר, נתן נטע הכהן","k":"בעל דרך אמונה","b":"רב בראדשיץ-תרמ\"ד,קאלביעל-תרנ\"ד. ?? לא באוצר ??"},{"i":12518,"n":"דאסה, ויטאל משלוניקי","b":"עורך המדור בלאדינו בעיתון \"איזראאיליטיקון ווימה\" בשלוניקי - אחרי השואה."},{"i":12519,"n":"דאסה, יצחק מירושלים","f":"יעקב","bt":"תריז","bp":"ירושלים","dt":"תרפא - כט אד\"א","dp":"ירושלים","b":"מחכמי ירושלים. ממיסדי ביה\"ח \"משגב לדך\" וממיסדי שכונת \"ימין משה\"."},{"i":12520,"n":"דאסה, משה משלוניקי","b":"תלמיד ר לוי ן חביב. מחכמי שלוניקי, לארסו."},{"i":12521,"n":"דאסואר, יוליוס מנייפעסט","bt":"1832","dt":"1883","b":"רב ניאולוגי בנייפעשט(=בודפשט). תרגם את פירוש רש\"י לגרמנית."},{"i":12522,"n":"דאפה, אהרן משלוניקי","dt":"תץ","dp":"שלוניקי","b":"מחכמי שלוניקי, ומלמד תורה ודקדוק."},{"i":12523,"n":"דאפיארה, משלם","b":"מגדולי משוררי ספרד בגירונה-שנת מ'"},{"i":12524,"n":"דאפירא, שלמה","f":"משלם","k":"בעל אמרי נועם","b":"חיבר \"אמרי נואם\" (די רוסי). ?? לא באוצר ??"},{"i":12525,"n":"דאפני, אברהם מאשכנז ורודוס","b":"מחכמי אשכנז ברודוס, ופגש אותו הנוסע ר משלם מוולטרא ברודוס-רמא."},{"i":12526,"n":"דארזאני, מרדכי מקושטא","b":"מחכמי קושטא, וממונה על איסור והיתר-תקיג."},{"i":12527,"n":"דארלי, אליעזר משלוניקי","b":"מדפיס בדפוס גדיליה בשלוניקי--רפא."},{"i":12528,"n":"דארלי, יוסף משלוניקי","b":"מדפיס בדפוס גדיליה בשלוניקי--רפא."},{"i":12529,"n":"דב","f":"אהרן מהורדנא","b":"רב בוילקוניק"},{"i":12530,"n":"דב בער","f":"יהודה ליבש","dt":"תקיג","b":"ספרא דד\"א"},{"i":12531,"n":"דב בער","f":"שמואל רבי יעקליש","b":"חתן ר בצלאל הכהן מאוסטרהא."},{"i":12532,"n":"דב בער אלי'ס מוילנא","b":"נכד ר דב בער פעסעלעס המכונה - ר ליבלע ר בערס מוילנא."},{"i":12533,"n":"דב בער בריל מרישא","k":"בעל דבש השדה","b":"מחכמי לנצהוט ואחר כך רישא-תרו. אסף סיפורים רבים אודות גדולי החסידות ומהם נדפס ספר \"דבש השדה\" בילגוריא תרסט (המדפיס ר צבי מיכלזון קרא לספר בשם זה לרמוז על המחבר דובריש), חיבר גם \"אמרי שפר\"."},{"i":12534,"n":"דב בער הכהן מהורדנא","dt":"תרה - יח אלול","b":"רב בהורדנא"},{"i":12535,"n":"דב בער הכהן מירושלים","b":"בשנת תקכג חתם על מכתב ירושלים לקהילת מיץ"},{"i":12536,"n":"דב בער הכהן מלברטוב","b":"מחכמי לברטוב(=ליברטוב)-תרלו, הסכים על חשק שלמה לר משה שלמה לוינזון."},{"i":12537,"n":"דב בער הכהן מסטריקוב","b":"פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":12538,"n":"דב בער הכהן מקלסני","f":"אריה ליב בעל הקצות","b":"אב\"ד קלסני."},{"i":12539,"n":"דב בער הלוי מטולטשין","f":"שלמה מקרלין","b":"חתן ר ברוך ממזבוז, ובזיוו\"ש חתן נכדת ר דוד הלפרין מאוסטרהא. בנו ר שלמה מטולטשין."},{"i":12540,"n":"דב בער הלוי מירושלים","dt":"תרל - לפני","b":"ראש השוחטים בירושלים, חתם-תריג על כתב סמיכה לשוחט ר נפתלי יצחק ראהלר. גידל בביתו את קרובו ר מיכל הכהן. רואה חשבון הכולל-תרי. ראה גם ר דב בער בן אריה מירושלים."},{"i":12541,"n":"דב בער הלוי מלבוב","f":"נפתלי הרץ","b":"דיין בלבוב, חתם-תצט על פסק, חתם-תקד על שטר מכירה על ביתו כדי לפדות את בנו ר יקותיאל זלמן שנשבה ביד בן נכר."},{"i":12542,"n":"דב בער הלוי ממוש וצפת","f":"יהודה","dt":"תרג - כ ניסן","dp":"ירושלים","b":"רב בעיר מוש, עלה לצפת, היה סגינהור ניצל בנס מהרעש בצפת ועבר לירושלים"},{"i":12543,"n":"דב בער הלוי סגל מבוזנוב","dt":"תרלה - בערך","b":"מחכמי בוזנוב, רב ביאנוב. תלמידו ר אברהם משה זומרשטיין על מקומו אחריו."},{"i":12544,"n":"דב בער וישיניץ (ויסנסטיץ)","f":"מרדכי ליב לאשברין","b":"חתן ר מרדכי ליב לאשברין מזשאמבקארעט. רב בטרנשטין-תק\"צ. בנו - ר נתן צבי בלומגרונט."},{"i":12545,"n":"דב בער מאוזרקוב וגרובוב","bp":"טרנוב","dt":"תשג","b":"אחיינו של ר צבי הירש מאיר ואליו עבר. רב בנשלסק, גרובוב-תרנח, אוזרקוב. בנו ר משה רב בזדונסקה-וולה על מקום חותנו ר אלעזר ליפשיץ."},{"i":12546,"n":"דב בער מאולינוב - נכד הבעשט","f":"צבי הירש","b":"מ\"מ באולינוב. נכד הבעש\"ט. החסידים נהגו לבקר אצלו כדי להיזכר בצורת רבם הבעשט שהיה דומה לו ביותר. חתנו ר צבי מנחם מנדל מדינוביץ-בן ר זושא מאניפולי."},{"i":12547,"n":"דב בער מאומין","b":"רב באומין-תק\"צ"},{"i":12548,"n":"דב בער מאוסטרהא","f":"יהודה ליב","b":"מחכמי אוסטרהא, ומיושבי הקלויז הגדולה. הסכים על \"מפלגי ראובן\"."},{"i":12549,"n":"דב בער מאוסטרהא","f":"שמואל ר יעקב'ס","dt":"תצח - א ניסן","b":"חתן ר בצלאל הכהן מאוספטא. פרנס מחכמי אוסטרהא. בנו ר צבי הירש מאוסטרהא, וחתנו ר אשר ענזיל בעל \"ברוך מבנים אשר\". נפטר בחיי אביו."},{"i":12550,"n":"דב בער מאזיפולי","b":"רב באזיפולי. תשובה אליו לסנוק - חסל\"א - תרכא."},{"i":12551,"n":"דב בער מאלסק","dt":"תרי - כא אלול","b":"פועל ישועות,סגי נהור,רב באלעסק"},{"i":12552,"n":"דב בער מדובנא","f":"יעקב יעקל מוילנא","b":"כינויו של אביו - ר יעקעלע ר ליבעלעס). רב בדובנא, קאוולא. אחיו: ר אליהו-המכונה \"ר אלינקע יעקילס\", ר מרדכי צבי, ר חיים. גיסו ר יעקב בן ר זיסל רפפורט ממינסק."},{"i":12553,"n":"דב בער מדוברומיל","b":"עושה ציצית מדוברומיל עלה לארץ - לפני תרלה."},{"i":12554,"n":"דב בער מואלאטשיסק","b":"רב בוואלאטשיסק"},{"i":12555,"n":"דב בער מויטבסק","f":"נחום מקאפוסט","b":"רב בויטבסק."},{"i":12556,"n":"דב בער מויטקא","k":"בעל גולת עילית","b":"נכד ר מרדכי פוזנר מאורשא. רב בויטקא."},{"i":12557,"n":"דב בער מוילנא","f":"יצחק ישראל איסר","k":"ר בערעלע ר איציק'ס","dt":"תרמח - יג טבת","dp":"וילנא","b":"מחכמי וילנא. חבר בכמה חברות קדש."},{"i":12558,"n":"דב בער מוילנא","f":"אליהו","dt":"תקלט","dp":"וילנא","b":"תלמיד הגר\"א."},{"i":12559,"n":"דב בער מוילנא","f":"דוד","dt":"תקסג - כ שבט","dp":"וילנא","b":"מחכמי שווינציאן, וילנא."},{"i":12560,"n":"דב בער מוילנא","f":"ירוחם מסקידל","dt":"תקע - א תמוז","dp":"וילנא","b":"מחכמי וילנא."},{"i":12561,"n":"דב בער מזאמושט","f":"אריה ליב","dt":"תקלט - ג אייר","b":"רב בקוזניץ-תקה, קרשניק-תקיד, רישא-תקיח, ר\"מ בלבוב-תקכה, חתם-תקלז על פס\"ד בלבוב."},{"i":12562,"n":"דב בער מזולקוא","f":"נתן נטע מטורבין","k":"בעל נטע שעשועים","dt":"תקכא - א תשרי","dp":"זולקוא","b":"נכד בעל \"מגלה עמוקות\". רב בפינסק, זולקווא."},{"i":12563,"n":"דב בער מחודרקוב","b":"תלמיד המגיד ממזריטש. נזכר ב\"יושר דברי אמת\" לר משולם פיבש מזבאריז."},{"i":12564,"n":"דב בער מטבריה","f":"עוזיאל","b":"חתן ר מנחם מנדל מויטבסק. נתאלמן מאשתו והשאיר תינוקת ויצא-תקמח לחו\"ל לשאת אישה, ועמד לחזור-תקנד."},{"i":12565,"n":"דב בער מטולטשין","f":"ברוך ממזיבוז","b":"רב בטולטשין-תק\"צ"},{"i":12566,"n":"דב בער מטורבין","dt":"תרכה - א תשרי","b":"רב בטורבין"},{"i":12567,"n":"דב בער מטיסאבעא","b":"רב בטיסאבעא-תקע\"ה"},{"i":12568,"n":"דב בער מיאסי","f":"יצחק משה","b":"רב ביאסי-תרסו, כתב הסמכה ממנו. (אולי הוא מצאצאי ר יצחק משה מיאס שהיה רב קהלת חב\"ד שם)."},{"i":12569,"n":"דב בער מיזלוביץ","b":"רב ביאזלוביץ,רב פעלים"},{"i":12570,"n":"דב בער מירושלים","f":"אריה","dt":"תריג - כג ניסן","dp":"ירושלים","b":"מחכמי ירושלים. חתם-תריג על כתב סמיכה לשוחט נפתלי יצחק. ראה גם: ר דב בער הלוי מירושלים."},{"i":12571,"n":"דב בער מלבוב","f":"אריה ליב מזמושץ","dt":"תקל-ט - ג אייר","dp":"לבוב","b":"תלמיד הבעשט. רב בקוזניץ-תקה, קרשניק-תקיד, רישא-תקיח, רב וראש ישיבה בלבוב על מקום ר אריה ליב רפפורט. הסכים על \"חלוקא דרבנן\", שבט מישראל\", \"פרי מגדים\", ועוד. מחותן עם ר חיים הכהן רפפורט מלמברג. נכדו ר שמחה אב\"ד בוברקא."},{"i":12572,"n":"דב בער מלובלין","f":"שמואל זנויל","dt":"תקמח - טז שבט","dp":"לובלין","b":"מחכמי זאמושטש. רופא מחכמי לובלין. חתם על חרם ר שאול מרגליות שלא לחדש מנינים בלובלין, ועוד."},{"i":12573,"n":"דב בער מלובלין","f":"בצלאל כץ שתדלן","dt":"תקסב - טו אד\"ב","dp":"לובלין","b":"מחכמי לובלין."},{"i":12574,"n":"דב בער מלודמיר","b":"מו\"צ בלאדמיר-תרכ\"ב"},{"i":12575,"n":"דב בער מלחוביץ","b":"חתן ר יעקב יוסף מאוסטרהא-נכד רב ייב\"י. רב בלחוביץ. (באלפסי יש ר משה דב בר מלחוביץ - האם זה אותו שם?)."},{"i":12576,"n":"דב בער מליאובה","f":"ישראל מרוזין","b":"הנהיג אדמו\"רות בליאובה"},{"i":12577,"n":"דב בער מליניץ","k":"בעל שבחי הבעשט","b":"חתן ר אלכסנדר סנדר משדה לבן-סופרו של הבעש\"ט. שו\"ב בליניץ-תקל, ומחבורת הבעש\"ט. חיבר \"שבחי הבעש\"ט\" עם הערות ממנו - הערותיו אבדו. בנו ר יהודה ליב ברנשטין - אבי שושלת רבנים שכיהנה בליניץ במשך כמה דורות. (כשנפטר חותנו בצעירתו נשארו 2 ילדות יתומות שגדלו בביתו של הבעש\"ט - והוא שהשיא אחת מהם לתלמידו הזה). ?? לא באוצר ??"},{"i":12578,"n":"דב בער מליסא","b":"דיין בליסא-ת\"ע"},{"i":12579,"n":"דב בער מנוברדוק","b":"דיין ומו\"צ בנוברדוק-תרן בערך."},{"i":12580,"n":"דב בער מסטניסלב","dt":"תקכד - יב טבת","b":"רב בסטאניסלב"},{"i":12581,"n":"דב בער מפלונגיאן","b":"רב בפלונגיאן והגליל-תעו. נזכר ב\"כנסת יחזקאל\". בנו - ר זאב וולף מראסיין-חותנו של ר שמואל חסיד מראסיין."},{"i":12582,"n":"דב בער מפרגה","dt":"תקמט - ב אדר","b":"רב בפרגה-וורשה"},{"i":12583,"n":"דב בער מקאוולא","b":"רב בקאוולא"},{"i":12584,"n":"דב בער מראסיין","dt":"תריד - בערך","dp":"ראסיין","b":"דרשן בראסיין. גיסם של - ר אלכסנדר זיסקינד לוין מראסיין, ר שמואל לוין מראסיין."},{"i":12585,"n":"דב בער מראסיין וירושלים","dt":"תר - בערך","dp":"ירושלים","b":"דיין בראסיין, עלה לירושלים. בנו - ר יעקב מראסיין וירושלים."},{"i":12586,"n":"דב בער מרוזדוביץ","b":"רב ברוזדוביץ - תשובה אליו בישועו\"י."},{"i":12587,"n":"דב בער משדה לבן","b":"רב בשדה לבן-תק\"נ"},{"i":12588,"n":"דב בער משידלובצא","b":"תלמיד ר מנחם מנדל מקוצק."},{"i":12589,"n":"דב בר בן אברהם ממזריץ’","bt":"1704","dt":"ה'תקלב 1772","bk":[["אגרות קודש",""],["אור תורה",""],["מגיד דבריו ליעקב והוא לקוטי אמרים",""]]},{"i":12590,"n":"דב בר\"א","b":"פרסם מאמרים ב\"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף."},{"i":12591,"n":"דב ברקה מלוורטוב","b":"תלמיד ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק, ור מרדכי יוסף מאיזביצא."},{"i":12592,"n":"דב חיה'לס מלאדיזין","b":"תלמיד ר נחמן מברסלב. רב בלאדיזין, ויתר על הרבנות ועבר אל רבו בברסלב."},{"i":12593,"n":"דב טוביה משצריץ","f":"אהרן משה","dt":"תרמב","b":"רב בשצריץ."},{"i":12594,"n":"דב יצחק איזיק הכהן ממינסק","f":"צבי מאיר","dt":"תריא - יח אדר","dp":"מינסק","b":"ר\"מ במינסק."},{"i":12595,"n":"דב ליב","f":"נחמיה מדובראוונא","k":"בעל אמונת חכמים","b":"נכד בעל התניא-מצד אמו. תלמיד ה\"צמח צדק\". ?? לא באוצר ??"},{"i":12596,"n":"דב מאוסטרהא","f":"חיים","dt":"תקפב - כט אדר","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":12597,"n":"דב מוילנא","f":"שמואל רובזעויצער","dt":"תקעג - יח תשרי","dp":"וילנא","b":"מחכמי וילנא. נקבר לצד ר חיים צבי בן משה רוקח."},{"i":12598,"n":"דב מטשעהרין","b":"תלמידו ומחותנו של ר נחמן מברסלב שהרבה לספר בשבחו."},{"i":12599,"n":"דב מפיאנטניצא","b":"רב בפיאנטניצה(=פיאטניצע)-פלך לומזה-תרן, שילעל. בנו - ר בנימין משובאץ."},{"i":12600,"n":"דב משה","f":"זוסמן"},{"i":12601,"n":"דב צבי הכהן","f":"אריה ליבש הכהן","dt":"תקצט - ד תמוז","b":"רב בוואשצאווי"},{"i":12602,"n":"דבוריצר, אברהם ממינסק","f":"יהודה","dt":"תריג - יד ניסן","dp":"מינסק","b":"תלמיד ר גרשון תנחום ממינסק. ר\"מ בישיבת מינסק ששכנה בביהמ\"ד \"בלומקה\"(=קלויז בלומקעס) במינסק. רבו בילדותו של ר יהושע איזיק שפירא \"העילוי מגלובוק\" לימים ר אייזל חריף. חברו של ר ישעיה זכריה יולס ממינסק."},{"i":12603,"n":"דבורץ, אליעזר זאב","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":12604,"n":"דבורץ, יצחק","b":"פרסם מאמרים ב\"תבונה\" - קובנא תרפא."},{"i":12605,"n":"דבורץ-פלטין, ישראל זיסל","f":"בצלאל","k":"עורך תבונה","bt":"תרמח","bp":"דוינסק","b":"תלמיד ישיבת סלובודקה, והיה מזכיר הישיבה. רב ביאד-ליד לודז, קומאי(=קאמיי), ויאזנה, עלה לארץ-תרפו והקים בירושלים \"בנק לפתוח חברון\" והיה מיוזמי העברת ישיבת סלובודקה לחברון. עורך \"דברי תבונה\" - קובנא תרף, \"תבונה\" - קובנא תרפא, \"תורת הארץ\" - פתח תקוה תרצה. פרסם מאמרים ב\"תבונה\" - לודז תרפב. עורך ומו\"ל כתב העת \"תבונה\" - ירושלים תשא."},{"i":12606,"n":"דבורקין, יצחק","b":"רב באוקראינה-תרסה."},{"i":12607,"n":"דבוש, אליהו מטריפולי","bt":"תרם","dt":"תש","b":"רב בטריפולי, ר\"מ בישיבת דאר אסרוסי."},{"i":12608,"n":"דבוש, חיים מלוב","bt":"תרך","bp":"זליתן","dt":"תרצד","b":"רב וראש ישיבת \"עץ חיים\" בביהכ\"נ \"דאר ביבי\". נזכר ב\"אנשי אמונה\" לר פריג'א זוארץ."},{"i":12609,"n":"דבוש, כליפא (כלאפו) מלוב","bt":"תרן","dt":"תשי - בערך","b":"רב ודיין בבנגזי."},{"i":12610,"n":"דבוש, משה מלוב","f":"יוסף","bt":"תקע","bp":"זליתן-לוב","dt":"תרם - בערך","b":"רב ומקובל במסאלתה-לוב. אחיו של ר פרג'אללה. נזכר ב\"מסעי ישראל\" ליק 1859."},{"i":12611,"n":"דבוש, פרג'אללה מטריפולי","f":"יוסף","bt":"תקעה","bp":"זילתן-לוב","dt":"תרמח-נא","dp":"טריפולי","b":"היה סגינהור. רב בטריפולי, והשיב לשאלות גם מארץ ישראל. בנו ר רפאל היה דיין בטריפולי."},{"i":12612,"n":"דבוש, ראובן מטריפולי","f":"אליהו מטריפולי","bt":"תרף","bp":"זליתן-לוב","dt":"תשנד - ד אלול","dp":"מושב זיתן","b":"מחכמי לוב, תלמיד ר יוסף חיים זארוק. עלה לארץ-תשד בערך, וכיהן כרב במושב זיתן."},{"i":12613,"n":"דבוש, רפאל מטריפולי","f":"פריג'א-פרג'אללה","bp":"זליתן-לוב","dt":"תרפז - י כסלו","dp":"טריפולי","b":"רב ואב\"ד בטריפולי. חתם עם רבני עירו על הסכמה. חיבר הסכמה ל\"יוסף חן\" טריפולי. נספה בהתמוטטות מבנה בזמן שערך חופה."},{"i":12614,"n":"דבוש, שאול מטריפולי","f":"פריג'א-פרג'אללה","bp":"זליתן-לוב","dt":"תשה","dp":"טריפולי","b":"מחכמי טריפולי. עורך כתב העת \"למדו עברית\"-טריפולי תרצג. נהרג עק\"ה."},{"i":12615,"n":"דבזלה, חזקיה","b":"בשנת תמז בשליחות בקרפנטרנץ, בשנת תנט שליח צפת וירושלים בצרפת. לדעת בניהו המדובר בר חזקיה די סילוה."},{"i":12616,"n":"דבח, יצחק מאר\"ץ","f":"ישעיה","dt":"תקסד","b":"רב באר\"ץ"},{"i":12617,"n":"דבח, ישעיה מאר\"ץ","f":"יצחק","dt":"תקלב","b":"רב באר\"ץ, הסכים על \"ברך יצחק\" לר יצחק ברכה, ו\"חנן אלקים\". מחדושיו נאסף \"מחלב הארץ\" ירושלים תשכו, וב\"שערי רחמים\"."},{"i":12618,"n":"דבליצקי, שריה מבני ברק","b":"רב ומקובל בבני ברק."},{"i":12619,"n":"דבנישסקי, איזיק מאיר מליטא","k":"א. וויטער","bt":"1879","bp":"ביניאקון-פלך וילנא","dt":"1919","dp":"וילנא","b":"עתונאי ומהפכן. התצרטף ל\"בונד\", עורך \"דער וועקעיר\" נשלח לסיביר, חזר לוילנא גורש שנית לסיביר-1913 חזר לוילנא-1918 וכתב ב\"פאלקס צייטונג\" ועוד. נרצח ע\"י חיילים פולנים שכבשו את וילנא-1919. לזכרו \"וויטער בוך\" וילנא 1920."},{"i":12620,"n":"דבראשוילי, גבריאל","f":"רחמים","bt":"תרנו","bp":"צחינבאלי","dt":"תשמה","b":"למד תורה בברסט, נסמך על ידי רבני מינסק, רב ברוראמי"},{"i":12621,"n":"דבראשוילי, משה מגרוזיה","f":"רחמים","bt":"תרנג","bp":"צחינוואלי-גרוזיה","dt":"תשם","dp":"ירושלים","b":"תלמיד ר אברהם חווליס בישיבה בצחינוואלי, ועבר ללמוד אצל החפץ חיים בראדין. רב בכותיאסי-גרוזיה ראש העדה ונבחר לפרלמנט המקומי-תקעח. עלה לירושלים."},{"i":12622,"n":"דברון, יהוסף משלוניקי","b":"מחכמי שלוניקי-שנות ה-ש'."},{"i":12623,"n":"דבש, דוד מטריפולי","bp":"טריפולי","dt":"תריז - יט תשרי","dp":"ירושלים","b":"תלמיד ר נתן אדאדי. מקובל מחכמי טריפולי, עלה לירושלים (חצר בירושלים נקראה על שמו \"חצר הרב דבש\"), בשליחות בטריפולי-תריג, ונזכר אצל רבו ר נתן אדאדי ב\"ויקרא אברהם\". חתם עם רבני ירושלים על פסק הלכה שנשלח לר אברהם אדאדי."},{"i":12624,"n":"דגאלו, יצחק משלוניקי","dt":"רפז - כב תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":12625,"n":"דגאנא-שוילי, מרדכי מבאנדזא","f":"דוד","bt":"תרטז","b":"תלמיד ישיבת קולאש. רב בבאנדזא-פלך כותאיס-תרלט וראש ישיבה. נסמך מאת: ר יצחק בן משה דגאנא-שעלה לירושלים."},{"i":12626,"n":"דגוצקי, מנחם דב מאנגליה","f":"בנימין","bt":"תרו","bp":"טאוריג-פלך קובנא","b":"תלמיד ר בצלאל אסמינער בוילנא. נסמך מאת: ר יעקב יוסף מניו יורק. היגר לאנגליה וכיהן כרב במנצסטר-תרמו, ברמינגהם-תרנד, יוהנסבורג-דרום אפריקה-תרנו, וחזר למנצסטר והקים מוסדות וישיבה בראשות ר צבי הירש פרבר מזאגר."},{"i":12627,"n":"דגן, משה מגריבוב.","b":"תשובה אליו - \"בנין צבי\"-תרץ."},{"i":12628,"n":"דדון, אברהם מאלגיר","bt":"תקל","dt":"תרי - בערך","b":"דיין, רב ומו\"ץ באלגיר, חתם עם רבני אלגיר על פסק דין-תקצד. הסכים על \"ספר הזכרון\" - ליוורנו תרה."},{"i":12629,"n":"דדון, יוסף מאלגיר","f":"אברהם","bt":"תקע","dt":"תרם - בערך","b":"רב באלגיר. חיבר הקדמה ל\"תוכחות מוסר\" לר סעדיה אזוביב. חיזק את ידי ר יוסף - נינו של ר סעדיה אזוביב, בהוצאת ספר זקנו."},{"i":12630,"n":"דדון, מקיקץ פרץ מתונס","k":"בעל פדה בשלום","bp":"גאבס","dt":"תרצט","b":"מחכמי תונס. נפטר צעיר."},{"i":12631,"n":"דדון, משה","b":"מרביץ תורה באלג'יר-תר\"נ"},{"i":12632,"n":"דה לה פריגולה, רפאל מאלכסנדריה","bt":"תרלו","bp":"איטליה","dt":"תרפג - יב אלול","b":"רב באלכסנדריה-תרע."},{"i":12633,"n":"דה פריס, בנימין","bt":"1905","dt":"ה'תשכו 1966","b":"פרסם מאמרים ב\"המאור\" - תל אביב תרצה.","bk":[["מבוא כללי לספרות התלמודית",""]]},{"i":12634,"n":"דה-פריס, שמעון","bt":"תרלא","dt":"תשג","b":"רב בהארלם(הולנד)"},{"i":12635,"n":"דואינייאס, יצחק מאזמיר","b":"מחכמי אזמיר, בשליחות במכנאס-תרכה, והביא עמו ספר \"אהל יעקב\" ור דוד משאש ביקש מתלמידיו להעתיקו."},{"i":12636,"n":"דואינייאס, שמעיה מאיפסולה","f":"רפאל","b":"רב באיפסולה-תכז, חתום על ההסכם עם נתן העזתי."},{"i":12637,"n":"דואני, עמרם מסלאתי מטריפולי","f":"דואני מסלאתי","bt":"תס","dt":"תקל - בערך","dp":"טריפולי","b":"רב, דיין וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":12638,"n":"דואני, פדלון מטריפולי","f":"אשר","bt":"תקך","dt":"תקצה - בערך","b":"רב ודיין בטריפולי ומלמד תורה. חתם בפנקס בי\"ד טריפולי. נזכר ב\"כמוס עמדי\" לר כמוס עגיב. יש אומרים שהיה רב בשנת - תרך."},{"i":12639,"n":"דואני, שלמה מטריפולי","f":"אשר","bt":"תץ","dt":"תקס - בערך","dp":"טריפולי","b":"רב בטריפולי."},{"i":12640,"n":"דוב בער בן אברהם ממזריץ","f":"אברהם","k":"המגיד ממזריטש","bt":"תסד","bp":"לוקאטש","dt":"תקלג - יט כסלו","dp":"אניפולי","b":"מדברי תורתו של המגיד ממעזריטש הובאו בספרים שונים, מהם: מגיד דבריו ליעקב; אור תורה; אור האמת. מתלמידיו המפורסמים: בנו ר' אברהם [המלאך]; ר' אלימלך מליזענסק; ר' זושא מאניפולי; ר' שנאור זלמן מלאדי.","bk":[["תורת המגיד – עה\"ת",""],["אור תורה",""],["מגיד דבריו ליעקב",""],["רבי דב בער [המגיד] ממזריטש",""]]},{"i":12641,"n":"דובאוו, יצחק ממנצסטר","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":12642,"n":"דובובנא, בנימין מצורטקוב","b":"דיין בצורטקוב-תרעח."},{"i":12643,"n":"דובזביץ, אברהם דב מארה\"ב","f":"יוסף עזרא","k":"בעל המצרף","bp":"פינסק","dt":"תרס - יד תשרי","dp":"ניו יורק","b":"סופר משכיל ומלמד לילדי הגבירים בקיוב, היגר לארה\"ב-תרנא. חיבר ה\"מצרף\" על אגדות חז\"ל - אודסה תרלא. ביקר אצל הגדול ממינסק. גיסו של ר אברהם ליב בנימינזון. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":12644,"n":"דוביאנסקי, שמעון מקידאן","dt":"תשג","b":"מרביץ תורה בקידאן. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":12645,"n":"דובינסקי, מאיר הכהן מקיוב","f":"פנחס","bt":"תרמג","b":"רב בקיוב-תרסז."},{"i":12646,"n":"דוביצקי, אברהם שמואל מגולדינגן","f":"נפתלי","bt":"תרכב","b":"חתן ר משה לרנבלאט מסאסמקין. רב בסאסמקען(=סאסמקין)-תרמב, פרוינבורג-קורלנד-תרסב, סאסמקין על מקום חותנו, גולדינגן-קורלנד-תרסה."},{"i":12647,"n":"דובנא, שלמה (יואל) - רש\"ד","f":"יואל מקרמניץ","bt":"תצא-ח","bp":"דובנא","dt":"תקעג","dp":"אמשטרדם","b":"תלמיד ר שלמה חעלמא בעל \"מרכבת המשנה\", תלמיד ר נפתלי הרץ בן ר הירש מהלברשטט ואחיו של ר שלמה דב בריש מגלוגא. מדקדק ותלמיד חכם, חברו של משה מנדלסון בברלין - והיה יוזם ומסייע בביאור התורה של מנדלסון, בהמשך נפלה מחלוקת ביניהם ועבר לוילנא - בהשפעת רבו של ר שלמה שביקר בברלין ואמר לו \"בהתחברך עם אחזיהו פרץ ה' את מעשיך\" (ורמז למנדלסון). נתבקש ע\"י הגר\"א לברר מסורת נביאים וכתובים (העיד על כך ר פסח פינפער מוילנא - \"בית ועד לחכמים\" -ליעדז תרסב, ו\"מסורת התורה והנביאים\" וילנא תרסו). רצה להדפיס תורה עם ביאור וכנראה קיבל הסכמות מגדולי ליטא ובהם ר חיים מוולוזין ואחיו ר שלמה זלמן (יש החולקים על כך) - אך החומש לא נדפס (על כך ב\"ישורון\"-ח - קמינצקי). מאמר ממנו ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. בנו - ר אברהם משה מאמשטרדם."},{"i":12648,"n":"דובנוב שמעון","bt":"1860","dt":"ה'תשא 1941","bk":[["פנקס המדינה",""]]},{"i":12649,"n":"דובנוב, שמעון","b":"היסטוריון"},{"i":12650,"n":"דובנעט, ירחמיאל מקאליש","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":12651,"n":"דובעס, יצחק ליב מגלנטא","b":"רב בגלנטא-תק.."},{"i":12652,"n":"דובער יצחק איזיק ממינסק","bp":"קרוסנא","b":"ר\"מ במינסק-תר בערך, חברו של ר ישעיה זכריה יולס ממינסק."},{"i":12653,"n":"דובער ממיטאוי","f":"בנימין הקדוש","bp":"ליטא","b":"מראשי קהלת מיטאוי-תק."},{"i":12654,"n":"דובערל מוארשא וצפת","dt":"תרפג","dp":"צפת","b":"תלמיד ר אברהם מסוכטשוב בעל \"אבני נזר\" ונסמך ממנו, מו\"ץ אצל רבו כ-30 שנה, ומלמד אצל בעל חדושי הרי\"ם. עלה לארץ והתישב בצפת. תלמידו - ר שמואל הורביץ מספר עליו בספרו \"ימי שמואל\" שהיה חריף ובקי כאחד הגאונים הראשונים."},{"i":12655,"n":"דובצינסקי, זלמן מיאנישוק","dt":"תשג","b":"רב ביאנישאק"},{"i":12656,"n":"דוברוב, ירוחם מסלוצק","b":"מרביץ תורה בסלוצק-תר\"נ"},{"i":12657,"n":"דוברוף, יעקב עוזר מארה\"ב","bt":"תרמא","b":"ר\"מ זיבוטוב-תרס\"ז,רב בשפיצניץ-תרס\"ט,סטיריזובקה-תרפ\"א,וושינגטון-תרפ\"ד"},{"i":12658,"n":"דוברושס, משה מלובלין","f":"ישכר בעריש מקרקא","b":"פרנס דד\"א בלובלין-ת\"פ"},{"i":12659,"n":"דובריזינסקי, מאיר אברהם מאלכסנ","b":"חסיד האדמור מאלכסנדר בעל \"ישמח ישראל\". דומ\"ץ באלכסנדר-ליד לודז."},{"i":12660,"n":"דובריש מלנצהוט","b":"רב בלנצהוט. תשובה אליו - מהר\"ש."},{"i":12661,"n":"דובש, יהודה ליב מלבוב","f":"יהושע","k":"ר ליב ר יהושע'ש","b":"גביר מראשי קהלת לבוב-תק בערך. בנו - שמואל, חתנו - ר אלכסנדר זיסקינד בן משה."},{"i":12662,"n":"דובש, ישעיה כץ מלבוב","f":"אלכסנדר סנדר","dt":"תנב - אחרי","b":"ראב\"ד בלבוב בזמן הט\"ז, חתם-תכא, חתם-תנב על שטר מכירה, ועוד."},{"i":12663,"n":"דוגא, שמעון מכורדיסטן","b":"ראב\"ד בעמאדיה-שץ במשך כשלושים שנה. ב\"מעשה הגדולים\" לר עלואן אבידני מספר על הריגתו של ר שמעון."},{"i":12664,"n":"דוגאט, יהודה מפרשבורג","dt":"תשד","b":"רב בפרשבורג"},{"i":12665,"n":"דוד","f":"לוי","b":"רב-שנת תק\"ל"},{"i":12666,"n":"דוד","b":"מגדולי המקובלים הראשונים-ד'תתק\"צ"},{"i":12667,"n":"דוד","f":"משה השרף","b":"רב-שנת ת\"ק"},{"i":12668,"n":"דוד","f":"יסו","dt":"שכח"},{"i":12669,"n":"דוד","f":"סיני הלוי","b":"פייטן בארצות המזרח"},{"i":12670,"n":"דוד (דידו) הכהן מג'רבה","f":"ברכיה","k":"ר' דידו","dt":"תשי - ח אלול","b":"מלמד תינוקות בג'רבא"},{"i":12671,"n":"דוד אהרן מחברון","f":"חיים","b":"מחכמי חברון, חתם בשנת תקצט על סדרי הכוללות"},{"i":12672,"n":"דוד אורי מקריפטש(=קריויטש)","dt":"תשג","b":"רב בקריפטש. פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":12673,"n":"דוד אחי הרמב\"ם","f":"מימון","b":"אחי הרמב\"ם, טבע בים הודו"},{"i":12674,"n":"דוד איזיק מסטרליסק","b":"רב בסטרליסק"},{"i":12675,"n":"דוד איסר מאיזנשטט","k":"בעל צמח דוד","dt":"תעח - כז תשרי","b":"רב באונגריש-ברוד,אייזנשטט,בגירוש אוסטריה עבר למורביה-ת\"ל,רב בגיידינג,רב בטרעביטש"},{"i":12676,"n":"דוד איסרל מטרביטש","b":"רב בטרעביטש"},{"i":12677,"n":"דוד אריה מירושלים","b":"מחכמי ישיבת פירירה בירושלים-תקיח."},{"i":12678,"n":"דוד אריה מירושלים","bt":"תסח - בערך","b":"מחכמי ישיבת בית יעקב פיררה בירושלים-תקיח."},{"i":12679,"n":"דוד בלומא מזלצבורג","b":"מחכמי שוואבן. צירף חתימתו לר יצחק איזיק גינצבורג במחלוקת ר שמעון גינצבורג עם ר נתן שאטן."},{"i":12680,"n":"דוד במוהרמ מטבריה","b":"מחמכי האשכנזים בטבריה, בשנת תקפז חתם על כתב שליחות ר ישראל קרא שיצא לתורכיה."},{"i":12681,"n":"דוד בן זכאי","b":"מחכמי ירושלים בזמן עלייתו של ר יהונתן מלוניל וחבריו, בידיו היה מכתב מאת הכליף אל נאזיר לעדין אללה לקרבו כמו נגיד ולאפשר לו כניסה למקומות הקדושים האסורים בכניסה ליהודים. הוא השתדל רבות למען אחיו היהודים ובהשתדלותו השיגו מאת מלך ירושלים אל עדול (אחי השולטן צלח א דין) רשיון לאפשר ליהודי אירופה להגיע לירושלים, אלחריזי מצאו בשנת ד תתקע (1210) בירושלים"},{"i":12682,"n":"דוד בעווערונג מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":12683,"n":"דוד בער מפרגה","dt":"תקעט - ב אדר","b":"רב בפרגה"},{"i":12684,"n":"דוד בערצא מטלוסט","dt":"תר - כו אדר","b":"רב בסקאלא,שפיטיבקה,טלוסט"},{"i":12685,"n":"דוד ברוך החסיד משלוניקי","b":"ראש ישיבה בק\"ק פולייא בשלוניקי."},{"i":12686,"n":"דוד גרשון ממצרים","f":"גרשון?","bt":"שעה-צה","dt":"תס או תצח","b":"רב באשיד(=ראשיד)-מצרים-תיג על מקום ר מרדכי הלוי (שעבר לקהיר) ור שבתי נאווי על מקומו אחריו, ודיינים אצלו - ר שמואל נחמיאש, ר יוסף בן מנשה, ר יוסף סורמאני. נזכר בגנת ורדים. (לדברי רוזניס נפטר בן כ-100 שנה)."},{"i":12687,"n":"דוד דניאל מטשיטשילניק","b":"בנו של תלמיד הבעשט שעמד בראש עדת חסידים. רב בטשיטשילניק."},{"i":12688,"n":"דוד דרשן מקראקא ולובלין","f":"מנשה","k":"בעל שיר המעלות","b":"דרשן בקרקא, לובלין-שלד. התכוון לעלות לארץ. חיבר גם \"אביר יעקב\", \"בית דוד\", \"כסא דוד\", \"התנצלות הדרשנים\",ועוד."},{"i":12689,"n":"דוד הבבלי","f":"מרואן אל מקמץ","b":"חכם קדמון, נזכר אצל ר יהודה אלברצלוני."},{"i":12690,"n":"דוד הדוטור משלוניקי","dt":"שז - כא כסלו","dp":"שלוניקי","b":"רופא מחכמי שלוניקי."},{"i":12691,"n":"דוד החסיד","f":"יהודה החסיד בן הרמבן","k":"בעל אור זרוע","b":"מקובל. נכד הרמב\"ן. חיבר \"אור זרוע\" - מוזכר אצל בעל \"מנות הלוי\" בספרו \"אפריון שלמה\" - בכת\"י. חיבר גם \"יסודות מעשה מרכבה\" ו\"מעשה בראשית\" - בספריית ר דוד אופנהיים, חיבר גם \"מראות הצובאות\"."},{"i":12692,"n":"דוד החרש","b":"מחכמי פאס, הגיע לארץ ישראל עם חברו ר אבודני, בדרך פגשו את ר סעדיה גאון, בשובם לאפריקה הביאו אתם את ספר היצירה המפורש בידי רב סעדיה גאון. כך כותב דונש בן תמים איש קירואן בפירושו לספר יצירה."},{"i":12693,"n":"דוד הכהן","f":"רפאל"},{"i":12694,"n":"דוד הכהן","f":"אהרן","k":"בעל מגדל דוד","b":"תלמיד המהרש\"ל. בנו ה\"ל את ספרו \"מגדל דוד\" - שלוניקי שי, עם הקדמה ממנו."},{"i":12695,"n":"דוד הכהן הפייטן","b":"פייטן - שנות ה-ק'. מפיוטיו במחזור אלגיר וצרפת, חיבר \"יחשיך בחלו מהביט בהודו\"."},{"i":12696,"n":"דוד הכהן מאדרינופול;","f":"פנחס מאדרינופול","b":"רב באדרינופול-שנות ה-ת'. ור משה בנבנישתי מקושטא הסכים על פסק שלו."},{"i":12697,"n":"דוד הכהן מאובן","f":"יעקב","b":"רב באובן-שנות ה-ש' על מקום ר יוסף זלמן."},{"i":12698,"n":"דוד הכהן מאודסה","f":"מאיר","dt":"תקצה - יג אדר","dp":"אודסה?","b":"מחכמי אודסה-תקפא, חיבר ספר זכרונות בשם \"זכרון ספר משפחה\" - נדפס בידי נכדו דוד כהנא בקובץ \"כנסת ישראל - תרמו."},{"i":12699,"n":"דוד הכהן מאזמיר","b":"מחכמי איזמיר"},{"i":12700,"n":"דוד הכהן מאלגיר","bt":"קי","dt":"קף - בערך","b":"רב בדזאייר(=אלגיר). אחיו של ר שאול הכהן מאלגיר. נזכר בשו\"ת הריב\"ש יחד עם אחיו ר שאול - שסייעו להתישבות מגורשים מספרד באלגיר ומנעו מזימה להפריע להם."},{"i":12701,"n":"דוד הכהן מאלגיר","bt":"תן","dt":"תקי - בערך","b":"רב באלגיר. נזכר ב\"בית יהודה\" לר יהודה עייאש. נזכר ברשימת הנפטרים של קהלת אלגיר."},{"i":12702,"n":"דוד הכהן מאלגיר","f":"כלפא","k":"בעל דברי חכמים","dt":"תשח","b":"סגי נהור. רב בקצמטינא. תרגם לערבית יהודית את \"עשיר ורש\" לר בן ציון אלקלעי יחד עם ר מ' טוביאנא. הו\"ל \"שבוע טוב\", \"שאו זמרה\" סוסה תרפט, חיבר \"דברי חכמים\" תונס תרעא, \"אור דוד\", \"שבחי אבות\" סוסה תרפא, זכרי כהונה\" גרבא תשח, ועוד. מתלמידיו - ר יוסף גנאסיא."},{"i":12703,"n":"דוד הכהן מאלטונא","f":"מנחם מהנאו","k":"בעל מזמור לתודה","bp":"הנאו","dt":"תיג - אחרי","dp":"אלטונא","b":"רב בהענוי(=הנאו), הראב\"ד הראשון באלטונא-תיא. נזכר בזכרונות גליקל, בניו: ר אליהו-חתן דודתה של גליקל, ר מנחם, חתנו - ר יצחק שפירא-חותנו של ר יונתן איבשיץ."},{"i":12704,"n":"דוד הכהן מאנגורה","dt":"שפה - לפני","b":"רב באנגורה-שנות ה-ש', התכתב עם ר יוסף טרני מקושטא."},{"i":12705,"n":"דוד הכהן מבאטורקז","dt":"תקצ - יז ניסן","b":"רב בבאטורקעז,רעטה"},{"i":12706,"n":"דוד הכהן מבודון","b":"רב בבודון-שנות ה-ת'."},{"i":12707,"n":"דוד הכהן מבוז'עא","k":"בעל תפלה לדוד","b":"מחכמי מרוקו, אב\"ד בבוז'עא(מרוקו), דרשן, חיבר \"תפלה לדוד\""},{"i":12708,"n":"דוד הכהן מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":12709,"n":"דוד הכהן מג'רבה","f":"אברהם הכהן","k":"בעל דברי דוד","dt":"תרעג - כד טבת","dp":"גאבס","b":"מקובל, מדקדק, רב בג'רבא-תרע על מקום אביו. חיבר גם \"שירי דוד\".","bk":[["שלום דוד",""]]},{"i":12710,"n":"דוד הכהן מג'רבה","f":"משה הכהן","bt":"תקפה - ב אלול","bp":"ג'רבא","dt":"תרלא - חשון","dp":"ג'רבא","b":"מחכמי ג'רבא, חיבר \"משגב לדך\""},{"i":12711,"n":"דוד הכהן מדמשק","b":"רב בדמשק, חתם-תקצא על ביצוע גביית כתובה עבור רבני צפת, יחד עם ר מאיר דוויק הכהן."},{"i":12712,"n":"דוד הכהן מטבריה","b":"מחכמי טבריה, חתם בשנת תקטו על אגרת שליחות ר שמואל שלם שיצא לאירופה."},{"i":12713,"n":"דוד הכהן מטיטואן-מרוקו - א","dt":"תסח - יט תמוז","b":"מקובל, ור\"מ בטיטואן-מרוקו, נזכר ב\"משפט וצבי\", חתם על פס\"ד-תסה עם ר חסדאי אלמושנינו. הניח דרושים לנפטרים - בכת\"י - והיו בבית עקד של משפחת ן צור.","bk":[["דברי דוד",""]]},{"i":12714,"n":"דוד הכהן מטיטואן-מרוקו - ב","b":"רב בטיטואן, חתם-תכט על פס\"ד עם ר דוד הכהן מטיטואן (שנפטר-תסח)."},{"i":12715,"n":"דוד הכהן מטרנטשין","dt":"תקמט","b":"רב בטרענטשין-תקי\"ט"},{"i":12716,"n":"דוד הכהן מלאריסה","f":"אברהם","b":"דיין בלאריסה-תן."},{"i":12717,"n":"דוד הכהן מליסקא","b":"רב בליסקא-תקע\"ה"},{"i":12718,"n":"דוד הכהן ממוגאדור-מרוקו","dt":"תריז - ז ניסן","dp":"מוגאדור","b":"מחכמי מרוקו, נקרא על שם הצדיק ר דוד ן ברוך."},{"i":12719,"n":"דוד הכהן ממודנא","f":"אברהם יצחק ממודנא","dt":"תקמב - ט אלול","b":"מחכמי איטליה,רב במודנא(=מודינא)-תק. אחיו של ר ישמעאל הכהן בעל \"זרע אמת\" שהביא מתורתו בספרו. פסקים ממנו היו בידי ר אברהם גור אריה מפינאלי."},{"i":12720,"n":"דוד הכהן ממרוקו","bp":"פאס","b":"מו\"ץ במרוקו, חתם-תקעט עם ר שמואל הצרפתי, חתם על פס\"ד עם ר שאול סירירו ור חיים דוד סירירו. נזכר אצל ר שמעון ן סעדון."},{"i":12721,"n":"דוד הכהן ממרוקו","k":"מול אדרע","dt":"מראקש-ליד","b":"צדיק במרוקו, על קברו באים רבים להשתטח."},{"i":12722,"n":"דוד הכהן מספרד","b":"מחכמי ספרד, כתב חידושים למסכת ביצה"},{"i":12723,"n":"דוד הכהן מספרד","b":"תלמיד הרשב\"א, נזכר אצל רבנו ירוחם."},{"i":12724,"n":"דוד הכהן מעכו","f":"משה","b":"מחכמי עכו בשנת נ (1289), מהחותמים על חרם ראש הגולה בדמשק בשנת מו נגד המדברים על הרמבם, ומובא בסוף \"פאר הדור\" להרמבם. פגש את הרמבן בהיותו בעכו ולמד ממנו תורת הקבלה. מובא בספר \"מאירת עינים\" לר יצחק בן שמואל מעכו המביא שמועות בשם רבו."},{"i":12725,"n":"דוד הכהן מפודהייץ","f":"אריה ליב בעל הקצות","b":"רב בפודהייץ-תקפה. הוציא לאור ספר אביו \"שב שמעתתא\" עם מפתח בנו ר אשר מרדכי שהיה תלמיד זקנו."},{"i":12726,"n":"דוד הכהן מפמורן","k":"בעל אהבת דוד ויונתן","b":"רב בפאמארן-תקס. חיבר \"אהבת דוד ויונתן\" על \"אורים ותומים\" - למברג תקסא."},{"i":12727,"n":"דוד הכהן מפרובנס","f":"יצחק הכהן","b":"מגדולי הראשונים בפרובינצא-שנת י',רב בנרבונא,פוסק,מרביץ תורה"},{"i":12728,"n":"דוד הכהן מצפת","dt":"שע - אחרי","b":"נמנה על תלמידי האר\"י ומוזכר בספר החזיונות, כן מוזכר בשות מהרי\"ט. בשנת שנז חתם על תקנה לשחרור תלמידי חכמים ממס (כנראה הכוונה אליו)."},{"i":12729,"n":"דוד הכהן מקולומיאה","b":"רב בקולומייא-ת\"ע"},{"i":12730,"n":"דוד הכהן מקורפו","f":"חיים","k":"בעל שו\"ת הרד\"ך,רד\"ך","bt":"רך","bp":"קורפו ?","dt":"רצ","b":"ממגורשי ספרד-רנב, מגדולי הפוסקים, למד תורה בקורפו ואיטליה, רב בכמה קהלות ובהם קורפו, שלוניקי, פטרץ וראש ישיבה שם. חיבר שו\"ת רד\"ך. מחתניו: ר דוד וידאל מפטרץ וארטא. בנו - ר חיים מקושטא.","bk":[["רד\"ך","שו\"ת - אחרונים"],["רד\"ך - שו\"ת -",""],["הרד\"ך (שו\"ת)",""]],"e":"רכ\"ה~-ר\"צ"},{"i":12731,"n":"דוד הכהן מקראקא","f":"יואל","b":"חתן החבר ר יהושע. רב בקראקא-ש' בערך. בנו חורגו - בעל \"שארית יוסף\"."},{"i":12732,"n":"דוד הכהן מקרסטיר","b":"רב בקרסטור(=קרסטיר)-תקף, זברז-תרה."},{"i":12733,"n":"דוד הכהן משיביליא-ספרד","k":"בעל מלים נכריות בלש","b":"מחכמי שביליא(=סביליה)-ה'קמו. חיבר ספר בערבית - על מלות נכריות בלשון הקודש."},{"i":12734,"n":"דוד הכהן משלוניקי","f":"יעקב בן דוד הקדוש","k":"בעל מגדל דוד","b":"ראב\"ד באויבן-שמ, מחכמי שלוניקי. נכד הקדוש ר דוד משלוניקי. חיבר \"מגדל דוד\" שלוניקי שנז."},{"i":12735,"n":"דוד הכהן מתונס","k":"בעל שלום דוד","b":"רב בתוניס"},{"i":12736,"n":"דוד הכהן ס\"ט מאיטליה","b":"מחכמי איטליה-תקמ, אחיו - ר ישמעאל ממודנא."},{"i":12737,"n":"דוד הכהן קאסאוור","k":"ראש בית דין","b":"ראב\"ד בקסובה, ר\"מ ב\"ישיבת הארבעים\" בשניפישוק ובוילנא-תקפח. ישיבת הארבעים נוסדה-תקפח לאחר גזירת הגיוס של הצאר ניקולאי (ובחורי הישיבות נפטרו מהגיוס - שנעשה ע\"י ראשי הקהלה)."},{"i":12738,"n":"דוד הלבן מצרפת","f":"אברהם בן יהודה מקוצי","k":"בעל מסורת הברית","b":"מגדולי חכמי צרפת-שנת מ'"},{"i":12739,"n":"דוד הלוי"},{"i":12740,"n":"דוד הלוי הרופא מקושטא","b":"תלמיד ר משה הכהן. רופא מחכמי קושטא-שנות ה-ת', פעל לטובת יהודי ירושלים."},{"i":12741,"n":"דוד הלוי מאוסטרהא","f":"שמשון","dt":"תקז - א ניסן","dp":"אוסטרהא","b":"מצאצאי בעל הט\"ז. פרנס באוסטרהא יחד עם ר יצחק הלפרין הרופא וחתם לצדו בפנקס הח\"ק. מצאצאציו הדיין ר ישראל יעקב הלוי מאוסטרהא."},{"i":12742,"n":"דוד הלוי מאיזנשטט","b":"רב באייזנשטט-ת\"ל"},{"i":12743,"n":"דוד הלוי מאיטליה","b":"מחכמי איטליה. חברו של הרב יהודה עייאש שהביא ממנו בספרו \"לחם יהודה\"."},{"i":12744,"n":"דוד הלוי מדובנא","b":"מ\"מ בדובנא."},{"i":12745,"n":"דוד הלוי מוילנא","f":"ברוך","b":"פרנס מראשי קהלת וילנא, הסכים על \"שערי בנימין\" עם היסו\"ד ור אליהו מיילס, חתם על כתב רבנות ר שמואל כראב\"ד וילנא."},{"i":12746,"n":"דוד הלוי מלבוב","f":"אהרן שלום הלוי","dt":"תט - כא כסלו","dp":"לבוב","b":"ר\"מ בלבוב. אחיו - ר יצחק מליסא בעל \"בית לוי\"."},{"i":12747,"n":"דוד הלוי ממגנצא","b":"מגדולי הראשונים,מחכמי מגנצא-ד'תש\"ס"},{"i":12748,"n":"דוד הלוי ממרוקו","b":"מחכמי סאלי-תצ\"ב"},{"i":12749,"n":"דוד הלוי ממרוקו -","k":"תמ\"ך - בעל המלכות","b":"מקובל, בגירוש ספרד עבר למרוקו-רנ\"ב, למד תורה בפאס, דיין בתאמגרות-מרוקו, חיבר ספר \"המלכות\", פיוט, חידה הנמצאת ב\"מיני מתיקה\"."},{"i":12750,"n":"דוד הלוי מסאלי-מרוקו","b":"מחכמי סאלי-מרוקו, חתם על פס\"ד-תצב עם ר יוסף הכהן."},{"i":12751,"n":"דוד הלוי מסטעפין","f":"יהודה ליב-תלמיד הבעש","k":"אדמור מסטעפין","dt":"תקע-א - יא תשרי","b":"נקרא \"המגיד מסטעפין\". תלמיד הבעשט, והמגיד ממזריטש. חתן ר יוסף יואל הלפרין מסטעפין-תלמיד הבעשט, ובזיוו\"ש חתן ר יחיאל מיכל מזלוטשוב-תלמיד הבעשט. מגיד מישרים בסטעפין על מקום חותנו, ורב בסטעפין על מקום גיסו ר אהרן שמואל בעל \"וציוה הכהן\". הנהגותיו ב\"סדר הנהגת אדם\". מחותן עם ר אברהם יוסף מדינאווא וסורוקה (באוצר הרבנים שם אביו: שמואל)."},{"i":12752,"n":"דוד הלוי מפיררה","b":"דיין בפירארה-ר\"פ"},{"i":12753,"n":"דוד הלוי משלוניקי","dt":"שף","b":"מלמד תורה מחכמי שלוניקי."},{"i":12754,"n":"דוד הלוי משפיירא","f":"שמואל הלוי","b":"מגדולי חכמי שפירא-ד'תתנו. רש\"י שאל ממנו. חיבר קינה \"אמונים שודרו\", \"ה' אלקי רבת\" על גזירות תתנו."},{"i":12755,"n":"דוד הלוי מתימן","k":"בעל ילקוט מדרש","b":"מגדולי חכמי תימן-רמ\"ד"},{"i":12756,"n":"דוד המלך","bt":"ב\"א תנה \\ ב\"א תתנד","dt":"ו סיון","bk":[["תהלים",""]]},{"i":12757,"n":"דוד הנזיר הכהן מחברון","b":"בשליחות בבלגרד-תכט."},{"i":12758,"n":"דוד הנקדן","f":"שלמה","b":"פייטן-שנות ה-ק', חיבר \"אנחתי כבדה ולבי לבשה חרדה\"."},{"i":12759,"n":"דוד הפייטן","f":"אלכסנדר","b":"פייטן שנות ה-ק'-ר'. חיבר קינה \"אזכרה נגינותי מקדם\"."},{"i":12760,"n":"דוד הפייטן","f":"הונא","b":"פייטן אולי משנות -הד'תתק. חיבר יוצרות לפסח ונמצאו במחזור רומא ורומניה."},{"i":12761,"n":"דוד הפייטן","f":"יעקב בן יהודה","b":"פייטן - שנות ה-ק'. חיבר פזמון לנעילה \"אליך קוני נשאתי עיני\"."},{"i":12762,"n":"דוד הפייטן","f":"ישי","b":"פייטן. חיבר פיוטי יוצרות, וסליחות שנכנסו למחזור צרפת."},{"i":12763,"n":"דוד הפייטן","f":"משלם","b":"פייטן באשכנז-שנות ה-ד'תתק'. חיבר הסליחה \"אלקים אל דמי לדמי לא תחרש\" על גזירות תתנו."},{"i":12764,"n":"דוד הפייטן","f":"שמשון","b":"פייטן, מפיוטים במחזור צרפת-ה'לח, ובהם \"דם נזרק יום\" לזכר הקדושים - ר אליעזר, ר יעקב, ר ברוך, ר שמשון שנשרפו עק\"ה בשבת."},{"i":12765,"n":"דוד הפייטן מינואי-נוא","f":"גדליה בן יחיאל בן יע","b":"פייטן - שנות ה-ד'תתק'. מפיוטיו במחזור קושטא."},{"i":12766,"n":"דוד הראובני","b":"משיח שקר, הגיע למצרים-רפג ושהה אצל ר אברהם קאשטרו, היה בירושלים, אלכסנדריה, ונציה ופגש את האפיפיור וסיפר לו על עשרת השבטים, נאסר ושוחרר, התחבר אל ר שלמה מולכו, לאחר הריגתו של ר שלמה נאסר ומת בכלא."},{"i":12767,"n":"דוד הרוקח מקובנא","b":"רוקח בקובנא-ש' בערך, בנו - ר מתתיה קאלהורה-נהרג עק\"ה."},{"i":12768,"n":"דוד וחיון ן, מימון מאלגיר","b":"רב במוגניא(=מרניא)-תרל. סייע בהדפסת \"בית שלמה\" לר א' שלמה פרידמן - ירושלים תרנא - ונזכר ברשימת התורמים בראש הספר."},{"i":12769,"n":"דוד ומשה מירושלים","bp":"ירושלים","dt":"א חשון","dp":"תמסטינת","b":"מגדולי חכמי ירושלים, דרשן, נשלח כשד\"ר למרוקו, מתוך דאגה למצבו הירוד של הציבור, עודד את רוחו, והגיע להרי האטלס, בכפר תמסטינת היתה מגיפה קשה, הוא החליט למסור נפשו עליהם, שם נקבר והמגיפה נעצרה, המקום הפך למקום תפילה ועליה לרגל"},{"i":12770,"n":"דוד זאב הכהן מפינטשוב","f":"יצחק כץ","b":"רב בשטעקטשין,פינטשוב"},{"i":12771,"n":"דוד חיים משלוניקי","f":"חיים שבתי","dt":"תכח","dp":"שלוניקי","b":"תלמיד ר דניאל אישטרושא. רב בשלוניקי."},{"i":12772,"n":"דוד טבלי","f":"אליעזר-דמשק אליעזר"},{"i":12773,"n":"דוד טבלי הלוי","f":"יצחק אריה הלוי","b":"גביר תלמיד חכם."},{"i":12774,"n":"דוד טבלי מוינה","k":"חתן הרש\"ל","dt":"שכז - יז כסלו","b":"מגדולי חכמי ווינה"},{"i":12775,"n":"דוד טבלי מטורבין","dt":"תיט - יד תשרי","b":"ר\"מ בטורבין"},{"i":12776,"n":"דוד טבלי מטרייר","f":"יצחק ולך","bt":"שפ","dt":"תנב","b":"רופא, מקובל, ודיין בטרייר-תלא. מקורב לר גרשון אשכנזי בעל \"עבודת הגרשוני\" המזכירו בספרו, ונזכר גם ב\"חוות יאיר\"."},{"i":12777,"n":"דוד טבלי מלבוב - א","f":"שמואל","dt":"שצט - יח ניסן","dp":"לבוב","b":"תלמיד מהר\"ם מלובלין שהזכירו בספרו. מרביץ תורה בלבוב."},{"i":12778,"n":"דוד טבלי מלבוב - ב","b":"דיין בלבוב-תע\"ג"},{"i":12779,"n":"דוד טבלי מלודמיר","f":"אפרים פישל מלודמיר","b":"פרנס דד\"א בפולין-תפ\"א"},{"i":12780,"n":"דוד טבלי ממינסק","f":"משה","k":"בעל בית דוד","bt":"טורעץ-ליד מיר","dt":"תרכא - יז אייר","dp":"מינסק","b":"תלמיד ר חיים מוולוזין בישיבת וולוזין. מגדולי חכמי דורו, בזיוו\"ש חתן ר יהושע אלטשול מטשאווס (וגיסו-ר שלמה זלמן אלטשול - היה גם חתן נכדתו ותלמידו). רב בסטויפץ-תקעז, מינסק-תרכ (או תרט) והגדול ממינסק על מקומו אחריו-תרמג (לאחר תקופה ממושכת שלא היה רב). חתנו ר משה ליב בעל \"מילי דאבות\". בנו ר יצחק - מו\"ץ במינסק וחתנו ר שאול חיים הורביץ בעל \"מצפה שאול\" מדוברובא - הו\"ל את ספרו \"דברי דוד\" ובהקדמה מביא את תולדותיו. פרסם מאמרים ב\"פליטת סופרים\" - וילנא תרכג. מאמר ממנו ב\"תבונה\" - ירושלים תשא."},{"i":12781,"n":"דוד טבלי מפוזנא והמבורג","f":"בנימין בינש וולף מפו","k":"בעל שערי ציון","bp":"פוזנא","dt":"תס - יד כסלו","dp":"המבורג","b":"נכד ר יצחק דרשן לבוב. תלמיד ר שבתי שעפטל בעל \"ווי העמודים\". גלה מפוזנא להמבורג וישב אצל הפרנס ר נתן בן משה וכיהן כמו\"ץ, ושם חיבר את ספרו. היה מחלוקת על הרבנות בינו לבין ר מאיר בן ב חתן - ר ברוך רופא מפוזנא. נימין וולף אשכנזי, ור אהרן שמואל קיידנובר פסק שעל ר דוד טבלי לעזוב את הרבנות, ונזכר ב\"אהל יעקב\" לר יעקב ששפורטש. נזכר גם אצל ר יונתן איבשיץ כמקור לכך שקהלת המבורג היתה כפופה לאלטונא. חיבר גם \"במסורה\", במוסר\". בנו חיבר הקדמה לספרו"},{"i":12782,"n":"דוד טבלי מצפת","f":"אשר","k":"התנא מצפת","b":"מחכמי צפת ולאחר מכן ירושלים, בשנת שמד בשליחות לפולין, מוזכר ב\"תוספות יום טוב\" (פאה פ\"א ג) \"ומפי ר טבלין מירושלים שמעתי וכו'\". נראה שהוא חתום על כתב יד של רזיאל המלאך שנדפס באמשטרדם תסא. בשנת שסח היותו בשליחות באיטליה פנה ר דוד פארדו לר עזריה פיגו שישתדל אצל רבו ר ישכר בר איילנבורג לעזור לר דוד בשליחותו. כנראה מתלמידי הארי. לדעת יערי הוא ר דוד בן אשר בעכינגען שהיה בורמיזא בשנת שסט."},{"i":12783,"n":"דוד טוביה ממינסק","f":"יהודה ליב","dt":"תרלד - כד תשרי","dp":"מינסק","b":"דיין ור\"מ במינסק."},{"i":12784,"n":"דוד טעביל טבלי הכהן מצעפלאוו","f":"אלעזר רפפורט מפיאסק","b":"חתן ר מרדכי - אב\"ד קרילעוו(=קרילוב?). אב\"ד טצעפאלוו. נכדו - ר יצחק דוד פרייליך מנור. גיסו של אביו - מהר\"ם מינץ מפיאסק-דודו של מהרי\"ד מקוזניץ."},{"i":12785,"n":"דוד טעביל מאוסטרהא","f":"מרדכי","dt":"תקי - ו אד\"א","b":"רב באוסטרהא. בנו ר נתן פרנס באוסטרהא."},{"i":12786,"n":"דוד טעבל מלבוב","f":"מאיר","b":"דיין בלבוב, חתם-תעג על פסק דין."},{"i":12787,"n":"דוד יאנאווער מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":12788,"n":"דוד ידידיה מוארשא","dt":"תרב - ד אייר","b":"דיין בוורשה-תקס\"ב"},{"i":12789,"n":"דוד יהודה הכהן מירושלים","dt":"תרכא - כג טבת","dp":"ירושלים","b":"מחכמי ירושלים, שליח חברון בשנת תריא, חתן ר אברהם גאגין."},{"i":12790,"n":"דוד יהודה הלוי מירושלים","f":"יצחק אייזיק","b":"שליח ירושלים בברסלוי, בשנת תצא מופיע ברשימות שוערי העיר."},{"i":12791,"n":"דוד יהודה מוילנא","f":"אורי","b":"דיין בוילנא-תקכו עד תקמב."},{"i":12792,"n":"דוד יואלי מפוגשטדט","b":"רב בפוגשטדט-תר\"ל"},{"i":12793,"n":"דוד יוסף משלוניקי","dt":"תקמא","dp":"שלוניקי","b":"רופא בשלוניקי, נפטר במגפה הגדולה-תקמא."},{"i":12794,"n":"דוד יוסף משלוניקי","f":"יוסף דוד-בית דוד","k":"הנכד","dt":"תפה - לפני","dp":"שלוניקי","b":"רב בשלוניקי-שנות ה-ת'. נפטר צעיר. פסק ממנו ב\"דבר משה\" לר משה אמריליו, וב\"בית דוד\" לאביו. בנו - ר יוסף."},{"i":12795,"n":"דוד יחזקאל ממיטאוי","f":"יקותיאל","dt":"תקפג","dp":"מיטאוי","b":"רב בואבאלניק-ליד פוניבז, זאגער, מיטאוי-קורלנד-תקד. חיבר פירוש על \"הלכות גדולות\" - בכת\"י, (בן יעקב אוצר הספרים). הקיסרית אליזבת בקשה ממנו ברכה כשעברה במיטאוי-תקע. תשובה ממנו ב\"גדולת מרדכי\" לר מרדכי רבינר. בנו - ר אליהו."},{"i":12796,"n":"דוד יעקב","f":"אייזי מסטריא"},{"i":12797,"n":"דוד יעקב מבוליחוב","b":"חתן ר מרדכי מסקול. ר מנחם מנדל מקוסוב קראו \"השרף הנורא\", ור צבי הירש מזידיטשוב קראו \"הקדוש מבוליחוב\"."},{"i":12798,"n":"דוד יעקב מקדלבורג","b":"תלמיד החת\"ס. דיין בקדלבורג."},{"i":12799,"n":"דוד יצחק משלוניקי","dt":"תלג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":12800,"n":"דוד כץ מטבריה","f":"אלכסנדר הכהן","b":"אחיו של ר אברהם כץ מקאליסק"},{"i":12801,"n":"דוד כתבן מזולקוא","f":"יצחק מפרג","k":"חתן הש\"ך","dt":"תנט - ה אייר","dp":"זולקוא","b":"גביר, מנהיג המדינה בלבוב וזולקוא ופרנס דד\"א. חתן הש\"ך (ויש אומרים שאלמנתו - טויבה - נשאה אחר פטירתו לר אהרן מגזע צבי - אולם הדבר לא יתכן משם שקברי שניהם נמצאים צמודים בזולקוא ואם כן ר אהרן היה נשוי לבת אחרת של הש\"ך). מחתניו: ר נחמן בן שמחה רפפורט, ר יצחק באבד מברודי וברעזן. בנו חורגו - הגביר ר שמשון."},{"i":12802,"n":"דוד לאה'קס מבאר","bt":"תמו","dt":"תקס - כא ניסן","b":"תלמיד הבעשט. רבה של באר. בזקנותו-מעל 70 נולדו לו שני בנים ובת. בנו ר מאיר הורודצקי. חתניו ר מרדכי מטשרנוביל, ר מאיר רוקח מלובלין. מתורתו ב\"משנת חסידים\"."},{"i":12803,"n":"דוד ליב מבריסק","f":"נמחיה מבריסק","dt":"תרטו - כח אלול","dp":"בריסק","b":"גביר מחכמי בריסק."},{"i":12804,"n":"דוד ליב מנאנאש","b":"רב בנאנאש--תק\"צ"},{"i":12805,"n":"דוד מאדרינופול","f":"אהרן","b":"רב באדרינופול-שנות ה-ש'."},{"i":12806,"n":"דוד מאוסטרהא","b":"ר' דוד מאוסטרהא. (חתנו - ר חיים לנדא מפודקמין - כך באוצר הרבנים - ואולי טעות)."},{"i":12807,"n":"דוד מאוסטרהא","f":"יעקב","dt":"תקו - כה אב","dp":"אוסטרהא","b":"מחכמי אוסטרהא. בנו ר יעקב מגבאי הח\"ק ורשם את בנו דוד לח\"ק-תקיד."},{"i":12808,"n":"דוד מאוסטרהא","f":"משה אב\"ד בוצאץ","dt":"תקלה - ז ניסן","dp":"אוסטרהא","b":"פרנס מחכמי אוסטרהא. אביו של ר אשר צבי קארצער."},{"i":12809,"n":"דוד מאוסטרהא","f":"יהודה ליב מפינסק ואו","k":"בעל אותות למועדים","dt":"תקל? - י אד\"ב","dp":"אוסטרהא","b":"אחיו של ר אשר ענזיל בעל \"ברוך מבנים אשר\". מתורתו בספר אחיו \"אותות למועדים\" וסייע לאחיו בכתיבת הספר."},{"i":12810,"n":"דוד מאוסטרהא","f":"חיים מחמעלניק","dt":"תקסב - ז חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא. חתם על כתב הרבנות לר מאיר חריף."},{"i":12811,"n":"דוד מאוסטרהא","f":"יצחק יעקב","b":"דיין באוסטרהא אצל ר חיים רפפורט בעל \"מים חיים\". הסכים על \"סדר עבודה ומורה דרך\" יחד עם ר חיים רפפרוט - סלאויטא תקצו."},{"i":12812,"n":"דוד מאוסטרהא","f":"אברהם","dt":"שעב - יב אב","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אולי בנו של ר אברהם בעל \"כור לזהב\"."},{"i":12813,"n":"דוד מאטיניא","b":"רב באטיניא. בנו ר חיים - בעל תפלה בברודי."},{"i":12814,"n":"דוד מאיטליה","f":"יהודה","k":"בעל פירוש על רות","b":"מחכמי איטליה. חיבר פירוש על רות ועל מורה נבוכים - מוזכר ב\"שורש ישי\"."},{"i":12815,"n":"דוד מאיליז","b":"רב באיליז"},{"i":12816,"n":"דוד מאיר","k":"הרד\"ם","b":"רב בסווירז-תר\"כ"},{"i":12817,"n":"דוד מאישפלאטו","f":"יצחק מפולין","b":"רב באישפלאטו-שנות ה-ת'-תק'."},{"i":12818,"n":"דוד מארץ ישראל","f":"מנחם מנדל","b":"נמנה על ראשוני העולים החסידים לארץ."},{"i":12819,"n":"דוד מאשכנז","f":"קלונימוס בן מאיר","b":"נכד ר מאיר ממינצברג. פייטן מגדולי הראשונים בחכמי אשכנז, חתם על התקנות-ד'תתקפ עם ר אלעזר בן יהודה בעל הרוקח, ועם ר ברוך בן שמואל בעל התרומות."},{"i":12820,"n":"דוד מבגדד","f":"מאיר","bt":"תקעז","bp":"בגדד","dt":"תרסו","dp":"ירושלים","b":"מחכמי בגדד וראש ישיבה, עלה לירושלים בתרסה."},{"i":12821,"n":"דוד מבוברקא","f":"חיים","b":"רב בבוברקא-תר\"י"},{"i":12822,"n":"דוד מבוקובסק","b":"רב בבוקובסק. מכתבו-תרם בראש דרישת הזאב (פוהורילס) לברודי."},{"i":12823,"n":"דוד מבילאבא","b":"תלמיד ר מנחם מנדל מקוצק."},{"i":12824,"n":"דוד מבינגן","b":"מחכמי אשכנז. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":12825,"n":"דוד מבירז","f":"חיים","k":"בעל שירה לדוד","b":"ספרא ודיינא בבירז-תקן בערך. חיבר \"שירה לדוד\" הורדנא תקנז. (לפי אלבום ליטא - רב בבירז על מקום ר שלמה זלמן זקש, ור משולם שרגא סגל-נפטר תריט על מקומו אחריו)."},{"i":12826,"n":"דוד מבנוביץ","b":"רב בבנוביץ-תקע\"ה"},{"i":12827,"n":"דוד מבעלי התוספות","b":"בשנת קעא (1411) עלה לארץ בשיירת שלש מאות בעלי התוספות."},{"i":12828,"n":"דוד מברוד","f":"מרדכי","k":"בעל יפה עינים","bt":"תק","dt":"תקעו","b":"מחכמי ברודי. חיבר \"יפה עינים\" למברג תקנט."},{"i":12829,"n":"דוד מבריסק","f":"משה יצחק","b":"פרנס בבריסק, חתם-תקיב עם כמה מחבריו על מכתב לר יונתן איבשיץ בענין הקמיעות. הסכים ב\"שערי בנימין\" על התרמה לבנין ביהכ\"נ של ה\"בית יוסף\" בניקופול."},{"i":12830,"n":"דוד מברעזי (פרג)","b":"רב בברעזי-תק\"י"},{"i":12831,"n":"דוד מגיד משדה לבן","b":"נכד ר אברהם פודולסק תלמיד הבעשט. תלמיד ר לוי יצחק מברדיטשוב, ור שניאור זלמן בעל התניא."},{"i":12832,"n":"דוד מדבשקוביץ","f":"משה מטערישוי","k":"בעל ארחות צדיקים","b":"העתיק ספר \"ארחות צדיקים\" בדאבשכוויץ(=דבשקוביץ)."},{"i":12833,"n":"דוד מדויד הורודוק","f":"זאב וולף מדויד הורוד","k":"אדמור מדויד הורודוק","dt":"תרכה"},{"i":12834,"n":"דוד מדומברובה וצפת","dt":"תקמו","dp":"צפת"},{"i":12835,"n":"דוד מהורדנא","f":"ראה: דניאל מהורדנא"},{"i":12836,"n":"דוד מהערפורט מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":12837,"n":"דוד מואשוואר","b":"רב בוואשוואר-ת\"ר"},{"i":12838,"n":"דוד מודילבוזיץ","b":"תלמיד ר מנחם מנדל מקוצק."},{"i":12839,"n":"דוד מוונגרוב","k":"אדמור מוונגרוב","b":"תלמיד ר שמואל מקאריב ואדמור על מקומו אחריו, נסע כאדמור אל ר שמחה בונם מפשיסחא. עבר מוונגרוב לפרגה."},{"i":12840,"n":"דוד מויזון","f":"שלמה","k":"יוסעלע וויאוזענער","dt":"תרח - כט אייר","b":"גביר מחכמי ויזון-ליטא, חובב ספר והקים ספריה גדולה (הראשונה בליטא) ואירח חכמים שבאו לשבת בביתו ולהשתמש בספריו."},{"i":12841,"n":"דוד מוילנא","f":"יהודה ליב","dt":"תקנח - ט אב","dp":"וילנא","b":"דיין בוילנא. הסכים על \"דרך המלך\"-תקנה."},{"i":12842,"n":"דוד מוילנא","f":"לוי","dt":"תקנג - יד אייר","dp":"וילנא","b":"מחכמי וילנא."},{"i":12843,"n":"דוד מוילנא","f":"יעקב","k":"דוד חייעש","dt":"תקעז","dp":"וילנא","b":"מחכמי וילנא. חבר בועד בראשות ר משה בן אברהם אשר - שנבחר אחרי פטירת הגר\"א כדי ללחום בחסידות."},{"i":12844,"n":"דוד מוילנא","f":"משה","b":"ראב\"ד בוילנא-תקנד."},{"i":12845,"n":"דוד מוילנא","f":"דב בער","dt":"תקעג - יד אד\"א","dp":"וילנא","b":"סו\"ד בוילנא."},{"i":12846,"n":"דוד מוילנא ופטרבורג","f":"אברהם אריה ליב מעתיק","bt":"תרכג","dt":"תרנו - כז תמוז","b":"למד משפטים בפטרבורג אצל הפורפ' גרזבסקי ולא קיבל משרת פרופ' בגלל יהדותו. היה עו\"ד ויהודי נאמן - והיה מתיעץ עם רבני וילנא בעניני חו\"מ להשוותם עם חוקי המדינה. חיבר מאמרים בכתבי עת ברוסית להגן על עם ישראל מפני מקטרגים."},{"i":12847,"n":"דוד מוירצבורג","b":"מגדולי בעלי התוספות,מרביץ תורה בוירצבורג-ד'תתק\"כ"},{"i":12848,"n":"דוד מזאמושט","f":"אריה יהודה ליב סירקי","b":"רב בזאמושט על מקום אביו. נכדו - ר זכריה מנדל מפודהייץ."},{"i":12849,"n":"דוד מזואניץ","b":"רב בזוואניץ"},{"i":12850,"n":"דוד מזולקוא","f":"דניאל","b":"חתם-תסה על תקנות קהלת זולקוא, חתם-תנא על בחירת ראשי הקהלה."},{"i":12851,"n":"דוד מזולקוא","f":"אליעזר ליפמן","b":"מחכמי זולקוא, חתם-תעו על תקנה שלא יהיה אחד מקרובי הרב בין מנהיגי הקהלה."},{"i":12852,"n":"דוד מז'וסלי","f":"יצחק מז'וסלי","dt":"תקצא-ד- כד תמוז","b":"רב בזסלי(=ז'וסלי) על מקום אביו כ-40 שנה, ובנו ר מנחם מנדל על מקומו אחריו כ-40 שנה."},{"i":12853,"n":"דוד מזעלין","b":"תלמיד ר אלימלך מליזנסק. מראשוני חסידי החוזה מלובלין."},{"i":12854,"n":"דוד מטבריה - א","f":"אהרן","b":"רב בטבריה-תק אצל ר חיים אבולעפיה, חיבר שיר ונדפס ב\"זמרת הארץ\"."},{"i":12855,"n":"דוד מטבריה - ב","f":"אהרן","b":"מראשי החסידים בטבריה, חתם בשנת תרו על אגרת שליחות ר משה יפה מחברון"},{"i":12856,"n":"דוד מטיסמניץ ולבוב","f":"אליעזר מטיסמניץ","b":"מראשי קהלת לבוב, חתם-תקל בפנקס הקהלה."},{"i":12857,"n":"דוד מטריקולה","f":"שבתי","b":"רב בטריקולה-שנות ה-ש'."},{"i":12858,"n":"דוד מטרני","b":"מגדולי חכמי ספרד-שנת ל\"ב"},{"i":12859,"n":"דוד מטשכנוב(=טשכנובצא)","dt":"תקעט - ז שבט","b":"רב בטשכנווצה. צדיק מפורסם בדורו, והחוזה מלובלין היה ממעריציו."},{"i":12860,"n":"דוד מטשנסטחוב","k":"בעל בית דוד","b":"רב בטשנסטחוב, פיעטריקוב-תרס."},{"i":12861,"n":"דוד מיאנוב ואוסטרהא","f":"יהודה ליב","dt":"תקלא - ד סיון","dp":"אוסטרהא"},{"i":12862,"n":"דוד מיאנובה","k":"בעל רזוהי גליין","b":"רב ביאנובה-תק\"ל"},{"i":12863,"n":"דוד מיגולניצה","f":"נתן מרוזוודוב","k":"בעל ברכת דוד","r":"שלחן ערוך מהדורת מכון ירושלם בתחילתו","dt":"תקנא - ח חשון","b":"רב ביגולניצה ואולשקוביץ. חיבר \"ברכת דוד\" זולקוא תקכו.","bk":[["ברכת דוד",""]]},{"i":12864,"n":"דוד מירושלים","f":"זכריה","b":"חתם בשנת שח על התקנה לשחרר תלמיד חכמים ממס."},{"i":12865,"n":"דוד מירושלים","f":"ישועה","b":"מחכמי ירושלים בשנים רן-ש, מבני ישיבתו של הנגיד ר יצחק שולל."},{"i":12866,"n":"דוד מירושלים","f":"אברהם","k":"בעל מחזה שדי","dt":"תרה - כז תשרי","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":12867,"n":"דוד מירושלים","f":"אליעזר יצחק","b":"מחכמי האשכנזים בירושלים, חתם בשנת תקי על אגרת שליחות ר מרדכי פתחיה קצנלבויגן."},{"i":12868,"n":"דוד מירושלים","f":"דוב בר","b":"מחכמי האשכנזים בירושלים, בשנת תקי חתם על כתב שליחות ר מרדכי פתחיה אשכנזי."},{"i":12869,"n":"דוד מירושלים","f":"עוזר מאויבן הי\"ד","b":"מחכמי ירושלים בשנת תס, בין החותמים נגד אנשי חבורת ר יהודה החסיד שנתפסו לשבתאות, חותם: \"דוד ב\"ר עוזר הי\"ד מאובן\""},{"i":12870,"n":"דוד מלאצקי ושטמפן","b":"מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן."},{"i":12871,"n":"דוד מלבוב","b":"דיין בלבוב-תמ\"ז"},{"i":12872,"n":"דוד מלבוב","f":"דניאל","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":12873,"n":"דוד מלבוב","f":"יצחק נחמיש","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":12874,"n":"דוד מלבוב","f":"אפרים","b":"מחכמי לבוב. חתם-תסא על תקנת קהלת זולקוא."},{"i":12875,"n":"דוד מלבוב","f":"מרדכי","b":"דיין בלבוב-תח בערך, חתם עם בעל \"ווי העמודים\", ר יהודה ליב בן ישראל מקראקא, ונזכר בספר \"איתן האזרחי\". ראה גם: ר דוד סגל אשכנזי מפוזנא."},{"i":12876,"n":"דוד מלבוב","f":"חיים","b":"דיין בלבוב, חתם-תמז על שטרות."},{"i":12877,"n":"דוד מלבוב","f":"יוסף","b":"דיין בלבוב, חתם-תקלד עם ר אריה ליב רפפורט."},{"i":12878,"n":"דוד מלובין וצפת","f":"יוסף","dt":"תרנב - ז טבת","b":"נכד ר משה שמואל מלובער. תלמיד ר שמואל השני מקמינקא, ור ישראל מרוזין. עלה לצפת-תרה והיה ממנהיגי קהילת החסידים שם. בנו היחיד ר יוסף נפטר בחייו."},{"i":12879,"n":"דוד מלובלין","f":"ברוך סגל","b":"מחכמי לובלין. חתם בכת\"י על הדף הלבן ב\"זכרון משה\" לובלין שעא - נמצא באוסף אופנהיים באוכספורד."},{"i":12880,"n":"דוד מלובלין","f":"יהודה","k":"בעל פירוש לתרגום אסת","b":"חיבר פירוש על תרגום אסתר - קראקא תד."},{"i":12881,"n":"דוד מלובלין","dt":"תסד - אדר","dp":"לובלין","b":"מחכמי לובלין. נהרג עק\"ה."},{"i":12882,"n":"דוד מלובלין","f":"משה","dt":"תקלו - אחרי","b":"חתם על כתב החרם של ר יעקב חיים מלובלין על היוצאים כנגד ר יהונתן איבשיץ-תקיא. הניח צוואה לבניו בכת\"י - ותרם הרבה לצדקה."},{"i":12883,"n":"דוד מלומאז'","dt":"תרסו - ה סיון","b":"חסיד קוצק וגור."},{"i":12884,"n":"דוד מליפאנטו ולאריסה","f":"שמואל ליאון","b":"מחכמי ליפאנטו - שנות ה-ש', רב בלאריסה."},{"i":12885,"n":"דוד מלעשנוב","b":"רב בלעשנוב-תקפ\"א,עבר לברודי"},{"i":12886,"n":"דוד ממאניסטריזץ","f":"מהר\"י סגל אשכנזי","b":"שאלה ממנו-תח אל ר מאיר בן אברהם ז\"ק ור יוסף בן אליקים געץ ונזכר ב\"איתן האזרחי\"."},{"i":12887,"n":"דוד ממארטש","bp":"קרוז'","b":"רב במארטש."},{"i":12888,"n":"דוד ממודנא","f":"אברהם","k":"בעל דבר טוב","b":"מחכמי מודנא-שנות ה-ש'. חיבר \"דבר טוב\" והוא באור שרשי לשון הקדש בתרגום איטלקי - ונציה שנו."},{"i":12889,"n":"דוד ממיטפאליר","b":"דיין במיטפאליר אצל ר שלמה."},{"i":12890,"n":"דוד ממינסק","f":"חיים מוילנא","dt":"תקיב - ו ניסן","dp":"מינסק","b":"רב במינסק. אביו היה סו\"ד בקהלת וילנא."},{"i":12891,"n":"דוד ממינצבורג","b":"מגדולי בעלי התוספות,פוסק,פייטן,רב במינצבורג-ד'תתק\"פ"},{"i":12892,"n":"דוד ממיקולייב","b":"רב במיקולייב-שנת תק\"ל"},{"i":12893,"n":"דוד ממיקולייב - א","dt":"תקס - כה שבט","b":"תלמיד הבעשט, והיה בעל תפלה של מוסף יוה\"כ אצל הבעשט, ואחר פטירתו נסע אל ר פנחס מקוריץ. מתורתו ב\"משנת חסידים\", נזכר ב\"יושר דברי אמת\" לר משולם פיבש מזבאריז. בנו ר יוסף."},{"i":12894,"n":"דוד ממיקולייב - ב","dt":"תקכ - לפני","b":"תלמיד הבעשט. חברו של ר דוד ממיקולייב בעל התפלה אצל הבעשט. נפטר בחיי הבעשט."},{"i":12895,"n":"דוד ממיר - א","b":"רב במיר-תק\"ס"},{"i":12896,"n":"דוד ממיר - ב","dt":"תכו - כח טבת","b":"רב במיר"},{"i":12897,"n":"דוד ממצרים","f":"דניאל","bt":"ד'תתיז (1057)","bp":"ארץ ישראל","b":"ראש הגולה במצרים-ה'מח, חיבר פיוטים (נתפרסמו בחורב כרך ו-ח), בעל מחלוקת עם ר אביתר הכהן. פסק דין ממנו משנת תתמה בפוסטאט, (מאן בספרו ח\"א). החרים בבית דינו את ר שלמה פטיט שיצא כנגד \"מורה נבוכים\"."},{"i":12898,"n":"דוד ממצרים","f":"שלמה","b":"מחכמי מצרים דיין בבית דינו של ר' אברהם בן הרמב\"ם"},{"i":12899,"n":"דוד מנאשלסק","b":"תלמיד ר מנחם מנדל מקוצק."},{"i":12900,"n":"דוד מנוח מירושלים","f":"ישועה","b":"מחכמי ירושלים-רע."},{"i":12901,"n":"דוד מסופיה","f":"אהרן","b":"דיין בסופיה-תקיט עם ר יעקב טיבה."},{"i":12902,"n":"דוד מסטניסלב וירושלים","dt":"תרז - כו שבט","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":12903,"n":"דוד מסעגעד","f":"ישכר דב","b":"דיין בסעגעד-תרמד אצל ר אברהם חיים לעף."},{"i":12904,"n":"דוד מסעלץ ובריסק","f":"בצלאל","b":"מחכמי סעלץ, ר\"מ בבריסק-תרך. המליץ לקבל את הגדול ממינסק לרב בסעלץ."},{"i":12905,"n":"דוד מספרד","f":"סעדיה","k":"בעל משפטי שבועות","b":"מגדולי חכמי ספרד הקדמונים-ד'תת. חיבר \"משפטי שבועות\"(בערבית)"},{"i":12906,"n":"דוד מספרד","f":"יהודה החסיד","k":"בעל לבנת הספיר","b":"מקובל, נכד הרמב\"ן, חיבר \"לבנת הספיר\" ובו דרשות על התורה. ?? לא באוצר ??"},{"i":12907,"n":"דוד מספרד","f":"שיעור","b":"מחכמי ספרד, נשא ונתן עם הריב\"ש"},{"i":12908,"n":"דוד מסקלט","b":"רב בסקלט. תשובה אליו - טוט\"ד."},{"i":12909,"n":"דוד מפאס","k":"ר' דוד החרש","b":"מחכמי פאס, הגיע לא\"י, פגש ברס\"ג, וחזרו לאפריקה עם פירוש הרס\"ג ל\"ספר יצירה\""},{"i":12910,"n":"דוד מפאפילסון","b":"רב בפאפילסון-ת\"ר"},{"i":12911,"n":"דוד מפולדא","f":"יצחק","k":"בעל אמת המשפט","b":"מחכמי פולדא-שנה. חיבר \"אמת המשפט\" על האשר\"י (הרא\"ש?) ובו 3 חלקים: \"אבן הראשה\", \"תהום רבה\", \"מפתח בית דוד\"."},{"i":12912,"n":"דוד מפולין וארץ ישראל","f":"אברהם בלאמיש","b":"תלמיד המהרש\"ל. עלה לארץ והיה לסופר סת\"ם. נזכר בשו\"ת מהרש\"ל בענין תפילין."},{"i":12913,"n":"דוד מפרג","f":"יהודה","k":"בעל מגדל דוד","b":"מגדולי התורה ברוסיה-פולין. חיבר \"מגדל דוד\" - פרג שעו - לישב השגות הלבוש על הרמ\"א."},{"i":12914,"n":"דוד מפרובנס","f":"לוי","k":"בעל מכתם","b":"מחכמי פרובאנס-שנת ס', עלה לארץ. חיבר \"מכתם\" ונזכר ב\"בית יוסף\"."},{"i":12915,"n":"דוד מפרמישלן","f":"מנחם מנדל מפרמישלן","b":"עלה עם אביו לטבריה-תקכד."},{"i":12916,"n":"דוד מפרשבורג","f":"צבי הירש","b":"מחכמי פרשבורג, חתם-תקסז על כתב מנוי רבנות לחת\"ס."},{"i":12917,"n":"דוד מקאלוש","f":"מאיר מפרמישלן","k":"אדמור מקאלוש","b":"אדמור בקאלוש, ואחיינו ר יצחק בן אהרן אריה על מקומו אחריו."},{"i":12918,"n":"דוד מקאמאי ווילנא","f":"אברהם","b":"אב\"ד קאמיי(=קאמאי)-תקמה, דרשן בוילנא-תקנז. חתם על מנוי ש\"ץ-תקסב. הסכים על \"דרך המלך\"-תקנה."},{"i":12919,"n":"דוד מקארוב פרגה","f":"שמואל מקארוב","k":"אדמור מקארוב בפרגה","dp":"וארשא","b":"תלמיד החוזה מלובלין. אדמור בפרגה-וארשא לאחר פטירת אביו. נסע אל ר אורי מסטרליסק, ור שמחה בונם מפשיחסא."},{"i":12920,"n":"דוד מק\"ב מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":12921,"n":"דוד מקוברין","b":"תלמיד ר אשר מסטולין. מנהיג קהילת החסידים בקוברין, ואף ר משה מקוברין הלך לשלחנו לפני שנתפרסם."},{"i":12922,"n":"דוד מקולומיא","f":"שלמה","dt":"תצב - טז שבט","b":"רב מגיד בקולומיא. תלמיד הבעשט, נחשב לראשון שהכיר בגדלותו, ונפטר לפני שהבעשט החל להנהיג עדת חסידים."},{"i":12923,"n":"דוד מקוריסטשוב","b":"תלמיד הבעשט. אב\"ד קוריסטשוב, פעל יחד עם ר צבי המגיד מישרים לביטול גזירה בזמן מגפת החולירע בקוריסטשוב."},{"i":12924,"n":"דוד מקושטא","f":"מאטאלון","b":"חכם שלם, דיין בקושטא-תקכ\"ה"},{"i":12925,"n":"דוד מקושטא","f":"משלם","b":"רב בקושטא-ש'."},{"i":12926,"n":"דוד מקושטא","f":"יצחק","b":"רב בקושטא-שנות ה-תק, הו\"ל ספר אביו - \"דברי אמת\" עם הקדמה ממנו."},{"i":12927,"n":"דוד מקנישין","b":"רב בקנישין-תר\"ע"},{"i":12928,"n":"דוד מקסטוריאה","f":"אליעזר","b":"מחכמי קאסטוריאה-טורקיה - שנות ה-ר'. חיבר פיוטים ומהם במחזור קושטא."},{"i":12929,"n":"דוד מקרטינגה ושירווינט","b":"מגיד בשירווינט והתפרסם ברחבי ליטא."},{"i":12930,"n":"דוד מקריפטש","b":"רב בקריפטש"},{"i":12931,"n":"דוד מקרלסבורג","f":"בנימין","b":"פרנס בקרלסבורג-תק בערך."},{"i":12932,"n":"דוד מראסיין","b":"רב בראסיין-תקפ\"ה"},{"i":12933,"n":"דוד מרוזדול","dt":"תקפא - ד ניסן","b":"רב בראזדאל"},{"i":12934,"n":"דוד מרוזינאי","b":"מגיד ברוזינאי-ת\"ס"},{"i":12935,"n":"דוד משאריגורד","b":"תלמיד הבעשט."},{"i":12936,"n":"דוד משברשין","k":"בעל פירוש על ת\"י","b":"רב בשברשין-ש\"ס"},{"i":12937,"n":"דוד משה מקאבאלה","b":"רב בקאבאלה-שנות ה-ש'."},{"i":12938,"n":"דוד משה שמשון משלוניקי","b":"דיין בשלוניקי-שנג."},{"i":12939,"n":"דוד משירווינט","b":"מקובל, אב\"ד שירווינט, ובנו ר מנחם נחום חריף על מקומו אחריו."},{"i":12940,"n":"דוד משלוניקי","f":"יוסף דוד - מהרי\"ד","dt":"תעט","dp":"שלוניקי","b":"דיין בשלוניקי. נפטר צעיר."},{"i":12941,"n":"דוד משלוניקי","f":"אליה בן דוד","b":"מדפיס בשלוניקי אצל אברהם בן דוד נחמן ויום טוב קאנפיליאש-תס."},{"i":12942,"n":"דוד משלוניקי","f":"וידאל נחמן","b":"מדפיס בשלוניקי-תקיז אצל מרדכי נחמן ורפאל קלעי."},{"i":12943,"n":"דוד משערשוב","f":"יעקב","k":"בעל חומות ירושלים","bt":"[תק..]","b":"מגדולי דורו-תקס, רב בשארשוב-ליטא. מתלמידיו - ר זאב וולף מפרוזין וסלונים. הגיע אל הגר\"א לשאול אותו בקשר לראש חדש. מתלמידיו - ר יוסף משארשוב-בנו של ר חיים מוולוזין (שפנה לחסידות)."},{"i":12944,"n":"דוד ן, יוסף מאלגיר","bt":"קך - בערך","dt":"קץ - בערך","b":"בן למשפחה מיוחסת. דיין בקצמטינא. נזכר בתשב\"ץ שהיה מקהל התושבים (הקהלה הותיקה שלא מספרד)."},{"i":12945,"n":"דוד ן, ראובן ממרוקו","f":"שמעון","k":"בעל עוז והדר","dt":"תשלה - ז סיון","b":"מחכמי מרוקו. נכד ר סעדיה ן דוד. גדל בביתו של הבבא סאלי ולמד עם בנו ר מאיר. רב בבנחמד, קזבלנקה ולימד שם עם ר רפאל עבו ב\"אוצר התורה\". עלה לארץ-תשטז והתישב באשקלון. חיבר גם \"גלי רזיא\", \"קול מבשר\", \"נפש טוב\"."},{"i":12946,"n":"דוד נאשקין מוילנא","b":"ממיסדי ותומכי ישיבת מייליס בוילנא."},{"i":12947,"n":"דוד נחמן מירושלים","b":"מחכמי ירושלים-תקעד."},{"i":12948,"n":"דוד נחמן משלוניקי וקושטא","b":"מדפיס בשלוניקי, עבר לקושטא-תקב לדפוס של בנימין בן משה רוסו."},{"i":12949,"n":"דוד נתן מאלקוש","dt":"תשג","b":"רב באלקוש"},{"i":12950,"n":"דוד נתנאל רופא מטבריה","f":"יחזקאל שאול","bp":"טבריה","dt":"תרסג","dp":"תונס","b":"מחכמי טבריה, בשנת תרל בשליחות במרוקו, ר אברהם אנקאווה נתן לו במתנה את ספרו \"כרם חמר\" עם הקדשה. בשנת תרלא בשליחות באלגיר ותונס, בשנת תרלב ללקומצנטינא והיה שם אחד משבעה טובי העיר, נפטר בהיותו בשליחות בתונס"},{"i":12951,"n":"דוד סגל הלוי מצפת","b":"מחכמי צפת. בשנת תטו בשליחות יחד עם ר יום טוב צהלון באירופה, בניהו פרסם כמה מכתבים אליהם (\"ארץ ישראל\" ספר ג), כנראה כבר בשנת תט בשליחות. לדעת בניהו ר דוד הוא שהיה בקהילת בודון ונזכר בתשובותיו של ר דניאל אישטרוקשה מחכמי שלוניקי ויתכן שבדרכו לשליחות באיטליה התגורר בתורכיה."},{"i":12952,"n":"דוד סופר מאניפולי","b":"תלמיד המגיד ממזריטש וסופרו, אחיו של ר לייב מסינאווי-תלמיד הבעשט."},{"i":12953,"n":"דוד פורקעס ממזבוז","f":"ישראל מאיר","dt":"תקלב - י אב","dp":"עיר חדש","b":"תלמיד הבעשט, והוא זה שקירב את ר אהרן הגדול מקרלין לחסידות. רב במזבוז,"},{"i":12954,"n":"דוד צבי הלוי מקראקא","b":"ראב\"ד בקרקא-תק\"ס"},{"i":12955,"n":"דוד צבי מזשלנידורף","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":12956,"n":"דוד צבי מפמורן","b":"רב בפמובן. תשובה אליו - \"ובחרת בחיים\"."},{"i":12957,"n":"דוד קאנטשינרו מטורנא","f":"אליהו מנדל","b":"מחכמי טורנא, לימד לעתים בישיבת ר אליעזר אב\"ד אמשטרדם בהיותו בטורנא. בניו: ר אלכסנדר זיסקינד בעל \"מצנפת בד\", ר מרדכי מטורנא."},{"i":12958,"n":"דוד קויפמן מצעהלים","b":"רב בצעהלים-תצו ור אהרן ליב המבורגר על מקומו אחריו-תקיא."},{"i":12959,"n":"דוד ראובן מאנקונא","dt":"שיו - ז תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":12960,"n":"דוד שאול (גולדברג) מרזפניק","b":"רב ברזפניק-תרלד."},{"i":12961,"n":"דוד שאלתיאל מבודפשט","b":"גביר מחכמי בודפשט, סייע בידי ר יהודה ן סיד בעל \"נר מצוה\"."},{"i":12962,"n":"דוד שבח מאוסטרהא","f":"ישראל אברהם","b":"דיין באוסטרהא אצל ר אברהם משלם זלמן אשכנזי. חתם על צוואת הגביר ר יוסף יוזפא אוסטרר עם ר אריה יהודה ליב בן שמואל."},{"i":12963,"n":"דוד שבתי משלוניקי","dt":"תנג","dp":"שלוניקי","b":"מחכמי שלוניקי. אביו של ר יוסף דוד משלוניקי."},{"i":12964,"n":"דוד שולם הרופא משלוניקי","b":"רופא בשלוניקי-שנות ה-ש'."},{"i":12965,"n":"דוד שלמה מטולטשין","f":"שמואל מברוד","k":"בעל התעוררות התפילה","dt":"תר - יח ניסן","b":"רב בטולטשין. תלמיד ר ברוך ממזבוז, ר שלום שכנא מפרוהובישט. חיבר גם \"מגדל דוד\"."},{"i":12966,"n":"דוד שלמה מלבוב","f":"בירך","k":"בעל דרך טוב","bt":"תק","dt":"תקע","b":"בא מבריסק ללמברג, חתן ר מרדכי זאב אב\"ד למברג. חיבר \"דרך טוב\" למברג תקסט."},{"i":12967,"n":"דוד שלמה מסורוקא","b":"עלה לארץ בשיירת תקלז או סמוך לכך."},{"i":12968,"n":"דוד שמואל שמלקא (שידלוב) מקראק","f":"יהודה ליב מראקוב וקר","dt":"תקא-יא - ה אב","dp":"קראקא","b":"רב בחמלניק-תפט, קראקא-תצב על מקום אביו, רב בזאלוזשיץ. הסכים על \"גאון צבי\"-תצג. חתם על החרם-תצה נגד הרמח\"ל יחד עם אחיו ר יצחק איזיק מטרנוב. בנו - ר יעקב משה מנחם מנדל. (בחכמי קראקא תאריך פטירתו - תקא)."},{"i":12969,"n":"דוד שמערל'ס מבריסק","b":"גביר בבריסק-שכז."},{"i":12970,"n":"דוד שמריהו משלוניקי","f":"אברהם שמריה","k":"בעל תורת אמת","dt":"של?","b":"מקובל, רב בשלוניקי, חיבר \"תורת אמת\" על הזוהר - שלוניקי שסד."},{"i":12971,"n":"דוד שניאור","bp":"איטליה","b":"עלה מאיטליה לארץ ישראל, היה פרנס ירושלי בזמן פרעות אבן פארוך בשנת שפה."},{"i":12972,"n":"דוד, חנן משלוניקי","k":"בעל בני יצחק","b":"רב בשלוניקי. מתורתו בספר \"בני יצחק\" על התורה לר יצחק חנן."},{"i":12973,"n":"דוד, יחזקאל","f":"מועלם","bt":"תריא","b":"רב ראשי בבצרה-תרסה."},{"i":12974,"n":"דוד, ישראל מלימנוב","k":"ישראל רבי","b":"בא מרדומשיל לכהן כרב בלימנוב-תרנג, רב ברזחיב, זאכוב-גליציה. חיבר \"תורה ומצות\" ברטפלד תרסז."},{"i":12975,"n":"דוד, מנחם מנדל מטלומטש","b":"רב בטלומטש-תרך, ליסיעץ-תרכט, סלטוינה-תרנט."},{"i":12976,"n":"דוד, שבתי משלוניקי","dt":"תעד","b":"דיין בשלוניקי. אחיו של ר יוסף דוד בעל \"בית דוד\"."},{"i":12977,"n":"דודאי גאון פומפדיתא","b":"ראש ישיבת פומבדיתא-ד' תקכ\"א-תקכ\"ד, אחיו של ר' יהודאי גאון(בימיו של ענן הקראי)"},{"i":12978,"n":"דודוביץ (בן דוד), יהודה ליב","k":"תרגם החנוך - תרנד","bt":"1855","bp":"וילנא","dt":"1898","dp":"אודסה","b":"רופא צבאי, סוציאליסט בוילנא, עבר לתנועה הלאומית, ב-1876 לחם לצד הסרבים בסלאבופיל. פרסם מאמרים בעניני חנוך ב\"המליץ\", \"היום\", \"השלוח\", ועוד. תרגם לעברית ספר \"החנוך\" - אדוארד ספנסר - וארשא תרנד. יסד באודסה חברת \"שפה ברורה\" והיה מהראשונים-1890 שהנהיג את העברית כשפת דיבור יום יומית."},{"i":12979,"n":"דודי, אליהו מירושלים","b":"מחכמי ישיבת \"כנסת ישראל\" בירושלים-תקיח."},{"i":12980,"n":"דודידוביץ, יצחק זאב משאוול","dt":"תשג","b":"רב בשאוועל"},{"i":12981,"n":"דודינגא, משה משלוניקי","f":"אברהם","dt":"רצא - ד חשון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":12982,"n":"דודמן, דוד נחמן מפושויטין","dt":"תש..","b":"רבה האחרון של פושויטין. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":12983,"n":"דודסון ישראל","bt":"1870","dt":"ה'תרצט 1939","bk":[["שלוש הלצות עם הערות",""]]},{"i":12984,"n":"דוהאן, חיים יואל מהאלאש","f":"מאיר צבי","bt":"תרמא","bp":"גרוסורדין","dt":"תשלג - ג כסלו","dp":"ירושלים","b":"נכד ר קופל חריף מוורבוי. תלמיד ישיבת ר משה הרש פוקס בגרוסורדין. רב בבראשוב ותרם מכספו לבנית מוסדות ציבור לקהלה. רב בהאלאש-תרעד, ניצל מהשואה ואחריה חזר להאלאש וניסה לשקם את הקהלה. עלה לירושלים ונמנה על חכמי \"אוצר הפוסקים\", והיה רב בביהכ\"נ \"הריס\" ברחביה."},{"i":12985,"n":"דוהאן, מאיר צבי מגורסורדין","f":"אברהם מעיר חדש","bt":"תרו","dt":"תרסו - כט כסלו","dp":"גרוסורדין","b":"יתכן שר אברהם מעיר חדש הוא זקנו ולא אביו. תלמיד הכת\"ס. חתן ר יעקב קופל חריף אלטנקונשטט מוערבע. מחכמי גרוסורדין. בנו ר חיים יואל אב\"ד האלאש ועלה לירושלים."},{"i":12986,"n":"דוהאני, יוסף מהאלאש","b":"רב בקרונשטט,האלאש-תרע\"ד,עלה לירושלים-תש\"ז."},{"i":12987,"n":"דווארעצקי, אריה מיכל מזטיל","b":"מתורתו ב\"מאסף דרושי\" - וילנא תרסט."},{"i":12988,"n":"דוויק - משפחה","b":"משפחה מארם צובא."},{"i":12989,"n":"דוויק, אבטליון מקושטא וצפת","f":"מרדכי","k":"בעל חדשים לבקרים","bt":"של","bp":"קושטא","dp":"אדרינופול","b":"מחכמי קושטא, עלה לצפת ולמד שירה אצל ר ישראל נג'ארה, שיריו נדפסו בספר \"שירי ישראל בארץ הקדם\" ו\"נעים זמירות\"."},{"i":12990,"n":"דוויק, אברהם הכהן","k":"כלוצי","dt":"תרסא - יב תמוז","b":"רב באנטוכיה, דיין, חכם באשי בארם צובא"},{"i":12991,"n":"דוויק, אברהם יצחק הכהן מחלב","b":"תרגם \"שבט מוסר\" לעברית - נדפס בירושלים תרפה."},{"i":12992,"n":"דוויק, אליהו הכהן מחלב","k":"בעל ברכת אליהו","b":"רב בחלב-תקסג עלה לירושלים, רב בירושלים, חיבר ספר \"ברכת אליהו\" ליוורנו תקנג, חתום עם רבני ארם צובא. מוזכר בספר \"מחנה יהודה\" לר יהודה קצין. אחיו - ר שמעון בעל \"ריח שדה\"."},{"i":12993,"n":"דוויק, אליהו הכהן מירושלים","f":"שאול","dt":"תשט","b":"מרביץ תורה בישיבת \"פורת יוסף\", ראש ישיבת \"רחובות הנהר\" על מקום אביו."},{"i":12994,"n":"דוויק, אפרים הכהן מחלב","b":"רב בארם צובה-תר\"כ"},{"i":12995,"n":"דוויק, גבריאל אברהם הכהן","bt":"תקסו","bp":"טבריה","dp":"צפת","b":"מחכמי טבריה, בשנת תקצג בשליחות טבריה, בתקצו הסכים בעיר ווצירא במרוקו על ספר \"מאור ושמש\" לר יהודה קוריאט, בשנת תריז חתם בטבריה על אגרת לחכמי אזמיר, חתימתו אינה כוללת את השם גבריאל (כנראה נוסף לו עקב מחלה), מוזכר בספר \"משא חיים\" לר חיים פאלג'י, וב\"ילקוט יוסף\" לר יוסף ילוז."},{"i":12996,"n":"דוויק, חיים הכהן מצפת או טבריה","b":"חתם-תקצא על כתב שליחות ר יהודה נחמד מטעם קהלת טבריה, עם ר אלעזן ן דנאן, ר שמואל בכר אלקלעי, ר משה שמחון, ועוד."},{"i":12997,"n":"דוויק, חיים רפאל אברהם הכהן","dt":"תקלו","dp":"מירון","b":"מחכמי צפת, ישב בפקיעין, שליח טבריה לאפריקה הצפונית לפני תקך, עבר בתונס ופגש את ר מרדכי ברוך קאראבליו בעל \"תועפות ראם\", לאחר מכן שליח בארצות ערב עבר בקהילת בויסנג'אק (כורדיסטן), ולאחר מכן בתורכיה ובשנת תקלד פגש בבלגרד את ר דוד פארדו."},{"i":12998,"n":"דוויק, חיים שאול מחלב - השד\"ה","f":"אליהו","k":"בעל איפה שלמה","bt":"תריח (בא' תרכב)","bp":"ארם צובא","dt":"תרצג - ד טבת","dp":"ירושלים","b":"מקובל מחכמי חלב, רב בדמשק, תלמיד ר אליהו משען בעל \"שפת אמת\", ר נסים הררי רפול בעל \"הרי נהר\", ר עוזיאל טוויל ור מרדכי עבאדי בעל \"מעין חיים\". עלה לירושלים-תרן עם קבוצת מקובלים, וביניהם ר יום טוב ידיד ור עזרא רפול והצטרפו לישיבת \"בית אל\". לאחר שהתעוור המשיך בלימודיו והנהגותיו. מבני חבורתו היו ר מנחם מנכין היילפרין, ר שלמה אלישיב בעל \"לשם שבו ואחלמה\", בשנת תרנו הקים הגביר ר נסים נחום את ישיבת \"רחובות הנהר\" בשכונת הבוכרים ור חיים שאול עבר לשם ועמד בראש הישיבה, ובנו ר אליהו על מקומו אחריו. היה מקורב לר' שלמה אליעזר אלפאנדרי, רבים וגדולים באו אליו להתברך וכדי שיתפלל עליהם. חיבר ספרים בקבלה \"איפה שלמה\" ירושלים תרב רסז, \"אמת וארץ\" ירושלים תרע, ועוד."},{"i":12999,"n":"דוויק, יהודה הכהן","f":"אברהם","dt":"תרפח - כז ניסן","dp":"ירושלים","b":"מחכמי חלב,מקובל,תלמיד ר' אברהם עדס,מדקדק,עלה לירושלים,חיבר חידושים על הש\"ס וספר על הלכות סת\"ם"},{"i":13000,"n":"דוויק, יהודה הכהן מחלב","f":"אפרים מחלב","bt":"תרכ","b":"נסמך מאת: ר מנשה סתהון, ר משה סוויד, ר משה הכהן. רב בארם צובה-תרע."},{"i":13001,"n":"דוויק, יוסף","dt":"תרמג","b":"מרבני ארם צובה"},{"i":13002,"n":"דוויק, יעקב שאול הכהן","k":"בעל דרך אמונה","dt":"תרעט - ב סיון","b":"רב בארם צובה"},{"i":13003,"n":"דוויק, יצחק הכהן","b":"מגדולי רבני טבריה-תרמ\"ח"},{"i":13004,"n":"דוויק, מאיר הכהן מדמשק","dt":"תקצח - ח חשון","dp":"דמשק","b":"רב בדמשק, חתם-תקצא על ביצוע גביית כתובה בשם רבני צפת יחד עם ר דוד הכהן מדמשק."},{"i":13005,"n":"דוויק, מנחם הכהן מטבריה","b":"מגדולי רבני טבריה-תרמ\"ח"},{"i":13006,"n":"דוויק, משה","dt":"תרלה - יז אב","b":"רב בארם צובה"},{"i":13007,"n":"דוויק, משה הכהן מחלב","dt":"תקפ - ח טבת","dp":"חלב","b":"דיין בחלב עם ר דוד שלמה סתהון ור אליהו שמאע. תשובה ממנו ב\"ויקרא יצחק\"."},{"i":13008,"n":"דוויק, משה הכהן מחלב","f":"אליהו","k":"בעל אדר היקר","b":"נכד המקובל ר חיים שאול דווייק. רב בחלב - המאה ה-20. ?? לא באוצר ??"},{"i":13009,"n":"דוויק, משה הכהן מחלב (קצאב)","k":"בעל קנה המדה","dt":"תשו - יח כסלו","dp":"ניו יורק","b":"רב בחלב. חתן ר יעקב שאול דווייק. עבר לניו יורק וכיהן שם כרב. חיבר גם \"בן דוד\". ?? לא באוצר - קנה המדה ??"},{"i":13010,"n":"דוויק, שאול הכהן מחלב","f":"עזרא","k":"בעל אמת מאר\"ץ","dt":"תרלד - ד שבט","b":"אחיו של ר אברהם עזרא דוויך הכהן החכם באשי בחלב. תלמיד ר אברהם ענתבי. רב בחלב על מקום ר חיים מרדכי לבטון-תרכט. חיבר חיבורים על הש\"ס, שו\"ע ושו\"ת ועוד. נכדו ר חיים שאול הו\"ל את ספרו \"אמת מארץ\"."},{"i":13011,"n":"דוויק, שאול הכהן מחלב וברזיל","f":"אברהם (כ'אלוצי)","k":"בעל המזכה לחיי אבא","b":"מחכמי חלב, עבר לברזיל - בתחילת המאה ה-20. ?? לא באוצר ??"},{"i":13012,"n":"דוויק, שמואל הכהן מחלב","f":"משה","k":"בעל משפטים ישרים","dt":"תרכח - ג טבת","dp":"חלב","b":"דיין בחלב. חיבר גם \"תנובת השדה\". ?? לא באוצר ??"},{"i":13013,"n":"דוויק, שמעון הכהן מחלב","k":"בעל ריח שדה","b":"מחכמי חלב-תסח, היה במחלוקת עם ר שמואל לניאדו - רבה של חלב (שהיה קרובו). אחיו - ר אליהו בעל \"ברכת אליהו\"."},{"i":13014,"n":"דוחאן, יעקב ישראל - השבתאי","b":"מנביאי ש\"ץ."},{"i":13015,"n":"דוחמאן, יוסף גדליה מקארמא","f":"שניאור זלמן מקארמא","bt":"תרטז","b":"חתן ר יואל חייקין מפדבוברנקע-פלך מוהילוב. רב בקארמא-פלך מוהילוב-תרס לצד אביו, ועל מקומו אחריו-תרע. גיסו של ר יהושע חיים באסאיו מגרייוא-קורלנד."},{"i":13016,"n":"דוחמאן, שניאור זלמן מקארמה","dt":"תרע - בערך","b":"חסיד ליובאויטש. אב\"ד קארמה, ובנו ר יוסף גדליה על מקומו אחריו."},{"i":13017,"n":"דוידבסקי, יוסף צבי מנוברדוק","k":"בעל אמרי יוסף","b":"ר\"מ בנוברדוק,רב בטשרנוביץ"},{"i":13018,"n":"דוידוביץ, אליהו ממארמארוש","f":"דוד","k":"בעל שם אליהו-תשלא","dt":"תשכה","dp":"ארה\"ב","b":"שו\"ב בכפר אונטר-רינה-מארמרוש. ניצל מהשואה ואחריה היגר לארה\"ב, והתישב בקליבלנד."},{"i":13019,"n":"דוידוביץ, אליעזר ממיהאלביץ","dt":"תשד","b":"תלמיד בעל \"ערוגות הבושם\". חתן הרב מסובראנץ. רב במיהאלביץ, אב\"ד גליל ויננא - וכונה \"דער סטראניאנר דיין\", נחשב לדיין מומחה והוזמן לבוררויות ודינים גם מחוץ לעירו."},{"i":13020,"n":"דוידוביץ, דוד דב","f":"מרדכי","k":"בעל חידות מני קדם"},{"i":13021,"n":"דוידוביץ, דוד ממיטל אפשא","b":"חתנו - ר שלמה פרוכטר מסוטשעל."},{"i":13022,"n":"דוידוביץ, חיים מארה\"ב","f":"יוסף יצחק","bt":"תרסח","bp":"סיטשעל","b":"תלמיד ישיבות סטמר, סיגט. נסמך מאת: ר חיים צבי טיטלבוים, ר שלמה זלמן ארנריך משימלוי בעל \"לחם שלמה\". חתן ר נתן נטע ארבעל משימלוי. היגר לארה\"ב וכיהן כרב בבפלו-ניו יורק, דנבר-תשה. חבר אגודת הרבנים באמריקה."},{"i":13023,"n":"דוידוביץ, יוסף אהרן","b":"רב בוורשה-תר\"כ"},{"i":13024,"n":"דוידוביץ, יצחק יחיאל (יואל) מק","b":"רב בקרליץ-תרל. (לפי ברוורמן שמו - יצחק יואל). חתניו - ר יעקב קטנרוביץ מטרנטין-ארה\"ב, ר אליהו פיינשטין מפרוזין (או ר דוד פיינשטין - אביו של ר משה מניו יורק)."},{"i":13025,"n":"דוידוביץ, מיהאי מסט-גיורגי","b":"תלמיד ביהמ\"ד לרבנים בבודפשט. רבה האחרון של סט-גיורגי."},{"i":13026,"n":"דוידוביץ, משה יהודה מסיגט","b":"גביר ואספן ספרים בסיגט, בעל ספריה חשובה. הספרן אצלו ר צבי כהנא מסיגט בעל \"אוצר יהודה\" - רשימת הספרים בספריה, כ-1700 ספרים."},{"i":13027,"n":"דוידוביץ, שלום יהודה","dt":"תשג","b":"רב בוועקסנא"},{"i":13028,"n":"דוידוביץ, שמואל הלוי","b":"רב בגרושקביץ-תר\"נ"},{"i":13029,"n":"דוידובסקי, יהונתן מזעלווא","b":"איש מופת, רב בזעלווא-תרס. הסכים על \"זאת נחמתי\" וארשא תרס."},{"i":13030,"n":"דוידובסקי, יצחק יעקב מנעשוויז","f":"יונתן דוידובסקי","dt":"תשג","b":"דיין בנעשוויז"},{"i":13031,"n":"דוידובסקי, יצחק מנעסכיז","dt":"תשג","b":"רב בנסכיז"},{"i":13032,"n":"דוידזון, א' מ' מארה\"ב","bp":"רוסיה","dt":"תרצב - כז אב","b":"רב ביהמ\"ד \"מגן אברהם\" בהוקובן-ניו ג'רסי."},{"i":13033,"n":"דוידזון, אברהם אבלי מביאלה","f":"חיים דוידסון","b":"רב בביאלה"},{"i":13034,"n":"דוידזון, בן ציון מחרבין","b":"למד תורה בילדותו בליטא, נטש את הדת עם משפחתו ובהמשך עבר לחרבין-סין-תרפב, חזר בתשובה עם משפחתו וחיבר \"נאקת חלל\" - על עיקרי האמונה."},{"i":13035,"n":"דוידזון, ה'","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":13036,"n":"דוידזון, יואל מהערץ","f":"דוד מסיווען","k":"הו\"ל שאילת שלום","bt":"תר","b":"נכד-אבי אמו ר משה בעל קורא מהערץ. תלמיד ר ישעיהו ראובן מסיווען, ר שלום טויבש מבאטשאן בעל \"שאילת שלום\". מו\"צ בגאלאץ-תרלא אצל ר משה לאהר, רב בהערץ-תרנב על מקום זקנו. הו\"ל שו\"ת רבו ר שלום טויבש בשם \"שאילת שלום\" עם תוספות ממנו, חיבר שו\"ת, פירוש להגדה - בכת\"י."},{"i":13037,"n":"דוידזון, יצחק מאיר מליאווא"},{"i":13038,"n":"דוידזון, ישראל מגוליגור","f":"יצחק","k":"בעל בית ישראל","bp":"גוליגור","dt":"תרלה","dp":"ישראל","b":"מראשי הקהלה בגוליגור. עלה לארץ. חיבר \"בית ישראל\" למברג תרלא."},{"i":13039,"n":"דוידזון, ישראל מליטא וארה\"ב","k":"בעל אוצר השירה","bt":"1879","bp":"יאנובה","dt":"1939","dp":"ניו יורק","b":"תלמיד ישיבת סלובודקה, היגר לארה\"ב-1888. מורה עברי ותלמיד בסיטי קולג' בנ\"י. מלמד תלמוד בסמינר התיאולוגי בנ\"י, ופרופסור. חיבר אוצר השירה והפיוט ב-4 כרכים ובה כל השירה העברית מאז חתימת התנ\"ך. גילה בגניזה את \"מחזור ינאי\", הו\"ל \"שלש הלצות\" לר יוסף ן זבארה, \"ספר שעשועים\" מהנ\"ל, ועוד מספרי הקדמונים שמצא בגניזת קהיר."},{"i":13040,"n":"דוידי, אוריאל מירושלים","bt":"תשרי תרפה","bp":"כונסאר(איראן)","dt":"תשסו - חשון","dp":"ירושלים","b":"מרביץ תורה, דיין, דרשן, עלה לא\"י"},{"i":13041,"n":"דוידמן, אשר מטיסמניץ","b":"דיין בטיסמניץ."},{"i":13042,"n":"דוידס, אהרן ישכר מרוטרדם","bt":"תרנח","dt":"תשה","dp":"ברגן-בלזן","b":"רב בפריזלנד-תרפ\"ג,גרוינינגן,ליוורדן,רוטרדם-תרפ\"ט"},{"i":13043,"n":"דויטש, איגנץ (יצחק) מוינה","b":"בנקאי בוינה. מתומכי ישיבת הכת\"ס בפרשבורג. ארגן את העברת כספי ארץ ישראל בצורה רשמית (עד אז היה בהסתר)."},{"i":13044,"n":"דויך, מנחם כץ","b":"מוזכר ב\"מטה אפרים\"."},{"i":13045,"n":"דויס, אליעזר ליפמן מהמבורג","dt":"תקץ - כו חשון","dp":"אלטונא","b":"דיין בגרעץ, מחכמי ביהמ\"ד המכונה \"ר ליב בר שאול קלויז\" בהמבורג, יחד עם ר משה ברלין."},{"i":13046,"n":"דוכאן, יעקב מאלגיר","bt":"תקץ","dt":"תרע - בערך","b":"רב בקצמטינא ודיין אצל ר אליהו עלוש, ואח\"כ אב\"ד בקצמטינא."},{"i":13047,"n":"דוכאן, שמעון מאלגיר","f":"יעקב","b":"רב בקצמטינא, דיין אצל ר סידי פרג' חלימי. דרשה ממנו בתוך לוח שנה לשנת תרעד בהוצאת ר צמח צרפתי."},{"i":13048,"n":"דוכובני, אברהם יהודה מרמת גן","k":"בעל ברכת אברהם","bt":"תרך","dt":"תשטו","b":"רב ברמת גן. חיבר \"ברכת אברהם\" ובו קורות חייו."},{"i":13049,"n":"דוכפלינט, משה מויסוביץ","b":"רב בויסוביץ-תרסח."},{"i":13050,"n":"דול, אהרן מצורטקוב","f":"[אורי]","bt":"תקצט","dt":"תרסה","dp":"שצבניץ","b":"נאמן בית של ר דוד משה מצורטקוב ומלמדו של ר ישראל מצורטקוב."},{"i":13051,"n":"דול, אורי מצורטקוב","b":"תשובה אליו - מהרש\"ם-תרלז. כנראה אביו של ר אהרן."},{"i":13052,"n":"דולדר, צבי דוב","b":"חריף,דומ\"צ בפרישטטל-תר\"י"},{"i":13053,"n":"דולינסקי, שלמה זלמן הכהן","bt":"תרכט","dt":"תרעא","b":"איש מוסר, ר\"מ בישיבת מיר. מאמר ממנו ב\"תבונה\" - ירושלים תשא."},{"i":13054,"n":"דולניצקי, יעקב","f":"דב","bt":"1855","bp":"אלקסוט-ליטא","dt":"1933","dp":"שיקגו","b":"תלמיד ישיבות ליטא והתפרסם כעילוי בעל זכרון מיוחד. למד באוניברסיטה בגרמניה וצרפת. היה בידידות עם ר אליעזר גורדון מטלז ועם ר ישראל סלנטר. היגר לארה\"ב לפני 1890 והתישב בשיקגו. לימד תורה ונתפרסם כאחד מגדולי הלמדנים באמריקה (כעדות הרידב\"ז)."},{"i":13055,"n":"דומא, ברוך משארוואר","b":"חתן ר שמעון פולק מזענטא. נכד ר שלמה זלמן אולמן ממאקווא. חתנו - ר מאיר שרגא הכהן קליין מבודפשט."},{"i":13056,"n":"דומאן, משה מקרלסבורג","dt":"תרל.. - בערך","b":"רב בקרלסבורג אצל ר יחזקאל פאנט בעל \"מראה יחזקאל\", דיין באלבה יוליה, רב בכפר איקלוד וסידר שם גט."},{"i":13057,"n":"דומב, איתמר מקראקא","f":"יוסף מלוביטש","bt":"תרן","dt":"תשג","b":"מראשי חסידי בלז בקראקא וראש הישיבה שלהם שם. השאיר חיבורים בכתב יד. נספה בשואה."},{"i":13058,"n":"דומב, הירש מרוזוודוב","f":"נחמיה","b":"היה מעורב בדין תורה והרב המקומי שאל אודותיו את מהר\"י שמעלקיס והשיב לו ב\"בית יצחק\"."},{"i":13059,"n":"דומב, מנחם","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":13060,"n":"דומב, משה דוד מלודז (ולא דוב)","dt":"תשג","b":"רב בלודז-תרעח."},{"i":13061,"n":"דומב, צדוק צבי מרוזוודוב","f":"יהושע","k":"בעל אמרי צבי","bt":"תרפד","bp":"רוזוודוב","b":"תלמיד כתר תורה דרדומסק. תלמיד קרובו ר אברהם יצחק הורביץ מפרוביזנא. בזמן השואה ברח לסיביר, בשובו אב\"ד אייכשטט וגיבלשטט בגרמניה. עלה לארץ ונתמנה לרב בהוד השרון. חדושיו בכתבי עת שונים. חיבר \"אמרי צבי\" בני ברק תשמד."},{"i":13062,"n":"דומיניץ, אברהם משה משינאווא","f":"יהודה ליביש מגרודזיס"},{"i":13063,"n":"דומיניץ, אהרן מגרודזיסק","f":"יהודה ליבוש מגרודזיס","bt":"תקנה","dt":"תרי","b":"מחסידי הרבי מקוצק. חברו של ר צבי אלימלך מדינוב הבני\"ש. נערץ ע\"י ר חיים מצאנז."},{"i":13064,"n":"דומיניץ, חיים יעקב מניישטט","f":"נפתלי נתן נטע הירש","k":"בעל עולת שבת","r":"אדמו\"ר מרעדים, ובסוף ימיו גם רב דעיר חדש","bt":"תקף","dt":"תרמד - כו שבט","b":"תלמיד ר חיים מצאנז ור חנוך העניך דב מאלסק. רב ואדמור ברעדים, רב בניישטט(=עיר חדש)-ליד פרמישלא. כתב קמיעות והיה מחלוקת כנגדו על כך. חיבר \"עולת שבת\" פרמישלא תרלב, ועוד.","bk":[["מגילת ספר - יוחסין",""],["עולת שבת",""],["עולת שבת , מגילת ספר - יוחסין, עולת החודש",""]]},{"i":13065,"n":"דומיניץ, יהודה ליבוש מברזוב","f":"נפתלי נתן נטע הירש","bt":"תקעה","dt":"תרמא","b":"חתן ר משה אבא בער. רב ברזוב ואיסטריק על מקום חותנו."},{"i":13066,"n":"דומיניץ, יהודה ליבוש מגרודזיסק","k":"יוסף מגיד","bt":"תקב","bp":"שיניבה","dt":"תקפ-צה - א ניסן","b":"חתן הצדיק ר נתן נטע בן מנחם מנדל. תלמיד החוזה מלובלין, ותלמיד חבר לנועם אלימלך. מגיד ורב ברעדים, בנו על מקומו אחריו. עבר לגרודזיסק. בניו: ר אהרן, ר אברהם משה משינאווא, ר מנחם מנדל, ור יצחק."},{"i":13067,"n":"דומיניץ, יהודה ליבוש מרעדים","f":"חיים יעקב","bt":"תרח","dt":"תרץ","b":"מחכמי רעדים. חסיד צאנז המקורב לגדולי החסידות."},{"i":13068,"n":"דומיניץ, יצחק מזדיבראווע","f":"יהודה ליביש מגרודזיס","b":"איש קדוש שהתגורר בכפר זדיבראווע-ליד פשמישל."},{"i":13069,"n":"דומיניץ, מנחם מנדל","f":"יהודה ליביש מגרודזיס","b":"תלמיד ר מנחם מנדל מרימנוב."},{"i":13070,"n":"דומיניץ, מרדכי מנחם מנדל מרדים","f":"נפתלי נתן נטע הירש","bt":"תקעו","dt":"תרמו","b":"רב ברעדים על מקום אביו."},{"i":13071,"n":"דומיניץ, נפתלי נתן נטע הירש","f":"יהודה ליביש מגרודזיס","r":"אדמו\"ר מרעדים ואב\"ד שם, ואח\"כ אב\"ד בהוסיקוב","bt":"תקנח","dt":"תריח","b":"תלמיד ר שמואל זאנוויל מאיסטריק, וחברו של ר שמעון מירוסלב. אב\"ד רעדים, הוסקוב-תקץ. חסיד ר זנויל מליטוביסק. מבניו: ר מרדכי מנחם מנדל על מקומו אחריו ברעדים. ר אברהם מחירוב, ור יהודה ליביש מברעזוב ואיסטריק.","bk":[["עולת מועד",""]]},{"i":13072,"n":"דומיניץ, שלמה מויליצקה","f":"יהודה ליבוש","k":"בעל דורש לפרקים","bt":"תרכה","bp":"רדימנא","dt":"תשג","b":"חסיד שיניבה. חתן הגביר ר אברהם גרין מויליצ'קה. לימים היה עשיר גדול וגם למדן ובן תורה. חיבר \"דורש לפרקים\", \"רמזי אלול\" קראקא תרפח, ועוד. פרסם מאמרים ב\"אחיאסף\" - סטריזוב תרפט."},{"i":13073,"n":"דומן, משה","b":"דומ\"צ בקרלסבורג-תקע\"ח"},{"i":13074,"n":"דון בנבנישת, אברהם","b":"מחכמי ספרד, רב של קסטיליה-קצ\"ב"},{"i":13075,"n":"דון דין, אברהם","b":"מחכמי ספרד, עבר לאיטליה, מרבני פיזה-של\"ג"},{"i":13076,"n":"דון יחיא","k":"משפחה","b":"משפחת רבנים בליטא. אבי המשפחה - הגביר ר ישעיה מגינשפורג (גינצבורג?) הגיע לרוסיה-תק בערך - בן למשפחה ממגורשי ספרד שהתישבה באשכנז. בני המשפחה כיהנו במשך דורות בקהלת דיסנא(=דריססא)."},{"i":13077,"n":"דון יחיא שבתי","bt":"1909","dt":"ה'תשמא 1981","bk":[["רבי אליעזר דון יחייא",""]]},{"i":13078,"n":"דון יחיא, אליעזר מויזון","f":"שבתי מדיסנא","k":"בעל אבן שתיה","r":"אב\"ד בוויזון שבפלך קאוונא, ואח\"כ בלוצין","bt":"תקצח","bp":"דריסא","dt":"תרפו - ד תמוז","dp":"לוצין","b":"תלמיד וחתן דודו - ר אהרן זליג ציוני מליצין. רב בויזון-פלך קובנא-תרכד על מקום ר דוד גינצבורג ובנו (כנראה צריך להיות אחיו) ר חיים דון יחיא על מקומו אחריו, לוצין-פלך ויטבסק-תרלט על מקום חותנו. חתם על כרוז לתמוך בישוב בארץ ביחד עם ר מאיר שמחה הכהן בעל \"אור שמח\". תולדות בספר \"רבי אליעזר דון יחיא - מגילת חייו\" לר שבתי דון יחיא. הסכים על תשובה לר מנחם מנדל פנחס פערעוואזניק ב\"תורה מציון\" - ירושלים תרנה-תרסה. בנו (יחידו) - ר בן ציון ממאריהויז-פלך ויטבסק. חתניו: ר ישראל ציוני מניו יורק, ר שמריהו כץ מויזון, ר חיים מנחם מנדל נחמקין.","bk":[["אבן שתיה - שו\"ת",""]]},{"i":13079,"n":"דון יחיא, בן ציון ממרינהויז","f":"אליעזר","k":"בעל לקוטי מגדים","bt":"תרכט-לא","bp":"וויז'ון","dt":"תשא","dp":"לוצין","b":"תלמיד ישיבת וולוזין. חתן דודו זקנו - ר יצחק ציוני בעל \"עולת יצחק\". רב במארינהויז-ווילאקי-לטביה-תרס (וילאקי=ויטבסק?), לוצין-תרפו על מקום אביו. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי מסלובודקא, ר צבי מה-יפית מוילקוביסק. ציר בועידה הציונית בפטרבורג-תרעז וחבר ב\"מזרחי\". פרסם שו\"ת מאמרים ומחקרים. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":13080,"n":"דון יחיא, ברוך מדיסנא","f":"ישעיה מגינשפורג","b":"חתן ר שלמה האזניפיטר. רב בדיסנא-תקל, ובנו ר דוד על מקומו אחריו, בנו גם - ר מענקא ווידוער מווידז. (לפי ברוורמן-אנשי שם - שם אביו משה)."},{"i":13081,"n":"דון יחיא, ד' מריגא","b":"פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא."},{"i":13082,"n":"דון יחיא, דוד מדיסנא","f":"ברוך מדיסנא","dt":"תקס - בערך","b":"רב בדיסנא על מקום אביו, ובנו ר חיים על מקומו אחריו."},{"i":13083,"n":"דון יחיא, דוד מפלוצק","f":"חיים מדיסנא","b":"ראש ישיבה בפלוצק."},{"i":13084,"n":"דון יחיא, חיים מדיסנא","f":"דוד מדיסנא","b":"רב בדיסנא-תקס על מקום אביו, ובנו ר שבתי על מקומו אחריו, בניו גם: ר צבי מאושאץ, ר שלמה יצחק מאולע, ר דוד מפלוצק, ר זליג."},{"i":13085,"n":"דון יחיא, חיים מויזון","f":"שבתי מדיסנא","bt":"תר","dt":"תרעג","b":"מגדולי ההוראה בדורו, רב בהורדושיץ-פלך מוהילוב-תרכח, ויזון-פלך קובנא על מקום אחיו (ולא אביו) ר אליעזר, רב החסידים בשקלוב, דריססא-תרסב על מקום אביו, ובנו ר יהודה ליב על מקומו אחריו. (בחכמי ליטא מופיע שם אביו - אליעזר - כנראה טעות והכוונה לאחיו)."},{"i":13086,"n":"דון יחיא, יהודה ליב מליטא","f":"חיים בן שבתי","k":"בעל בכורי יהודה","bt":"תרכט-תרל","dt":"תשב - ו חשון","b":"חסיד חב\"ד, תלמיד דוד ר אליעזר בעל \"אבן שתיה\" בלוצין, ישיבת וולוזין והיה מקורב לר חיים סולוביציק. חתן ר שלמה כהן בעל \"חשק שלמה\" מוילנא. רב קהלת החסידים בשקלוב-תרסב, ווייטקה-תרעא, רב בדריסא(=דריססא)-תרעג, צרניגוב-תרפה, עלה לארץ-תרצו. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא. נסמך מאת: ר שלמה הכהן מוילנא, ר שמואל משה שפירא מבוברויסק."},{"i":13087,"n":"דון יחיא, מנחם מנדל מקפוסט","f":"שבתי מדיסנא","b":"רב בקאפוסט-תרמ. חתנו - ר חיים נתן יודין מהלאווטשין. בנו - ר שמואל מריגא."},{"i":13088,"n":"דון יחיא, מענקא וידוער מוידז","f":"ברוך מדיסנא","b":"רב בוידז."},{"i":13089,"n":"דון יחיא, משה מאולא","f":"שלמה יצחק מאולא","bt":"תרכו","b":"נסמך מאת: ר שמריה נח מבוברויסק. רב באולא-פלך ויטבסק-תרסו על מקום אביו."},{"i":13090,"n":"דון יחיא, צבי מאושאץ","f":"חיים מדיסנא","b":"רב באושאץ."},{"i":13091,"n":"דון יחיא, שבתי מדריססא(=דיסנא)","f":"חיים מדיסנא","bt":"תקעז","dt":"תרסז","b":"מגדולי תנועת חב\"ד, רב בדריסה(=דריססא, דיסנא)-תרז על מקום אביו - למעלה מ-50 שנה, ובנו ר חיים על מקומו אחריו. בנו גם - ר אליעזר מויזון בעל \"אבן שתיה\", ר מנחם מנדל מקאפוסט."},{"i":13092,"n":"דון יחיא, שלמה יצחק מאולא","f":"חיים מדיסנא","b":"רב באולא-פלך ויטבסק תרמ, ובנו ר משה על מקומו אחריו."},{"i":13093,"n":"דון צאז מספרד","dt":"נה (1295)","b":"מחכמי ספרד ושר ומקורב למלכות בזמן הרשב\"א."},{"i":13094,"n":"דונדון, יצחק","b":"מגדולי חכמי דורו-ת\"ל"},{"i":13095,"n":"דונדון, יצחק מספרד וקושטא","f":"משה","dp":"קושטא","b":"ממגורשי ספרד והגיע לקושטא. (אולי הוא שהיה גם בפאס-מרוקו)."},{"i":13096,"n":"דונדון, יצחק מפאס","dt":"שכג - לפני","b":"רב בפאס, חתם על התקנות-שה, וחתם על פס\"ד-שד עם ר אברהם ביטון ור שמואל חגיז ור יהודה הכהן. אולי הוא שהיה קודם בתורכיה והגיע לפאס."},{"i":13097,"n":"דונדי, יוסף מירושלים","f":"יצחק","b":"מחכמי ירושלים-רע."},{"i":13098,"n":"דונוזו, אברהם מאזמיר","dt":"תל - בערך","b":"רב באזמיר(=גיקומידיאה, איזנימיט)-שצה-תא."},{"i":13099,"n":"דונט, יצחק חזקיה פיבל מאנאד","f":"שמואל מפרשבורג","bt":"תרס","bp":"פרשבורג","dt":"תשד","b":"תלמיד הדעת סופר, ועוד. חתן ר חיים מאיר שיק מאנאד. גר בשוראן. רב באנאד-תרפז על מקום חותנו (שחלה). נספה בשואה."},{"i":13100,"n":"דונט, ליב מגיזטראוו","bt":"תרג","bp":"מורבא-מאדיארד","dt":"תרלו","b":"תלמיד הכת\"ס, ור עזריאל הילדסהיימר. רב בגיזטראוו-תרל."},{"i":13101,"n":"דונט, מנחם מנייטרא","f":"שמעון מנייטרא","b":"בנו - ר שמואל מפרשבורג."},{"i":13102,"n":"דונט, מנחם מפולדא","f":"שמואל מפרשבורג","bp":"פרשבורג","dt":"תשלז - כז טבת","dp":"ירושלים","b":"תלמיד הדעת סופר, וישיבת ברלין. חתן ר יוסף נובל מהלברשטט. דיין בפולדא-תרעד, ליבק, פינא, ראנדג-תרפג, פפדמ. עלה לירושלים-תרצט."},{"i":13103,"n":"דונט, מרדכי יהודה מפרשבורג","f":"שמואל מפרשבורג","dt":"תשג","b":"מרביץ תורה בפרשבורג"},{"i":13104,"n":"דונט, משה אליעזר ליפמן מפרשבו","f":"שמואל מפרשבורג","k":"בעל דיבורי אמת","bt":"תרנח","bp":"פרשבורג","dt":"תש..","b":"תלמיד הדעת סופר. רב בטפלשטיין(=טפלטשין)-תרפב, עיר חדש-תרפה, פרשבורג-תרצג על מקום אביו. נספה בשואה. חיבר \"אהל משה\" ועוד. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"בית ועד לחכמים\" - סטמר תרפב, \"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":13105,"n":"דונט, שמואל","dt":"תשד","b":"מייסד תומכי ישיבות,רב פעלים בהונגריה"},{"i":13106,"n":"דונט, שמואל מפרשבורג","f":"מנחם מנייטרא","k":"בעל חדושי שמואל","bt":"תרכא","bp":"נייטרא","dt":"תרצא - ג סיון","dp":"פרשבורג","b":"תלמיד השב\"ס, ור חזקיה פיבל פלויט משוראן. חתן ר עמרם קורצויל מפרשבורג. רב בפרשבורג-תרמח, וספרן החברא קדישא בפרשבורג."},{"i":13107,"n":"דונט, שמעון מנייטרא","b":"דיין בנייטרא. חתן ר ישראל כץ מסערדאוהל."},{"i":13108,"n":"דוניץ, יהודה מהליטש","b":"רב בהליטש-תרלה על מקום ר יעקב משה."},{"i":13109,"n":"דוניץ, פסח מאונסדורף","b":"תלמיד ה\"נודע ביהודה\". מחכמי אונסדורף-תקלא, וחברו של ר יואב מאונסדורף."},{"i":13110,"n":"דונסקי, יצחק נחמן","f":"ליפא","k":"בעל הכלל והפרט","bt":"1898","bp":"קובנא","dt":"1938","dp":"פריס","b":"ד\"ר לפילוסופיה וחוק. ציר בקונגרס הציוני העשרים.מרצה באוניברסיטה בקובנא. פרסם מאמרים בכתבי עת מדעיים ויהודיים בליטא ובחו\"ל. חיבר \"דעדאנקען און לעבן\" קובנא 1935. הניח כת\"י \"מוצאו והתפחתותו של הטיפוס היהודי בליטא\". ?? לא באוצר ??"},{"i":13111,"n":"דונש בן לברט המאה ה","bk":[["רבי דונש בן לברט",""],["שירים",""]]},{"i":13112,"n":"דוסא גאון","f":"סעדיה (רס\"ג)","bt":"ד'תרצ","b":"ראש ישיבת סורא-ד'תשע\"ג-תשע\"ז, ישב על כסא הגאונות לאחר ר' שמואל בן חופני, בגיל 83, ניסה להגן על חכמי בבל כאשר החלה לעלות ההשפעה של חכמי ספרד, והגן על פירושי רב האיי גאון מהתקפותיו של ר' שמואל הנגיד, חיבר מונוגרפיה על אביו הרס\"ג לבקשת ר' חסדאי אבן שפרוט"},{"i":13113,"n":"דוסא היווני מוידיגו","f":"משה היוני מבודין","k":"בעל פירוש ותוספות על","b":"רב בוידיגו(=בודין?). תלמיד ר שלום מניישטט. חיבר פירוש על רש\"י - בכת\"י (נעתק בשנת קן ע\"י ר דוד בן שמואל ירושלמי - ברשימת ר חיים בן יוסף מיכל)."},{"i":13114,"n":"דוסא, מישאל","k":"חותן הרמב\"ם","b":"מגדולי חכמי דורו-ד'תתק\"מ"},{"i":13115,"n":"דופלט, שרגא פיבל מאנטורפן","f":"חיים שמחה"},{"i":13116,"n":"דוקאץ, שמואל מואנגרוב","b":"רב בוונגראב(=ואנגרוב)-תכ. מחותן עם ר משה לימא בעל חלקת מחוקק - חתנו - ר לימא מקוצק (12669). גיסו - ר יצחק מפוזנא."},{"i":13117,"n":"דוקס, גבריאל מפרשבורג","b":"מראשי קהלת פרשבורג-תקמג."},{"i":13118,"n":"דוקס, יהודה ליב מפרשבורג","f":"צבי הירש","k":"בעל גנזי אוקספורד","bt":"תקע","bp":"פרשבורג","dt":"תרנא - כח תמוז","dp":"וינה","b":"תלמיד החת\"ס, ולמד גם בישיבת וירצבורג. נדד בין ספריות העולם. עבר ללונדון-תרט ולוינה. הו\"ל ספרים רבים מהקדמונים.","bk":[["נחל קדומים",""]]},{"i":13119,"n":"דוקס, יוסף מפרשבורג","dt":"תרז - ט כסלו","dp":"פרשבורג","b":"לאחר שנתייתם גדל אצל אביו החורג ר מיכאל אופנהיים. תלמיד ר מרדכי בנט בניקלשבורג. דרשן ומג\"מ בחברת \"תפארת בחורים\" בפרשבורג על מקום ר ברוך בייא-תקצב. הניח חדושים בכת\"י. מאחרוני הנקברים בבית העלמין הישן - וישנה עדות שהתפלל על כך בשנותיו האחרונות. בנו - ר זלמן, מחתניו - ר שמואל אונגר."},{"i":13120,"n":"דוקס, יחזקאל מאלטונא","k":"בעל חכמי אה\"ו","bt":"תרכח","bp":"סעלפטשעני","dt":"תשד - י אדר","dp":"אושוויץ","b":"תלמיד השב\"ס. מחכמי הקלויז ורב באלטונא-תרנא, ברח לאמשטרדם-תש. נספה בשואה. חיבר \"או\"ה למושב\", \"חכמי אה\"ו\" לתולדות רבני אלטונא."},{"i":13121,"n":"דוקס, יצחק זאב מאויסע וגלנטא","b":"רב באויסע,גלנטא-תקל\"ב"},{"i":13122,"n":"דוקס, ליאופולד","b":"מחכמי פרשבורג. פרסם מאמרים ב\"בכורי העתים\" - פרשבורג."},{"i":13123,"n":"דוקס, מנדל מקעסטהאל","b":"מראשי קהלת קעסטהאל-סלובקיה-תר בערך, חתם עם ר יצחק שפיץ ור ראובן גולדמן."},{"i":13124,"n":"דוקס, משה משלוניקי","dt":"רצה - טו אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":13125,"n":"דוקס, צבי הירש מפרשבורג","b":"מנכבדי פרשבורג בזמן החת\"ס, ונזכר בתשובותיו."},{"i":13126,"n":"דוראן - משפחה","b":"משפחה מיוחסת באלגיר שמוצאה בספרד. במשך כ-400 שנה העמידה רבנים ודיינים שכיהנו בקהילות אלגיר."},{"i":13127,"n":"דוראן, אבא מארי מאלגיר","f":"שלמה בן שמעון","bt":"של","dt":"תי - בערך","b":"מצאצאי הרשב\"ש. רב בדזאייר(=אלגיר), דיין ועסק לפרנסתו במסחר. חתם בשטרות בית דין - שעה-תז. חיבר סליחות וקינות. נזכר ב\"אשכבתא דרבנן\" של ביהכ\"נ הגדול באלגיר."},{"i":13128,"n":"דוראן, אהרן מאלגיר","f":"שלמה - רשב\"ש","b":"מקובל דיין ורב באלגיר על מקום אביו - יחד עם אחיו ר צמח ור שמעון. מתשובותיו בהגהות לשו\"ת הרשב\"ץ, ב\"חוט המשולש\" וב\"יכין ובועז\"."},{"i":13129,"n":"דוראן, אהרן מאלגיר","dt":"תלו","b":"דור תשיעי לרשב\"ץ. נגיד הקהל, רב ודיין באלגיר. נזכר ב\"אשכבתא דרבנן\" בבית הכנסת באלגיר."},{"i":13130,"n":"דוראן, אהרן מחכמי הסנה","f":"בעל יכין ובועז","b":"נהרג עק\"ה - שב-שמ בערך עם עוד חכמים ובהם ממשפחת צמח ונקראו \"חכמי הסנה\"."},{"i":13131,"n":"דוראן, בנימין מאלגיר","f":"יונה בן שמעון","dt":"תנה","b":"נכד הרשב\"ץ. רב מובהק ודיין גדול באלג'יר, פוסק והשיב גם לקהילות מרוחקות, קובץ שו\"ת ממנו בכת\"י, חדושים ממנו על הרמב\"ם, מתורתו ב\"זרע אמת\". דאג להעתקת שו\"ת התשב\"ץ ע\"י הסופר ר משה בן אפרים צרור. ממונה על התרומות לתושבי ירושלים."},{"i":13132,"n":"דוראן, בנימין מאלגיר","f":"שלמה בן שמעון","bt":"שמ","dt":"תי - בערך","b":"מצאצאי הרשב\"ש. דיין באלגיר. חתם אודות בית כנסת של משפחת קרשקש ונזכר ב\"פרי צדיק\", ועל אגרות מרבני אלגיר לקהלת ווהראן. חיבר סליחות וקינות. נזכר ב\"אשכבתא דרבנן\" באלגיר."},{"i":13133,"n":"דוראן, דוד מאלגיר","f":"יהודה","dt":"תקעא","b":"נגיד באלגיר. נהרג עק\"ה ע\"י אנשי הדיי (השליט) באלגיר."},{"i":13134,"n":"דוראן, חיים יונה מאלגיר","f":"צמח בן בנימין","bt":"תץ","dt":"תקס - בערך","b":"רב באלגיר. נסע לאיטליה להדפיס \"מגן אבות\" לרשב\"ץ - ליוורנו תקכג, עם הוספות ממנו."},{"i":13135,"n":"דוראן, יהודה מאלגיר","b":"פרנס ונגיד הקהלה באלגיר. חתם עם ראשי הקהל על פסק דין בענין חזקת חצר - ליוורנו תקסב. פעל לשמירת זכויות היהודים מול השליטים הצרפתים."},{"i":13136,"n":"דוראן, יונה מאלגיר","f":"שמעון בן צמח בן שמעו","dt":"תקץ-תקצג","dp":"צרפת","b":"דיין באלגיר. חתם עם ר משה משיש, ור אבא מארי דוראן על בקשה לפדיון שבויים. הו\"ל ספר דודו ר שלמה בן צמח דוראן - \"חשק שלמה\" ונציה שפג - ובו הספיד את דודו ועוד מבני המשפחה, ונפטר בדרכו חזרה בצרפת."},{"i":13137,"n":"דוראן, יוסף בנימין מאלגיר","f":"צמח בן בנימין","b":"מצאצאי הרשב\"ץ. רב באלגיר, ועסק במסחר והיה עשיר, תלמיד ודיין אצל ר יהודה עייאש - המזכירו בספרו - וכתב הקדמות לספרי רבו. הו\"ל \"יבין שמועה\" וחיבר לו הקדמה, פעל להדפסת ספר התשב\"ץ בעזרת ר מאיר קרשקש."},{"i":13138,"n":"דוראן, יוסף מאלגיר","f":"שלמה","bt":"ש","dt":"שע - בערך","b":"רב באלגיר והקים ישיבה שנקראה על שמו. תשובה ממנו בדבר מתנת ר יצחק זוראפה לר סעדיה בן דוד זוראפה."},{"i":13139,"n":"דוראן, יצחק האפודי מספרד","f":"משה","k":"בעל חשב האפוד","bp":"קסטיליה","b":"מחכמי ספרד, עמד בקשר עם ר חסדאי קרשקש. כתב כתבי פולומוס נגד הנצרות וכתב אגרת סטירית התוקפת את הנצרות \"אל תהי כאבותיך\" לחברו שהשתמד ר דוד בוניט בונגורן, ראשי הכנסיה שלא הבינו את הסאטירה - ציטטו קטעים ממנה בכתביהם עד שהתברר להם משמעותה האמיתית ודנו את האגרת לשרפה. נאנס להתנצר למראית עין-קנא, ברח לפרובנס-קס וחזר ליהדות. חיבר גם \"כלימת הגויים\" כנגד הנצרות."},{"i":13140,"n":"דוראן, ציון מאלגיר","bt":"תרל","dt":"תש - בערך","b":"רב במסילא-אלגיר. שאלה ממנו לר יוסף משאש מתלמסאן. היה האחרון לשושלת הרבנים בני משפחת דוראן באלגיר."},{"i":13141,"n":"דוראן, צמח אישטרוק מספרד","f":"יהודה דילשפילש","dt":"קסד","b":"נכד ר יהודה דיליספילש. רב במיורקה-ספרד, ברח בזמן פרעות-קנא לאלגיר, עסק במסחר והתעשר, מלמד תורה ומתלמידיו: ר שמואל חלאיו. אביו של התשב\"ץ - שמביא מתורת אביו בספריו."},{"i":13142,"n":"דוראן, צמח מאלגיר","f":"שלמה - הרשב\"ש","k":"הרצב\"ש - יכין ובועז?","bt":"ר - בערך","dt":"רס - בערך","b":"רב ודיין באלגיר-רכז על מקום אביו, והשיב לשאלות מקהלות רבות בצפון אפריקה ובספרד. תלמיד ר אברהם ן טוואה. השיב לקהלות שונות ורוב תשובותיו אבדו. מתשובותיו ב\"יכין ובועז\" וב\"חוט המשולש\". התנגד לפילוסופיה. נסע לצורך רפואה למיורקה וישב שם כ-3 שנים."},{"i":13143,"n":"דוראן, צמח מאלגיר","f":"בנימין","dt":"תפז","b":"רב באלגיר, מתורתו ב\"בית יהודה\" לר יהודה עיאש - המכנהו - אחד מגדולי הדור. מסר עותק של שו\"ת התשב\"ץ לשד\"ר ר שלם נעמיאש כדי להדפיסו באיטליה בדרכו חזרה לארץ ישראל - אך לא יצא לפועל, החזיק בכתבי זקנו הרשב\"ץ ועוד מבני משפחתו - פעל יחד עם בניו להדפסת ספרי אבותיו."},{"i":13144,"n":"דוראן, צמח מאלגיר","f":"יוסף בן שלמה","bt":"שך - בערך","dt":"שץ - בערך","b":"רב ודיין באלגיר. תשובות ממנו ב\"אהל דוד\" אוכספורד תרצב."},{"i":13145,"n":"דוראן, צמח מאלגיר","f":"חיים יונה בן צמח","bt":"תקי","dt":"תקץ - בערך","b":"דור 11 לרשב\"ץ. רב באלגיר. החזיק בחיבור זקנו הרשב\"ץ - \"מגן אבות\" - נדפס ע\"י ר אברהם טובייאנה. חיבר הקדמה ל\"זרע יעקב\" - ליוורנו תקמה לר\"י בן נאיים. חתם על שטר עדות מאלגיר עם הדיין ר עמרם עמאר ונזכר ב\"ברכות מים\" שלוניקי תקמט."},{"i":13146,"n":"דוראן, צמח מאלגיר","f":"יוסף בנימין בן צמח","bt":"תק","dt":"תקפ - בערך","b":"רב באלגיר. החזיק ב\"מגן אבות\" לרשב\"ץ שנדפס בידי ר אברהם טובייאנה - שהודה לו ולקרובו ר צמח בן חיים יונה שמסרו לו את החיבור להדפסה. החזיק בכת\"י קדום - \"זכר צדיק\" לר יוסף בן צדיק מספרד."},{"i":13147,"n":"דוראן, צמח מאלגיר","f":"שלמה בן צמח","dt":"שסה","b":"רב באלגיר. נפטר צעיר. ונספד בידי ר אברהם גבישון (שהספיד גם את בן דודו ר צמח בן שלמה - שנפטר צעיר גם הוא - \"שני שרי ישראל שבששה חדשים מתו שניהם)."},{"i":13148,"n":"דוראן, צמח מאלגיר","f":"שלמה בן שמעון בן שלמ","bt":"שלה","dt":"תטו","b":"רב ודיין באלגיר. חתם על שטר בית דין-תג, ועל שטר בענין ביהכ\"נ ר נהוראי קרשקש-תז ונזכר ב\"פרי צדיק\". כנראה אחיהם של ר אבא מארי, ור בנימין."},{"i":13149,"n":"דוראן, צמח מאלגיר","f":"שמעון בן צמח בן הרשב","dt":"שן","b":"תלמיד ר משה ור יוסף אצבי, ור אברהם בן טוואה. רב ודיין באלגיר. מתשובותיו ב\"יכין ובועז\", וב\"חוט המשולש\" - שם גם חילופי אגרות ממנו עם ר נחמן סונבאל. חיבר פירוש לשיר ר יצחק ן גיאת, פירושים לתנ\"ך - ואבדו יחד עם רבים מתשובותיו. היה תקיף בפסקיו והיה מעניש וקונס את המסרבים לפסקיו - בגלל הלשנה נמסר למלכות."},{"i":13150,"n":"דוראן, שלום מאלגיר","b":"נזכר ב\"אשכבתא דרבנן\" בביהכ\"נ הגדול באלגיר. (נזכר אצל בלוך)."},{"i":13151,"n":"דוראן, שלמה מאלגיר","bt":"ש","dt":"שע - בערך","b":"דיין באלגיר, ור\"מ בישיבה. תשובה ממנו ב\"חוט המשולש\". חיבר קונטרסים בהלכה ואגדה ובהם חדושים למסכת אבות."},{"i":13152,"n":"דוראן, שלמה מאלגיר","f":"שמעון","bt":"רל","dp":"ש - בערך","b":"כנראה נכד הרשב\"ש. רב באלגיר. כנראה הוא מחבר ההערות לשו\"ת תשב\"ץ. חיבר חדושים ל\"יבין שמועה\"."},{"i":13153,"n":"דוראן, שלמה מאלג'יר - ב","f":"צמח","k":"רשב\"ץ האחרון","dt":"שסה","b":"רב ודיין באלגיר-שנא. מתלמידיו ר יהודה כלץ, ר דוד אבולכיר, ר יהודה עלוש, ר שמואל חאגיז, ועוד. מתשובותיו ב\"חוט המשולש\". חיבר \"תפארת ישראל\", \"חשק שלמה\". בניו נפטרו בחייו והאחרון בהם ר צמח. פעל למען יהודי ארץ ישראל בעזרת הגביר ר יצחק קנשינו-ראש קהלת ווהראן."},{"i":13154,"n":"דוראן, שמעון מאלג'יר","f":"צמח בן שלמה","k":"רשב\"ץ השני","bt":"[רל]","dt":"שי - בערך","b":"נכד הרשב\"ץ. בן זקונים לאביו. רב ודיין באלגיר, העתיק והגיה את ספר התשב\"ץ לזקנו. רוב כתביו אבדו, מתשובותיו ב\"יכין ובועז\" לאביו. בנו ר צמח. מסופר כי הציל בחכמתו את העיר אלג'יר - בזמן הפלישה של קרל מגרמניה-שא - שקודם לכן כבש את תונס והרג יהודים רבים ולקח רבים בשבי."},{"i":13155,"n":"דוראן, שמעון מאלגיר","f":"צמח בן שמעון בן צמח","bt":"של","dt":"ת - בערך","b":"רב ודיין באלגיר. חיבר הקדמה ל\"עומר השכחה\", וכנראה מחבר ההערות ל\"חוט המשולש\". אחיו של ר שלמה."},{"i":13156,"n":"דוראן, שמעון מאלגיר","f":"צמח בן שמעון","bt":"שן","dt":"תך - בערך","b":"דיין באלגיר. חיבר הקדמה ל\"חשק שלמה\" לזקנו. כנראה הוא המחבר של קונטרס פירוש פסוקים מספר משלי. הסכים עם רבני אלגיר-שפח ונזכר ב\"פרי צדיק\". חיבר קינות."},{"i":13157,"n":"דוראן, שמעון מאלגיר","f":"שלמה בן שמעון בן הרש","bt":"רפ","dt":"שן - בערך","b":"רב באלגיר. חדוש ממנו בענין טריפות ב\"יבין שמועה\" לזקנו הרשב\"ץ. גלה מאלגיר."},{"i":13158,"n":"דוראן, שמעון מאלג'יר-רשב\"ש השנ","f":"שלמה - הרשב\"ש","k":"בעל יכין ובועז","bt":"קץ - בערך","dt":"רע - בערך","b":"רב ודיין באלגיר על מקום אחיו הצעיר ר צמח. השיב לקהלות צפון אפריקה, ואף ביקר בקהלות רבות וביניהם פאס. עסק רבות בפדיון שבויים, וביניהם חמשים יהודים מסביליה שנמכרו באלג'יר-רנט כנזכר בשלשלת הקבלה. תשובותיו בענין היחס ביהדות לבני אנוסים, הינה אחד המקורות הקדומים ביותר, ושימשה מקור לגדולי הפוסקים שעסקו בסוגיה. לדברי ר גדליה ן חייא ב\"שלשלת הקבלה\" - ברח ר שמעון מאלג'יר בגלל המצור הספרדי על העיר-רע, והגיע לתורכיה. מתשובותיו ב\"יכין ובועז\" - ליוורנו תקמב, ובספרי ר יוסף קארו, ועוד, ובהם תשובה מפורסמת בענין קירוב אנוסים."},{"i":13159,"n":"דורה, צאלח מביירות","b":"מחכמי ביירות-לבנון והחזיק בבית מדרש ובו לימד תורה."},{"i":13160,"n":"דורמשקין, וולף","f":"עקיבא","bt":"1908","bp":"וילנא","dt":"1947","dp":"תל אביב","b":"משורר ומחנך. עלה לארץ-1905, מורה בראש פינ הומטולה. חיברי שירי עם וילדים ובהם \"פה בארץ חמדת אבות\". תרגם מחזות ספורים ומאמרים. ביים הצגות."},{"i":13161,"n":"דורן שלמה בן שמעון","f":"שמעון - הרשב\"ץ","k":"רשב\"ש","r":"בן ר' שמעון בעל התשב\"ץ","bt":"קס","bp":"אלג'יר (=אלגזאיר)","dt":"רכז","b":"מצאצאי הרלב\"ג, הרמב\"ן ורבינו יונה. נכד ר יונה דיסמיסטרי, מגדולי דורו, דיין באלג'יר אצל אביו, וראב\"ד-רד על מקום אביו. מגדולי דורו והשיב לקהלות רבות בעולם. חיבר שו\"ת הרשב\"ש, \"מלחמת מצוה\", ועוד. בניו ר אהרן, ור צמח ור שמעון בעלי \"יכין ובעז\". מתלמידיו ר יוסף זמרון, ור יוסף אלאשקר, ר דוד הכהן בקרי. ממתנגדי הפילוסופיה.","bk":[["רשב\"ש",""],["רשב\"ש [שו\"ת]",""],["מלחמת מצוה",""],["תקון סופרים",""],["שו\"ת הרשב\"ש",""],["תיקון סופרים",""],["הרשב\"ש (שו\"ת)",""],["ספר הרשב\"ש",""]],"e":"ק\"ס~-רכ\"ז~"},{"i":13162,"n":"דורנבוש, מוריץ מפרשבורג","b":"מעורכי השבועון היהודי בגרמנית ביזמת ר שמעון סופר מקראקא - \"יידישעס וועלטבלאט\" - פרשבורג תרלח - מיועד ליהודי גליציה."},{"i":13163,"n":"דורנצויג, אברהם","b":"תשובה אליו - \"שדה יצחק\"."},{"i":13164,"n":"דורף, ראובן מרדומישל","b":"עבר מרדומישל-תרצה לפשמישל. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":13165,"n":"דורפמן, ישראל איסר מירושלים","f":"מאיר צערקאווער","bp":"ירושלים","b":"יצא מירושלים ללמוד בישיבת מוהילוב-תרכג, מכתב ממנו-תרכג לר יעקב ברלין-אבי הנציב בירושלים (על המכתב חתומים ר מאיר ברלין ור אליעזר ליפמן ריבלין - רבני מוהילוב)."},{"i":13166,"n":"דורפמן, מיכל מישראל","b":"משרידי הקלויז באומן, וממנהיגי חסידי ברסלב בארץ. חתן ר נתן בנו של ר אברהם שטרנהרץ-מנהיג חסידי ברסלב."},{"i":13167,"n":"דושאק, מרדכי מגאיא","f":"שמעון","k":"בעל ירושלים הבנויה","bt":"תקעו","bp":"טריטש","dt":"תרן - ד אב","dp":"וינה","b":"תלמיד החת\"ס, ור חיים יוסף פולק מטרביטש. רב בברנדאיס-תקצז, הבערען-תרא, אויסא-תרו, גאיא-תרטו, קראקא-תרלז (בקהל הנאורים), עזב בגלל מחלוקת לוינה. פרסם מאמרים ב\"אור תורה\" - לבוב תרלג."},{"i":13168,"n":"דושאק, צבי הרש אורי מאוסטרליץ","f":"שמעון","bt":"תקסה","bp":"טריטש","dt":"תרכו - כד אלול","dp":"אוסטרליץ","b":"תלמיד החת\"ס. רב בבודאשפיץ, אוסטרליץ-תרח."},{"i":13169,"n":"דושוביץ, ישראל מרעזיצא ונ\"י","f":"שמעון יהודה ליב","k":"בעל משכנות ישראל","bt":"תרלז","dt":"תשטז","b":"תלמיד ישיבת מיר אצל ר חיים ליב טיטינסקי ממיר. רב ברעזיצה-פלך ויטבסק-תרסד, ניו יורק-תרפה. פרסם מאמרים ב\"מגדל תורה\" - נ\"י תרפה, \"המסלה\" - נ\"י תרצו. חיבר ביאור על התשב\"ץ - בכת\"י."},{"i":13170,"n":"דושינסקי, דב בר מנאמעסטא","f":"מאיר מנאדאש","bt":"תקצח","dt":"תרפב - ח חשון","b":"נינו של ר יעקב פטרזלקי מנאדאש. תלמיד הכת\"ס, וקרובו ר פנחס דייטש מאילאווא. חתן ר אברהם יחזקאל רייך מבנאביץ ועבר לשם. רב בנאמעסטא-תרכז. בניו: ר יעקב קופל מקאסטל ולונדון, ור יחיאל מיכל מראקוש פאלאטא-תרעט - ועבר אל בנו לשם לאחר חורבן הקהלה. לתולדותיו בתוך - \"תולדות הגאון ר דוד אופנהיימר\" בודפשט תרפב."},{"i":13171,"n":"דושינסקי, יוסף צבי מחוסט","f":"ישראל מחוסט","k":"בעל שות מהריץ","r":"גאב\"ד העדה החרדית ירושלם","bt":"תרכח (ולא תרכה)","bp":"פאקש","dt":"תשט - יד תשרי","dp":"ירושלים","b":"תלמיד ר משה פולק מבאניהאד, והשב\"ס. חתן ר מרדכי יהודה ליב וינקלר בעל \"לבושי מרדכי\" מהעדילא-מאדע(=מאד), עבר לשם וסייע לחותנו בניהול הישיבה. בזיוו\"ש חתן ר יואל צבי נייהויז מקאטה. רב וראש ישיבה בגלאנטא-תרנה, חוסט-תרפא וישיבתו היתה מהגדולות בהונגריה (למעשה בצכוסלובקיה). עלה לירושלים-תרצג וכיהן בה כראב\"ד עדת החרדים וראש ישיבה, ובנו ר ישראל משה על מקומו אחריו וראש ישיבת בית יוסף צבי. פרסם מאמרים ב\"החיים\" - אונגואר תרפב. הניח שו\"ת וחדושים - בכת\"י. נסמך מאת - ר אליעזר זוסמן סופר בעל \"דמשק אליעזר\", ר יהודה גרינוולד בעל \"זכרון יהודה\", והשב\"ס.","bk":[["מהרי\"ץ [שו\"ת",""],["עה\"ת",""],["חי']",""],["דרשות מהרי\"ץ – מועדים, ז אדר",""],["הגדת מהרי\"ץ – הגדה של פסח",""],["חידושי מהרי\"ץ – ש\"ס",""],["שו\"ת מהרי\"ץ",""],["תהלות מהרי\"ץ – תהלים",""],["תורת מהרי\"ץ – עה\"ת",""],["משנת מהרי\"ץ – אבות",""],["דרשות מהרי\"ץ – מועדים",""],["ז אדר",""]]},{"i":13172,"n":"דושינסקי, יעקב קופל מקאסטל","f":"דב בר מנאמעסטא","k":"בעל תולדות יעקב","bt":"תרלח","bp":"נאמעסטא","dt":"תשד - כב תמוז","dp":"לונדון","b":"תלמיד השב\"ס, וגיסו ר מרדכי צבי מרטון מדיטשא - סנט מרטון. חתן ר פסח ברנט מלונדון. רב בקאסטל (מהערין)-תרסה, לונדון-תרסז."},{"i":13173,"n":"דושינסקי, יצחק מיכאל מראקוש","f":"דב בר מנמעסטא","bt":"תרם","dt":"תרצט - כג תמוז","dp":"ראקוש-פאלטא","b":"תלמיד השב\"ס, ודודו ר יעקב קופל רייך מבודפשט. חתן ר אליהו מנחם גויטין מהעדיעס. רב בראקוש-פאלאטא-תרנח כ-40 שנה, ובניו ר ירחמיאל יעקב דושינסקי ור מאיר צבי על מקומו אחריו."},{"i":13174,"n":"דושינסקי, ירחמיאל יעקב","f":"יצחק מיכאל מראקוש","k":"בעל בעקבי הפרשיות","bt":"תרעו","dt":"תשמז - יז כסלו","dp":"תל אביב","b":"תלמיד הדעת סופר, ור משה אשר אקשטין מסערעד. רב בראקוש-פאלטא-תרצט. ניצל מהשואה והמשיך ברבנותו עד תשח, היה גם רב צבאי-תשז. עבר לאמריקה, רב בקייפטאון - דרום אפריקה-תשי. פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":13175,"n":"דושינסקי, ירמיה מפרשבורג","b":"תלמיד השב\"ס. רב וגבאי ישיבת פרשבורג, עלה לירושלים. חתנו (בשני זיווגיו) - ר משה ניישלס מסערדאוהל - סקווירא. יצא בקול קורא נגד ר שמואל בטלהיים על מאמר שפרסם כנגד הישיבה."},{"i":13176,"n":"דושינסקי, ישראל מפאקש","f":"אהרן מנאדאש","b":"תלמיד הכת\"ס, ודודו ר משה מחסוט. חתן ר מרדכי וולף מפאקש, ועבר לשם. מחכמי פאקש."},{"i":13177,"n":"דושינסקי, ישראל משה מירושלים","f":"יוסף צבי?","b":"דיין בבית הדין להתרת עגונות ברומניה לאחר השואה. ר\"מ בישיבת בית יוסף צבי בירושלים. פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":13178,"n":"דושינסקי, מאיר צבי מטירנא","f":"יצחק מיכאל מראקוש","b":"חתן ר מאיר שטיין מטירנא. רב בטירנא על מקום חותנו-תרצג, ראקוש-פאלאטא על מקום אביו."},{"i":13179,"n":"דושינסקי, מיכאל","f":"דוב בער דושינסקי","b":"רב בראקוש-פאלטא-תרס\"ד"},{"i":13180,"n":"דושינסקי, משה מרדכי מירושלים","f":"ישראל מפאקש","k":"בעל עוד יוסף חי","bt":"תרם","bp":"פאקש","dt":"תשכה - ל אד\"א","dp":"ירושלים","b":"תלמיד הדעת סופר, ואחיו ר יוסף צבי דושינסקי מחוסט, ור יוסף ליב סופר מפאקש ועוד. חתן ר אשר טויסקי מוויצען, ועבר לשם. מחכמי בודפשט, עלה לירושלים-תרצד. חיבר \"עוד יוסף חי\" לתולדות אחיו ר יוסף צבי."},{"i":13181,"n":"דושינסקי, מתתיהו מבודפשט","f":"ישראל מפאקש","bt":"תרכד","bp":"פאקש","dt":"תרנב - ה שבט","dp":"פאקש","b":"תלמיד השב\"ס, ודודו זקנו מהרם שיק ועוד. חתן ר שרגא יהודה פיבל קליין מפאקש. מחכמי בודפשט. הו\"ל ספר רבו מהר\"ם שיק על פרקי אבות. מחדושיו בספר אחיו - שו\"ת מהרי\"ץ לאחיו."},{"i":13182,"n":"דושניז, נחמיה פיבל","k":"בעל דברי נב\"א","dt":"תח - כ טבת","b":"מקובל,מגדולי חכמי פרג"},{"i":13183,"n":"דושניץ, ברוך בנדט הלוי מנימיגן","dt":"תקסג - טו אלול","b":"חתן ר\"מ פישלס מפרג. רב בניימיגן-הולנד והמדינה. חתניו - ר ישראל לנדא בן הנודע ביהודה, ר אברהם משה להרן."},{"i":13184,"n":"דושניץ, ברוך בנדט מלעוורדן","f":"נפתלי","bt":"תקלא","dt":"תרמו - כה שבט","b":"רב בלעוורדן-תקצ\"ו"},{"i":13185,"n":"דושניצר, אליהו הכהן","k":"בעל נחלת אליהו","bt":"תרלו","dt":"תשט - כב חשון","b":"תלמיד ישיבות טלז וסלובודקה, משגיח בישיבת ראדין על מקום ר ירוחם ליבוביץ, רב בייאדוואבנה, ר\"מ בישיבת לומז'ה בפתח תקוה. תלמידו ר חיים קנייבסקי ערך משיעוריו את הספר \"נחלת אליהו\", והעיד על רבו כי היה אחד מל\"ו צדיקים. חתנו - ר חנוך פישמן מרוטקי-קוסקי בעל \"שמחת החג\"."},{"i":13186,"n":"דושנית, גדליה","f":"יעקב","k":"בעל שפה ברורה","b":"מדקדק. חיבר \"שפה ברורה\" - פרג תסד."},{"i":13187,"n":"דזובאס, אברהם יצחק מרוטרדם","f":"דוד מאיר","k":"בעל מלין חדתין","b":"רב ברוטרדם, לונדון. חיבר גם \"דגן בחורים\", \"זכרון אברהם\". פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד, \"הבאר\" - זאמושץ-וארשא תרפד, פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. עורך \"כרם בית שמואל\" - פיעטרקוב תרצב - לתלמידי ישיבת אלכסנדר, \"שערי חכמה\" - אוזרוב תרפד, \"תבונה\" - ירושלים תשא-תשח."},{"i":13188,"n":"דזימיטרובסקי, בצלאל","dt":"תשג","b":"רב באיווינטע"},{"i":13189,"n":"דזימיטרובסקי, י' יוסף","b":"מרבני ירושלים-תרע\"ט"},{"i":13190,"n":"דזימיטרובסקי, יחיאל מליטא","b":"חבר אגודת ישראל, מכתב ממנו-תרצח ליעקב לנדאו נשיא פועלי אגודת ישראל."},{"i":13191,"n":"דזימיטרובסקי, נחום בצלאל מיניש","f":"יצחק הלוי","bt":"תרלא","bp":"לידא-פלך וילנא או אישישוק","dt":"תשא","b":"תלמיד ישיבת מייליס בוילנא - אצל ר ישראל איסר הכהן, ישיבת סלובודקה, תלמיד ר איצה'לה מפוניבז. חברו של ר נפתלי טרופ מראדין. חתן ר יחיאל מיכל וולפסון מיאנישוק-פלך קובנא ועבר לשם. רבה האחרון של יאנישוק-תרס על מקום חותנו. חבר ב\"מזרחי\" בליטא. נספה בשואה. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":13192,"n":"דזניק, אברהם מרוצסטר","k":"עזריקם ספרא","b":"רב ברוצ'סטר-ארה\"ב. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד."},{"i":13193,"n":"דזענצאל, שמואל מבריסק","b":"מו\"ס בבריסק. הו\"ל \"דברי חכמים\" לר שמואל זיסל לוין - יחד עם חתנו ר משה פלבסקי."},{"i":13194,"n":"דחוח, דוד","f":"שלום","b":"מחכמי א\"י והמזרח, מרבני תימן, רב קהילת ג'בל עמר-תרי\"ג"},{"i":13195,"n":"דטנבר, מיכאל","b":"מקובל"},{"i":13196,"n":"די לה טורי, הלל מאיטליה","f":"שלמה יחיאל רפאל","k":"בעל טל ילדות","bt":"תקסד","bp":"קיענא-פיימונט-איטליה","b":"לאחר שנתייתם גדל אצל דודו (אחי אמו) ר שבתי אלחנן טרוויש באסטי בטורינו. רב בטורינו, ר\"מ בביהמ\"ד לרבנים בפדובה לצדו של שד\"ל. חיבר ספרים ומאמרים בחכמת ישראל בשפות שונות ובהם: \"אגלי טל\". פרסם מאמרים ב\"כוכבי יצחק\", \"אוצר נחמד\", ועוד."},{"i":13197,"n":"די-הונד, מאיר","bt":"תרמב","dt":"תשג","b":"דרשן,סופר,רב באמסטרדם"},{"i":13198,"n":"דיאונה, דוד חיים - הנכד","f":"אברהם שמואל","b":"ראב\"ד ברוויגה, ומלמד תורה, ומקובל. הניח פסקים ושו\"ת בכת\"י."},{"i":13199,"n":"דיאונה, דוד מאיטליה - הזקן","b":"נכד ר עזריאל. רב באיטליה-שנות ה-ת'. תשובה ממנו לר נתנאל סגרי ב\"השואל עפר יעקב\", ונזכר ב\"פחד יצחק\"."},{"i":13200,"n":"דיאמנט, אברהם מיורבורג-ליטא","f":"אשר","k":"בעל באר אברהם-בכת\"י","bt":"תרכג","dt":"תשא","b":"רב ביורברג(=יורבארג)-פלך קובנא-תרנא על מקום ר יחזקאל ליפשיץ. נסמך מאת: ר יצחק אלחנן מקובנא, ר יוסף דב סולוביציק. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"עמק הלכה\" - באטארקס תרפא, \"שערי ציון\" - ירושלים תרפא. חיבר גם \"אבן שוהם\", \"פנים מסבירות\" - בכת\"י."},{"i":13201,"n":"דיאמנט, אברהם מפיקלן","f":"צבי הירש מגאוורע","k":"אברהמלי חריף","b":"רב בפיקלן(=פיקלען)-תרי. תשובה אליו בשו\"ת מהרי\"א הלוי-תרכז."},{"i":13202,"n":"דיאמנט, אברהם שמואל בנימין","f":"נחום הכהן מפריישטט","bt":"תרלד","bp":"פריישטט","dt":"תרצא - כא אב","dp":"ברלין-המבורג","b":"נינו של החת\"ס. רב בהמבורג."},{"i":13203,"n":"דיאמנט, אליהו באלי בנימין מזיי","f":"דוב בר","bt":"תקצט","bp":"זידיק","dt":"תרנד - טו טבת","b":"לאחר פטירת אביו (בהיותו בן 11) גדל אצל דודו ר אברהם מפיקעלן. חתן הגביר ר זליג פאי (אביו של ר אליעזר שאולזון מוילקי). תלמיד ר ישראל סלנטר, ר יצחק אלחנן מקובנא, ור אליעזר ליפמן זילברמן מליק. רב בזאמעלען(=זיימל)-תרכד, פאסוואל(=פוסבול)-תרל, סימפראפול-תרמד, וענה משם לשאלות יהודי קרים והקווקז. התפרסם בתיקונים שעשה בחיי הקהילה בפוסבול, היה מהלוחמים נגד אתרוגי קורפו. היה מורו של פרופ' הרמן שפירא. הספיד את אביו לפני כל הקהל בגיל 11. חתניו: בן ציון קרצמר על מקומו אחריו בסימפרפול(=סימפראפול), ר שרגא פיבוש גרין, ר הלל שור מקרוסבאזאר. לתולדותיו ב\"נחלת אבות\", \"תולדות יהודי קורלנד\", בנו - ר בן ציון בעל \"עמק הבכא\"."},{"i":13204,"n":"דיאמנט, ברוך מזלישטשיק","b":"תשובה אליו - \"בית יצחק\"-תרמד."},{"i":13205,"n":"דיאמנט, דב בר מטאוריג זידיק","f":"צבי הירש מגאוורע","bt":"תקן","bp":"גארווא","dt":"תרי - כח שבט","b":"תלמיד ר ליב מטאוריג. רב בטבריג(=טאוריג, טויראגען) על מקום רבו, זידיק על מקום ר צבי הירש, פילטן(=פילטען)-קורלנד. בניו - ר באלי אליהו בנימין הספידו בגיל 11, ר מרדכי צבי, ר יהושע שמואל. הניח חדושים ופסקים - בכת\"י."},{"i":13206,"n":"דיאמנט, דניאל","b":"רב בבעצקא"},{"i":13207,"n":"דיאמנט, יהודה אליעזר מפילטאן","dt":"תרנו","dp":"ריגא","b":"רב בפילטען. מאמרים עליו ב\"הכנסת\", \"הבוקר\"."},{"i":13208,"n":"דיאמנט, יהודה מואוקאוואר","f":"משה מטרנטשין","b":"נכד ר ישראל יצחק אהרן מלנדסברג בעל \"מטה אהרן\". רב בוואוקאוואר."},{"i":13209,"n":"דיאמנט, יוסף בן ציון מיאלטא","f":"אליהו באלי בנימין","k":"בעל אוצר נחמד","bt":"תרלט","b":"תלמיד ישיבת וולוזין. מו\"ץ בסימפערפול על מקום אביו (שהיה האב\"ד), יאלטא (גם רב מטעם), והיה בעל קשרים טובים על השלטונות ופעל הרבה למען אחיו גם בענין איסור הישיבה. נסמך מאת: ר רפאל שפירא מוולוזין, ר חיים חזקיה מדיני, ר צבי הירש רבינוביץ מקובנא, ר מלכיאל צבי טננבוים מלומזה, ר יצחק יעקב ריינס מלידא. חיבר גם \"עמק הבכא\" - הספד על הנצי\"ב. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא, \"כנסת הגדולה\" - וארשא תרן, \"מאסף דרושי\" - וילנא תרסט, \"תלפיות\". גיסיו: ר בן ציון קרצמר מסימפרפול, ר שרגא פיבוש גרין, ר הלל שור מקרוסבאזאר."},{"i":13210,"n":"דיאמנט, יעקב יוסף מקורקלי","dt":"תשג","b":"רב בקורקלי."},{"i":13211,"n":"דיאמנט, ל' מפרשבורג","b":"מורה בביה\"ס של קהלת פרשבורג-תקפה."},{"i":13212,"n":"דיאמנט, משה מטרנטשין","bt":"תריח","b":"חתן ר ישראל יצחק אהרן לנדסברג בעל \"מטה אהרן\". רב בשאשנץ, טרענטשין-תרס. בנו - ר יהודה מואוקאוואר."},{"i":13213,"n":"דיאמנט, נחום הכהן מפריישטט","b":"חתן ר משה טוביה לעהמן שהיה חתן החת\"ס. רב בפריישטט, וינה."},{"i":13214,"n":"דיאמנט, צבי הירש מגאוורא","b":"רב בגאוורע(=גארווא)-תק\"נ"},{"i":13215,"n":"דיאמנט, שבתי מפעטשי-ניידורף","f":"מאיר","bt":"תקעה","bp":"טרביטש","dt":"תרכה - כח טבת","dp":"פעטשי ניידורף","b":"תלמיד החת\"ס, ור חיים יוסף פאלק מטביטש ור מאיר א\"ש. חתן ר שלמה גנצפריד מאונגוואר. רב בטשעטשביץ, פעטשי ניידורף-תרי. נספד ב\"מטה נפתלי\". מתורתו ב\"לחם ושמלה\". נזכר בשו\"ת \"כתב סופר\"."},{"i":13216,"n":"דיאמנט, שלום מנדל","f":"אריה ליבש קנר","dt":"תרעד - יג טבת","b":"רב בספינק"},{"i":13217,"n":"דיאמנט, שלמה","b":"פרסם מאמרים ב\"תצא תורה\" - קריניצה תרצא."},{"i":13218,"n":"דיאמנט-יהלומי, שלמה","f":"יוסף חיים","k":"בעל פניני אבות","bp":"סטריזוב","dt":"תשנד","b":"הקים בסטריזוב ישיבת עץ חיים ועמד בראשה. ניצל מהשואה - גלה לסיביר. בזיוו\"ש חתן ר מנחם אייזן. עלה לארץ דרך מינכן והתישב בתל אביב. פעיל במזרחי ובעל מוסף בביכ\"נ סדיגורא. חיבר \"פניני אבות\" תל אביב תשט."},{"i":13219,"n":"דיאמנטששטין, דוד","b":"תלמיד הכת\"ס-תרך."},{"i":13220,"n":"דיאש בראנדון, ב' רפאל","k":"בעל עמק בנימין","dt":"תק","b":"מרבני קהילת מרסן(הולנד) של הקהילה הפורטוגזית, חיבר שו\"ת \"עמק בנימין\""},{"i":13221,"n":"דיבאס, שבת אשרוף","f":"אשר בנימין חסיד","bt":"תרלז","bp":"טטאר פזרג'יק-בולגריה","dt":"תרצג - כ אדר","dp":"בית חנן","b":"ד\"ר לרפואה ומנהיג ציוני בבולגריה."},{"i":13222,"n":"דיבאריון,דוד בונגורן","f":"יום טוב","b":"מחכמי התכונה בספרד. תיקן כלי אסטרונומיה למלך"},{"i":13223,"n":"דידאווסקי יעקב בן עקיבא","dt":"ה'תש 1940","bk":[["החזקת התורה",""],["מחניך קדוש",""],["ציונים לתורה",""],["קיום התורה",""]]},{"i":13224,"n":"דידי, אברהם","k":"בעל ויעש אברהם","b":"מחכמי ג'רבא, חיבר \"ויעש אברהם\""},{"i":13225,"n":"דידי, אברהם מבבל ומרוקו","f":"יצחק בן אברהם","b":"מחכמי בבל, עבר לפאס- שנות התק' בערך."},{"i":13226,"n":"דידי, בנימין","f":"יצחק","k":"מקיקץ דידי","bt":"תרנט-אלול","bp":"חארה צגירא(ג'רבא)","dt":"תשכט - ל סיון","dp":"טבריה","b":"ראש ישיבה בתאטווין, עלה לטבריה, חיבר \"תולדות יצחק\"","bk":[["יד בנימין",""]]},{"i":13227,"n":"דידי, מכלוף נסים מג'רבה","k":"בעל נר תמיד","b":"מחכמי ג'רבא."},{"i":13228,"n":"דידי, צבי מג'רבה וטבריה","k":"בעל ארץ צבי","bt":"תרפט","bp":"ג'רבא","dt":"תשם - א תמוז","dp":"טבריה","b":"מחכמי ג'רבא, תלמיד ר מרדכי סגרון. עלה לארץ והתשיב בטבריה ולמד בישיבת \"אור תורה\". חיבר \"ארץ צבי\" תשלא.","bk":[["ארץ צבי",""]]},{"i":13229,"n":"דידיע זיין, יהושע","b":"מחכמי ירושלים-ת\"צ"},{"i":13230,"n":"דידיע שריזלי, א'ישראל","dt":"תרכו - י אב","b":"ראב\"ד קאהיר-תר\"ז"},{"i":13231,"n":"דיוואן, אפרים"},{"i":13232,"n":"דיוואן, חיים ממרוקו וארץ ישראל","f":"עמרם","b":"בא מא\"י למרוקו,נערכה לו הילולה בל\"ג בעומר"},{"i":13233,"n":"דיוואן, יהודה מירושלים","f":"עמרם","k":"בעל זבחי שלמים","dt":"תקיב","dp":"ירושלים?","b":"מחכמי ירושלים. חתן ר יעקב בן דוד הכהן מצפת ועבר לגור בצפת. בשנת תסח בשליחות צפת בפרס ולאחר מכן שליח חברון במזרח, ישנם תשובות ודרשות ממנו מארם צובא חמדאן בגדד ותימן, לאחר שובו רב בצפת. בשנת תפח בשליחות חברון-תסח בתורכיה, פרס, ותימן ואחריה התיישב בארם צובא. חיבר \"זבחי שלמים\" קושטא תצח, ו\"חוט המשולש\" קושטא תקט. עמד בראש ישיבה בקושטא. בשנת תצז עבר לירושלים והיה חבר בית דינו של הראשון לציון ר נסים חיים מזרחי בעל \"אדמת קודש\", חתם על תקנות בירושלים. הגיה את הספר \"פרי חדש\" לר אברהם אמיגו. בנו ר עמרם היה מגדולי הרבנים בחברון."},{"i":13234,"n":"דיוואן, עמרם מחברון","f":"אפרים או יהודה-חוט ה","bt":"תקיח","bp":"ירושלים","dt":"תקמב - אב","dp":"וזאן (מרוקו)","b":"מחכמי ישיבת \"נוה שלום\" בירושלים-תקיח, עבר לחברון, בשנת תקכג בשליחות למרוקו. ואחר כך עוד מספר פעמים. בשנת תקמב בשליחות עם החידא במצרים."},{"i":13235,"n":"דיזאניש, מאיר יצחק מקושטא","b":"חכם השלם,מגדולי חכמי קושטא-תק\"י"},{"i":13236,"n":"דיזנגוף, מאיר מתל אביב","b":"ראש עירית תל אביב. פרסם מאמרים ב\"המאור\" - תל אביב תרצה."},{"i":13237,"n":"דיזנגוף, מתתיהו ממוהילוב","bt":"תרכד","dt":"תרצו","b":"רב במוהליב-פודולסק"},{"i":13238,"n":"דיזנש, לוי מקושטא","b":"מגדולי חכמי קושטא-תק\"י"},{"i":13239,"n":"דיטמנט, מרדכי מזלישטשיקר","b":"רב בזלישטשיק-תרמד, קמינקא-תרסז."},{"i":13240,"n":"דייטלבוים, מאיר מפרשבורג","bt":"תריד","dt":"תרפח - ח חשון","dp":"פרשבורג","b":"תלמיד הכת\"ס. מחכמי פרשבורג."},{"i":13241,"n":"דייטש יהושע בן חיים יהודה","bt":"1910","dt":"ה'תשנ 1990","bk":[["בית הלחמי א",""],["בית הלחמי ב",""]]},{"i":13242,"n":"דייטש, אברהם מבעצקא","f":"יהודה ליב","b":"נכד ר דוד בעל אוהל דוד. רב בואג-ניישטדל-תרה, בעצקא. חתם ב\"תורת הקנאות\" כנגד הריפורמים."},{"i":13243,"n":"דייטש, אברהם מצילץ","f":"מרדכי מצילץ","b":"מחכמי צילץ-תקעט. אחיהם של ר דוד מזארהוי, ור ישראל מבייטען."},{"i":13244,"n":"דייטש, אברהם מקאסטל","f":"ישראל ממאדיאר-גנטש","bt":"תרמט","bp":"מאדיאר-גנטש","dt":"תשיג - י סיון","dp":"בני ברק","b":"תלמיד הדעת סופר, ור יוסף צבי מחוסט. חתן ר בנימין וולף פפנהיים מוינה. רב בלוצרן, קאסטל-מהרן-תרעד, נשיא מוסדות החנוך האורטודוכסים בבודפשט-\"יסודי התורה\"-תרף. ניצל מהשואה ואחריה עלה לארץ דרך שוויץ, התיישב בתל אביב והיה מראשי העסקנים החרדים."},{"i":13245,"n":"דייטש, אהרן דוד מבאלאש-ירמוט","f":"אברהם אהרן מרודניץ","k":"בעל גורן דוד","bt":"תקעג","bp":"רודניץ","dt":"תרלח - כג ניסן","dp":"באלאש-יארמוט","b":"גדל אצל זקנו ר יוסף דייטש מרודניץ. תלמיד ר יהודה ליב מגלוגא, ור רפאל שולהאף והחת\"ס. חתן ר נתן אליהו עהרמן מאירשא, ועבר לשם, ובזיוו\"ש חתן ר מנחם מנדל כץ מפרשבורג. רב בבודפשט, שעבעש-תרו, באלאש-יארמוט-תריא על מקום ר יעקב יהושע רפפורט ובנו ר יוסף ישראל על מקומו אחריו. ביקר בארץ ורכש דירה בבתי אונגרן בירושלים - וכשחזר הביא עמו אבן מירושלים שעליה עמד בעת תפלתו. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד.","bk":[["גורן דוד [שו\"ת]",""]]},{"i":13246,"n":"דייטש, אהרן דוד מגירבא-פינצהעל","f":"משה משאלגא-טאריאן","bt":"תרמ","bp":"שאלגא-טאריאן","dp":"קרית עקרון - ישראל","b":"תלמיד השב\"ס. חתן ר שלמה כץ מסאבסלוי. רב בגירבא-פינצעהעל-תרסה. רב צבאי בזמן מלחמת העולם ה-I. מחברי אגודת \"אהבת ציון\" ונואם באגודה - בהיותו בישיבת פרשבורג, עלה לארץ והתגורר בקרית עקרון. חיבר ספר דרושים בהונגרית."},{"i":13247,"n":"דייטש, אלחנן מהאהוט","b":"רב בהאהוט-תרע\"ד"},{"i":13248,"n":"דייטש, אליעזר חיים מהאנשוביץ","f":"אברהם","k":"בעל פרי השדה","bt":"תרי","dt":"תרעה - כט אלול","b":"נכד ר צבי חיות. חתן ר בצלאל גרוס מטאקייא. תלמיד ר מרדכי הורביץ מהאלמין, ר מנחם א\"ש באונגוואר, ר שלמה גנצפריד, ר יהודה אסאד, ישיבת ר יואל צבי מאויפאלא. מנהל ישיבה בטוקאי, רב בהאנשוביץ-תרלז וראש ישיבה, בוניהאד(=בניהאד,בונהרד)-תרנז וראש ישיבה ובנו ר משה על מקומו לצדו ואחריו. נסמך מאת: ר יקותיאל זלמן טיטלבוים מסיגט, ר דוד שיק בעל \"אמרי דוד\". ממנהיגי התנועה הציונית דתית \"מוריה\". בנו - ר משה מלעמעש, חתנו - ר יוסף שורץ בעל \"וילקט יוסף\". חיבר גם \"תבואת השדה\", ועוד. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"יגדיל תורה\" - ברלין-קראקא תרנא, \"הנשר\" - טירנוי תרצג-תשד,\"שערי תורה\" - קראקא תרפה, \"תל תלפיות\" - וייצען תרנב-תרעד. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!).","bk":[["פרי השדה [שו\"ת]",""]]},{"i":13249,"n":"דייטש, אליעזר מטאיעשט","f":"יוסף משה מהאליטש","bt":"תקעא","bp":"האליטש","dt":"תרנג - כב שבט","dp":"שטאמפען","b":"תלמיד החת\"ס. חתן ר אליעזר שטרסר מעיר חדש ועבר לשם-תקצח. רב ברייטץ-תרא, שטאמפען-תריב. אביו - ר יוסף משה נולד בברכת החת\"ס."},{"i":13250,"n":"דייטש, אליעזר ממטרדסדורף","dt":"תרץ - כב ניסן","dp":"מטרסדורף","b":"תלמיד הכת\"ס."},{"i":13251,"n":"דייטש, אריה ליב אשכנזי מברוד","b":"עבר מברודי לסטרי - תשובה אליו בטוט\"ד."},{"i":13252,"n":"דייטש, ארנסט מבראשוב","dt":"תשי או 1963","dp":"ירושלים","b":"רב הקהילה הניאולוגית בקאראן-סבש על מקום ד\"ר יוסף הורביץ, סט-מיקלוש, בראשוב(=בראשאו)-תרפז. חיבר ספרים על תולדות יהודי העיר, על הספרות העברית ודרשות בהונגרית ובגרמנית. עורך כתב העת של הקהילה. עלה לארץ."},{"i":13253,"n":"דייטש, בינוש מניקלשבורג","dt":"תקמו - יד תשרי","dp":"טימישואר","b":"חתן ר יוחנן בן יצחק מטימישואר. דיין בניקלשבורג, רב וראש ישיבה בטימישואר לצד חותנו."},{"i":13254,"n":"דייטש, בצלאל (בן אורי)","f":"משה מסאבדקא","k":"בעל מעשה בצלאל","dp":"ירושלים","b":"תלמיד הדעת סופר. עלה לירושלים. ?? לא באוצר ??"},{"i":13255,"n":"דייטש, גוטהרד מסינסינטי","bt":"1859","bp":"קוניז-אוסטריה","b":"תלמיד ביהמ\"ד לרבנים בברסלאו. רב בבריס?-1887. היגר לארה\"ב-1891 והיה פרופ' בביהמ\"ד בסינסינטי. פרסם מאמרים בעברית, גרמנית ואנגלית. חיבר ספרים באנגלית בנושאים יהודיים."},{"i":13256,"n":"דייטש, דוד","f":"גרשון","k":"בעל צנת דוד","b":"חיבר \"צנת דוד\" עם פירוש \"מקום דוד\" - פיורדא תקי."},{"i":13257,"n":"דייטש, דוד מדרעטאמא הנכד","f":"יחזקאל מעיר חדש","dt":"תרם - טז אב","dp":"עיר חדש","b":"תלמיד הכת\"ס, ור ברוך עקפלד מטשוס. מחכמי עיר חדש-תריט, רב בדרעטאמא. טבע בנהר וואג. (לפי ברוין שם אביו - ר מנחם מוערבאפצי בנו של ר דוד בעל אוהל דוד)."},{"i":13258,"n":"דייטש, דוד מזאהרוי","f":"מרדכי","k":"בעל אסוף אסיפה","bt":"תקסח-ע","bp":"צילץ","dt":"תרלג - ז אב","dp":"זאהרוי","b":"נתייתם בילדותו וגדל אצל קרובו ר מנחם דייטש בברסלוי. תלמיד חת\"ס ור מרדכי בנט בניקלשבורג. התגורר בברלין, בייטען. רב במיסלביץ-תקצח, זאהורי(=זאהרוי)-תרה, בנו ר עמנואל על מקומו אחריו. לחם ברפורמים וחיבר כנגדם \"אסוף אסיפה\". חיבר \"ישראל והעמים\". חבקוק מתורגם. הו\"ל ספר אחיו ר ישראל \"זרע ישראל\""},{"i":13259,"n":"דייטש, דוד מניקלשבורג","b":"דיין בניקלסבורג,רב בברין-תק\"פ"},{"i":13260,"n":"דייטש, דוד מעיר חדש הזקן","f":"מנחם מנייטרא וקיצע","k":"בעל אהל דוד","bt":"תקטז","bp":"נייטרא","dt":"תקצא-ה -כה סיון","dp":"עיר חדש","b":"תלמיד הנודע ביהודה בפרג, ומהר\"ם ברבי בפרשבורג. רב ביעמניץ(=יאמניץ), פרונקירכן-תקנט ור שלום אולמן על מקומו אחריו, סערדאוהל(=דונא סרדאהלי)-תקס וראש ישיבה עם חתנו ר מאיר א\"ש, עיר חדש=נאוואמסטא-תקע. עוד מחתניו: ר מיכאל בן צבי הכהן מסערדאוהל, ר וולף לייפניק. בנו ר יחזקאל מעיר חדש. בניו - ר מנחם מעורבאפצי, ר יחזקאל שהו\"ל ספר אביו \"אוהל דוד\" על יבמות ושבועות, ר יהודה ליו מבעקאוו. עמד בקשרי שו\"ת עם הנודע ביהודה - שכינהו \"דוד קיצע\", ועם החת\"ס, ועוד. (יש רושמים פטירתו - תקצ - כב סיון)"},{"i":13261,"n":"דייטש, דוד נתן מטרנופול","f":"יוסף יואל ממוסטרישץ","k":"בעל נפש דוד","bt":"תקף","bp":"טרנופול","dt":"תרלט - יא שבט","b":"קרוב למשפחת טיטלבוים ול\"ייטב לב\" מסיגט. חסיד רוזין וצורטקוב. חתן ר יצחק אייזיק מסטרי - חתנו של ר צבי מרודניק. רב בקרצינוב(=קרטשנוף) על מקום אביו, אב\"ד קרטשנוף-ליד סיגט ור צבי הירש ריינמן על מקומו אחריו. חיבר \"נפש דוד\" סעיני תרפט. בנו ר יצחק איזיק עלה לטבריה עם אמו אחר פטירתו - ונפטרו שם. הערות ממנו בספר אביו \"יד יוסף\"."},{"i":13262,"n":"דייטש, זאב וולף מהנשביץ","b":"דומ\"צ בהאנשביץ-תר\"כ"},{"i":13263,"n":"דייטש, זעקל מראזשנוי","f":"יוסף דייטש","b":"ראזשנוי-תר\"כ"},{"i":13264,"n":"דייטש, חיים אהרן דוד מיארמוט","f":"יוסף ישראל","k":"בעל תבואת הגורן","bt":"תרנח","dt":"תשד - כב סיון","b":"חתן ר ישעיה זילברשטין מוייצען ועבר לשם. רב ביארמוט-תרפט על מקום אביו וראש ישיבה, מתלמידיו האדמור מערלוי. עזר לפליטים מסלובקיה. מקובל והתכתב בעניני קבלה עם ר שפטל וייס משימאני. נספה בשואה. חיבר \"תבואת הגורן\" נדפס בסוף \"בן גרני\"-תשך."},{"i":13265,"n":"דייטש, חיים זאב מטארנאליא","bt":"תרלה","bp":"יאלשווא","b":"תלמיד השב\"ס. חתן ר אליעזר זוסמן סופר מדברצין. מחכמי טארנאליא."},{"i":13266,"n":"דייטש, חיים יהודה סגל ממקובה","f":"יוסף","k":"בעל מים חיים","bt":"תרלה","bp":"קליץ-ליד זשיבוי","dt":"תרצח - יח תשרי","dp":"מאקובה","b":"נולד בכפר קליץ ובו גרו שני יהודים בלבד. תלמיד ישיבת ר ישכר בער קאהן בערדא-סענזשארץ בעל \"בינת ישכר\", ובישיבת ר משה גרינוולד בעל \"ערוגת הבשם\" בקלינורדין ואח\"כ עבר עמו לחוסט. חתן ר אברהם יקותיאל שורץ-ירושלמי מחוסט. דיין במאקאווע(=מאקוב) אצל ר אברהם יוסף גרינוולד - בנו של רבו. חיבר גם \"רחבת ידיים\", \"אהבת חיים\" סטמר תרצח עם הקדמה ובה תולדות המחבר. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":13267,"n":"דייטש, חיים יעקב","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":13268,"n":"דייטש, חנוך יהודה מפרשבורג","dt":"תצז - תשרי","b":"בנו - ר מרדכי מפרישטט"},{"i":13269,"n":"דייטש, חנניה יו\"ט ליפא מאבישנא","k":"בעל טהרת יום טוב","bt":"תרסה","dt":"תשנא","b":"תלמיד בעל \"לבושי מרדכי\". רב באבישנא, העלמעץ, ניצל מהשואה ואחריה דיין בבית הדין לעגונות ברומניה. היגר לארה\"ב וכיהן כרב בקליבלנד. אחיו של ר יצחק צבי מדטרויוט. עסק בתיקון מקוואות בארה\"ב."},{"i":13270,"n":"דייטש, יהודה יואל מארה\"ב","f":"יעקב","k":"בעל משנת אבא - תשם","bt":"תרלב","bp":"ספינקא-ליד סיגט","dt":"תרעט - טו תשרי","b":"תלמיד ישיבת סיגט אצל \"הייטב לב\", ונסמך ממנו. חתן ר מאיר מילר מגאניטש. רב בגאניטש-תרנב וראש ישיבה. סירב לרבנות סטרי על מקום ר ענזיל."},{"i":13271,"n":"דייטש, יהושע השל מפריימאן","b":"רב בפריימאן, ניו יורק. חיבר הגדה של פסח עם דיני הלכות פסח."},{"i":13272,"n":"דייטש, יהושע מבראשוב וירושלים","f":"חיים יהודה ממאקאווע","bt":"תרע","bp":"מאקאווע","b":"תלמיד ישיבות הונגריה. חתן ר דוד שפרבר מבראשוב, דיין בבראשוב-תרצב אצל חותנו, רב בקזדי-וואשארהי-תרצח. ניצל מהשואה ואחריה עלה לירושלים וכיהן כרב שכונת קטמון, ומראשי חסידות בלז. הקים מכון \"מעין החכמה\" להוצאת ספרים תורניים."},{"i":13273,"n":"דייטש, יואל מגאניטש","b":"מאמר ממנו ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":13274,"n":"דייטש, יוחנן ממליץ ונ\"י","b":"היגר ממעליץ לארה\"ב-תרע. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":13275,"n":"דייטש, יוסף יואל מטרנופול","k":"בעל יד יוסף","bt":"תקן","dt":"תריג","b":"חתן ר משה דוד אשכנזי אב\"ד טאלטשווא. רב בקרצינוב(=קרטשנוף), דיין בטרנופול-תקץ, רב במונסטרישץ-תקצט, חודרוב-תריא. חיבר \"יד יוסף\" סיגט תרלה. בנו ר שמעון - יסד ישיבה בדרוהוביטש."},{"i":13276,"n":"דייטש, יוסף ישראל מבאלאש-ירמוט","f":"אהרן דוד מבאלש-ירמוט","k":"בעל בן גרני","bt":"תרה","bp":"פרשבורג","dt":"תרפז - כז שבט","dp":"באלאש-ירמוט","b":"תלמיד הכת\"ס, ואביו ר אהרן דוד. חתן ר נח יעקב לעווי מהארטיאן, ובזיוו\"ש חתן ר ישראל חיים קצבורג מאוזד-באליאק. רב בסענדרא-תרלד, באלאש-יארמוט-תרלח על מקום אביו כ-50 שנה וראש ישיבה, ובנו ר חיים אהרן דוד על מקומו אחריו. פרסם מאמרים ב\"המגיד\" - סטמר תרפח. ?? לא באוצר - המחבר ?? (באהלי שם - שמו יוסף יואל)"},{"i":13277,"n":"דייטש, יוסף מבסקביץ","b":"דיין בבסקוביץ, רב ברודניץ(=רויסניץ)-תקל. השתתף-תקמט במשלחת בראשות ר קופל טעבן אצל הקיסר בניקלשברג."},{"i":13278,"n":"דייטש, יוסף מניקלשבורג","b":"רב בניקלסבורג-תק\"ע"},{"i":13279,"n":"דייטש, יחזקאל מעיר חדש","f":"דוד","bt":"תקס","dt":"תרח","dp":"בודפשט","b":"רב-שנת ת\"ר. חתן ר אברהם בעק מהאליטש. הו\"ל ספר אביו - אוהל דוד. בנו - ר מנחם דייטש מפאלאנקא."},{"i":13280,"n":"דייטש, יעקב יהודה מטאריאן","dt":"תשד","b":"דומ\"צ בטאריאן"},{"i":13281,"n":"דייטש, יעקב מואג-ועטשע","f":"מרדכי","dt":"תרכח","b":"רב בוואג-וועטש. בנו - ר מנחם מנדל ונכדו ר משה דייטש מקאלין. (באוצר הרבנים שם אביו - ר מנחם)."},{"i":13282,"n":"דייטש, יעקב מפרשבורג","b":"גביר, מוהל מחכמי פרשבורג-תקעז, ערך בריתות רבות עם החת\"ס, ונזכר רבות בפנקס המילה של החת\"ס. אולי אשתו גליקל שנפטרה בפרשבורג תרה."},{"i":13283,"n":"דייטש, יעקב משה מסאנטוב","f":"ישראל ממאדיאר גנטש","bp":"מאדיאר-גענטש","dt":"תשה - יב אב","dp":"ציריך - ירושלים","b":"תלמיד השב\"ס והדעת סופר, ור יהודה ליב פרידמן מפרשבורג. חתן נכדת ר שמעון הכהן שאטין משאראש-פאטאק. רב בנעמעש-סאלוק-תרעד, פאסטא-תרפה, סנטוב-תרץ. ניצל מהשואה והגיע לציריך."},{"i":13284,"n":"דייטש, יעקב שמשון מזליחוב","dt":"תקפו - כג אייר","b":"תלמיד החוזה מלובלין. בזמן המחלוקת כנגד היהודי הקדוש מפשיסחא - היה מראשי המתנגדים אליו. אב\"ד בארנוב, זליחוב, פילוב, וראדזין."},{"i":13285,"n":"דייטש, יצחק מוינה ופרשבורג","f":"ישעיה דייטש טרנטשין","bt":"תקסח","bp":"פרשבורג","dt":"תרמו - יז אלול","dp":"פרשבורג","b":"נכד ר יצחק דוקלא לנדא בעל \"מעיני הישועה\". תלמיד החת\"ס. גביר מחכמי וינה. \"ראש משביר\" לכולל האשכנזים בירושלים-תריג, ונשיא ארץ ישראל לעדת הספרדים-תרכג. פעל לפרישת החרדים מהקהלה הכללית. שתלדן חשוב שסייע רבות ליהודים. מגדולי התומכים בישיבת פרשבורג. נספד ב\"מטה נפתלי\", ו\"לקוטי בית אפרים\"."},{"i":13286,"n":"דייטש, יצחק מיאלע-באגעדא","f":"ישכר בער מפעזינג","k":"בעל עקידות יצחק","bt":"תרא","bp":"פעזינג","dt":"תרפב - ד אלול","b":"תלמיד הכת\"ס. חתן ר יהודה ליב האן מליפטא סנט מיקלוש. רב בליפטא סנט מיקלוש. טירנא. יאלע-באגעדא-תרלב. ?? לא באוצר ??"},{"i":13287,"n":"דייטש, יצחק צבי מבוסטון","b":"רב ק\"ק סענדרא בבוסטון."},{"i":13288,"n":"דייטש, ישכר דב בריש ממיכלדורף","k":"בעל שפתי רננות","b":"רב במיכלדורף-תקצ\"ו."},{"i":13289,"n":"דייטש, ישעיה טרענשין מפרשבורג","dt":"תקעב - כסלו","dp":"פרשבורג","b":"חתן ר דוד לביאוס-חתנו של ר יעקב יצחק דוקלא בעל \"מעיני הישועה\". מחכמי פרשבורג, נזכר בפנקס האפוטרופסים של ביה\"ד של החת\"ס. בנו ר יצחק מפרשבורג."},{"i":13290,"n":"דייטש, ישעיה מגרוסורדין","f":"צבי הירש מנמנסדורף","dt":"תרן - כג תשרי","b":"רב בקש-ג'ולה-ליד גרוסורדין ובגלל שהקהלה נהיתה לניאולוגית - עבר לגרוסורדין. רב ודיין בגרוסורדין."},{"i":13291,"n":"דייטש, ישראל מבייטעהן-פרוסיה","f":"מרדכי מצילץ","k":"בעל זרע ישראל","bt":"תקס","dt":"תריג","b":"אב\"ד בייטעהן-פרוסיה. מהלוחמים בריפורמה. בקשרי שו\"ת עם ה\"כתב סופר\". אחיו - ר דוד מזאהרויא הו\"ל את ספרו \"זרע ישראל\"."},{"i":13292,"n":"דייטש, ישראל ממאדיאר-גענטש","b":"בניו - ר יעקב משה מסנטוב, ור אברהם מקאסטל - בודפשט."},{"i":13293,"n":"דייטש, ליבוש מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":13294,"n":"דייטש, מאיר בנימין מקוניץ ודרז","b":"רב בדרזניץ. ישב בביה\"ד בענין ר נתן אורהולץ שנחשד ע\"י היעב\"ץ בשבתאות וזוכה."},{"i":13295,"n":"דייטש, מאיר מנתניה","f":"משה מגאניטש","bt":"תרע","bp":"גאניטש","dt":"תשכב - ז אד\"ב","dp":"נתניה","b":"תלמיד הדעת סופר. חתן דודו ר בנציון כץ מטעטש, ועבר לשם. ניצל מהשואה ואחריה דיין בבית הדין לעגונות בפרשבורג, פריז. בזיוו\"ש חתן ר מאיר שוורץ ממונקטש. עלה לארץ-תשח וכיהן כרב בנתניה, בנו ר משה על מקומו אחריו. מתורתו ב\"אמרי מאיר\"."},{"i":13296,"n":"דייטש, מיכאל מארה\"ב","k":"בעל חזון מדת הבטחון","b":"רב בארה\"ב-תרסב."},{"i":13297,"n":"דייטש, מיכל (קיטאי) משאוולי","b":"רב \"מטעם\" בשאוולי."},{"i":13298,"n":"דייטש, מנחם מגלנטא","b":"רב בגלנטא-תר.. על מקום ר אהרן אליעזר פשקס."},{"i":13299,"n":"דייטש, מנחם מוערבאפצי","f":"דוד","dt":"תרלו - יב תמוז","dp":"טירנוי","b":"אב\"ד וערבאפצי. בנו - ר דוד מיעטרמא."},{"i":13300,"n":"דייטש, מנחם מוערבויץ","f":"צבי הרש מנמעסטא","dp":"טורנא","b":"רב בוערבויץ. אחיו - ר פנחס מאילאווא, ור ישעיהו מבעקעש דיולא מגרוסורדין."},{"i":13301,"n":"דייטש, מנחם מנדל","f":"יהונתן בנימין","bt":"תרך","bp":"כפר ספרמזאו","dt":"תשיב - אייר","dp":"ירושלים","b":"תלמיד ר מנחם מנדל פאנט בדעש, עבר מכפר ספרמזאו-אחרי מלחמת העולם ה-I והתישב בסאמוש-אויוואר, ניצל מהשואה ואחריה עלה לארץ-תשו, והתישב בפתח תקוה ליד בנו ר אליעזר דייטש."},{"i":13302,"n":"דייטש, מנחם מנדל הלוי מנאפראד","b":"רב בנאפראד. בנו - ר רפאל מסעפלאק (חתן הכת\"ס). חתניו - ר שמואל זאב יונגרייז מביהר נאדי באיאם, ר משה קלין מסילאדי טשעה."},{"i":13303,"n":"דייטש, מנחם מנדל מטאפלטשן","dt":"תרפו - ג חשון","b":"דומ\"צ בטאפאלטשין,עלה לירושלים"},{"i":13304,"n":"דייטש, מנחם מנדל מלודז","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":13305,"n":"דייטש, מנחם מנדל מנייטרא","f":"מרדכי","dt":"תקמה - יב אדר","b":"מו\"צ, ואב\"ד בנייטרא, רב בקיצע-תקכב, טיטשינא(=טושאף)-תקכט וגליל טאבור. נספד ע\"י ר אלעזר קליר. בנו - ר דוד מעיר חדש. (באוצר הרבנים תאריך פטירתו - תקעה - יב אייר)"},{"i":13306,"n":"דייטש, מנחם מנדל מסקוטשאו","b":"רב בסקטושוב(=סקוטשאו)-פולין-תרצו."},{"i":13307,"n":"דייטש, מנחם מפאלאנקא","f":"יחזקאל","k":"בעל אבני זכרון","bt":"תקעט","bp":"עיר חדש","dt":"תרסד - ט אלול","b":"גדל אצל זקנו ר דוד מעיר חדש. תלמיד הכת\"ס ודודו ר מאיר א\"ש מאונגוואר. חתן ר ישעיה פוקס מעיר חדש. רב בעיר חדש-תרה, גאלאנטא-תרי, פאלאנקא-תרטז. הו\"ל ספר זקנו \"אהל דוד\" - ובסופו ספריו שלו \"אבני זכרון\" ושארית מנחם\"."},{"i":13308,"n":"דייטש, מנחם צבי מואמוש-מוקולא","f":"יוסף ישראל דייטש","dt":"תשד","b":"דרשן,רב בוואמוש-מיקולא"},{"i":13309,"n":"דייטש, מרדכי מועליאטין","dt":"תשג","b":"רב בוועליאטין"},{"i":13310,"n":"דייטש, מרדכי מפריישטט","f":"חנוך יהודה","k":"בעל מור דרור","bt":"תסב","dt":"תקלו - יג תשרי","dp":"פריישטטל","b":"תלמיד ר דוד אופנהיים מפרג. רב בפאלין-בוהמיה-תעב, פריישטטל-תק וגם טיטשינע. בנו - ר מנחם מנדל מנייטרא. בניו - ר מנחם מנדל מנייטרא, ר יעקב מוואנועטשע, ר משה מפריישטטל, חתנו - ר שמעון פריישטטל. ר יהודה ליב לעסנר, ועוד."},{"i":13311,"n":"דייטש, מרדכי מצילץ","dt":"תקעג","b":"רב בצילץ. בניו ר דוד מזארהוי-תלמיד החת\"ס, ר ישראל בבייטען, ר אברהם מצילץ."},{"i":13312,"n":"דייטש, משה אהרן מרייניץ","b":"רב ברייניץ"},{"i":13313,"n":"דייטש, משה הלוי מאלטונא","f":"רפאל מסעפלאק","b":"נכד הכת\"ס. רב באלטונא-תרמט, פפד\"מ. תשובה אליו ב\"שבט סופר\"."},{"i":13314,"n":"דייטש, משה יצחק","b":"פרסם מאמרים ב\"שמוש חכמים\" - בני ברק תשז."},{"i":13315,"n":"דייטש, משה מגניטש","f":"יהודה יואל דייטש","bt":"תרמז","bp":"גאניטש-פלך מרמרוש","dt":"תשד","dp":"אושויץ","b":"תלמיד ישיבת אביו ונסמך ממנו ומאת בעל ערוגת הבושם. חתן ר נחמן זיידא הופמן מדיבעווע. רב בגאניטש על מקום אביו. נספה בשואה עם חלק ממשפחתו, ניצל בנו - ר מאיר מנתניה, ושתיים מבנותיו."},{"i":13316,"n":"דייטש, משה מדלטין","dt":"תשד","b":"רב בדעלאטין"},{"i":13317,"n":"דייטש, משה מטאריאן","f":"אהרן דוד דייטש","k":"בעל דרושי וחדושי הרמ","r":"רב בעיר שאלגא - טאריאן כשישים וחמש שנה","bt":"תרו-י","bp":"פרשבורג","dt":"תרצא - כז ניסן","b":"תלמיד הכת\"ס, ור הלל ליכטנשטין מקולומיא. חתן ר אליהו הכהן מרקוביץ מסטמר. ר\"מ בישיבת אביו בבאלאש-יארמוט-תרכו לצד אביו, שאלגא-טאריאן(=שאלגוי-טאריאן)-תרלה. חיבר דרושי וחדושי הרמבא\"ד - תשג. בנו - ר מנחם יוסף-חתן ר משה טננבוים.","bk":[["דרושי וחידושי הרמבא\"ד",""]]},{"i":13318,"n":"דייטש, משה ממונסטרישץ","f":"יוסף יואל","bt":"תקפה","dt":"תרל","b":"רב במונסטרישץ."},{"i":13319,"n":"דייטש, משה מנתניה","f":"מאיר מנתניה","b":"רב בנתניה על מקום אביו."},{"i":13320,"n":"דייטש, משה מסאבדקא","f":"אליעזר חיים מבאניהאד","k":"בעל כתב סופר","bt":"תרלט","bp":"האנשוביץ","dt":"תשב - ח אב","dp":"סאבדקה","b":"תלמיד השב\"ס. חתן ר שמעון סופר מערלוי(=אויהל) - בן הכת\"ס, ועבר לערלוי(=אויהל). רב בבניהאד-תרס לצד אביו, רב בלעמעש-תרסו, קאשוי, קאמארן-תרף, סאבקדה(=סבדקה, סובאטיצא)-תרפב וחתנו ר יהושע קאליש על מקומו אחריו. נסמך מאת: ר יעקב סנידרס, ר אברהם יצחק גליק מטאלטשווא, ר יוסף ליב סופר מפאקש. בנו ר בצלאל (בן אורי) בעל \"מעשה בצלאל\". פרסם מאמרים ב\"המעין\" - פרשבורג תרצד. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!). חיבר פירוש להגדה \"כתב סופר\"."},{"i":13321,"n":"דייטש, משה מסיגט","f":"דוד נתן-נפש דוד","b":"חתן ר אברהם יצחק הלר מצפת. אדמור בקרצינוב(=קרטשנוף) על מקום אביו, סיגט. נספה בשואה. בנו ר מרדכי בהקדמה לספר זקנו \"נפש דוד\"."},{"i":13322,"n":"דייטש, משה מקאלין","f":"מנחם מנדל","b":"נכד ר יעקב מואג-ועטשע בנו של ר מרדכי בעל מור דרור. אב\"ד קאלין."},{"i":13323,"n":"דייטש, נח יעקב מסעליש","f":"יוסף ישראל-בן גרני","b":"חתן ר חיים פנחס קליין מסעליש. ר\"מ בישיבת סעליש. נפטר ללא ילדים. הניח חיבורים בכת\"י. נספד ע\"י גיסו ר יוסף נחמיה קורניצר בספר הדרושים שלו. נזכר בהקדמת אחיו ל\"בן גרני\"."},{"i":13324,"n":"דייטש, פלטיאל מזלוטשוב","b":"תשובה אליו - טוט\"ד."},{"i":13325,"n":"דייטש, פנחס מאילאווא","f":"צבי מנאמעסטא","b":"חתן ר דוד דייטש בעל אוהל דוד (וגיסו של מהר\"ם א\"ש). רב באילאווא-תרל."},{"i":13326,"n":"דייטש, צבי הירש","b":"רב בנאוומסטא-תקפ\"ח"},{"i":13327,"n":"דייטש, רפאל הלוי מסעפלאק","f":"מנחם מנדל מנאפראד","b":"תלמיד הכת\"ס, חתן רבו הכת\"ס-תרטו. מחכמי סעפלאק. (אלמנתו נישאה בזיוו\"ש לר צבי הירש וייס מדומברובה)."},{"i":13328,"n":"דייטש, שלמה מנייטרא","f":"אברהם","k":"בעל שדה צופים","bp":"סערדאוהל","dt":"תרם - ז שבט","dp":"נייטרא","b":"תלמיד החת\"ס, ור יהודה אסאד. רב בנייטרא-תרו, איפלשאג-תריא, נייטרא-תרלב. דרשות ממנו בספר תלמידו \"כתבי מהרי\"ח\" וויצען תרעא. ?? לא באוצר ??"},{"i":13329,"n":"דייטש, שמואל מגרוסורדין","f":"ראה גם: דייטש, ישעיה","b":"רב בכפר דיולא(=ג'אלו)-ליד קלויזנבורג - באמצע המאה ה-19. עבר לגרוסורדין והיה שם מגיד. (כנראה נרשם בטעות באוצר הרבנים ובעוד רשימות - שמואל - ובאמת הוא ר ישעיה דייטש מקש-ג'ולה שעבר לגרוסורדין)."},{"i":13330,"n":"דייטש, שמואל מסמבור","k":"בעל עבודת הקרבנות","b":"חתן ר מרדכי טאסק מפרשבורג. רב מחוז סמבור-תרח מטעם השלטון. הגיש תזכיר-תריא לממשלה האוסטרית - לתקן את היהדות הגליצאית ע\"י העברת אוכלוסיה לחקלאות, הנהגת לבוש אירופי, דיכוי החסידות ומנהיגיה. הבנקאי מאיר קליר מברודי ניסה באמצעות רצ\"ה חיות לגייס את תמיכת החרדים לרעיון המעבר לחקלאות. חתנו - ר שלמה זלמן באניהאד מפרשבורג בעל \"מנחה טהורה\"."},{"i":13331,"n":"דייטש, שמחה בונם מקעלטשע","f":"רפאל הלוי מסעפלאק","k":"בעל שפתי בינה","bt":"תרל","bp":"ספלאק-ליד מרגרטן","dt":"תרעח - יט אב","b":"נכד הכת\"ס. תלמיד דודו השב\"ס. חתן הגביר ר אברהם סולומון מנאדי-באניא. מחכמי קעלטשע. ?? לא באוצר ??"},{"i":13332,"n":"דייטש, שמעון הלוי מאנטורפן","f":"רפאל מסעפלק-חתן הכתס","bt":"תרכה","bp":"סעפלק","dt":"תרפח","dp":"פפד\"מ","b":"נכד הכת\"ס. תלמיד השב\"ס. חתן ר יצחק צבי רצרסדורפר מאנטורפן, ועבר לשם."},{"i":13333,"n":"דייטש, שמעון מזליחוב","b":"רב בזליחוב-תק\"ס"},{"i":13334,"n":"דייטש, שמעון מירושלים","f":"אברהם אהרן","k":"בעל שדים סופדים","bp":"רודניץ","dt":"תרלח - ט שבט","dp":"ירושלים","b":"נכד ר יוסף דייטש מרודניץ. תלמיד ר רפאל שולהוף מפרג, החת\"ס והכת\"ס. עלה לירושלים-תרב ונשא אשה מעדות הספרדים, ובזיוו\"ש חתן משפחת בהר\"ן בירושלים. ממיסדי כולל אונגרין. בנו ר יצחק ממיסדי ישיבת \"תורת חיים\" בירושלים. מסופר כי החת\"ס התפעל ממדת החסד שלו - מזמן רעידת האדמה בצפת - והעניק לו ספר חובות הלבבות האישי שלמד בו בצעירותו עם הקדשה מיוחדת. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז.","bk":[["זבחי צדק - זבחים (כת\"י)",""],["סוד ה' - קבלה (כת\"י)",""],["שדים סופדים - הספד על החתם סופר, והכתב סופר",""],["שירת רש - על התורה (כת\"י)",""]]},{"i":13335,"n":"דייטש, שמעון מראוויטש","b":"תלמיד השב\"ס. מחכמי ראוויטש-תרם. תשובה אליו ב\"שבט סופר\"."},{"i":13336,"n":"דייטש, שמעון צבי מפיורדא","f":"יהודה","k":"בעל אור הגנוז","bt":"תרטז תריח","dt":"תרפט - בערך","b":"תלמיד הכת\"ס, ור עזריאל הילדסהימר. הו\"ל במיינץ יחד עם האב\"ד ר מאיר להמן את העתון \"דער איזראעליט\". מלמד בפפד\"מ-תרמה. רב הגליל בבורגפרעבאך-מדינת גרוספלד, פיורדא-תרנה."},{"i":13337,"n":"דייטש, שמעיה משוראן","f":"ישראל זכריה מאפאטשי","k":"בעל דברי שמעיה","dt":"תרצא - יב טבת","dp":"ליפובה (ליד שוראן)","b":"תלמיד השב\"ס, ור משה גרינולד מחוסט. חתן ר משה איבנשיץ משוראן. שו\"ב בשוראן, גאלאנטא, פעקעטע-ארדויא. ?? לא באוצר ??"},{"i":13338,"n":"דייטשלנדר, שמואל מפוחאף","f":"משה","k":"בעל מראה הלבנון","bt":"תקסו","bp":"בסקביץ","dt":"תרמג - ב אב","b":"תלמיד החת\"ס, ור בנימין זאב רפפורט מפאפא. רב בפוחאף-תרלה. ?? לא באוצר ??"},{"i":13339,"n":"דייטשמן, חיים","b":"מגדולי חכמי דורו, רב בגיויטש, הארשיץ, טריביטש, קאלין-תקע. מתלמידיו - ר אריה ליב שוואב, ר חיים פולק, ר צבי."},{"i":13340,"n":"דייטשמן, יעקב מאיר אשכנזי","f":"יצחק יהודה מבארלאד","b":"רב בבארלאד-מולדובה-תרל על מקום אביו, והיה מחלוקת על כך עם ר יצחק איזיק טויבש ועל כך ב\"הגו סיגם\" למברג תרלא, ובו מכתבי הרבנים שתמכו בו, וכנגדו פרסם ר יצחק טויבש את \"העקב למישור\"."},{"i":13341,"n":"דייטשמן, יצחק יהודה מבארלאד","f":"ר\"ז","b":"רב בבארלאד-תריב ובנו ר יעקב מאיר על מקומו אחריו. כנראה הוא שהיה גם רב בחרסון, תשובה ממנו ב\"צמח צדק\" בעינן עגונות, הסכים על \"ראשון לציון\" אודסה תרכז."},{"i":13342,"n":"דייטשר, אברהם מקראקא","f":"יצחק","k":"בעל תולדות רבנו תם","bt":"תרכה","bp":"קראקא","dt":"תרפה","b":"מחכמי קראקא. חיבר \"תולדות רבנו תם\" קראקא תרף. ?? לא באוצר ??"},{"i":13343,"n":"דייטשר, יעקב קופל מקראקא","b":"מחכמי קראקא וממשתתפי \"אהל מועד\"-תרנט."},{"i":13344,"n":"דייטשר, משה מקראקא","f":"שאול חנניה","bt":"תרם","bp":"קראקא","dt":"תשא","b":"חסיד גור. מדפיס בקראקא. פעיל ב\"אגודת ישראל\" וביסוד \"בית יעקב\" לבנות."},{"i":13345,"n":"דייטשר, שאול חנניה מקראקא","bt":"תרך","bp":"קראקא","dt":"תרע","b":"מחכמי קראקא ומדפיס. חסיד גור."},{"i":13346,"n":"דייכס, אהרן זליג","f":"דוד יהודה ליב מוילנא","dt":"תריט - ה אייר","dp":"וילנא","b":"מחכמי וילנא. מחותן עם ר ליבל איזיק'ס-מו\"צ בוילנא."},{"i":13347,"n":"דייכס, אליהו יהודה מירושלים","f":"דוד","bt":"תקעו","dt":"תריח - כד חשון","dp":"ירושלים","b":"אב\"ד שירווינט ניישטט(=ניישטט-שאקי), אביו ר דוד היה אב\"ד באושיאק, חתן - ר שמואל מדלהינוב, עלה לירושלים, השאיר ספרים בכתב יד, חתנו - ר אליהו סטרעלצר מירושלים."},{"i":13348,"n":"דייכס, אליעזר אליהו מוילנא","f":"שלמה צבי הירש","bt":"תקנח","bp":"וילנא","dt":"תרמב - טו תשרי","dp":"וילנא","b":"נולד בשנת פטירת הגר\"א ונקרא על שמו. רב בואראנאווא, פאדזעלווע, איישישוק, שניפישוק על מקום ר דוד יהודה טילס, דיין בוילנא כ-55 שנה על מקום אביו. 20 מבניו ובנותיו נפטרו בחייו."},{"i":13349,"n":"דייכס, אריה ליב מלידא","f":"אליהו ורקיס מקראקא","b":"רב בלידא, הורדנא-תקע. בניו: ר שמואל מוילנא, ר דוד מאיישישוק, ר מאיר - מו\"צ בקובנא."},{"i":13350,"n":"דייכס, אריה ליב צבי מקובנא","f":"דוד מאישישוק","k":"בעל זבחי תרועה","bt":"תריג","dt":"תרנא - כז אלול","dp":"קובנא","b":"רב ודיין בקובנא, דרשונישוק. בנו ר ישראל חיים בעל \"פרחי האביב\". (באוצר נולד - תקצג)."},{"i":13351,"n":"דייכס, בנימין מוילנא","f":"דוד יהודה ליב מוילנא","dt":"תרלד - יב תשרי","dp":"ליובטש","b":"מחכמי וילנא. נתברך בילדותו מפי הגר\"א וחי כ-88 שנה. נפטר ערירי."},{"i":13352,"n":"דייכס, בצלאל מאנגליה","f":"ישראל חיים מאנגליה","bt":"תרלט","bp":"וילנא","dt":"תשה","dp":"אדינבורג","b":"תלמיד ביהמ\"ד לרבנים בברלין ונסמך מאת: ר בצלאל (שלמה?) הכהן מוילנא. תלמיד אוניברסיטת ברלין ולייפציג. רב בהול-אנגליה-תרסד, סנדרלנד, אדינבורג. סגן נשיא ההסתדרות הציונית באנגליה ואירלנד. מנהיג \"בני ברית\". יו\"ר מועצת החינוך בסקוטלנד. פרסם מאמרים בפילוספיה ויהדות. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":13353,"n":"דייכס, דוד מאישישוק","f":"אריה ליב מלידא","dt":"תרכ - ט תשרי","b":"רב באיישישוק. בניו: ר אליהו יהודה מניישטט שירווינט, וילקוביסק, ר אריה ליב צבי בעל \"זבחי תרועה\", ר שמעון נטע מוילנא."},{"i":13354,"n":"דייכס, יהודה ליב מוילנא","f":"צמח","bt":"תקטו","dt":"תר - כט תמוז","b":"גביר בוילנא. אחיו של ר שלמה צבי הירש-מו\"ץ בוילנא. גבאי וחתם בפנקס הגר\"א-תקנט, ועוד. פרנס הקהלה עם ר ליבעלי ר בערש, ועם ר זלמן ר אורי'ס. בניו: ר בנימין שנתברך מפי הגר\"א, ר ישראל שסירב לרבנות פאסוויל, ר אהרן זליג. חתניו: ר ברל יורבארגער, ר ברל הכהן לאפ."},{"i":13355,"n":"דייכס, יעקב מרדכי מקראקא","b":"דיין בקרקא-תכ\"ו"},{"i":13356,"n":"דייכס, ירוחם","f":"מרדכי דייכש","b":"דיין בקרקא-תצ\"א"},{"i":13357,"n":"דייכס, ישראל חיים מליטא ואנגלי","f":"אריה ליב צבי","k":"בעל דרשות מהרי\"ח","bt":"תרכ","bp":"דארשונישוק","dt":"תרצז - טו תמוז","b":"תלמיד ישיבות קובנא, סלובודקה. חתן ר משה ביעליצקי(=טשערנעס?) מוילנא. מגדולי דורו, רב בניישטט-שאקי(=שירווינט)-תרמה, ולדיסלבוב-פלך סובאלק, לידס-אנגליה-תרנז או תרסא. חיבר גם \"פרחי האביב\", \"אמרי חן\", \"טהרת הקדש\" והיה מחלוקת עליו וכנגדו יצא \"להבדיל בין הטמא\" לר מרדכי צבי שורץ מטשיק-סערעד וקליבלנד. הו\"ל בלידס-תרסב \"בית ועד לחכמים\" - מאסף תורני. בניו: ר שמואל מלונדון, ר בצלאל מסנדרלנד-אנגליה."},{"i":13358,"n":"דייכס, ישראל מוילנא","f":"דוד יהודה ליב מוילנא","dp":"וילנא","b":"חתן ר איזיק קרינקער. סירב לרבנות פאסוול."},{"i":13359,"n":"דייכס, מאיר מקובנא","f":"אריה ליב מלידא","k":"בעל מאיר עיני חכמים","dt":"תקץ - בערך","b":"מו\"צ בקובנה-תרך. חתם בפנקס חברה \"לומדי ש\"ס\"-תקפד. חיבר מאמר \"מאיר עיני חכמים\" בקובץ \"בית ועד לחכמים\" לונדון תרסב."},{"i":13360,"n":"דייכס, מרדכי","dt":"תסו - כט טבת","b":"דרשן,ראב\"ד בקרקא"},{"i":13361,"n":"דייכס, רפאל מוילנא","f":"נטע","b":"דיין בוילנא? חתם על פסק מעשה רב-תקצה."},{"i":13362,"n":"דייכס, שלמה צבי הירש","dt":"תקפו - כד ניסן","b":"מו\"צ בווילנה"},{"i":13363,"n":"דייכס, שמואל","f":"אריה ליב מלידא","dt":"תקפו - ד ניסן","b":"חתן ר זאב וולף בן אהרן מרזיווענישוק-אחיינו של ר שמואל האב\"ד האחרון בוילנא. דיין בוילנא אצל ר אבלי. אחיו - ר מאיר מקובנא, ר דוד מאישישוק."},{"i":13364,"n":"דייכס, שמואל יצחק מלונדון","f":"ישראל חיים מניישטט","k":"בעל ספרות הבבלים","bt":"תרלז-ח","bp":"וילנא","dt":"תשט","dp":"לונדון","b":"תלמיד ביהמ\"ד לרבנים בברלין. נסמך מאת: ר בצלאל הכהן מוילנא, ר דוד צבי הופמן. תלמיד אוניברסיטת ברלין ולייפציג. רב בסנדרלנד-אנגליה-תרסה, מורה בביהמ\"ד לרבנים בלונדון. חוקר ההלכה והמדרש. מגדולי חכמי ישראל באנגליה. נשיא \"בני ברית\" באנגליה. חיבר ספרים באנגלית וגרמנית בנושאי יהדות. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":13365,"n":"דיין בפראג","dt":"תקסו","bk":[["הגהות רבי יעקב יהודה אויש",""]]},{"i":13366,"n":"דיין ן, שמואל מחלב - ב","dt":"תפב","b":"רב בחלב, מצאצאי ר שמואל ן דיין. נספד ע\"י ר שמואל לנאידו."},{"i":13367,"n":"דיין, אברהם מאזמיר","dt":"תקסג - טו אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":13368,"n":"דיין, אברהם מחלב","f":"ישעיה","k":"בעל שיר חדש","dt":"תרלז - יז חשון","dp":"חלב","b":"דיין בחלב, חיבר גם \"טוב טעם\", \"ויוסף אברהם\", \"הולך תמים ופועל צדק\"."},{"i":13369,"n":"דיין, אהרן מחלב","k":"בעל בית אהרן","dt":"תרנד - יד תשרי","b":"מחכמי ארם צובה, \"אור כשדים, אורפה, דיין, חכם באשי, חיבר \"בית אהרן\"-תרמ\"ז"},{"i":13370,"n":"דיין, אפרים מחלב","b":"דיין בחלב"},{"i":13371,"n":"דיין, דוד","dt":"תמו - ח חשון"},{"i":13372,"n":"דיין, דוד חי מצפת","dt":"תשמח","b":"רבה של צפת"},{"i":13373,"n":"דיין, דוד מחלב","b":"מחכמי חלב, בשליחות קהלת חלב-תרל."},{"i":13374,"n":"דיין, דון יצחק מספרד","f":"משה","k":"בעל נבון לב","b":"מחכמי ספרד בזמן הגירוש-רנב, עבר לאיטליה, תמך בר אברהם מינץ במחלוקת עם ר יוסף פולק. ?? לא באוצר ??"},{"i":13375,"n":"דיין, חייא מירושלים","b":"מחכמי ירושלים, חתם-תמח עם רבני ירושלים, ונזכר ב\"זרע אנשים\"."},{"i":13376,"n":"דיין, חיים מחלב","f":"משה","dp":"ארצות הברית","b":"דרשן,מוהל וש\"ץ בחלב,מרביץ תורה,התפרנס מסחר בתשמישי קדושה"},{"i":13377,"n":"דיין, ידידיה מחלב","f":"מרדכי","dt":"תקף","dp":"חלב","b":"דיין בארם צובה"},{"i":13378,"n":"דיין, ידידיה מחלב","f":"מרדכי","bt":"תקע","dt":"תרנח - כד חשון","dp":"חלב","b":"חכם שלם,מוהל ראשי בארם צובה"},{"i":13379,"n":"דיין, יחיאל מבאלטא","f":"צבי","bt":"תריד-ט","b":"רב בבאלטא-תרלט על מקום אביו."},{"i":13380,"n":"דיין, יצחק הלוי מאזמיר","f":"מאיר","b":"מחכמי קושטא, תלמיד ר יוסף טרני ונזכר בשו\"ת מהרי\"ט, רב באזמיר-שפ לצדו של ר יוסף אישקאפא (היה רב של 3 הקהלות הותיקות). לאחר שנסתמא נשאלו רבני קושטא האם יכול להמשיך לכהן ור יהושע בנבנישתי השיב שיכול להמשיך."},{"i":13381,"n":"דיין, יצחק הלוי מצפת","f":"משה","b":"רב בצפת בזמן ר יוסף קארו. חתם עם ר יוסף קארו ור משה טרני המבי\"ט על תשובה לאיטליה."},{"i":13382,"n":"דיין, ישראל מדמשק","dt":"תרלה - ט אב","dp":"דמשק","b":"רב בדמשק."},{"i":13383,"n":"דיין, מאיר רחמים מאר\"ץ","f":"משה-ישיר משה","dt":"תשלד - ד טבת","b":"רב בחלב, עלה לארץ."},{"i":13384,"n":"דיין, מרדכי מחלב","dt":"תקא - יג אב","b":"חתן ר חיים בן ישעיה עטייה. מחכמי חלב. הספידו ר גבריאל אשכנזי."},{"i":13385,"n":"דיין, מרדכי מחלב","f":"משה","b":"רב בחלב-שן בערך."},{"i":13386,"n":"דיין, משה ממראקש","dt":"תשו","dp":"מראקש","b":"רב ומקובל במראקש, ראש חרת הרשב\"י ומלמד קבלה לתלמידים."},{"i":13387,"n":"דיין, משה מקהיר","k":"בעל ליקוטי חמד","r":"אדמו\"ר מפרימישלאן","bt":"תרצא","bp":"קהיר","dt":"תשלט","dp":"ירושלים","b":"תלמיד ר עובדיה יוסף בקהיר, עבר לפריס וכיהן כרב ראשי בצרפת, עלה לארץ-תשכג, רב בסאן פאולו-ברזיל-תשלב.","bk":[["ליקוטי חמד",""]]},{"i":13388,"n":"דיין, משה מקושטא","b":"מחכמי קושטא-שנות ה-ש'-ת'."},{"i":13389,"n":"דיין, נח","k":"בעל תולדות נח","dt":"שצח - ג אדר","b":"מגדולי חכמי קרקא. ?? לא באוצר ??"},{"i":13390,"n":"דיין, עזריה מטריפולי","f":"מעתוק","bt":"תק","dt":"תקע - בערך","dp":"טריפולי","b":"תלמיד ר מסועד רוקח. מחכמי טריפולי-תקלח וחתם אז על תקנת הגאבילה."},{"i":13391,"n":"דיין, פרץ","dt":"תסו","b":"ראב\"ד בניקלסבורג"},{"i":13392,"n":"דיין, צבי מבאלטא","b":"רב בבאלטא-פודוליה-תרך ובנו ר יחיאל על מקומו אחריו."},{"i":13393,"n":"דיין, שאול מחלב","f":"אברהם","k":"הו\"ל שבחי הארי","b":"מחכמי חלב, הו\"ל \"שבחי האר\"י\". חיבר \"לקוטי תפלות\" בכת\"י. ?? לא באוצר ??"},{"i":13394,"n":"דיין, שלמה ממרוקו","dt":"תשו","dp":"מראקש","b":"מקובל מחכמי מראקש, וראש חברת הזהר. ידידו ורבו של ר שלום ביטון בקבלה."},{"i":13395,"n":"דיין, שמעון ממרוקו","f":"אליהו","k":"בעל זהב שבא - תשלז","bt":"תרע","bp":"דרעא-מרוקו","dt":"תשלה - ה ניסן","b":"אחיינו של ר שלמה דיין מראקש. תלמיד ר יעקב ן חמו שגדלו בביתו. למד יחד עם ר מאיר בנו של הבבא סאלי, ור אברהם בנו של הבבא חאקי, והבבא סאלי קירבו והיה קורא לו מאז בשם \"שמעון בני\", עבר עם רבו ר יעקב - שהיה לימים לגיסו, למוגדור, מכנאס ועוד, ובמהמשך הקימו עסק מסחרי ועסקו ביחד במסחר ובתורה. למד גם אצל ר יצחק סבאג ממכנאס, ור יעקב דהאן ממראקש. דיין בדמנת-מרוקו - תשטו, מראקש-תשך, קזבלנקה-תשכז, עלה לארץ-תשלג. חיבר חיבורים רבים בכת\"י."},{"i":13396,"n":"דיין-דייאן, חייא מחברון ומרוקו","f":"יוסף","k":"בעל אדרת אליהו","bp":"ירושלים","dp":"מכנאס","b":"מחכמי ירושלים ואחר כך חברון, ממשפחה המתייחסת לדוד המלך, בשליחות חברון וירושלים מספר פעמים במדינות רבות. חיבר \"אדרת אליהו\", הרביץ תורה בסאלי-מרוקו ומכנאס, בין תלמידיו היה ר חיים ן עטר הראשון סבו של \"אור החיים\", היה בין הלוחמים בשבתאות (אך לפי טולדנו-נר המערב היה שבתאי), השתקע בסאלי (יחד עם ר אלישע אשכנזי-אביו של נתן העזתי) ולאחר מכן במכנאס ושם נפטר."},{"i":13397,"n":"דיינארד, אפרים","bt":"1846","dt":"1930","b":"סופר וחוקר.","bk":[["אור מאיר",""],["כל ספרי ישראל",""],["מגלת סתרים",""],["ספרת ציון",""],["קהלת אמעריקא",""],["שבלים בודדות",""]]},{"i":13398,"n":"דיינה, דוד חיים מרוויגו","f":"אברהם שמואל","b":"רב ברוויגו יחד עם ר יצחק מודנא. הניח פסקים ושו\"ת בכת\"י. מובא ב\"לקוטי שושנים\" לר מרדכי שמואל גירונדי."},{"i":13399,"n":"דיינה, יעקב","b":"תשובה אליו ממהר\"ם פדובה."},{"i":13400,"n":"דיינה, עזריאל מאיטליה","b":"מגאוני איטליה הקדמונים. נזכר בתשובות מהר\"ם פדובה."},{"i":13401,"n":"דיינוב, ישראל מלונדון","f":"אברהם","bt":"תקצז","b":"תלמיד ישיבות ליטא. ר\"מ בחברת ש\"ס בוילנא, רב בלונדון-תרמב."},{"i":13402,"n":"דיינובסקי, דוד טעבל ממאלטש","f":"אלחנן","bt":"תרכה","dt":"תשג","b":"מרביץ תורה,מגדולי המוסר, דומ\"צ בווילקי-פלך קובנא-תרמו, ר\"מ בלומזה-תרנג, רב במאלטש-תרסז, פיאנטניצא."},{"i":13403,"n":"דייסוס ן, בנימין מונציה","f":"שמואל מונציה","b":"מחכמי ונציה, עמד לידמינו של ר ידידיה גלנטי-שסט עם פרנסי ונציה. נזכר באגרת מר יהודה אריה ממודנא בשם חכמי ונציה לקושטא בענין יבמה שחמיה ר ישמעאל מוולטירה הביאה לונציה - והזכיר את עזרתו של הגביר ר בנימין דייסוס שאספה לביתו וסייע לה בכסף."},{"i":13404,"n":"דייסוס ן, שמואל מונציה","f":"בנימין","b":"מחכמי פאטרץ-יוון, תלמיד ר שם טוב מלמד. עבר לונציה - כנראה עוד לפני גירוש היהודים מפאטרץ-שנו. והיה מדפיס ומגיה בונציה-שנו. חיבר הקדמות לחלק מהספרים שהדפיס, היה הראשון שהדפיס פאקסימיליה של חתימת ידו ב\"אגרת דופי הזמן\" לר יצחק עובדיה מפאטרץ. (השירים שנדפסו ב\"כתר שם טוב\" ו\"דברי שלום\" - אינם משלו - אלא של ר יהודה אריה ממודנא. בנו ר בנימין מחכמי ונציה."},{"i":13405,"n":"דייץ, אליהו מהמבורג","f":"יצחק משה","k":"בעל פי אליהו","b":"מחכמי המבורג-תס. חיבר \"פי אליהו\" - אלטונא תצה על פרק שירה לזכר בנו ואביו."},{"i":13406,"n":"דייץ, בער מוילנא ולובלין","f":"יצחק איזיק מוילנא","b":"למד רפואה והיה רופא בצבא פולין, עבר ללובלין. חיבר פירוש על הכוזרי - בכת\"י."},{"i":13407,"n":"דייץ, דוד הכהן (כץ) מקורוטשין","k":"בעל פעמוני זהב","dt":"תקלו","b":"דיין ודרשן בקורוטשין. חיבר \"מנחת כהן\", \"פעמוני זהב\" פיורדא תקכט."},{"i":13408,"n":"דייץ, יצחק איזיק מוילנא","f":"בנימין וולף מקניגסבר","k":"איזיק קרינקער","b":"חתן ר הרץ מקריניק(=קרינק) ועבר לשם. דיין בוילנא-תקצה בזמן ר שאול ור אבלי. מחותן עם ר ליב'לי צמח'ס. מדקדק ובקי בשפות. הסכים על ש\"ס סלאויטא-תקצה. מבניו: ר בער דייץ הרופא."},{"i":13409,"n":"דיכטוולד, אליעזר ליפמן מאיר הכ","b":"תלמיד ישיבת \"דעת משה\" בוארשא. רב באפטא, סלופיא חדש (פולין). פרסם מאמרים ב\"הכרם\" - וארשא תרצא, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":13410,"n":"דיכטוולד, אליקים גצל הכהן","f":"שמחה בונם","bt":"תרכא","dt":"תש..","b":"רב רב בווידיסלב, חלם, יבורוזנה, אב\"ד שצ'מיעשיץ, פינטקוב-ווענדרזיב(=יאוארזשנא)-תרכ, קאלעש. מאמרים ממנו ב\"שערי תורה\" - קראקא תרפה, \"קובץ דרושים\" - פיעטרקוב תרפג. נספה בשואה."},{"i":13411,"n":"דיכטוולד, זאב דוד הכהן מגירשקו","f":"שמחה בונם דיכטוול","b":"רב בגירשקוב-פלך לובלין-תרע."},{"i":13412,"n":"דיכטוולד, שמחה בונם מחעלמא","f":"אליקים גצל הכהן","bt":"תרכא","b":"נכד ר אליקום גצל מקלעש. מו\"צ בוודיסלב, רב בחלם-תרן. פרסם מאמרים ב\"שערי תורה\" - קראקא תרפה. בנו - ר זאב דוד מגירשקוב."},{"i":13413,"n":"דיכטר, אליעזר מפריז","dt":"תרפה","b":"שו\"ב בפריז. חותנו של ר יעקב קפלן הרב הראשי בצרפת."},{"i":13414,"n":"דיל, שלמה","b":"מקובל, ניבא-בשנת רעה - את נצחון השולטן סלים על מצרים."},{"i":13415,"n":"דילאטשי, יהודה מקרקסונה","f":"יעקב בן אליה בן יצחק","k":"בעל ספר האסופות","b":"מחכמי פרובאנס. נזכר ב\"אורחות חיים\"."},{"i":13416,"n":"דילובין, ישראל מאר\"ץ","f":"אלישע","b":"רב ודיין באר\"ץ-תקכג עם ר יהודה קצין ור רפאל שלמה לאניאדו."},{"i":13417,"n":"דילוג'י, דניאל מאדרינופול","b":"רב באדרינופול-שנות ה-ש'."},{"i":13418,"n":"דילון, מרק","f":"אריה","bt":"1843","bp":"פוניבז","dt":"1903","dp":"פטרבורג","b":"תלמיד ביהמ\"ד לרבנים בוילנא. למד משפטים במוסקבה. חבר ביה\"ד המוחוזי בפירם, קאזאן-1878. מגדולי עורכי הדין היהודים ברוסיה."},{"i":13419,"n":"דיליריא, גבריאל מליוורנו","dt":"תפח - י תמוז","b":"מקובל מחכמי ליוורנו,נפטר בדרך לירושלים. תשובות ממנו ב\"אורח לצדיק\", \"פני הכרובים\", \"דברי יוסף\". קינה עליו מאת ר מלאכי הכהן מליוורנו."},{"i":13420,"n":"דילישקש, יעקב מקושטא","k":"בעל אמרי נועם","b":"חיבר פירוש לתורה \"אמרי נעם\" - קושטא ש."},{"i":13421,"n":"דילמידיגו, אבא מקנדיאה","f":"יהודה","b":"רופא מחכמי קנדיה-קן בתקופת הרשב\"ץ. עשיר ובנה בתי כנסיות והקדיש ספרי תורה ועוד. נזכר בספר \"אלים\". בניו: ר אלקנה, ר משה, ר אליהו, נינו - יש\"ר מקנדיה בעל \"אלים\"."},{"i":13422,"n":"דילמידיגו, אבא מקנדיאה","f":"שמואל מנחם","b":"רב בקנדיה-ש'. אביו של ר אליעזר-אביו של ר אליהו-אביו של יש\"ר מקנדיה."},{"i":13423,"n":"דילמידיגו, אליהו מקנדיא","f":"משה בן אבא","k":"בעל בחינת הדת","bt":"ש?","bp":"קנדיא","dt":"רנו","dp":"קנדיא","b":"מחכמי קנדיה(=כרתים), בא לאיטליה-רכ, רב בבאשן, פירנצי, פדובה, ונציה בזמן מוהר\"י מינץ שהיה בר פלוגתיה (בענין סתם יינם) והמחלוקת גברה עד שהגיעה לרא\"ם בקושטא שפסק כמהר\"י מינץ, ולבסוף חזר לקנדיא. תלמיד מהרי\"ק ונזכר בשו\"ת מהרי\"ק. מתלמידיו ר שאול הכהן בן משה מקנדיא, תלמידו - השר הנוצרי פיקו דילה מירנדולה. בניו ר משה ור יהודה (בר פלוגתיה של מוהרם אלאשקר). מצאצאי ר יהודה הראשון שבא מאשכנז והתישב בקנדיאה והיה אבי משפחת הרבנים. חיבר \"בחינת הדת\" - כנגד למוד קבלה, וכנגדו חיבר יש\"ר מקנדיא - \"מצרף לחכמה\" (ובאמת חשש מהנוצרים שהשתמשו בקבלה להצדיק את הנצרות), ועוד חיבורים גם בלטינית."},{"i":13424,"n":"דילמידיגו, אליהו מקנדיא","f":"אליעזר מקנדיאה","b":"נכד ר אבא בן מנחם בן שמואל בן אלקנה בן אבא הזקן בן יהודה (כולם מחכמי קנדיא). רב בקנדיא-שס. חתן ר יוסף מקושטא-נכדו של מהר\"ם כומטני, אביו של היש\"ר מקנדיאה בעל ספר אלים. חתם בפסק \"דרך ימין\" למהר\"י סאמיגה."},{"i":13425,"n":"דילמידיגו, אליעזר מקנדיא","f":"אבא בן שמואל או מנחם","b":"זקנו של יש\"ר מקנדיא. מחכמי קנדיא(=כרתים)-ש', למד במצרים אצל ר יצחק בירב, אולי גם תלמיד ר' יוסף קארו, מהריב\"ל ונזכר בשו\"ת מהריב\"ל שר אלעזר שאל שאלה על מחלוקת בינו לבין גיסו ר יצחק חן. חתם בפסק \"דרך ימין\" למהר\"י סאמיגה עם שאר דייני קנדיאה. בנו - ר אליהו ונכדו גם ר אליעזר. היה במחלוקת עם הרמ\"ע."},{"i":13426,"n":"דילמידיגו, אלקנה מקנדיא","f":"אבא","b":"רב בקנדיא עם אחיו ר אליהו ור משה (שעלה לירושלים). הגנו על קרובם ר משה קפסלי במחלוקת כנגד מהר\"י קולון. בנו ר שמואל ומצאצאיו יש\"ר מקנדיא."},{"i":13427,"n":"דילמידיגו, יהודה","f":"אליהו דילמדיגו","b":"מחכמי איטליה-שנת ש'"},{"i":13428,"n":"דילמידיגו, יהודה","b":"מחכמי קנדיה"},{"i":13429,"n":"דילמידיגו, מנחם מארטא - ב","b":"רב קהלת קלבאריא בארטא, עלה לצפת-של."},{"i":13430,"n":"דילמידיגו, מנחם מקנדיא - א","f":"שמואל","b":"תלמיד ר יוסף קולון-מהרי\"ק. רב בקנדיאה-רפ, (קהלת קלבאריאה בארטא - הכוונה לרב אחר באותו השם בשנת - של). נלקח בשבי במלחמת ונציה עם הקיסר והגיע לאיטליה - והתמנה לרב וראש ישיבה בפדובה-רסט, בזמן ר יהודה מינץ."},{"i":13431,"n":"דילמידיגו, משה","f":"אבא הזקן מקנדיא","dp":"ירושלים","b":"בנו של ר אבא הזקן מקנדיא, עלה לירושלים-רע. נמנה על תומכיו של ר משה קאפסאלי."},{"i":13432,"n":"דילמידיגו, שמריהו מקנדיא","f":"יהודה","b":"מחכמי קנדיא-כרתים, בזמן ברשב\"ץ. בנו ר משה הוא אביו של ר אליהו בעל \"בחינות עולם\"."},{"i":13433,"n":"דילר, דוד מירוסלב","b":"רב בירוסלב לפני השואה. גיסו של ר מיכל בארער."},{"i":13434,"n":"דילר, חיים מאושפיצין","dt":"תרצב","b":"נכד הרב מזאטור. מחכמי יאסלו, אושפיצין. רב צבאי."},{"i":13435,"n":"דילר, יוסף משה","b":"חתן ר משה פליק מזאטור. נכד ר שמחה מניישטט (שרמ\"מ מרימנוב העיד כי עליו עומד שליש העולם)."},{"i":13436,"n":"דילרוזה, חיים מירושלים","k":"בעל תורת חכם","bp":"אזמיר או ירושלים","dt":"תקמו - ג תמוז","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים, ולמד אצל ר שלום שרעבי והחיד\"א. מחכמי המקובלים בישיבת בית אל, ונחשב ליד ימינו של ר שלום שרעבי-הרש\"ש. חיבר \"תורת חכם\" שלוניקי תרח. (לפי כנסת ישראל תאריך פטירתו - ו חשון). חתם-תקיב על שטר התקשרות חברים."},{"i":13437,"n":"דילרוזה, משה ישראל","b":"מחכמי ארץ ישראל, בשנת תיט בשליחות באשכנז."},{"i":13438,"n":"דילרוזה, רחמים מחלב","dt":"תרן - טז אייר","dp":"ירושלים או חלב","b":"מחכמי חלב וירושלים, בשנת תרלא בשליחות בארצות ערב, ואחר כך בשליחות באירופה,"},{"i":13439,"n":"דילריאו, גבריאל מליוורנו","f":"דוד","dt":"תצח - ה סיון","dp":"כפר שיזור","b":"רב בליוורנו, מגינו של הרמח\"ל, חתם על תשובה אחרי ר רפאל ברוך ור מנחם עטיאס - תצא. בשות \"שמש צדקה\" חתם עם רבני ליוורנו על פסק בנוגע לתפלין בחול המועד. בשנת תצו הסכים על ספרו של ר יוסף אירגאס \"שומר אמונים\", עלה לארץ-תצח ונפטר בהיותו בדרך ליד קבר ר שמעון שזורי בכפר שיזור. נספד על ידי ר מלאכי הכהן מליוורנו. נזכר בשו\"ת \"מים רבים\"."},{"i":13440,"n":"דילשפילש, יהודה"},{"i":13441,"n":"דים, אהרן הלוי מארה\"ב","f":"משה","bt":"תרנו","bp":"ליסקא-ליד סנוק","dt":"תשכה","b":"תלמיד קרובו ר נתן נטע יעקב דים מסנוק, ר אלעזר ברומר, ונסמך מהם ומאת: ר שמואל אנגל מרדומישל, ר י\"א איזנצוייג מנובומינסק. דיין באנטורפן-תרעז אצל ר\"מ רוטנברג הי\"ד. רב קהלת אנשי ליסקא בניו יורק-תרפה, וקהלות נוספות שם, ומנהל לשכת תקנת עגונות שע\"י \"דגל הרבנים\". חיבוריו ב\"הפרדס\"-תרצא."},{"i":13442,"n":"דים, דב בריש","b":"רב בנאראיוב-תר\"פ"},{"i":13443,"n":"דים, יהודה מיפו","bt":"תרנד","bp":"פולין","dt":"תשכז","b":"ניצל מהשואה. עלה לארץ-תשט וכיהן כרב בשכונת עג'מי ביפו."},{"i":13444,"n":"דים, יעקב הלוי מלינסק","k":"יענקל ברייער","bt":"תקעה","dt":"תרף","b":"ראש הקהל מלינסק. חתן ר אלימלך טורם. גיסו של הדב\"ח. נפטר בן 105."},{"i":13445,"n":"דים, נתן נטע יעקב סגל מסנוק","bt":"תרך","bp":"לינסק","dt":"תרף","b":"רבה של זבורוב. סאנוק-תרנד והקים שם ישיבה."},{"i":13446,"n":"דים, שמעון","f":"חיים מקראסנא","b":"חתן ר נתן לוין מרישא. אביו היה גביר מקראסנא - נכד ר צבי הירש מסוקולוב בעל \"אמרת הצרופה\"."},{"i":13447,"n":"דימאיו, יצחק מקושטא","b":"גביר בקושטא-תצח, סייע לר יהודה נבון בהדפסת \"מחנה אפרים\" לאביו - ר אפרים נבון."},{"i":13448,"n":"דימטמן, ישראל","bt":"1901","bp":"סובאלק-ליטא","dt":"1944","dp":"מחנה שטוטהוף","b":"תלמיד ישיבות ליטא. למד באוניברסיטה בליטא. מורה בבי\"ס תרבות ביורבורג, טאווריג, קובנא. מנהל הגימנסיה העברית בוילנא. ביקר בארץ-1936. בזמן השואה היה בגיטו וילנא והיה פעיל בעניני חינוך. חיבר שם \"עד השער\" - דרמה באידיש מחיי הגיטו. נשלח למחנה קלואוגה-אסטוניה, ואח\"כ למחנה שטוטהוף. פרסם רומן ברוסית."},{"i":13449,"n":"דימיטיניא, יוסף אשכנזי מירושלי","b":"פרנס ירושלים-רמא, ונזכר אצל ר משלם בן מנחם מוולטארה."},{"i":13450,"n":"דימיטרובסקי, יעקב יוסף הלוי","b":"פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ."},{"i":13451,"n":"דימילאב, יוסף מקרפנטרץ","f":"מוסקאט, יוסף דמילאב","k":"בעל אוצרות יוסף","b":"חיבר \"אוצרות יוסף\"."},{"i":13452,"n":"דימנשטין, ליאופולד","f":"אליעזר","bt":"1865","bp":"ליטא","dt":"1927","dp":"קובנא","b":"עורך דין מפורסם בליטא. חבר עירית קובנא ומנהל הבנק לאשראי הדדי. פעיל בחיי הציבור היהודי."},{"i":13453,"n":"דין ישעיה בן מרדכי","k":"בעל זה כתב ידי","bt":"תקצג","bp":"אר\"ץ","dt":"תרסג","b":"רב באר\"ץ-תרן למעלה מיובל שנים. משפחת דיין היתה לפנים נקראת \"נשיא\". חיבר \"אמרי נועם\", צאצאיו הדפיסו \"חזון ישעיה\" ובו מתורתו ותולדותיו. חתנו - ר עזרא שעיו.","bk":[["אמרי נועם",""],["זה כתב ידי",""]]},{"i":13454,"n":"דין משה בן אברהם","f":"אברהם","k":"בעל ישיר משה","dt":"תרסא - ב ניסן","b":"מחמכי חלב","bk":[["ישיר משה",""]]},{"i":13455,"n":"דין, חיים אליעזר הרופא מירושלי","b":"רופא מחכמי ירושלים-סוף שנות ה-תק',"},{"i":13456,"n":"דינזון, אריה ליב","f":"יעקב מליבויא","b":"חתן ר אהרן שער מוורנה-פלך קובנא."},{"i":13457,"n":"דינזון, יעקב מליטא ווארשא","k":"בעל הערשעלע","bt":"1856","bp":"זאגר חדש","dt":"1919","dp":"וארשא","b":"סופר אידי. תלמיד ישיבות ליטא, מושפע מסופרי ההשכלה. פרסם מאמרים ב\"המגיד\", ועוד. חיבר רומנים באידיש שזכו לתפוצה רבה, ספרי ילדים. התגורר בקיוב, וארשא. היה במחלוקת עם ההיסטורין גרץ - על שלא החשיב בספרו את יהודי רוסיה, והיה במחלוקת עם סופרים עבריים שזלזלו בשפה האידית. חברו של י.ל. פרץ."},{"i":13458,"n":"דינזון-כהנא, יעקב זאב מפוסוואל","f":"אברהם מואסילקוב","k":"בעל שארית יעקב","b":"רב בגוורא(=גאוורי), קראק, פאסוואל-תר\"י. חיבר גם \"גבעת ירושלים\"."},{"i":13459,"n":"דינטי, חיים מיאנינה","b":"מראשי קהלת יאנינה-שנות ה-ת'."},{"i":13460,"n":"דיני ן, מאיר מאלגיר","bt":"[ש]","dt":"שע - בערך","b":"רב במסתגאנם, עם הדיין ר אהרן בן חגי ן אלזוק. נזכר בשות ר שלמה בר צמח."},{"i":13461,"n":"דינין, שמואל יהודה מדזינקוב","f":"יואל","bt":"תרכה","b":"רב בדזינקוב-פלך קיוב-תרמט."},{"i":13462,"n":"דינסזון, יעקב מוארשא","f":"בנימין","k":"בעל הנאהבים והנעימים","bt":"תרכב","bp":"זאגר חדש","b":"סופר. תלמיד ר אבא וילדא ממוהילוב. מורה לעברית. סוכן אצל הגביר הורביץ, התגורר בקיוב, עבר לוארשא. חיבר גם \"אבן נגף\", ועוד."},{"i":13463,"n":"דינסטג, בנימין בינוש מברנוב","f":"יעקב","k":"בעל תתן אמת ליעקב","bt":"תרלח","bp":"ברנוב","dt":"תשכו","dp":"ריישא","b":"היגר לארה\"ב-תרעג, רב בברוקלין. חיבר \"תתן אמת ליעקב\" ניו יורק תשיז."},{"i":13464,"n":"דינקלס, יוסף הלוי","k":"בעל אמונת יוסף","bt":"תרנד","dt":"תשלו","b":"תלמיד ר איצל'ה מפוניביז, ר ברוך בער ליבוביץ, ר חיים עוזר. עלה לארץ-תרפה עם ישיבת חברון, פרסם מאמרים ב\"שערי אמונה\" - ירושלים תרצה, \"תורת ארץ ישראל\" - ירושלים תרץ - תשובה לר יצחק בן מנחם מפתח תקוה. חיבר גם \"דעת יוסף\" ועוד."},{"i":13465,"n":"דינר, אליעזר מקראקא","k":"בעל דברתי דברי","b":"חיבר \"דברתי דברי\" ירושלים תשז. ?? לא באוצר ??"},{"i":13466,"n":"דינר, זאב יצחק הלוי מקלן","f":"אליעזר","bt":"תקצו","bp":"קראקא","b":"תלמיד ר\"ד במברגר, ובעל \"ערוך לנר\". מלמד בקלן, ואח\"כ עסק במסחר. היה למדן מופלג והתכתב עם גדולי דורו - ובהם ר יוסף זכריה שטרן, ר אליעזר ליפמן פרינץ (ראה בערכו מכתב ממנו), נזכר ב\"זכר יהוסף\". אחיו של ר יוסף צבי מאמשטרדם."},{"i":13467,"n":"דינר, יהושע השל מברוד","b":"מתורתו - \"גפן פוריה\"-תרפז."},{"i":13468,"n":"דינר, יוסף צבי מקראקא","f":"אליעזר","k":"בעל חדושי הריצד","r":"רב הקהילה באמשטרדם ומנהל בית המדרש לרבנים שם","bt":"תקצג","bp":"קראקא","dt":"תרעב","b":"תלמיד חכם שלמד גם באוניברסיטה וקיבל תואר דוקטור. עבר לאמשטרדם בהזמנת ר מאיר לעהרן ולימד שם בסמינר לרבנים. נתקבל כרבה של אמשטרדם בהשפעת ר עקיבא לעהרן. היה מעמודי התווך של היהדות החרדית המודרנית במערב אירופה. חיבר מאמרים רבים בשפות שונות, וביניהם חיבר \"הגהות והערות\" פפדמ תרנו. חיבר \"חדושי הריצ\"ד\" ירושלים תשמא.","bk":[["הגהות – ש\"ס",""],["הגהות על משנה תורה",""]]},{"i":13469,"n":"דינר, מרדכי ברוך מאושפיצין","b":"רב באושפיצין."},{"i":13470,"n":"דינר, נחמיה מצפת","b":"מראשי החסידים בצפת-תקפא."},{"i":13471,"n":"דיסיניי, דריווש מאיטליה ולוב","b":"רב בטורינו-איטליה, הוזמן לכהן כרבה הראשי של לוב-תרצא-תרצג."},{"i":13472,"n":"דיסנר, אלעזר","b":"חסיד ר שניאור זלמן בעל התניא. עלה לארץ והיה חברו של ר אברהם מקאליסק, וחזר מרוב געגועיו לרבו."},{"i":13473,"n":"דיספק, דוד","b":"תלמיד ר יעקב פופרש-תץ בערך."},{"i":13474,"n":"דיסקין, אברהם שמואל","f":"בנימין מהורדנא","k":"בעל לבני בנימין","r":"רב בפלונסק, ואח\"כ בוילקוביסק וראש ישיבה שם","bt":"תקפא","dt":"תרמז - יא טבת","b":"דיין בלומז'ה, רב בפלונסק, וילקוביסק-תרכה על מקום בעל \"עמודי אור\" וראש ישיבה שם. חיבר \"לבני בנימין\". אחיו של המהרי\"ל מבריסק וירושלים. פרסם מאמרים ב\"הפלס\" - ברלין תרסא-תרסה.","bk":[["לבני בנימן - ארבעים ואחת מערכות בכל מקצועות התורה",""]]},{"i":13475,"n":"דיסקין, אהרן יעקב","f":"שמעון משה דיסקין","bt":"תרס","dt":"תשלה - כו תמוז","b":"רב בלאכוביץ,מרביץ תורה בלוד-תש\"ט"},{"i":13476,"n":"דיסקין, בנימין מהורדנא","f":"יהודה ליב חסיד","k":"בעל שמלת בנימין","bt":"תקנח","bp":"סלונים","dt":"תרד - כה אדר","b":"רב בהורדנא-תקעח, וולקוביסק, אב\"ד בהורדנא(-גרודנא), רב בלומזה. מתלמידיו גיסו ר שמואל אביגדור מקרלין, ור יצחק אלחנן ספקטור. בניו ר יהושע ליב דיסקין המהרי\"ל, ר אברהם שמואל מוולקוביסק, ר זרח, ר נח יצחק. מאמר ממנו בשם \"שמלת בנימין\" ב\"הפלס\" - ברלין תרסא-תרסה..","bk":[["תורת האוהל (ר' בנימין דיסקין)","מפרשי ש\"ס - אחרונים"]]},{"i":13477,"n":"דיסקין, בנימין מקובנא","f":"זרח בן בנימין","b":"חתן ר מנחם מנדל בן זאב וולף מקובנא."},{"i":13478,"n":"דיסקין, זרח מהורדנא","f":"בנימין מהורדנא","bt":"תקפד","b":"נסמך מאת: ר יצחק אביגדור מקובנא, ר יו\"ט ליפמן מביאליסטוק. רב בהורדנא-תרכז על מקום אביו. הניח חדושים על הש\"ס. בנו - ר בנימין."},{"i":13479,"n":"דיסקין, יהושע זליג","f":"שמעון משה דיסקין","bt":"תרנח","dt":"תשלב","b":"רב פעלים,רב בבפרמיסלב-תרפ\"ה,עלה לא\"י תרצ\"ד,רב בפרדס חנה-תשל\"ב"},{"i":13480,"n":"דיסקין, יהושע זליג משומייאץ","dt":"תרלד - י תשרי","b":"צדיק מחכמי שומייאץ, וחברו של האב\"ד-ר יום טוב ליפמן בעל מלבושי יום טוב. מבניו - ר שמעון משה מלוחוביץ בעל מדרש שמעוני, ונכדו ר יהושע זליג מפריסלוב ופרדס חנה."},{"i":13481,"n":"דיסקין, יצחק","f":"בנימין דיסקין","b":"מו\"צ בלומזה-תר\"י"},{"i":13482,"n":"דיסקין, יצחק ירוחם מירושלים","f":"משה יהושע יהודה ליב","k":"תרפ\"ה","bt":"תרה (באוצר תקצז","dt":"תרפה","dp":"ירושלים","b":"מחכמי ליטא שעלה לירושלים בשנת תרסח, למד בישיבת וולוזין. היה ראש ישיבת \"אהל משה\" ובית היתומים שהקים אביו. מראשי הקהלה החרדית בירושלים. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה תרנג, \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\", \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":13483,"n":"דיסקין, מאיר מלומזה","f":"נח יצחק מלומזה","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":13484,"n":"דיסקין, משה יהושע יהודה ליב","f":"בנימין מהורדנא","k":"בעל שות מהריל דיסקין","r":"אב\"ד בלומז'א, קובנה, שקלוב, ובריסק","bt":"תקעט","bp":"גרודנא","dt":"תרנח - כט טבת","dp":"ירושלים","b":"רב בלומזה ונרדף לאחר שהוכיח את אחד התקיפים על עניני שבת, מזריץ', קובנא וגורש ע\"י שר הפלך לאחר שפגע בחוכר מס הבשר, שקלוב, בריסק על מקום ר צבי הירש אורנשטין ור מאיר יונה בעל שער החדש על מקומו אחריו, עלה לירושלים-תרלז ועסק בתורה ובצרכי ציבור ועמד בראש בי\"ד נפרד משל ר שמואל סלנט. למרות שהתנגד לציונות, תמך בישוב הארץ ובמושבות פ\"ת ויסוד המעלה. חיבר \"דיני שביעית בקצרה\" ירושלים תרסג, ועוד רובם בכתב יד. אשתו \"הרבנית מבריסק\" היתה עזר כנגדו בעבודתו הציבורית. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. הספד עליו מאת ר אליהו חיים מייזל ב\"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["מהרי\"ל דיסקין","מפרשי תורה"],["מהרי\"ל דיסקין (ר' יהושע לייב)",""],["אהלים",""],["דיני שביעית – בקצרה",""],["כתבי מהרי\"ל דיסקין – או\"ח",""],["לקוט אמרים",""],["לקט אמרים – באגדה ובהלכה",""],["מהרי\"ל דיסקין – עה\"ת",""],["שו\"ת מהרי\"ל דיסקין",""],["תורת אהל משה",""],["תורת האהל",""],["תורת האוהל (מהרי\"ל דיסקין)","מפרשי ש\"ס - אחרונים"],["מהרי\"ל דיסקין","שו\"ת - אחרונים"]],"e":"תקע\"ז-תרנ\"ח"},{"i":13485,"n":"דיסקין, נח יצחק מלומזה","f":"בנימין מהורדנא","dt":"תרסח - ח תמוז","b":"דרשן,ראב\"ד בלומז'ה-תרלד. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה תרנג."},{"i":13486,"n":"דיסקין, שמעון משה","f":"יהושע זליג משומייאץ","k":"בעל מדרש שמעוני","r":"ר\"מ בישיבת קול תורה בירושלים","bt":"תרלה","dt":"תרצא","b":"דרשן, ,מג\"מ בלובנא, רב בלאכוויץ(=לוחוביץ). בנו - ר יהושע זליג מפריסלוב ופרדס חנה.","bk":[["מדרש שמעוני",""],["משאת המלך",""],["משאת המלך - על התורה וש\"ס",""]]},{"i":13487,"n":"דיעי, בן ציון מגרבה","f":"כואס","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":13488,"n":"דיעי, מכלוף מג'רבה","k":"בעל מר דרור","b":"שו\"ב וסופר סת\"ם בג'רבא."},{"i":13489,"n":"דיעי, עזיזי מג'רבה","bt":"תרעב","bp":"ג'רבא","dt":"תשנט - טו אדר","b":"תלמיד ר מרדכי סגרון ממדנין-תונס. מתורתו ב\"אוצר התורה\" ג'רבא תרפט. עלה לארץ-תשי וכיהן כרב בחצור הגלילית."},{"i":13490,"n":"דיק, איזיק מאיר מוילנא","k":"בעל וויצן און שפיצן","bt":"1807","bp":"וילנא","dt":"1893","b":"משכיל בוילנא, אבי הספרות האידית החילונית. מייסד \"טהרת הקדש\" ביהכ\"נ המודרני הראשון בוילנא. היה ממעודדי ההגירה לאמריקה. חיבר גם \"האורח\", ועוד."},{"i":13491,"n":"דיק, צבי הרש הכהן מאוהל ובאלאד","f":"אחד מחכמי טאלטשווא","bt":"תרלב","dt":"תשד","b":"תלמיד השב\"ס, ור אברהם יצחק גליק מטאלטשווא, ור אלעזר לעוו באויהל. חתן ר שמואל זאב הלוי יונגרייז מביהאר-נאדי-באיאם. דיין ומו\"צ באויהל-תרנה, וכיהן כר\"מ בישיבה על מקום ר יואל פלנר שעבר לאוהל - סירב לכהן כרב וסירב לתואר \"מורה מורנו\". נספה בשואה."},{"i":13492,"n":"דיקאלו, ישראל אברהם","b":"דיין בארטה-תעד בענין השליח ר שמשון גומץ פאטו."},{"i":13493,"n":"דיקוריאל, אברהם מאזמיר","dt":"תסה - טז אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":13494,"n":"דיקמן, יעקב קופל צבי הירש","f":"גבריאל","k":"בעל קרני ראמים","bt":"תקסה","dt":"תרן","b":"מחכמי סניאטין, עבר להואש. חיבר \"קרני ראמים\" טשרנוביץ תרכד, ועוד."},{"i":13495,"n":"דיקמן, מרדכי מבקשביץ","b":"שו\"ב בבקשביץ על מקום אביו. תשובה אליו - \"מנחת שי\"."},{"i":13496,"n":"דיקסלר, חיים יהודה מבורשטין","b":"מחכמי הליטש. דיין בבורשטין."},{"i":13497,"n":"דיקשטין (דייקן), פלטיאל","f":"יהודה","bt":"1865","bp":"וילייקה-פלך וילנא","b":"עורך דין בפטרבורג, וחקר המשפט העברי. פרסם באנציקלופדיה היהודית-רוסית עשרות מאמרים. קיבל פרס צייטלין של חברת מציפי השכלה על מחקר בשאת העגונות. מראשי חברת המשפט העברי במוסקבה. עלה לארץ. עורך \"המשפט העברי\" במוסקבה ואח\"כ בתל אביב. עורך \"הפרקליט\" 1943."},{"i":13498,"n":"דירנפלד, אברהם","r":"רב בפאפא","dt":"תשד","b":"ר\"מ בפאפא","bk":[["בית יוסף – ברכות",""],["בית ישראל – ברכות",""]]},{"i":13499,"n":"דירנפלד, זאב וולף מברזן","f":"משה","dt":"תרץ","b":"ר\"מ בישיבת \"תושיה\" שיסד המהרש\"ם, ר\"מ בבוצאץ. סטניסטלב-תרעט. בעל תפלה קבוע בימים נוראים אצל ר יודלה בברזן."},{"i":13500,"n":"דירנפלד, יהודה ליב","dt":"תשד","b":"מרביץ תורה בסאמבאטהעלי"},{"i":13501,"n":"דירקטור, ישעיה טוביה הלוי מנ\"י","k":"בעל תורת תקוני עירוב","b":"רב בניו יורק. ?? לא באוצר ??"},{"i":13502,"n":"דירקטור, צבי הירש מאמציסלב","k":"בעל בנין שלום","dt":"תרעא","b":"רב בקופצ'ווה(=קופצאווה), סוקולקה, אמציסלב."},{"i":13503,"n":"דישבק, דוד מפפד\"א ומיץ","f":"יואל","k":"בעל פרדס דוד","bt":"תקד","dt":"תקנד","b":"פרנס, שתדלן, דיין, רב בפיורדא, פפד\"מ, מירינגע-תקלא, שוורצוולד, ר\"מ במיץ-תקלח, רב בפיירשדורף ומדינת ברייט-תקמה. חיבר \"פרדס דוד\". נשא ונתן עם ר יוסף שטינהרט, ר יעקב מברלין בעל \"באר יעקב\". (בשנת תקלז הפסיד חמשה ועשרים אלף זהובים)."},{"i":13504,"n":"דישפולטי, ברוך אברהם","f":"פתחיה","b":"מחכמי איטליה לאחר גירוש ספרד, רב במודנא"},{"i":13505,"n":"דישקס, צבי הירש (גרינולד) מאופ","dt":"תרטו - טז אלול","b":"תלמיד קרובו החוזה מלובלין, ששלחו לשליחויות שונות. נסע אל היהודי הקדוש מפשיסחא, ר שמחה בונם מפשיסחא, ור מנחם מנדל מקוצק - והיה מנבחרי החבורה שם. רב באפוטשנא-תרל. מתורתו ב\"לקוטים חדשים\", \"נפלאות חדשות\", \"משענת משה\" - לנכדו ר יחיאל משה מיאדימוב."},{"i":13506,"n":"דכוביץ, צבי הירש מנאויגרד","f":"שלמה זלמן","k":"בעל פרי שלמה","bt":"תרמז","bp":"סאקאלי-פלך לומזה","b":"תלמיד ישיבות ראדין, סלוצק, קריניק, וולוזין. נסמך מאת: ר רפאל שפירא מוולוזין, ר משה בצלאל מסובלק. רב בנוביגרוד-תרסז, וורניאן-תרעג, היגר לארה\"ב וכיהן כרב בקהלת \"אגודת אחים אנשי לובאוויץ בברוקלין. פרסם מאמר ב\"אוהל יוסף\" נ\"י תשו."},{"i":13507,"n":"דכנר, חיים אלתר מסערט","f":"יעקב מדלטין","k":"אדמור מסערט","bt":"תרך","dt":"תרצא - יא טבת","dp":"סערט","b":"מצאצאי ר מנחם מנדל מקוסוב בעל \"אהבת שלום\". חתן ר שמואל שמלקא רובין מסרעט נכד השר שלום. רב באובר-ויקוב (בוקובינה), מוסיף(=מאסיף, מיסיעף)-מרמורוש-תרן, סרעט(=סערעטה)-תרסה על מקום חותנו וראש ישיבה ור יצחק וידמן על מקומו אחריו, אדמור בסערט על מקום חותנו ובראשות ישיבת \"תמכין דאורייתא\" מיסודו של ר עקיבא סופר בן שלמה אלכסנדרי. נסמך מאת: ר יצחק אהרן איטינגא מלבוב, ר אריה ליב הורביץ מסטניסלב, ר ליב לנדא בעל \"יד יהודה\". בניו: ר יוסף חתן ר אברהם יהושע פריינד האדמור מנאסאד, ישראל."},{"i":13508,"n":"דכנר, יוסף","f":"חיים אלתר מסערט","dt":"תש..","b":"חתן האדמור מנאסוד ר אברהם יהושע פריינד. מחכמי ראדנא. נספה בשואה."},{"i":13509,"n":"דכנר, יעקב שמשון מברהמט","f":"פנחס יוסף מבערהאמעט","k":"אדמור מבערהמט","bt":"תרסד","dt":"תשמד","dp":"מונרו","b":"חתן ר ישראל מדלטין (אליק). אדמור בדלטין. ניצל מהשואה ועבר לארה\"ב. כיהן כאדמור מבערהמט בניו יורק."},{"i":13510,"n":"דכנר, ישראל","f":"חיים דכנר","b":"רב-שנת תר\"צ"},{"i":13511,"n":"דכנר, מאיר עובדיה מסקאלא","f":"קלונימוס","bt":"תרי","dt":"תרע","b":"רב בסקאלא."},{"i":13512,"n":"דכנר, מנחם מנדל אלתר מברהומט","f":"פנחס יוסף מקוסוב","bt":"תריג","dt":"תרפד - יח חשון","b":"רב בברהומט(=בערהאמעט)-בוקובינה-ליד ויזניץ-תרמא. חתן ר טוביה ליפשיץ מבריגל. בניו: ר פנחס יוסף איואניטש, ר חיים. חתניו: ר אליעזר דאדקי-נכד ר מנחם מנדל מקוסוב, ר ישראל דכנר מסערט."},{"i":13513,"n":"דכנר, סיני מוואיניטש","f":"מנחם מנדל מבערהמעט","b":"רבה של וואיניטש לפני השואה. חתן ר הירש רובין ממישלניץ"},{"i":13514,"n":"דכנר, פנחס יוסף מוויניטש","f":"מנחם מנדל אלתר","b":"רב בוויניטש=איונוביץ, ברהומט על מקום אביו. חתן ר אריה ליב טיטלבוים מרודניק."},{"i":13515,"n":"דכנר, צבי אריה מוליע-מיכובה","b":"מצאצאי ר פנחס מקוריץ. רב בוליע-מיכובה וגבאי ארץ ישראל."},{"i":13516,"n":"דכנר, שמואל שמלקא","f":"ישראל","bt":"תרעא","dt":"תשלט","b":"חסיד ויזניץ. תלמיד ר מנחם מנדל מוישובה, וה\"דמשק אליעזר\" בויזניץ. חתן ר דב פרידלנדלר מסטנוביץ. ניצל מהשואה, ואחריה עסק מטעם אגו\"י בהצלת ילדים וחינוכם. בזיוו\"ש חתן ר יוסף צבי גרינפלד מטשרנוביץ. עלה לארץ-תשח - דרך קפריסין. פעיל בחסידות ויזניץ והיה בשליחות באנטורפן במשך 3 שנים מטעם החסידות."},{"i":13517,"n":"דכנר-שפירא, פנחס יוסף מקוסוב","b":"נכד ר שמשון שפירא מזסלב. שינה שמו משפירא לדכנר כשעבר לאוסטריה. חתן ר חיים מקוסוב."},{"i":13518,"n":"דלאטאש, בוניטו (מזל טוב)","dp":"כפר לאטעס-ליד מונטפלייר","b":"רופא ואסטרונום בפרובנס, לאחר הגירוש-רנח עבר לרומא והיה לרופאו של האפיפיור אלכסנדר השישי וליאו העשירי. סייע לדחות את עלילות המומר פעפערקארן כנגד היהודים, נזכר בספרו של רייכלין."},{"i":13519,"n":"דלאטאש, משה עמנואל","b":"מגדולי חכמי איטליה ברומא-של\"ד"},{"i":13520,"n":"דלאקרוט, יוסף משברשין","f":"מתתיהו דלאקרוט","b":"מגדולי חכמי דורו,רב בשברשין-שע\"ו"},{"i":13521,"n":"דלה טורה, יצחק מליוורנו","k":"בעל שירים ומשלים","b":"משורר מחכמי ליוורנו-שנות ה-תר'. חיבר שירים ומשלים - בכת\"י."},{"i":13522,"n":"דלוגץ, אורי מסטנאב","dt":"שצו","b":"רב בסטאנוב. חיבר ספר על שו\"ע ובו הוספות לסמ\"ע. נספד ב\"איתן האזרחי\"."},{"i":13523,"n":"דלוגץ, ברוך מטרמבובלה","bp":"זלוזיץ","dt":"תש..","b":"חסיד הוסיאטין. חתן ר מרדכי מסטר ועבר לטרמבובלה בה כיהן בהמשך כרב. נספה בשואה."},{"i":13524,"n":"דלוגץ, משה מנחם מנדל מטרנופול","b":"תשובה אליו - \"ובחרת בחיים\"."},{"i":13525,"n":"דלוגץ, שמואל","f":"משה","k":"בעל אגודת שמואל","bt":"תנט","b":"הדפיס תנ\"ך המגיד עם פירוש \"אגודת שמואל\" ומתאר בהקדמה כי ישב בבית האסורים בארץ ערבית ומספר על קהלה יהודית - לא ידועה - משבט בנימין, ושרבם נקרא ר יעקב טלקי, ונדד דרך ברצלונה לפפד\"מ."},{"i":13526,"n":"דלויה, יהודה ממראקש","f":"מרדכי","b":"מחכמי מראקש-מרוקו."},{"i":13527,"n":"דלויה, יהודה ממראקש","dt":"תסא","b":"מחכמי מראקש. נהרג עם אחיו ר יצחק עק\"ה."},{"i":13528,"n":"דלויה, יוסף יצחק ממראקש","b":"רב במראקש."},{"i":13529,"n":"דלויה, יעקב ממכנאס","b":"מחכמי מכנאס. שיר לכבודו מאת ר דוד חסין ב\"תהלה לדוד\"."},{"i":13530,"n":"דלויה, יעקב ממראקש","f":"מרדכי","b":"מחכמי מראקש."},{"i":13531,"n":"דלויה, יצחק ממראקש","dt":"תעא - אב","dp":"מכנאס","b":"רב וראש ישיבה במראקש-מרוקו. ישב במאסר בגלל מלשינות-תסא ושוחרר. אחיו: ר יהודה שנפטר ללא ילדים, ור משה. מתלמידיו: ר שלמה עמאר, ר אברהם אזולאי שחיבר הגהות על כתבי האר\"י."},{"i":13532,"n":"דלויה, יצחק ממראקש","b":"מחכמי מראקש-תצג. בנו - ר מרדכי."},{"i":13533,"n":"דלויה, מאיר ממכנאס","f":"יעקב","b":"רב במכנאס."},{"i":13534,"n":"דלויה, מאיר ממראקש","b":"רב במראקש, מתורתו ב\"מראה עינים\" לר אלעזר בהלול."},{"i":13535,"n":"דלויה, מרדכי ממראקש","f":"יצחק","b":"מו\"ץ במראקש."},{"i":13536,"n":"דלויה, משה ממראקש.","dt":"תס-ה - אב","b":"מחכמי מראקש, אחיו של ר יצחק דלויה רבה של מראקש - היעב\"ץ שלח אגרת תנחומים אליו בפטירת אחיו."},{"i":13537,"n":"דלטאש, עמנואל מרומא","b":"רב ברומא. תשובה ממנו ב\"פחד יצחק\"."},{"i":13538,"n":"דליאינה, דוד","f":"עזריאל","k":"בעל עפר יעקב","b":"חיבר \"עפר יעקב\" בכת\"י. ב\"פחד יצחק\" תשובה ממנו. בנו ר א' דיינה (דליאינה), ונכדו ר דוד חיים דיינה מרוויגו."},{"i":13539,"n":"דלילה","f":"יהונתן","k":"ראה: דלויה","b":"מחכמי ירושלים, וחתם במחלוקת בענין הרב גאגין-תרו. בשליחות \"בית אל\" במרוקו-תריד."},{"i":13540,"n":"דלילה, שלמה מאלגיר","bt":"תקס","dt":"תרל","b":"רב ודיין באלגיר. נזכר ב\"מסעי ישראל\". יתכן והכוונה לר שלמה דלויה."},{"i":13541,"n":"דלמן, אברהם אהרן מנדבורנה","dt":"תרפח","b":"מראשי חסידי זידיטשוב בנדבורנה. אחיו של ר אליעזר מסטניסלב. חתן הגביר ר נחום דרימר."},{"i":13542,"n":"דלניקה, מאיר חיים ממאטעלא","f":"אברהם צבי","bt":"תרמב","b":"תלמיד ר צבי הירש חורגין מפאהאסט, ר דוד מאניפאליא מסמיאטיץ, כולל קובנא. רב במאטעלע-פלך גרודנא-תרע. נסמך מאת: ר עקיבא ברגמן ממאטעלע, ר ברוך דב ליבוביץ מסלובודקא, ר יעקב יצחק ריינס מלידא, ר אליהו בן שמואל מרומשישוק, ר ברוך אפשטין בעל \"תורה תמימה\", ר משה מישל שמואל שפירא בעל \"שכיות החמדה\". הניח חבורים על הש\"ס ושו\"ע."},{"i":13543,"n":"דלען - משפחה","b":"מקור השם בר אליעזר דלען מוילנא - כשנדרשו היהודים לשמות משפחה פתח תנ\"ך בפסוק מספר יהושע \"ודלען והמצפה ויקתאל\" ובחר בשם זה כמשפחתו. בהמשך נקראו גם דילאן."},{"i":13544,"n":"דלען, אליעזר מוילנא","f":"ברוך בנדיט מנישוויז","dt":"תקצח - ב תמוז","dp":"וילנא","b":"גביר מחכמי וילנא. בקי בשפת המדינה והיה קבלן לצרכי צבא רוסיה במלחמה בנפוליאון - וקיבל מדליה בפטרבורג-תקעד. השתתף באסיפה במינסק-תקעו, ובמשלחת לפטרבורג-תקעח. הצאר אלכסנדר התארח בביתו והצליח אז לשכנע את הצאר בנוגע לעלילת דם בנעשוויז והצאר אמר לו ידעתי כז זו עלילת שקר אבל מה שאתם לוקחים רבית מעמי הארץ בזאת לא תעשו טובה לעצמכם. לימים נאסר בגלל הלשנה והצליח להשתחרר. בנו ר יעקב זבולון, ונכדו ר מיכאל דילאן."},{"i":13545,"n":"דלען, יעקב זבולון מוילנא","f":"אליעזר מוילנא","dt":"תרל - כד אייר","dp":"וילנא","b":"חתן ר צבי הירש אב\"ד מינסק."},{"i":13546,"n":"דלען, מיכאל מוילנא","f":"יעקב זבולון מוילנא","dt":"תרנה - כו שבט","dp":"באלטא-ליטא","b":"תלמיד ר ישראל זורעציער."},{"i":13547,"n":"דלקראט, מתתיהו - הזקן","k":"בעל צל עולם","b":"ראש גדולי פולין בקבלה ומדעים בקרקא-ש\"מ. בנו ר יוסף."},{"i":13548,"n":"דלקראט, מתתיהו אברהם - הנכד","f":"יוסף דלקראט","b":"דיין וספרא דמתא בקרקא-שנת ת', לובלין-תה"},{"i":13549,"n":"דלקראט, שלמה מאיטליה","b":"מגדולי חכמי איטליה,מרביץ תורה בבולוניה"},{"i":13550,"n":"דלקראנו, מתניהו","f":"שלמה","k":"בעל צל העולם","b":"רב ומקובל. חיבר \"צל העולם\", פירוש על \"שערי אורה\" ונדפס, ביאורים על ספר הזהר - בכת\"י."},{"i":13551,"n":"דם, אשר מלבוב","f":"נתן","k":"בעל היכל כאורה","bt":"תרל","dt":"תש","b":"מחכמי למברג. חיבר \"היכל כאורה\" למברג תרץ. ?? לא באוצר ??"},{"i":13552,"n":"דמבו, יצחק","f":"אהרן","k":"בעל השחיטה והבדיקה","bt":"1848","bp":"שאוולי","dt":"1894","b":"רופא ומלומד. לחם באיסור השחיטה ברוסיה, וחיבר ספר על השחיטה היהודית מצד צער בעלי חיים. הספר תורגם לשפות שונות. ?? לא באוצר ??"},{"i":13553,"n":"דמבינסקי, חיים ברוך הלוי","f":"בצלאל","k":"אדמור מואלברזש,בעל תורת חיים","dt":"תשג - א תשרי","b":"נכד ר יחיאל מאלכסנדר. חתן ר יעקב משה טורנהים האדמור מואלברזש. תלמיד דודו-אחי אמו האדמור ר ירחמיאל ישראל יצחק מאלכסנדר. רב ואדמור בואלבארזש(=ואלבארז)-חלך פיעטרקוב-תרפד על מקום גיסו ר אלעזר מאיר טורנהים שעבר לזדונסקוואלא. רב בטושין-ליד לודז, חזר לואלברזש-תש והנהיג את עדתו עד שנספה בשואה. הו\"ל ספר חתונו זקנו ר ישכר דב בעריש \"עבודת ישכר\". בנו ר יחיאל שמחה - נספה בשואה. נסמך מאת: ר אליהו חיים מייזל מלודז, ר יהושע שוורצברג מזאריק, ר בנימין זאב מזאלאזרין."},{"i":13554,"n":"דמבינסקי, יצחק חיים דוד ממקובא","f":"שרגא פיבל שלום מאנטו","k":"אדמור מאלכסנדר מקובא","dt":"תש..","b":"בן האדמור מאלכסנדר אנטורפן. חתן דודו זקנו ר בצלאל יאיר מאלכסנדר לודז. אדמור במקובא-תרצד, וארשא. נספה בשואה."},{"i":13555,"n":"דמבינסקי, שרגא פיבל שלום הלוי","f":"בצלאל","k":"אדמור מאלכסנדר אנטור","dt":"תשיד - ט שבט","b":"נכד - בן בתו - ר יחיאל דנציגר האדמור מאלכסנדר. חתן ר ישראל יצחק טאוב מזדונסקוואלא. אדמור באנטורפן וניו יורק."},{"i":13556,"n":"דמביצר, אברהם מדזיקוב","f":"יהושע צבי מדזיקוב","bt":"תרצא","bp":"דזיקוב","dt":"תשנט","b":"אחיו של ר דוד משולם. חתן ר צבי הירש מעט מבלוזוב. ניצל מהשואה."},{"i":13557,"n":"דמביצר, חיים נתן מקראקא","f":"יקותיאל זלמן","k":"בעל מגני ארץ ישראל","bt":"תקף","dt":"תרנג","b":"חתן ר משה דייטשר אשכנזי. רב בקראקא-תרט ואחר כך ראב\"ד. עסק בחקר דברי ימי ישראל והיה בקשר עם חכמי זמנו בתחום. חיבר \"מגני ארץ ישראל\" למברג תריב, ועוד.","bk":[["כלילת יופי – תולדות הרבנים בלבוב ועוד",""],["מגני ארץ ישראל – מעות ארץ ישראל",""],["מכתבי בקרת – ועד ד' ארצות",""],["תורת חן (דברי חן) – עשה ול\"ת ועוד",""]]},{"i":13558,"n":"דמביצר, יואל מקראקא","f":"יקותיאל זלמן","k":"בעל מפלת עיר הצדק","bt":"תקפט","dt":"תרלט","b":"חתן ר ישכר ויינגוט אב\"ד טשנסטוכוב ומילא את מקום חותנו למשך שנתיים. עבר לקראקא ועסק בחינוך. חיבר \"מפלת עיר הצדק\" וינה תרלח. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. ?? לא באוצר ??"},{"i":13559,"n":"דמביצר, יצחק קלונימוס מקראקא","f":"יקותיאל זלמן","bt":"תקפה","bp":"קראקא","dt":"תרלג","b":"מחכמי קראקא. קינה עליו בספר \"משפיל גאים\" לרנ\"י ויניג. בנו ר ישראל חתן ר ליבר לנדא מויליצקה."},{"i":13560,"n":"דמביצר, יקותיאל זלמן מקראקא-א","bt":"תקנב","dt":"תקצג","b":"תלמיד ר יצחק הירש למלר מאיבשיץ. גיסו של רבו ר יצחק הירש למלר דיין בקראקא."},{"i":13561,"n":"דמביצר, יקותיאל זלמן מקראקא-ב","f":"משה יעקב","k":"בעל יד יקותיאל","bt":"תקצט","dt":"תרעב - כב סיון","b":"דיין ודרשן בקראקא. חיבר \"יד יקותיאל\" קראקא תרעב - יצא לאור אחר פטירתו ע\"י אחיו ר פנחס אליהו בעל גבעת פנחס. הו\"ל ספר אביו \"מימי הדעת\", ואת ספר דודו ר חיים נתן \"תורת ח\"ן\"."},{"i":13562,"n":"דמביצר, מרדכי אורי מקראקא","f":"יהושע","b":"תלמיד ישיבת בובוב בקראקא. רב בבובוב. חתן ר שמואל פליבוים מקראקא. ניצל מהשואה ועבר לארה\"ב."},{"i":13563,"n":"דמביצר, משה יעקב מקראקא","f":"יקותיאל זלמן","k":"בעל מימי הדעת","bt":"תקעט","dt":"תרכג","b":"דיין בקראקא-תרו ואחר כך ראב\"ד. חיבר \"מימי הדעת\" למברג תרכו."},{"i":13564,"n":"דמביצר, פנחס אליהו מקראקא","f":"משה יעקב","k":"בעל גבעת פנחס","bt":"תרט","dt":"תרף","b":"חתן ר אברהם יהודה גולדמינץ. דיין בקראקא-תרן, חיבר \"גבעת פנחס\" קראקא תרפה."},{"i":13565,"n":"דמוהי, זרח ממצרים","b":"רב במצרים-שסו."},{"i":13566,"n":"דמוהי, משה בעל הנס ממצרים","k":"ר' משה דמוהי בעל הנס","b":"רב במצרים-תן. ונקרא בעל הנס משום מעשה שהיה ומסופר ב\"טוב מצרים\"."},{"i":13567,"n":"דמוהי, משה מירושלים ומצרים","b":"מחכמי ירושלים, חתם בשנת שמז על התקנה לשחרור תלמידי חכמים ממס. חתם-שכט במכתב הרבנים לטובת דון יוסף נשיא, עם ר ישמעאל הכהן ור יום טוב ן סיד, ועוד."},{"i":13568,"n":"דמוהי,זרח","b":"מחכמי קהיר-שנ\"ז"},{"i":13569,"n":"דמונטנייא, יוסף","b":"עלה מונציה דרך ביירות בשנת ר\"מ. נתמנה פרנס בירושלים. בשנת רמא שלח מכתבים ללומברדיא ובו תיאור קורותיו, כמה ממכתביו נדפסו לימים. מוזכר בספרו של ר משולם מוולטרא כ\"ר יוסף דמונטנייא אשכנזי הפרנס\". יצא פעמיים בשליחות ירושלים. איגרת שליחותו נדפסה ב\"ציון\" א על ידי פריימן, לדעת חוקרים זהה עם יוסף מנטבייא אשכנזי."},{"i":13570,"n":"דמו\"ש, מרדכי","b":"מגדולי חכמי פרג-שפ\"ג,ראש המקובלים,איש מופת"},{"i":13571,"n":"דמן, יצחק זאב מרוזוודוב","f":"מרדכי","bt":"תרעג","bp":"רוזוודוב","dt":"תשנו","b":"מקורב לאדמורים. ניצל מהשואה - גלה לסיביר. חתן ר יצחק דוד פרידמלנד. עבר להענעויל-צרפת, עלה לארץ."},{"i":13572,"n":"דמן, משה מקרלסבורג","b":"דיין בקרלסבורג. נזכר אצל החת\"ס."},{"i":13573,"n":"דמנאתי, אליהו","dp":"בוז'עד(מרוקו)"},{"i":13574,"n":"דמפ, מרדכי מפרוכניק","b":"רב בפרוכניק-תרע."},{"i":13575,"n":"דמרי, אברהם משה מתונס","f":"מעתוק","k":"בעל זכרון משה","bt":"תרנח","dt":"תשי - כג אב","b":"דרשן, מו\"ץ בגאבס-תונס, חיבר \"זכרון משה","bk":[["חסד ורחמים",""]]},{"i":13576,"n":"דמרי, מנצור מדמאר-תימן","f":"שלמה-סלימן אלמעלם","k":"מרי חטר אלמעדי","bp":"דמאר-תימן","dp":"תימן","b":"מגדולי הרבנים בתימן-קפג. חיבר ספרים במדרש ופילוסופיה, חיבר מדרש מאור השכלים - סראג' אלעקול, מאה שאלות-קפג, \"שרח אלקואעד\" ועוד."},{"i":13577,"n":"דמרי, מעתוק רחמים","k":"בעל שעת הרחמים","dt":"תרצד - א אלול","b":"רב בטוזר, טמזרת."},{"i":13578,"n":"דמרי, משה מתימן","f":"שלמה","bt":"תרם","bp":"תימן","dt":"תשלג - יט שבט","b":"רב במנקדה שבמחוז ד'מאר בתימן, עם ר שלום בן יחיא ור יוסף בוטיל. עלה לארץ -תשט-י."},{"i":13579,"n":"דמרי, סעדיה מתימן","f":"דוד","k":"בעל מדרש הביאור","bp":"תימן","dt":"רמד - אחרי","dp":"תימן","b":"יש המזהים אותו עם מרי סעדיה בן דוד עדני. רב בתימן-רא, חיבר מדרש הביאור - צפנת פענח."},{"i":13580,"n":"דמרי, פרג'י מג'רבה","k":"בעל פרח לבנון","b":"מחכמי ג'רבא. ור חיים בלעיש הסכים על ספרו."},{"i":13581,"n":"דמרי, רפאל חיים מתונס","k":"בעל דברי חיים","dt":"תשמט","dp":"באר שבע","b":"מחכמי גאבס-תונס, עלה לארץ והתישב בבאר שבע."},{"i":13582,"n":"דמשק אליעזר - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה בידי ר רפאל סורא."},{"i":13583,"n":"דמשק, אברהם אליעזר ליזר מקראקא","f":"יוסף בן שמעון","k":"בעל אבני קדש","r":"מקראקא","bt":"תקלב","bp":"לאסק","dt":"תרז - יא תמוז","dp":"קראקא","b":"נינו של ר שמואל לסקר מלאסק, ור יצחק גולדעס מלאסק. חתן ר אפרים פישל מקראקא. תלמיד ר מאיר צילך בלאסק. דיין בקראקא-תרסה-ע אצל ר דוד צבי הלוי. חיבר \"אבני קדש\" וארשא תקעט, \"יקרא דחיי\", ועוד. פעל נגד אסיפת הריפורמים בברונשוייג. בנו - ר יוסף מפיאסצנא וקראקא הספידו בספרו \"מספד מר\". גיסו - ר חננאל מלוטימורסק.","bk":[["אבני קודש – שו\"ת וחידושים",""],["יקרא דחיי - דורש במילי דאגדתא",""]]},{"i":13584,"n":"דמשק, יוסף מפיאסצנא וקראקא","f":"אברהם אליעזר ליזר","k":"בעל מספד מר","bt":"תקפה","bp":"קראקא","dt":"תרנג","b":"מחכמי קראקא, דיין בוארשא, רב בפיאסצנה, ריטשוואל, קראקא. חיבר \"מספד מר\" זולקווא תרח, מכתביו ניצל \"כתב י\"ד\" וארשא תרמו."},{"i":13585,"n":"דמשק, מנחם מנדל מקראקא","f":"יוסף","k":"בעל דברי מנחם","bt":"תרי","dt":"תרפד","b":"דיין בקראקא-תרסג על מקום אביו. חיבר \"דברי מנחם\" קראקא תרפה. נפטר ללא ילדים."},{"i":13586,"n":"דמשקר, יהודה מירושלים ודמשק","k":"ר יודא דמשקר","b":"תלמיד ר חיים מוולוזין. חתן ר יהושע בן יהודה נטקין מירושלים. עלה לירושלים, עבר לדמשק. נזכר ב\"זית רענן\" להגאון מקוטנא. בנו - השופט יוסף בלאנק."},{"i":13587,"n":"דמתי, חיים סעדיה","f":"סעדיה","k":"בעל ישכר וזבולון","bt":"תרלג","bp":"דמת-תימן","dt":"תרעז - כג כסלו","dp":"ירושלים","b":"עלה לירושלים-תרן (או תרמה) מהעיר דמת-תימן בגיל 17, למד בישיבת \"תורת חיים\" ובישיבת \"בית אל\", פעמיים בשליחות בתימן להקמת ת\"ת בנוסח תימן. דיין בבית הדין של העדה התימנית אצל ר אברהם אלנדאף, ועמד בראש ישיבת \"חיי עולם\" של העדה. חברו של ר יוסף חיים זוננפלד, למד עם חברו ר שלום אלשיך עם ר חיים שאול דוויק ב\"רחובות הנהר\". ?? לא באוצר ??"},{"i":13588,"n":"דמתי, עובדיה יוסף מתימן","b":"רב באלחדד-תימן, עלה לארץ-[תשט] וכיהן כרב."},{"i":13589,"n":"דן","f":"יצחק מראדזיוויל","dt":"כה סיון","b":"רב בראדזיוויל-תר\"י. חתן ר יהושע השל מאפטא."},{"i":13590,"n":"דן בן יעקב אבינו","dt":"ט אלול"},{"i":13591,"n":"דן האשכנזי","b":"רב בתקופת הרשב\"א ונזכר בספריו וכן אצל הריטב\"א והר\"ן, ונזכר גם ב\"בשמים ראש\" בתשובה המיוחסת לרא\"ש."},{"i":13592,"n":"דן מברוד","b":"תלמיד הבעשט, חברו של ר יצחק מדרוהוביטש. בנו ר משה מדולינא - גם הוא תלמיד הבעשט."},{"i":13593,"n":"דן מזולקוא","dt":"תשג","b":"מרביץ תורה בישיבת ראדין"},{"i":13594,"n":"דן מרדכי מליזנסק","b":"רב בליזנסק-תקם בימי הנועם אלימלך."},{"i":13595,"n":"דנא די בריטו ן, יצחק חיים מאמש","f":"ראה: בריטו די, יצחק"},{"i":13596,"n":"דנאן - משפחה","k":"ראה: דנון","b":"משפחת רבנים במרוקו"},{"i":13597,"n":"דנגור עזרא ששון בן ראובן","f":"משה או ראובן","k":"בעל עדי זהב","r":"הרב הראשי לבגדד ואגפיה","bt":"תרח - כו אב","bp":"בגדד","dt":"תרץ - יג טבת","dp":"בגדד","b":"שם המשפחה היה במקור \"דן גור\". תלמיד ר עבדאללה סומך ב\"בית זלכה\". רב בבגדד-תרלו, רב ושו\"ב ברנגון-בורמה-תרם עד תרמו, חזר לבגדד והיה חזן ובעל תפקידים שונים בקהלה, חכם באשי-תרפג, ובשנת תרפח התפטר בגלל מחלוקת. בשנת תרסג קיבל רשיון מהשולטן להדפיס ספרים והקים דפוס בבגדד. חתם על המחאה ב\"המגיד\", ו\"הלבנון\" - כנגד הפגיעה ב\"בן איש חי\" מצד אחד המשכילים. בניו ציון, אליהו ומשה - המשיכו להדפיס אחריו והו\"ל ספר זכרון לתולדות אביהם. אחיו ר יחזקאל ברוך נהרג עק\"ה עם עוד 17 יהודים ע\"י התורכים בעלילה בשנת תרעז.","bk":[["עדי זהב - על התורה",""],["מגלת קהלת",""]]},{"i":13598,"n":"דנגור, אברהם נסים","dt":"תרפג","b":"עוסק בצרכי צבור בבגדאד"},{"i":13599,"n":"דנגור, אלישע","k":"בעל גדולות אלישע","dt":"תרנה - כז אדר","b":"דיין, מחכמי בבל, חכם באש בבגאד-תר\"מ, חיבר \"גדולות אלישע\". ?? לא באוצר ??"},{"i":13600,"n":"דנגור, משה מבבל","dt":"תרעד - סוכות","b":"תלמיד ר אלישע דנגור. מחכמי בבל. ונספד ע\"י ר יעקב בן יוסף חיים."},{"i":13601,"n":"דנגור, שלום מבבל","bt":"תקצג","bp":"בגדד","dt":"תרעו","dp":"סוויס","b":"תלמיד ר עבדאללה סומך ב\"בית זלכה\". דיין בבגדד. רב במצרים-תרנז, וחזר לבגדד-תרסד, חכם באשי בסוויס, ביקר בארץ כמה פעמים - תרנט-תרעד, ורכש אדמות בנגב - ונקראו על שמו אדמות דנגור, ציוה לקברו באדמותיו אולם בגלל מלחמת העולם ה-I לא נתאפשר הדבר."},{"i":13602,"n":"דנגלוב, יעקב מאוסטרליה","bt":"תרמא","bp":"אנגליה","b":"תלמיד ביהמ\"ד לרבנים בלונדון. דיין במלבורן-תרסו אצל ר יוסף אברהמס. חבר בחברת \"חוקרי קורות ישראל\"."},{"i":13603,"n":"דנויט, בן ציון","f":"רפאל","b":"תלמיד ר יעקב לנדא בעל האגור\", וכיהן כדיין אצל רבו ואצל ר יהודה מסיר ליאון."},{"i":13604,"n":"דנון - משפחה","b":"משפחת רבנים במזרח."},{"i":13605,"n":"דנון, אברהם מאדרינופול","f":"יוסף","k":"בעל תולדות בני אברהם","bt":"תריז","bp":"אדרינופול","dt":"תרפה - כח ניסן","dp":"פאריס","b":"משכיל מחכמי אדרינופול, מלומד וחוקר, בקי בשפות, יסד חברת \"דורשי השכלה\", עבר לקושטא, הקים מוסדות שונים להשכלה, ובהם ביהמ\"ד לרבנים בקושטא שהיה מחלוקת כנגדו מצד הרבנים. חיבר גם \"משכיל לאיד'ן\", ועוד."},{"i":13606,"n":"דנון, אברהם ממרוקו - ג","f":"מנשה","bt":"תקנו-יג כסלו","bp":"מרוקו","dt":"תקצג - יב אדר","dp":"פאס","b":"מחכמי פאס, סייע לר יונתן סירירו בפסק דין. נפטר צעיר, קינה לזכרו מר דוד חסין ב\"תהלה לדוד\"."},{"i":13607,"n":"דנון, אברהם מפאס","f":"שאול","bt":"תכ","bp":"פאס","dt":"תץ","b":"דיין בפאס-תסה. בנו - משה. אחיו ר שמואל בעל \"דברי הימים קורות יהודי פאס\"."},{"i":13608,"n":"דנון, אברהם מפאס","f":"שאול","dt":"שיז - לפני","b":"מו\"ת בפאס, בזמן היעב\"ץ ור\"י ן מלכא וחתם עמם כמה פעמים. אחיו - ר שמואל בעל \"דברי הימים\"."},{"i":13609,"n":"דנון, אברהם מפאס - א","dt":"שז - אחרי","b":"מו\"צ בפאס-ש\"ז"},{"i":13610,"n":"דנון, אברהם מפאס - ב","dt":"תקח","b":"רב בפאס"},{"i":13611,"n":"דנון, אליעזר מטבריה","dp":"טבריה","b":"מחכמי טבריה, בשנת תקס בשליחות בארצות ערב והודו. בשנת תקפג חתם על כתב שליחות ר יצחק בן סמחון, חתימות נוספות משנת תקץ"},{"i":13612,"n":"דנון, ברכה","f":"יעקב-כבוד יום טוב","dp":"ירושלים","b":"אביו ר יעקב בעל \"כבוד יום טוב\" ובסוף הספר חדושים מבנו ר ברכה בשם ב\"ד קודש (ראשי תיבות ברכה דאנון) שלוניקי תרו. נספד בספר \"תהלה לדוד\""},{"i":13613,"n":"דנון, ברכיה - בכור ברכה מירושל","f":"יום טוב דאנון","k":"בעל בד קדש","dp":"ירושלים","b":"מגדולי חכמי ירושלים-תק\"פ"},{"i":13614,"n":"דנון, חי מסרייבו ווינה","b":"גביר מראשי קהלת סרייבו, עבר לוינה עם רבים מבני הקהלה-תקס בערך בזמן מרד הסרבים."},{"i":13615,"n":"דנון, חייא מירושלים","b":"מחכמי ירושלים, חתם-תמח עם ר משה גלנטי בענין קהלת טבריה."},{"i":13616,"n":"דנון, חיים יום טוב מירושלים","dp":"ירושלים","b":"מחכמי דורגוטלו קאסאבה(תורכיה), דיין. עלה לירושלים."},{"i":13617,"n":"דנון, חיים יעקב מקושטא","f":"עמנואל","b":"מחכמי אדרינופול, דיין בקושטא-תקמט."},{"i":13618,"n":"דנון, חיים מפאס","b":"מחכמי פאס-מרוקו-תר, מוהל ובפנקס המילה שלו מאות שמות של ילדים שמל וכתב ששמע מר שמואל ן דנאן שמי שמל כחשבון שמו ניצל מגיהנם. בניו: ר משה, ר אליהו, ר שמואל, ר סעדיה-שנהרג עק\"ה-א אייר תרעב."},{"i":13619,"n":"דנון, חיים שמואל מאדרינופול","b":"רב באדרינופול-תקסו, אחד מ-4 החכמים שמונו לתקן הסכמה בענין המס (יחד עם ר אברהם פרץ, ר יעקב אברהם גירון ור אברהם ן ארוליא)."},{"i":13620,"n":"דנון, יהודה יוסף מסליבנה","b":"דיין בסליבנה(=איסלימנה)-תקן בערך אצל ר שמואל משה אלצייג, יחד עם ר רחמים אליעזר הלוי.."},{"i":13621,"n":"דנון, יהודה מאזמיר וטבריה","dp":"טבריה","b":"מחכמי אזמיר, עלה לטבריה-תרי ועמד בראש ישיבה, רבים מתלמידיו נמנו על חכמי טבריה."},{"i":13622,"n":"דנון, יהודה מפאס","f":"סעדיה","k":"בעל נודע ביהודה","b":"דרשן ובעל מעשים בפאס-תם, נזכר ב\"אהבת הקדמונים\", ישב גם בטיטואן. חיבר \"נודע ביהודה\" דרשות. בניו: ר יונה-נפטר בחייו-תם, ר סעדיה."},{"i":13623,"n":"דנון, יום טוב מאדרינופול","bt":"תקי","bp":"אדרינופול","dp":"ירושלים","b":"ש\"ץ בקהל \"מחזיקי תורה\" באדרינופול. עלה לירושלים."},{"i":13624,"n":"דנון, יום טוב מאזמיר","b":"דיין באזמיר-תקן בערך, עם ר יוסף ן יקר ור אברהם ן עזרא."},{"i":13625,"n":"דנון, יום טוב מאזמיר וירושלים","k":"בעל כבוד יום טוב","dt":"תקפג - ה אב","dp":"ירושלים","b":"מחכמי אזמיר. עלה לירושלים ושימש אב\"ד עדת הספרדים. בשנת תקעד חתם על מכתב המלצה לר יהודה זרחיה אזולאי, נתמנה ל\"ראשון לציון\" בשנת תקפב לאחר פטירת ר רפאל חזן, היה מחלוקת כנגדו מצד ר אליעזר חזן. נדפס ב\"תהלה לדוד\" וב\"מראה הגדול\" וב\"כסא שלמה\". סידר גט למומר עם ר יוסף ן יקר ור אברהם ן עזרא."},{"i":13626,"n":"דנון, יונה ממרוקו","bp":"טיטואן","dt":"תמ - סיון","b":"מחכמי טיטואן, מגדולי חכמי מרוקו, חתן ר סעדיה ן דנאן. נפטר צעיר ואשתו נפלה ליבום לפני אחיו - ר סעדיה-שנפטר גם הוא ללא ילדים."},{"i":13627,"n":"דנון, יוסף יעקב מבלגרד","f":"משה","dt":"תס","b":"תלמיד ומזכיר ר יוסף אלמושנינו בבלגרד, רב בבלגרד, אמשטרדם, לונדון והקים שם בימ\"ד. הו\"ל \"פרי חדש\" לר חזקיה די סילוה."},{"i":13628,"n":"דנון, יוסף מאדרינופול","f":"שמואל","k":"בעל דבר יוסף","b":"רב ומשורר באדרינופול-תקפ. נזכר אצל ר אברהם דנון ב\"תולדות בני אברהם\" שהביא משיריו."},{"i":13629,"n":"דנון, יוסף מאדרינופול","b":"מראשי קהלת אדרינופול-תרנא, חתם על ביטול רבנות משפחות גירון וכמוהר\"ר באדרינופול, עם ר נסים בן ישראל, ור נסים בן אהרן."},{"i":13630,"n":"דנון, יוסף מסרייבו וצפת","f":"יעקב","k":"בעל דברי יוסף","dt":"תקעה - יח תשרי","dp":"ירושלים","b":"רב בסרייבו, בשנת תקמג עלה לצפת. חיבר \"דברי יוסף\" שלוניקי תר. מחדושיו בספר \"דברי הנוגה\" לר רפאל אשכנזי. ?? לא באוצר ??"},{"i":13631,"n":"דנון, יוסף מפאס","b":"מחכמי פאס-שנות ה-ש'. בנו - ר יעקב ן דנאן."},{"i":13632,"n":"דנון, יעקב מאדרינופול","b":"רב באדרינופול-שצה, שאלה ממנו לר חיים בנבנישתי."},{"i":13633,"n":"דנון, יעקב מירושלים","dt":"תקיח - ח שבט","b":"מרבני ירושלים"},{"i":13634,"n":"דנון, יעקב מסרייבו וירושלים","f":"יוסף","bt":"תרטו","bp":"סרייבו או ירושלים","dt":"תרפט - כב אלול","dp":"ירושלים","b":"מחכמי סרייבו, עלה לירושלים והיה חבר בית הדין, רב בדמשק-תרעא. חזר לירושלים-תרפו. בשליחות במקומות רבים גם לטובת עולי תימן בירושלים וסייע בהקמת שכונת התימנים בכפר השילוח."},{"i":13635,"n":"דנון, יעקב מפאס","k":"בעל ספר פסקים-כת\"י","b":"סופר ביה\"ד בפאס-שסו, ואח\"כ מו\"ץ ודיין בפאס עם ר שאול סירירו, ור שלמה ן דנאן, ור חיים עוזיאל-שפד."},{"i":13636,"n":"דנון, יעקב מפאס","f":"שאול בן סעדיה","b":"רב בפאס."},{"i":13637,"n":"דנון, יעקב מפיליפופולי וירושלי","b":"רב בפיליפופולי(=פיליבי), רב ברומניה, עלה לארץ. בנו - ר מנחם ונכדו ר נסים יהודה מנחם מירושלים."},{"i":13638,"n":"דנון, יצחק","dp":"ארץ ישראל","b":"מחכמי ארץ ישראל, נספד בספר \"קול יעקב\" לר יעקב שאול (אזמיר תקך)."},{"i":13639,"n":"דנון, יצחק מאזמיר וטבריה","dt":"תרנב - כז סיון","dp":"טבריה","b":"מחכמי אזמיר, עלה לארץ והתישב בטבריה. רב בטבריה-תריז, וחתם על יסוד הישיבה \"בית יעקב\"."},{"i":13640,"n":"דנון, יצחק מפאס","k":"בעל ליצחק ריח","bt":"תקצו","dt":"תרס - כד אייר","b":"מו\"ץ בפאס. בניו: ר מימון, ר שמואל, ר יעקב."},{"i":13641,"n":"דנון, ישראל מאדרינופול","b":"רב באדרינופול-תקס."},{"i":13642,"n":"דנון, מאיר בנימין מנחם מסרייבו","k":"בעל באר בשדה","dt":"תרטו - כב חשון","dp":"ירושלים","b":"רב בסרייבו, עלה לירושלים וכיהן כדיין אצל הרב אג\"ן. חיבר \"באר בשדה\" ירושלים תרו. בשנת תרד חתם על הסכם שלום בעדה. (לדעת שושנה הלוי בספרה נפטר בתרט). חתם על מכתב רבני ירושלים כנגד אספת הריפורמים בברונשויג בתוך \"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":13643,"n":"דנון, מאיר מאזמיר - א","dt":"תמט - טז טבת","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":13644,"n":"דנון, מאיר מאזמיר - ב","dt":"תעז - ד אד\"א","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":13645,"n":"דנון, מימון","b":"משורר בזמן גירוש ספרד. ונזכר ב\"עומר השכחה\"."},{"i":13646,"n":"דנון, מימון - השלישי","f":"משה","k":"רמב\"ם אלפסי","bt":"ר - בערך","dt":"רס - בערך","b":"ראה גם: משה בן מימון ן דנאן."},{"i":13647,"n":"דנון, מימון מספרד","f":"שמואל או סעדיה","dt":"רפו - לפני","b":"ממגורשי ספרד, עבר לפאס והיה מגדולי הדור. נהרג עק\"ה-לפני רפו. לפי \"מלכי ישורון\" הגיע לווהראן, וקצמטינא-אלגיר."},{"i":13648,"n":"דנון, מימון מפאס","f":"סעדיה","b":"מחכמי פאס, מכתב ממנו-שפד, אודות הרעש בפאס, והצלת היהודים."},{"i":13649,"n":"דנון, מימון מפאס - א","b":"מחכמי גרנדה-ספרד, פאס - לפני ק'. אבי המשפחה. נזכר בהקדמת \"אשר לשלמה\"."},{"i":13650,"n":"דנון, מנחם","f":"יעקב דאנון","dt":"תרעד - ג אלול","dp":"ירושלים","b":"מחכמי ירושלים. בניו: ר נסים יהודה מנחם, ר בכור יעקב."},{"i":13651,"n":"דנון, מנשה מפאס - א","f":"אברהם","dt":"תקכז","dp":"[פאס]","b":"רב בפאס. נספד ב\"נער בוכה\" לר אליהו צרפתי."},{"i":13652,"n":"דנון, מנשה מפאס - ב","f":"שמואל","b":"נכד ר אליהו הצרפתי. מו\"ץ בפאס-תקכג. נתברך ע\"י השד\"ר ר עמרם ן דיוואן, בבן זכר, ונתקיים ובנו - ר שמואל שהיה סבו של ר שלמה בעל \"אשר לשלמה\"."},{"i":13653,"n":"דנון, מסעוד מפאס","f":"יעקב","b":"מחכמי פאס בתחילת שנות ה-תר."},{"i":13654,"n":"דנון, משה מאזמיר","f":"מאיר","b":"תלמיד ר י חיים יהודה אלגזי. מחכמי אזמיר-תץ."},{"i":13655,"n":"דנון, משה מטאטאר פאזארג'יק","f":"חיים","bt":"תרנב","bp":"טאטאר פאזארג'יק","b":"למד רפואה בשוייץ, פעיל ציוני. עלה לארץ והתישב בתל אביב-תרפד."},{"i":13656,"n":"דנון, משה מספרד ואדרינופול","k":"בעל כללים על הרמבן","b":"מחכמי ספרד בזמן הגירוש. תלמיד ר יצחק אבוהב, ור חיים אלגזי. עבר לאדריאנופול. חיבר כללים על הרמב\"ן."},{"i":13657,"n":"דנון, משה מסרייבו","dt":"תקצ - כ סיון","dp":"כפר סטולאץ-הרצגובינה","b":"תלמיד ר חיים יצחק מוספיא. רב בסרייבו, נאלץ לברוח מהמושל התורכי בגלל עלילה של המומר משה חביליו, עלה לארץ אולם נפטר בדרכו בהרצוגובינה. תלמידו - ר אליעזר פאפו בעל \"פלא יועץ\" המזכירו בספרו \"אורות אילים\". הציל את קהילתו."},{"i":13658,"n":"דנון, משה מפאס","f":"מימון","k":"רמבם אלפאסי","b":"רב בפאס-קצח, ניצל בנס מהערבים שדנוהו לשריפה. אבי משפחת אבן דנאן במרוקו. זקנו של ר סעדיה מגראנדה. חיבר חדושים על התלמוד. נזכר בהקדמת \"אשר לשלמה\", וב\"מעשה שעשועים\". (היו שהחליפו בינו לבין הרמב\"ם)."},{"i":13659,"n":"דנון, משה מפאס","f":"חיים","dt":"תריו - ט אב","dp":"פאס","b":"מחכמי פאס."},{"i":13660,"n":"דנון, משה מפאס","f":"שלמה","dt":"תרצז","b":"רב בפאס. מתורתו בסוף \"תדשן אדמה\"."},{"i":13661,"n":"דנון, משה מפאס","f":"שמואל","dt":"תריז","b":"מחכמי פאס. נפטר בגיל צעיר בחיי אביו. בנו ר שלמה בעל \"אשר לשלמה\". חיבר חדושים בכת\"י. נמצאה חתימתו על ספר שנדפס בשנת תרך!"},{"i":13662,"n":"דנון, נסים יהודה מירושלים","f":"מנחם","bt":"תרכז או תרלד","bp":"ירושלים","dt":"תרץ - טו שבט","dp":"ספאקס-תונס או ירושלים","b":"נכד ר יעקב מפיליפופולי. רב בירושלים, ביירות-תרסז, רודוס-תרע עד לכיבוש האיטלקי, אזמיר, רב ראשי בצפת-תרעא ואחר כך \"ראשון לציון\" בירושלים-תרעה - במינוי זמני. תיווך במחלוקת בין העדות בצפת-תרעא. בשליחות בתונס-תרץ ונפטר בשליחותו."},{"i":13663,"n":"דנון, נסים ממרוקו","b":"רב בפאס. חתם עם ר מרדכי צבע-תץ."},{"i":13664,"n":"דנון, סעדיה ממרוקו","f":"יעקב","dt":"תקעט - תמוז","b":"בנו ר שאול נהרג עק\"ה-תקעט. חיבר בקשה \"אבוא אליך\"."},{"i":13665,"n":"דנון, סעדיה מפאס","f":"אברהם בן שמואל","b":"מחכמי פאס-שעג, וכתב על אסונות טבע שהיו אז בפאס."},{"i":13666,"n":"דנון, סעדיה מפאס","f":"יהודה","b":"רב בפאס-תם, יבם את אשת אחיו ר יונה. נפטר ללא ילדים."},{"i":13667,"n":"דנון, סעדיה מפאס - ב","f":"שמואל בן מימון","dt":"שם","b":"רב בפאס-שי. יתכן ששמואל הוא זקנו שגדלו לאחר שאביו סעדיה נפטר לפני לידתו. נזכר ב\"אהבת הקדמונים\" אודות הזכות של משפחת ן דנאן בבית הכנסת. חיבר דרושים וביאורים לתורה ונזכרו ב\"מלכי רבנן\". בנו ר שמואל שנמנה על \"חכמי התקנות\"."},{"i":13668,"n":"דנון, סעדיה מפאס - ג","f":"שמואל","dt":"תם","b":"רב בפאס, וחתם על כתב מינוי לנגיד ר יצחק הצרפתי. היה במחלוקת עם ר יעקב ששפורטש. חיבר שירים ופיוטים בכת\"י. חתם-שצח עם ר יוסף גיקטיליא, ר שאול (או עמנואל) סירירו ועוד."},{"i":13669,"n":"דנון, סעדיה מפאס - ה","f":"מימון","b":"מחכמי פאס בסוף שנות ה-ר'."},{"i":13670,"n":"דנון, סעדיה מפאס וגרנדה - א","f":"מימון","k":"בעל חמדה גנוזה","dt":"רנג","b":"מחכמי פאס, עבר לספרד והיה אחרון משוררי ספרד. רב בגרדנה. ממגורשי ספרד והגיע עם בנו ר מימון לווהראן(=אוראן)-אלגיר עם רבים מהגולים, ומשם לקונסטנטין-אלגיר - ושם נעלמו עקבותיו, המשפחה המשיכה משם לפאס-מרוקו. נזכר ב\"עומר השכחה\" לר אברהם גאבישון. חיבר פיוטים שו\"ת ועוד. חיבר מאמר על סדר הדורות, תשובה ממנו בענין אנוסים. חיבר שירים ותשובות. מתשובותיו נדפסו עם \"תשובות הרמב\"ם\" ב\"פאר הדור\". חיבר ספר \"השרשים\", \"הערוך\". מצאצאיו - ר שאול ן דנאן שכתב על תולדות זקנו."},{"i":13671,"n":"דנון, צדיק מסרייבו","b":"גביר בסרייבו-שנות ה-ת', אבי משפחת דנון מסרייבו."},{"i":13672,"n":"דנון, רפאל אהרן ממרוקו","f":"חיים","bt":"תרג","bp":"פאס","dt":"תרן - אב","b":"נכד ר רפאל אהרן מונסונייגו - ונקרא על שמו. מחכמי פאס. מתלמידיו ר יוסף הכהן ור יוסף ן נאיים."},{"i":13673,"n":"דנון, שאול - א מפאס","f":"סעדיה?","dt":"תמט - אלול","dp":"פאס","b":"מו\"ץ בפאס, חתם-תמו עם ר יהודה עוזיאל, ר מנחם סירירו ור מימון אפללו. נספד ע\"י היעב\"ץ ב\"עת ספוד\". (יש בלבול בין כמה חכמים עם אותו השם)"},{"i":13674,"n":"דנון, שאול - ד מפאס","dt":"תרלא","dp":"מרוקו","b":"מו\"ץ במרוקו-שנות ה-תק'-תר'. חתן ר יהודה הכהן-מוהרי\"ך. חיבר חדושי דינים חו\"מ בכת\"י. חותנו של ר שלמה ן דנאן - ג."},{"i":13675,"n":"דנון, שאול הכהן ממרוקו","f":"שלמה","k":"בעל הגם שאול","dt":"תשלב - כג ניסן","b":"רב במראקש, על מקום ר יהושע בירדוגו, מוגדור, רבאט, עלה לירושלים-תשך. חיבר גם \"שנה שאול\"."},{"i":13676,"n":"דנון, שאול ממרוקו","f":"סעדיה","dt":"תקעט - כסלו","b":"מחכמי פאס. נהרג עק\"ה באיית עתאב, ונזכר ב\"דברי חכמים\" לר דניאל ן צולטאן ומביא שם הדעה כי נהרג ע\"י יהודים שרצו שיהיה להם קבר של צדיק."},{"i":13677,"n":"דנון, שאול שמואל מפאס","f":"יעקב בן שאול מפאס","bt":"תס - בערך","dt":"תקכח-ל","b":"אולי הוא נכדו של ר שאול הראשון. נסמך מאת ר יעקב ן צור-היעב\"ץ. דיין בפאס עם ר רפאל עובד ן צור, ר אליהו הצרפתי, ר אפרים מונסונייגו, ור משה ן זמרא. לאחר שחלה נוסף לו השם שמואל. אחד מחמשת הדיינים שכונו בית דין של חמש בפאס (ר שאול שמואל דנון, ר אפרים בן אברהם מונסונייגו, ר רפאל עובד בן יעקב ן צור, ר אליהו בן יוסף הצרפתי, ר מתתיהו בן מנחם סירירו)."},{"i":13678,"n":"דנון, שלמה מפאס-מרוקו - א","f":"סעדיה","b":"דיין בפאס, חתם-שפו עם ר יעקב חגיג ור חיים עוזיאל, וחתם עם ר שאול סירירו, ר אברהם חגיג, ור יוסף גיקטיליא. רופא ובקי בחכמת השרטוט."},{"i":13679,"n":"דנון, שלמה מפאס-מרוקו - ב","f":"משה בן שמואל","k":"בעל אשר לשלמה","bt":"תרח","bp":"פאס","dt":"תרפט - כח חשון","b":"מחכמי פאס ופרנס, לאחר שנתייתם גדל אצל זקנו ר שמואל, ודודו ר יצחק בעל \"ליצחק ריח\". תלמיד ר אבנר ישראל הצרפתי (=האי\"ש הצרפתי). חתן ר שלמה ן דנאן (?). ביקר בארץ עם דודו ר יצחק-תקלו, וכשחזר לפאס עודד את בני הקהלה לעלות לארץ.דיין בפאס-תרלט עם דודו ר יצחק ועם ר יוסף סירירו. דיין ברבאט-תרעט בבית הדין הגדול, אך ביקש לחזור לפאס וכיהן כרב ראשי-תרפא. מקורב לשלטון הצרפתי. מתלמידיו ר מתתיהו סירירו דיין בפאס, ר משה ן שמחון דיין במוגאדור. בנו ר שאול דיין במרוקו, ובנו ר משה על מקומו אחריו בפאס."},{"i":13680,"n":"דנון, שמואל מאדרינופול","b":"חתן ר רפאל יעקב אברהם גירון. רב באדרינופול-שנות ה-תק'."},{"i":13681,"n":"דנון, שמואל מאוראן-אלגיר","dt":"שצ","b":"מרבני אוראן"},{"i":13682,"n":"דנון, שמואל מירושלים","dt":"תקעה - ח אדר","dp":"ירושלים","b":"רב בירושלים."},{"i":13683,"n":"דנון, שמואל ממרוקו","f":"יצחק","k":"בעל תדשן אדמה","bt":"תרלז","dt":"תשכב - כח אד\"ב","b":"מחכמי מרוקו, אירח בביתו את השליחים שבאו מארץ ישראל. חיבר גם \"דשנת בשמן\", \"לשד השמן\"."},{"i":13684,"n":"דנון, שמואל ממרוקו - ב","dt":"תקנח - יד תשרי","b":"מחכמי פאס. חתן ר אליהו הצרפתי בעל \"נער בוכה\" שהספידו בספרו, נפטר צעיר."},{"i":13685,"n":"דנון, שמואל מפאס","f":"שאול","k":"בעל דברי הימים קורות","bt":"תכח","dt":"תץ","b":"אחיו של ר אברהם מפאס. חיבר \"דברי הימים קורות יהודי פאס\"."},{"i":13686,"n":"דנון, שמואל מפאס-מרוקו","f":"סעדיה","k":"בעל חדושי דינים","bt":"רצב","dt":"שפב - יד אדר","dp":"פאס","b":"נכד ר שמואל בן מימון ן דנאן. תלמיד ר משה סדיקארו מפאס, ולמד בישיבת ר שמואל חגיז. סופר ביה\"ד בפאס יחד עם ר מכלוף אסולין, רב בפאס על מקום ר סעדיה ן רבוח. נספד ע\"י ר שאול סירירו. חיבר חדושי דינים, ונחשב למומחה במנהגי המגרב וקשטיליא. חתם שמו - 'שב\"ד'."},{"i":13687,"n":"דנון, שמואל מפאס-מרוקו","f":"מנשה","bt":"תקס","dt":"תרלב","b":"שו\"ב, ודרשן מחכמי פאס. בזמן פטירתו גילה שבשנה זו ימותו עשרה מחכמי ישראל - וכן היה. בניו: ר משה-נפטר בחיי אביו, ר יצחק בעל \"ליצחק ריח\"."},{"i":13688,"n":"דנון, שמואל מפאס-מרוקו - א","f":"מימון בן סעדיה","dt":"שכו","b":"רב בפאס, חתם-שיא על תקנה, היה מעורב במחלוקת על הנפיחה. אחד ממאתים רבנים שסמכו את ר יוסף קארו (ואולי הכוונה לדברי היעב\"ץ שקבלו את ספרו השו\"ע)."},{"i":13689,"n":"דנון, שמואל שאול מפאס","f":"סעדיה","bt":"תנב","dt":"תקכט - כב כסלו","b":"מו\"צ בפאס"},{"i":13690,"n":"דנון, שניאור מאיפסולה","f":"אברהם","b":"רב באיפסולה-שנות ה-ת'. (ראה גם ר שניאור בן אברהם ממרוקו וונציה ואולי הוא אותו הרב)."},{"i":13691,"n":"דנון, שניאור ממרוקו ונציה","f":"אברהם","b":"רב במרוקו, עבר לונציה וכיהן כרב-תכח, חברו של ר שמואל אבוהב בעל \"דבר שמואל\" - המזכירו בספרו. מהלוחמים נגד השבתאים ובמיוחד נגד נתן העזתי והיה בין שבעת החכמים שבדקו אותו. חיבר סדר וידוי לחולה ונדפס בתוך \"דקדוקה של נפש\". אולי הוא שהיה גם באיפסולה."},{"i":13692,"n":"דנושבסקי משה בן אברהם","dt":"ה'תרע 1910","bk":[["באר משה",""]]},{"i":13693,"n":"דניאל","b":"מגדולי אשכנז-ר\"כ"},{"i":13694,"n":"דניאל","b":"רב בשימאנדי-תקע\"ג"},{"i":13695,"n":"דניאל","f":"עזריה","bp":"בגדד","dt":"ד'תתכב (1062)","b":"ממשפחת ראשי הגולה, עלה לארץ ישראל ונתמנה גאון אחרי פטירת ר שלמה בן יהודה. היה בסכסוך עם ר אביתר הכהן כמתואר ב\"מגילת אביתר\", שימש כגאון בין ד תתיא (1051) ל תתכב (1062), החליף מכתבים עם ר אפרים בן שמריהו בפוסטאט. עמד בקשרים עם ר שמואל הנגיד שאף חיבר שיר לכבודו, מכל תורתו נשארו כמה מעשי בית דין בחתימתו."},{"i":13696,"n":"דניאל","f":"אליעזר","b":"מגאוני בבל, ראש ישיבה בבגדד-ד'תתקס\"ח"},{"i":13697,"n":"דניאל הבבלי","f":"סעדיה","b":"מחכמי בגדד ודמשק, תלמיד ר' שמואל בר עלי הלוי, ראש ישיבה בבגדד-ד'תתק\"ל, דרשן בדמשק-ד'תתק\"פ, התנגד לדרכו של הרמב\"ם, ר' אברהם בן הרמב\"ם סירב לנדותו, בסוף נידהו ראש הגולה והוא נפטר בשברון לב. חיבר השגות על הרמבם"},{"i":13698,"n":"דניאל הדיין","f":"יהודה","b":"מחבר הפיוט \"יגדל אלקים חי\" המבוסס על יג עיקרים של הרמב\"ם. נינו - ר דניאל בן שמואל הרופא מאיטליה, אולי הוא הנזכר אצל עמנואל בן שלמה הצפרוני."},{"i":13699,"n":"דניאל הכהן מג'רבה","b":"דיין ורב באלחארה לכבירה"},{"i":13700,"n":"דניאל הכהן מטריקאלה","k":"דניאל איש חמודות","b":"רב בטריקאלה-שצג-תכז."},{"i":13701,"n":"דניאל הכומסי הקראי","f":"משה","b":"מחכמי הקראים-שנות ה-ת'. חיבר ספר מצוות ונזכר אצל ר יפת שמביא ממנו בספרו."},{"i":13702,"n":"דניאל הלוי","b":"מגדולי רבני שארייא בושנא,עלה לירושלים"},{"i":13703,"n":"דניאל הלוי מטרטקוב","b":"רב בטרטקוב-תרכב."},{"i":13704,"n":"דניאל יצחק מליפאנטו","b":"רב הכולל בליפאנטו-שנות ה-ת'. דיינים אצלו: ר טוביה בוטון, ר אברהם בן משה עמאר, ר מנחם פילוס, ר זכריה הכהן."},{"i":13705,"n":"דניאל מאיטליה","f":"שלמה","b":"רופא מחכמי איטליה, ישב בבלמנטו-ליד פאנו-רח. חיבר פירוש על ראב\"ע לתורה, הערות לפירוש הרד\"ק, ובסופו סיפור מסעיו לאי קרעטא(=כרתים)."},{"i":13706,"n":"דניאל מאיטליה","f":"שמואל דניאל","k":"בעל אבן פנה","b":"רופא מחכמי איטליה-שנות ה-ר'. חיבר \"אבן פנה\" שנכתב עבורו ע\"י הסופר ר אברהם קרשיף-רמז. לדברי צונץ הוא נכד ר דניאל בן יהודה שחי כ-100 שנה קודם לכן."},{"i":13707,"n":"דניאל מאפיון","f":"שמואל","b":"רב באפיון(=קארה-היסאר)-שנות ה-ש'."},{"i":13708,"n":"דניאל מהורדנא - ראה גם דוד","f":"יעקב","k":"בעל חמודי דניאל","dt":"תקסז - כא ניסן","dp":"הורדנא","b":"מו\"צ בהורדנא-תקכז כ-40 שנה. נספד ב\"אגודת אזוב\" לר משה זאב מביאליסטוק. אחיו - ר ישראל מפיעסק."},{"i":13709,"n":"דניאל מוילנא","f":"ידידיה","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":13710,"n":"דניאל מזולקוא","f":"מנחם","b":"מחכמי זולקוא, חתם-תנד על תקנת הקהלה, ועל בחירת ראשי הקהלה-תנג."},{"i":13711,"n":"דניאל מטבריה","f":"אברהם מפלאצק","b":"בשליחות קהילת החסידים-תקמו, חזר לארץ-תקמט, בשליחות-תקס. חתימתו האחרונה משנת תקעא."},{"i":13712,"n":"דניאל מטרביי-צרפת ושלוניקי","dt":"שו - ה שבט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":13713,"n":"דניאל מלבוב","f":"ראובן זליג","b":"מחכמי לבוב, חתם-שצא בפנקס הקהלה."},{"i":13714,"n":"דניאל ממצרים","f":"יוסף","b":"מחכמי מצרים בדורו של הרמב\"ם"},{"i":13715,"n":"דניאל מרדכי משלוניקי","dt":"תנג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":13716,"n":"דניאל מרומא","f":"יחיאל מרומא","b":"אחיו של ר נתן בעל הערוך. פייטן, מגדולי חכמי רומא-ד'תת. חיבר פירוש למשניות, פיוטים ובהם \"אהלל אל במנים ועוגב\"."},{"i":13717,"n":"דניאל משימאנדא","b":"רב בשימאנדא-תקעג, ונזכר בשו\"ת \"חתם סופר\" שהשיב לו בענין ר אהרן חורין מכפר קורטיש שזלזל בתקנת חז\"ל"},{"i":13718,"n":"דניאל שמואל מאזמיר","f":"שמואל דניאל-זקן שמוא","b":"מחכמי אזמיר. מתורתו בספר אביו \"זקן שמואל\", תשובות ממנו ב\"כנסת הגדולה\", \"מרכבת המשנה\" לר אהרן אלפנדרי."},{"i":13719,"n":"דניאל, יצחק מבולגריה","f":"משה","bt":"תרנה","bp":"רוסג'וק-בולגריה","b":"פעיל ציוני, ואיש תיאטרון בתל אביב."},{"i":13720,"n":"דניאל, ששון מבגדד","dt":"תרפז - א ניסן","dp":"בגדד","b":"תלמיד ר שמעון אגסי, תלמיד ישיבת \"מאיר אליהו\" בבגדד. נפטר צעיר. נזכר ב\"צדקה ומשפט\"."},{"i":13721,"n":"דניאנאס, שאול מפאס","f":"שלמה סאלם","b":"מחכמי פאס-רפו, וחתם בהסכמה אודות הנפיחה."},{"i":13722,"n":"דניאנאס, שמואל מפאס","b":"מחכמי פאס, חתם-שי על תקנה."},{"i":13723,"n":"דנילביץ, זאב מקובנא ומשפחתו","f":"דניאל","b":"מוכס בקובנא-רמ בערך, מחשובי היהודים בליטא ובעל השפעה בחצר המלך, לאחר גירוש ליטא-רנה עבר לפולין, וחזר לקובנא-רסג לאחר שהורשו היהודים לחזור. אחיו - מיכאל, צמח, סעדיה, אברהם?"},{"i":13724,"n":"דנילביץ, טעבל מטלז","f":"מאיר","b":"מראשי קהלת טלז-תקץ בזמן המרד הפולני."},{"i":13725,"n":"דנילביץ, צבי הירש מקרוז","b":"עסקן מחכמי קרוז. נכדו - קלמן מגיד מארמיאנסק."},{"i":13726,"n":"דנינו, דוד","f":"מסעוד","k":"בעל רסיסי לילה","b":"מרבני מרוקו, דרשן, חיבר \"רסיסי לילה\""},{"i":13727,"n":"דנינו, יהודה ממכנאס","b":"מחכמי מכנאס. חתם-תקס עם ר יוסף חלואה בענין ביהכ\"נ של ר יהודה בירדוגו."},{"i":13728,"n":"דנינו, יצחק מירושלים","b":"מחכמי ירושלים, בשנת שפה חתם על התקנה לשחרור תלמידי חכמים ממס. בשנת שץ חתם על כתב שליחות ר אברהם ביטון ור שמואל רימון, סבל בפרעות אבן פארוך."},{"i":13729,"n":"דנינו, מרדכי ממכנאס","b":"מחכמי מכנאס, חתם-תקסד עם ר יעקב בירדוגו."},{"i":13730,"n":"דנינו, משה ממראקש","dt":"תרעב","b":"רב במראקש."},{"i":13731,"n":"דנינו, נחמיה מחברון","b":"מחכמי חברון, בשנת תנב הסכים על \"שער אפרים\", חתם על כתב שליחות ר יוסף הלוי-תמט. בשנת תן התמנה לראש הרבנים."},{"i":13732,"n":"דניס, בייניש","b":"חרקוב-תק\"כ"},{"i":13733,"n":"דניס, שמואל חיים מטלז","f":"בייניש דניס","dt":"תש","b":"מרביץ תורה בטלז"},{"i":13734,"n":"דנישבסקי, יעקב מניו יורק","k":"בעל בית יעקב","b":"רב בניו יורק. ?? לא באוצר ??"},{"i":13735,"n":"דנישבסקי, משה מסלובודקה","f":"מאיר שמחה","k":"בעל באר משה","bp":"סמרגון","dt":"תרסח","dp":"סלובודקה","b":"תלמיד ישיבת איישישוק. רב בסוויר, סלובודקה-תרנד בהמלצת ר יצחק אלחנן ספקטור - שבא במיוחד להחתים את ר צבי לויתן על כתב הרבנות, ר משה מרדכי אפשטין על מקומו אחריו בסלובודקה. ר יצחק אלחנן הורה שמי שרוצה סמיכה ממנו חייב לקבל קודם מר משה דנישבסקי. תלמידו - ה\"אור שמח\". פרסם מאמרים ב\"הועד\" - פיעטרקוב תרעד."},{"i":13736,"n":"דנציג אברהם בן יחיאל מיכל","f":"יחיאל מיכל (שמעון)","k":"בעל חיי אדם","r":"מחותנו של הגאון מוילנא","bt":"תקח","bp":"דנציג","dt":"תקפא - ד תשרי","dp":"וילנא","b":"נכד ר שמואל בעל \"נחמות ציון\". תלמיד ר יוסף ליברמן בפרג, ובישיבת ר יחזקאל לנדא הנודע ביהודה. חתן ר משה סגל מוילנא (ולפי פין - חתן ר יחיאל מיכל משוטלנד), התישב בוילנא והתפרנס ממסחר, לזקנתו-אחר שאיבד את רכושו מו\"צ ודיין בוילנא. בשנת תקסד ניצל בנס מפיצוץ שאירע בחצרו והרג 13 נפשות. מחותן עם הגר\"א. מבניו: ר יצחק, ר חייא, ר משה שלום-נפטר בחיי אביו-תקעה. נשא ונתן עם ר מאיר פוזנר משוטלנד, ר חיים ברוידא מהורדנא. תלמידו - ר ישראל גינצבורג מזארעצא-ליד וילנא חיבר הקדמה לספרו \"חיי אדם\".","bk":[["זכרו תורת משה – שבת",""],["חיי אדם, נשמת אדם – או\"ח",""],["חכמת אדם, בינת אדם – יו\"ד",""],["שערי צדק – הלכות דארץ ישראל",""],["חיי אדם",""],["חכמת אדם",""],["זכרו תורת משה – שבת , שערי צדק – הלכות דארץ ישראל, חכמת אדם, בינת אדם – יו\"ד, חיי אדם, נשמת אדם – או\"ח ,",""],["זכרו תורת משה - קהילת יום טוב",""],["בינת אדם",""],["בית אברהם",""],["דרך אדם",""],["זכרו תורת משה",""],["חיי אדם וחכמת אדם",""],["חיי אדם עם נשמת אדם",""],["חיי אדם עם תוספות חייים",""],["מצות משה",""],["נשמת אדם",""],["קצור מספר חיי אדם",""],["קצור ספר חרדים",""],["קצור ספר חרדים מנין המצות",""],["שערי צדק",""]],"e":"תק\"ח-תקפ\"א"},{"i":13737,"n":"דנציג, אליהו מוילנא","f":"חייא מוילנא","bt":"תקף","dt":"תקצח - טו אייר","dp":"וילנא","b":"נכד בעל \"חיי אדם\". חתן ר יעקב מקרלין בעל \"משכנות יעקב\". נפטר צעיר."},{"i":13738,"n":"דנציג, אליהו מוילנא","f":"יצחק","bt":"תריז או תרכה","dt":"תקפא - ו אב","b":"נכד-אבי אמו ר יהודה ליב-בן הגר\"א. חתן ר עזריאל בן נחום טריווש. נזכר בספר זקנו \"חיי אדם\"."},{"i":13739,"n":"דנציג, חייא מוילנא","f":"אברהם - בעל חיי אדם","dt":"תרכג - כ אייר","dp":"וילנא","b":"חתן ר אריה אקסלרוד-בן מרדכי ואחיו של ר אליהו הינדעס. גביר מחכמי וילנא, התישב במאסקוי(=מוסקבה). פעל במקומות רבים ונדחים לטובת החיילים היהודים, ופעל לשכנוע שרי הצבא לתת להם מנוחה בשבתות ומועדי ישראל, יסד בית תפלה עבורם במוסקבה, ובסמולנסק. בזמן מגפת החולירה בוילנא-תקצא דאג לחולים בהשגחתו ובכספו וכן במגפה-תרח, וברעב-תרד הקים בית תמחוי והציל רבים מרעב. בניו ר אליהו ור אריה נפטרו בחייו וכן בתו. נספד ב\"המגיד\" (שנה יא), \"הכרמל\" (שנה ג). נוסח מצבתו מאת המשורר אד\"ם הכהן."},{"i":13740,"n":"דנציג, יהודה ליב מוילנא","f":"אליהו-נין הגר\"א","bt":"תקעד","dt":"תרמא - ל תשרי","dp":"וילנא","b":"נקרא ע\"ש אבי זקינו ר יהודה ליב-בן הגר\"א. נינו של בעל \"חיי אדם\". חתן ר וועלוועלע ר אשר'ס גינצבורג-חתן ר ישכר בר אחי הגר\"א. תלמיד ר אברהם בן מאיר לוטשינר. גביר מחכמי וילנא. חתניו: ר יהושע גרדשטין מלובלין בן ר שמחה אפרים פישל, ר מאיר אברהם הכהן מויטבסק בן ר זאב וולף שמלקש,"},{"i":13741,"n":"דנציג, יעקב שמעון","f":"אליעזר","bt":"תקל","bp":"קראקא","dt":"תקצז","b":"תלמיד הנועם אלימלך והחוזה מלובלין, חברו של ה\"מאור ושמש\". חתן ר אברהם סגל הורביץ ראב\"ד קראקא."},{"i":13742,"n":"דנציג, יצחק מוילנא","f":"אברהם - בעל חיי אדם","dt":"תריג - ד ניסן","b":"חתן ר יהודה ליב-בן הגר\"א. גביר מחכמי וילנא. חתם על מסמכים שונים בעניני הקהלה. חיבר הקדמה לספר צוואת אביו \"בית אברהם\". בנו היחיד ר אליהו נפטר בחייו. נכדו ר אריה יהודה ליב הקים מצבה על קברם."},{"i":13743,"n":"דנציג, יצחק מיאנוב","k":"בעל תשובות מהריד","bt":"תקצז","b":"מו\"צ ביאנוב-תרכ, מגיד במלאווא-תרכט, מוהילוב, מו\"צ בפטרבורג-תרם. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. חיבר \"אבל משה\" - הספד על מונטיפיורי - פטרבורג תרמו."},{"i":13744,"n":"דנציג, מרדכי מוועטש","f":"חיים מצעהלים","bt":"תקצז","bp":"צעהלים","dt":"תרפב - כז שבט","dp":"ליפטא סנט-וועטש","b":"תלמיד הכת\"ס, ור עזריאל הילדסהימר. חתן ר מנחם קירץ. רב בוועטש. נזכר בשו\"ת \"מחנה חיים\"."},{"i":13745,"n":"דנציג, מרדכי מוילנא","f":"אריה בן חייא","b":"מצאצאי בעל \"חיי אדם\". בקי בשפות. חתן הגביר ר שכנא אקרמן מגארזד. גביר מחכמי וארשא."},{"i":13746,"n":"דנציג, שלום מויליצקה","b":"מתורתו - \"ועד חכמים\"."},{"i":13747,"n":"דנציג, שמואל בנימין מסיגט","f":"מרדכי מוואג-וועטש","bt":"תרלה","bp":"וואג-וועטש","dt":"תש..","b":"תלמיד השב\"ס, וישיבת פפד\"מ ובעל תואר ד\"ר מברלין. חתן ר בנימין זאב קרויס מדברצין. רב הקהילה הספרדית בסיגט-תרסו. נסמך מאת: השב\"ס, ר שלמה זלמן ברייער מפפד\"מ. פעיל בתנועה הציונית ועמד בראש הג'וינט שם. נספה בשואה. בנו הלל בעל \"בצל הסוסים\"."},{"i":13748,"n":"דנציגר, אברהם חיים","f":"שמואל צבי מאלכסנדר","bt":"תרמב?","dt":"תשג - י תשרי","dp":"טרבלינקה","b":"ראש ישיבה ונשיא רשת הישיבות \"בית ישראל\" בפולין יחד עם אחיו האדמור מאלכסנדר בעל \"עקדת יצחק\", מנהל עניני החסידות מטעם אחיו, ומראשי הצבור היהודי בפולין. נספה בשואה."},{"i":13749,"n":"דנציגר, אברהם יהודה מלודז","f":"בצלאל יאיר מלודז","bt":"תרמג","dt":"תשג - א תשרי","b":"אדמו\"ר מאלכסנדר בלודז על מקום אביו. נספה בשואה."},{"i":13750,"n":"דנציגר, אברהם מוינקוביץ","f":"שלמה או שמעון דרימר","bt":"תרכג","b":"רב במיחלאפליא-פודוליה-תרמג, בווינקוביץ-פודוליה-תרנג. נסמך מאת: ר משלם פיבל הכהן."},{"i":13751,"n":"דנציגר, אברהם מליבאוי","b":"גביר מחכמי ליבאוי, יסד חברת גמ\"ח-תקפח."},{"i":13752,"n":"דנציגר, בצלאל יאיר מלודז","f":"יחיאל מאלכסנדר","k":"אדמור מאלכסנדר בלודז","bt":"תרכא","dt":"תרצד - כה אדר","dp":"לודז - אלכסנדר","b":"חתן החסיד ר צבי הירש מפלאוונא. אדמור בלודז-תרעד. בנו ר ירחמיאל - נספה בשואה."},{"i":13753,"n":"דנציגר, גבריאל","b":"רב בשיטיק,ראדום-תרט\"ו"},{"i":13754,"n":"דנציגר, יחיאל מאלכסנדר","f":"שרגא פייבל מגריצא","k":"אדמור מאלכסנדר","bt":"תקפח","dt":"תרנד - יד שבט","b":"חתן ר דוד מפשיסחא. תלמיד ר מרדכי מנחם מווארקי, ר דב בעריש מביאלא. רב בטורטשין, גריצא, רב ואדמור בפילץ, אלכסנדר-ליד לודז. מתורתו ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":13755,"n":"דנציגר, יעקב בונם","b":"רב-שנת תר\"פ"},{"i":13756,"n":"דנציגר, יעקב ירחמיאל יחזקאל","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":13757,"n":"דנציגר, יעקב פנחס שרגא","f":"יצחק מנחם מנדל מאלכס","bt":"תרף","dt":"תרצח - יג אד\"א","b":"בן האדמור מאלכסנדר. נפטר בצעירותו בחיי אביו. קונטרס לזכרו ובו מתורתו בתוך \"נהור שרגא\" - אלכסנדר תרצט."},{"i":13758,"n":"דנציגר, יעקב שמחה בונם","f":"שמואל צבי מאלכסנדר","dt":"תשא","dp":"וארשא","b":"בן האדמור מאלכסנדר. נספה בשואה."},{"i":13759,"n":"דנציגר, יצחק מנחם מנדל","f":"שמואל צבי מאלכסנדר","k":"אדמור מאלכסנדר","r":"אדמו\"ר מאלכסנדר","bt":"תרמ","bp":"אלכסנדר","dt":"תשב-ג - כג אלול","b":"תלמיד זקנו - האדמור ר יחיאל מאלכסנדר, דודו בעל \"ישמח ישראל\". חתן הגביר ר מיכאל אורבך מלודז. אדמור באלכסנדר-תרפד, הקים רשת ישיבות \"בית ישראל\" ברחבי פולין ובארץ ישראל הקים ישיבת \"ישמח ישראל\". נספה בשואה. חיבר \"עקידת יצחק\". מתולדותיו ב\"רועה נאמן\". בניו: ר ירחמיאל ישראל יוסף, ר יעקב פנחס שרגא.","bk":[["עקידת יצחק [עה''ת] (אלכסנדר)",""],["עקידת יצחק – עה\"ת ומועדים",""]]},{"i":13760,"n":"דנציגר, ירחמיאל ישראל יוסף מאל","f":"יצחק מנחם מנדל מאלכס","bt":"תרעג","dt":"תשב - כג אלול","dp":"טרבלינקה","b":"בן האדמור מאלכסנדר. חתן ר נתן דוד מפרצוב (שושלת פשיסחא). נספה בשואה."},{"i":13761,"n":"דנציגר, ירחמיאל ישראל יצחק","f":"יחיאל מאלכסנדר","k":"אדמור מאלכסנדר","bt":"תריג","dt":"תרע - א שבט","b":"חתן משפחת גורמן מפולטוסק. אדמור באלכסנדר-תרנד. נפטר ללא ילדים. חיבר\"ישמח ישראל\". מתולדותיו ב\"תפארת ישראל\".","bk":[["ישמח ישראל (אלכסנדר)",""],["ישמח ישראל",""]]},{"i":13762,"n":"דנציגר, פיבל מאוסטרובא","b":"רב באוסטרובה-תר\"פ"},{"i":13763,"n":"דנציגר, שמואל צבי מאלכסנדר","f":"יחיאל מאלכסנדר","k":"אדמור מאלכסנדר","r":"אדמו\"ר מאלכסנדר","bt":"תרך-ם","dt":"תרפד - כט תשרי","b":"חתן הגביר ר יעקב גורמן מפולטוסק. אדמור מאלכסנדר-תרע על מקום אחיו ר ירחמיאל ישראל. חיבר \"תפארת שמואל\", מבניו: ר שרגא פיבל מראדום הי\"ד, ר יעקב שמחה בונם, ר אברהם חיים, חתנו ר יצחק מאיר זינגר מאלכסנדר.","bk":[["תפארת שמואל [עה''ת] (אלכסנדר)",""],["תפארת שמואל – עה\"ת",""]]},{"i":13764,"n":"דנציגר, שמעון","b":"מרביץ תורה-תר\"ל"},{"i":13765,"n":"דנציגר, שרגא פיבל מגריצא","f":"צבי הירש","dt":"תרט - כג תשרי","b":"מייסד שושלת אלכסנדר, תלמיד ר יעקב מליסא וסידר את ספרו \"נתיבות למשפט\" לדפוס. רב בשעפס, גומבין-תרג, גריצא, מקובא. תלמיד החוזה מלובלין, ר שמחה בונם מפשיסחא ובנו ר אברהם משה, ר יצחק מווארקי. אדמור במאקובה אחר פטירת רבו. מתולדותיו ב\"עשר זכיות\". פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":13766,"n":"דנציגר, שרגא פיבל מראדום","f":"שמואל צבי מאלכסנדר","dt":"תרעד - יב אלול","b":"בן האדמור מאלכסנדר. רב בראדום. נהרג עק\"ה במלחמת העולם הראשונה."},{"i":13767,"n":"דנציגר-טיברג, אברהם מנחם מאלכס","f":"יהודה משה מאלכסנדר","k":"אדמור מאלכסנדר ב\"ב","b":"חתן ר חנניה יוסף הלפרין. אדמור מאלכסנדר בבני ברק. חבר מועצת גדולי התורה של אגו\"י."},{"i":13768,"n":"דנציגר-טיברג, יהודה משה","f":"יחיאל יוסף","k":"אדמור מאלכסנדר","r":"האדמו\"ר מאלכסנדר","bt":"תרנג-סג","dt":"תשלג - כג אד\"א","b":"חתן ר בצלאל יאיר דנציגר האדמור מלודז אלכסנדר. שינה שמו מטיברג לדנציגר. ניצל מהשואה ואחריה אדמור מאלכסנדר בבני ברק. חיבר \"אמונת משה\", \"מאורן של ישראל\".","bk":[["אמונת משה [עה''ת]",""],["חשבה לטובה (אלכסנדר)",""],["אמונת משה – עה\"ת וש\"ס",""],["אמונת משה – עה\"ת וש\"ס, נחלת צבי, וזאת ליהודה – בנין דוד, חידושי אמונת משה, חשבה לטובה – שו\"ת",""],["וזאת ליהודה – בנין דוד",""],["חידושי אמונת משה",""],["חשבה לטובה – שו\"ת",""],["נחלת צבי",""]]},{"i":13769,"n":"דנציגר-קאהן, אברהם חיים מוארש","b":"פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"המאסף\" - ירושלים תרנו, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":13770,"n":"דנקליס, יוסף מסלובודקא","b":"תלמיד בכולל סלובודקא. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב."},{"i":13771,"n":"דנקר, יוסף מירושלים","f":"אליהו מליצין","bt":"תרח","bp":"ירושלים","dt":"תרפז - י ניסן","dp":"ירושלים","b":"שומר קברות הצדיקים בירושלים."},{"i":13772,"n":"דסברג, שמעון מפריסלנד","b":"רב בפריסלנד"},{"i":13773,"n":"דסלר, אליהו אליעזר מלונדון","f":"ראובן דוב מקלם","k":"בעל מכתב מאליהו","r":"ראש כולל בלונדון ומשגיח בישיבת פוניבז'","bt":"תרנא","bp":"קלם","dt":"תשיד","b":"למד גם קבלה וחסידות חב\"ד. חתן נכדת ר שמחה זיסל זיו מקלם, התפרנס ממסחר והיה מאנשי \"בית התלמוד\" בקלם. מחנך, מגדולי בעלי המוסר, הגיע לאנגליה-תרפו וכיהן כרב ומחנך, ר\"מ בגייטסהאד, הוזמן ע\"י ר חיים עוזר לכהן כרב בוילנא וסירב, משגיח בישיבת פוניביז'-בני ברק-תשח. . תלמידיו ר אליהו כרמל ור אלתר הלפרין הו\"ל את ספרו \"מכתב מאליהו\". פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא, \"תבונה\" - קובנא תרפא.","bk":[["מכתב מאליהו",""],["חידושי הגרא\"א דסלר",""],["חידושי הגרא\"א דסלר – סוגיות",""],["מכתב מאליהו – מוסר",""],["מכתב מאליהו – מוסר , חידושי הגרא\"א דסלר – סוגיות",""]],"e":"תרנ\"ב-תשי\"ד"},{"i":13774,"n":"דסלר, ראובן דוב","b":"מגדולי המשפיעים בתורת המוסר בהומל,קלם-תר\"נ. אביו של ר אליהו אליעזר."},{"i":13775,"n":"דסמשתרי, יונה מספרד","b":"מחכמי ספרד. חותנו של הרשב\"ץ."},{"i":13776,"n":"דסמשתרי, שלמה מספרד ואלגיר","f":"יונה","dt":"קץ","dp":"אלגיר","b":"רב במיורקה-ספרד, עבר לאלגיר, הוניין, קצמטינא. גיסו של הרשב\"ץ ודודו של הרשב\"ש המכנהו בתואר \"המאור\". מתלמידיו ר נתן נגאר. חתנו - ר יוסף בן אברהם ששפורטש."},{"i":13777,"n":"דעדוש, כליפא מטריפולי","bt":"תקעח","dt":"תרנח - כח אדר","dp":"טבריה","b":"רב בטריפולי. עלה לארץ והתישב בטבריה והקים ישיבה שנקראה על שמו - \"צלאת רבי כליפא דעדוש\". (יש רושמים תאריך פטריתו - תרסג)."},{"i":13778,"n":"דעהן, יעקב אברהם","dt":"תקפא - ח שבט","b":"רב בלוורדן"},{"i":13779,"n":"דעוויס, אלכסנדר ברוך מסידני","b":"רב בסידני-אוסטרליה-תרע. חתנו - ר יוסף אברהמס ממלבורן."},{"i":13780,"n":"דעליטשער, יוסף מדיאליטשיץ","dt":"תריט - תשרי","dp":"סלונים","b":"מגדולי החסידות בליטא, מקורב לאדמורי סלונים ר מרדכי מלכוביץ ובנו ר נח, מחסידי ר משה מקוברין ותלמידו ר אברהם מסלונים. מסופרים עליו מופתים וגילוי רוח הקדש. מכתב ממנו הקורא לחסידים לבוא להכתרת ר אברהם וינברג כאדמו\"ר מסלונים-תריט."},{"i":13781,"n":"דעליס, יהושע מבריסק","k":"המגיד מסלונים","dt":"תרסב - א שבט","b":"דרשן,מגיד בבריסק"},{"i":13782,"n":"דעסוי, ברוך מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":13783,"n":"דעסוי, דב בער מהמבורג","f":"יונה מדעסוי","dt":"תקיח - יג אייר","dp":"אלטונא","b":"דיין מחכמי הקלויז ישן בהמבורג של ר ישכר בר הכהן. בנו - ר יצחק מהמבורג ונכדו - ר צבי הירש מאטנזען."},{"i":13784,"n":"דעסוי, יצחק איזיק","b":"ראש הקהל בברלין-תקמ יחד עם גיסו הגביר ר דניאל יפה."},{"i":13785,"n":"דעסוי, יצחק איצק מהמבורג","f":"צבי הירש","dt":"תרכו - יג תמוז","dp":"המבורג","b":"מלמד בהמבורג."},{"i":13786,"n":"דעסוי, נתן","b":"דומ\"צ בנייטרא-תר\"י"},{"i":13787,"n":"דעסויער, גבריאל הלוי מבאלאטן","f":"נתן הלוי","k":"בעל יד גבריאל","bt":"תקסה","bp":"נייטרא","dt":"תרלח - כט אייר","b":"תלמיד החת\"ס, ור יוסף פלעש מנייטרא. רב בבאלאטן-פעקאיאר."},{"i":13788,"n":"דעסויער, גבריאל משיו-פוק","k":"בעל יד גבריאל","dt":"1905","b":"רב בקהילה הניאולוגית בשיוק-פוק-מחוז וספרם-תרלח. חיבר גם \"האריאל\", \"דגל הלוי\", ועוד. (אולי הוא זהה עם הרב מבאלאטן - ויש טעות בתאריכים)."},{"i":13789,"n":"דערבוי, יוסף ליב מפולין","b":"תלמיד החת\"ס. הגיע מפולין לפני תריב. מובא עליו ב\"מחנה חיים\"."},{"i":13790,"n":"ד'פאנו, אלכסנדר מאיטליה","b":"רב בקורפו, רב הכולל במילנו-איטליה-תרנג."},{"i":13791,"n":"דקינגן, יצחק איזיק","dt":"תלז","b":"רב באמסטרדם-תכ\"ז"},{"i":13792,"n":"דקל, סעדיה מתימן","b":"מחכמי צנעא-תקלא ונזכר בפנקס בית הדין בצנעא."},{"i":13793,"n":"דראב, יהודה","b":"דיין ברייגרוד,רב בגראייבה-תר\"מ,ארה\"ב תרס\"ב"},{"i":13794,"n":"דראביטשער, דב בער דובער מקמניץ","b":"רב בקמניץ, מכתב ממנו-תרצד."},{"i":13795,"n":"דראזד, זאב מבגדרבקה","f":"דוד","k":"בעל שני הפכים","bt":"תרכט","bp":"רוסיה","b":"מלמד לנערים בגיל 14. עבר אל חותנו בפטרפוולאווקה-פלך יקטרינסלב. קיבל תעודת מורה-1902. חיבר \"שני הפכים ספור\". פרסם מאמרים ב\"גן שעשועים\"."},{"i":13796,"n":"דראזד, שלמה יצחק משעביז","bt":"תקפז-צ","bp":"שעביז","dt":"תרסד - ח אדר","b":"תלמיד ר ישראל סלנטר בוילנא. רב בשעביז. תומך בציונות וממיסדי \"המזרחי\" - היה במשלחת הרבנים הציוניים לצדיקי פולין ובהם הרב ריינס. תשובות ממנו בספר חברו - ר יצחק ציוני מרעזיצא."},{"i":13797,"n":"דראך (טראך)","k":"משפחה","b":"מקור המשפחה בכפר שיטצען ליד שטמפן."},{"i":13798,"n":"דראך, אברהם מפפד\"מ","f":"[שמואל]","b":"פרנס ומראשי קהילת פפד\"מ-תך."},{"i":13799,"n":"דראך, עמנואל מפפד\"מ ווינה","dt":"תצט","b":"חתן ר שמואל אופנהיים מפפד\"מ. פרנס ונציג קהילת פפד\"מ בוינה עם חברו ר זיסקינד שטרן, והיה בקשר עם ר שמשון ורטהיים שהיה מייצג את עניני היהדות בפני הקיסר. בזמן גירוש וינה-תפג הותר לו להישאר בגלל מעמדו כנציג קהילת פפד\"מ בוינה."},{"i":13800,"n":"דראך, שמואל מפפד\"מ","b":"ראב\"ד בפפד\"מ-תקנה - והדיינים שעמו ר חיים גונדרשהיים, ור שלמה טריר. (היה בי\"ד נוסף בראשות ר מאיר שיף)."},{"i":13801,"n":"דראע, דוד הלוי","f":"דוד הלוי בעל המלכות","k":"בעל ספר המלכות","dt":"ז סיון","b":"מקובל, בגירוש ספרד עבר למרוקו-רנ\"ב, למד תורה בפאס, דיין בתאמגרות, חיבר ספר \"המלכות\""},{"i":13802,"n":"דרבקין, דוד מירושלים","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"תבונה\" - ירושלים תשא-תשח, \"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":13803,"n":"דרבקין, יצחק מחרסון","b":"רב ביאזר - מושבה יהודית בפלך חרסון."},{"i":13804,"n":"דרבקין, צבי","f":"שמואל הלל","k":"העילוי משקלוב","bt":"תרכב","bp":"שקלוב","dt":"תרפט","dp":"חברון","b":"תלמיד ישיבת וולוזין, חתנו של ר נתן רובין רבה של בוברויסק ולאחר פטירת חותנו מילא את מקומו. בשנת תרפה עלו שני בניו ללמוד בישיבת חברון בחברון, ובשנת תרפט הצטרף אליהם בחברון ונרצח בפרעות. חדושים שלו בשם \"מזכרת צבי\" בסוף ספר בנו ר אליהו דרבקין \"בכורי אליהו\" ירושלים תשכב."},{"i":13805,"n":"דרברמדיקר, אברהם יעקב מפשקאן","k":"אדמור מפשקאן","dt":"תשכד","b":"מצאצאי ר לוי יצחק מברדיטשוב. חתן ר פנחס לנדמן מאוקנא. אדמור בפשקאן. עלה לארץ והתישב בתל אביב. חיבר \"לנפש חיה\"."},{"i":13806,"n":"דרברמדיקר, אלימלך","f":"יוסף יהושע","bt":"תרלז","b":"חתן ר חיים סטיפנסקי מברזדוב. רב במיזיקוב(=מיזיקאב)-פודוליה-תרסה."},{"i":13807,"n":"דרברמדיקר, דב בר","f":"לוי יצחק מברדיטשוב","bt":"תקל","dt":"תקפד","b":"בנו ר לוי יצחק מסמוטריטש ור זאב וולויל."},{"i":13808,"n":"דרברמדיקר, זאב מאישישוק","b":"חתן ר יונה קפליבטובסקי מקאפרעשטי. מחכמי איישישוק."},{"i":13809,"n":"דרברמדיקר, יוסף יהודה ליב מריצ","f":"לוי יצחק","bt":"תרז","b":"רב בריצוב-ווהלין-תרלח."},{"i":13810,"n":"דרברמדיקר, יוסף ישראל איסר","f":"מאיר","b":"נכד ר לוי יצחק מברדיטשוב. אביו של ר שניאור זלמן חתן ר פנחס מסלאויטא (קוריץ)."},{"i":13811,"n":"דרברמדיקר, יעקב","f":"לוי יצחק דרברמדיג","b":"רב בפאקשאן-תר\"ס"},{"i":13812,"n":"דרברמדיקר, ישראל מפיקוב","f":"לוי יצחק מברדיטשוב","k":"בעל תולדות יצחק בן ל","dt":"תקעח - כג אלול","b":"חתן ר עקיבא ממיקוליב. רב בפיקוב, ברדיטשוב על מקום אביו. חיבר גם \"תורת ישראל\", \"לקוטי מהרין ותולדות יצחק\" ברדיטשוב תקעא. מבניו ר שמואל שמלקא, ר פנחס ור מתתיהו יחזקאל. חתנו ר משה הלוי שטאל מטריאנוב."},{"i":13813,"n":"דרברמדיקר, לוי יצחק מניגרשט","b":"רב בניגרשט"},{"i":13814,"n":"דרברמדיקר, לוי יצחק משיטאווה","f":"ישראל מפיקוב","k":"אדמור מפיקוב","b":"נכד ר לוי יצחק מברדיטשוב."},{"i":13815,"n":"דרברמדיקר, מאיר","f":"לוי יצחק מברדיטשוב","dt":"תקסו - כט תשרי","b":"חתן הלבושי שרד ובזיוו\"ש חתן ר אליעזר ראש ישיבה בקרלין-פינסק. רב בפיקוב-(תן? - כך באוצר הרבנים). נפטר בחיי אביו. נזכר בספר אביו \"קדושת לוי\". בניו ר יוסף ישראל איסר, ר אליעזר."},{"i":13816,"n":"דרברמדיקר, משה","f":"לוי יצחק מברדיטשוב","b":"רב-שנת תק\"צ"},{"i":13817,"n":"דרברמדיקר, משה יהושע מפיקוב","f":"ישראל מפיקוב","b":"נכד ר לוי יצחק מברדיטשוב. רב בפיקוב-תר."},{"i":13818,"n":"דרברמדיקר, מתתיה יחזקאל","f":"משה דרברמדיגר"},{"i":13819,"n":"דרברמדיקר, מתתיה יחזקאל","f":"פנחס דרברמדיגר"},{"i":13820,"n":"דרברמדיקר, פנחס","f":"מתת' יחזק' דרברמדיגר"},{"i":13821,"n":"דרברמדיקר, שמעון אהרן","f":"מתתיה יחזקאל","bt":"תרלו","b":"רב בבאהוש(=בוהוש)-רומניה-תרסג ור\"מ בישיבת \"בית ישראל\" (הישיבה היחידה ברומניה המאושרת בידי השלטון) - בראשות האדמור רמ\"מ פרידמן."},{"i":13822,"n":"דרגו, אברהם מאלגיר","bt":"שי","dt":"שע","b":"שאלה ממנו לר אברהם ן טוואה ונזכר ב\"חוט המשולש\"."},{"i":13823,"n":"דרגינסקי, יצחק יוסף מלאייעוו","f":"יהודה","bt":"תרך","b":"רב בלייאוב(=לאייעוו)-פלך מינסק-תרן."},{"i":13824,"n":"דרוהוביטש, ברוך מרוסטוב ומזיבו","f":"יחיאל מיכל מדרוהוביט","b":"מצאצאי הבעש\"ט. רב ברוסטוב-דון, מזיבוז על מקום אביו. מכתב ממנו לרב קוק-תרצה ובו מבקש עזרה בעליה לארץ."},{"i":13825,"n":"דרוהוביטשר, יצחק מימפולא","f":"יוסף מימפולא","k":"אדמור ממזבוז","b":"נגד המגיד מזלוטשוב. חתן ר ברוך ממזבוז, אדמור במזבוז על מקום חותנו. בנו ר יחיאל מיכל מימפולא-חתן האדמור מרדכי מטשרנוביל."},{"i":13826,"n":"דרוהוביטשר, ישראל נחמן מצפת","f":"יוסף-תלמיד הבעשט","k":"בעל חמדת ישראל","bt":"תקה","bp":"סטניסלב","dt":"תקפה-תקץ","dp":"צפת","b":"נקרא ע\"ש הבעשט. תלמיד ר יוסף בלוך בעל \"גנזי יוסף\". חתן ר שמואל מאוסטרהא (ואשתו היתה דור חמישי למהרש\"א), דיין באוסטרהא ואחר כך ראבד בעיר שימאנדא-הונגריה, ראש ישיבה בגרוסורדין. עלה לארץ-תקסד ובדרכו עבר בליוורנו התגורר שם ולמד אצל החיד\"א שם - הזכירו החיד\"א בספרו \"חומת אנך\". (נקרא שם בשם פאלאקי ע\"ש מדינתו). היה אב\"ד צידון, התישב בצפת, בשליחות-תקעג בליוורנו. בזיוו\"ש חתן ר אברהם דוויך הכהן מבירות. היה מהחכמים הראשונים שהעבירו ידיעות על החסידות לחכמי ספרד והמזרח. עלה לארץ בסוף ימיו. נדד בקהלות שונות כדי למכור את ספריו - \"פקודת המלך\" ליוורנו תקסד, \"יקרא דחיים\" שלוניקי תקעג, \"שארית ישראל\", \"אמת ליעקב\" (כך לפי וינר) - הספד על ר יעקב חיים בן נאים . ועוד. אולי הוא שהסכים על \"עץ חיים-קוריץ תקמב.","bk":[["פקודת המלך","מפרשי רמב\"ם"]]},{"i":13827,"n":"דרוויש, עזרא אליהו מעירק","k":"בעל ספר הזכרון","b":"רב בעקר-עירק, בזמן ר אהרן ברזני וה\"בן איש חי\"."},{"i":13828,"n":"דרווסקי, ישראל נחום","f":"אברהם משה","k":"בעל קורות היהודים","bt":"תריד","bp":"מוהילוב","b":"מורה בקיוב. פרסם מאמרים ב\"המליץ\", \"הצפירה\", ועוד. חיבר \"לקורות היהודים בקיוב\" - תרסג, ו\"בר מצוה\" - בכת\"י."},{"i":13829,"n":"דרויא, יוסף יהודה משילאל","b":"רב בשילאל-תרעד עד תרף."},{"i":13830,"n":"דרוינוב, אבא אברהם אשר אלתר","f":"אליקום פסח גצל","k":"בעל ספר הבדיחה והחיד","bt":"1870","bp":"דרוייה-ליטא","dt":"1938","dp":"תל אביב","b":"סופר וחוקר פולקלור. תלמיד ישיבת וולוזין. מזכיר ועד חובבי ציון באודסה. עורך \"העולם\", \"רשומות\", \"מימים ראשונים\". הו\"ל \"כתבים לתולדות חיבת ציון\"-תרעט."},{"i":13831,"n":"דרום, זלמן מפפד\"מ","dt":"תצא - אייר","b":"גביר בפפד\"מ, בשנת תמט אירח את ר אברהם קונקי שליח קהלת חברון, ובקש ממנו לרשום לו את ידיעותיו על שבתי צבי."},{"i":13832,"n":"דרום, ליב מפפד\"מ","b":"פרנס בפפד\"מ-תפה, פעל נגד השבתאות."},{"i":13833,"n":"דרום, משה מפפד\"מ","f":"אברהם רייניש","dt":"תצא - טו ניסן","dp":"פפד\"מ","b":"דיין בפפד\"מ. הו\"ל \"יוסף אומץ\" לר יוסף האן - זקנה של אשתו."},{"i":13834,"n":"דרוק, אברהם מסניאטין","b":"ראב\"ד סניאטין לפני מלחמת העולם הראשונה. חתן ר חיים יעקב לנדא אב\"ד צורטקוב. אב\"ד צורטקוב על מקום חותנו."},{"i":13835,"n":"דרוק, אברהם מצורטקוב","dt":"תרפו","b":"מחכמי קיטוב - בין החותמים שם על קריאה לסיוע לאחר השרפה-תרסג. חתן ר שמואל מזמושץ - אחיו של ר חיים לנדא מצורטקוב. ממלא מקום הרב בצורטקוב ובתרפו נתמנה על מקומו."},{"i":13836,"n":"דרוק, חיים מנחם שלמה מירושלים","f":"בנימין","k":"בעל אורות חיים","r":"ראש חבורה בישיבת עץ חיים, ובכולל בית זבול","bt":"תרף","bp":"ירושלים","dt":"ח אדר תשמג","b":"חתן ר משה אהרן גולומב. תלמיד ישיבות ירושלים ור\"מ בישיבה. חיבר \"אורות חיים\" ירושלים תשטז.","bk":[["אורות חיים - בין השמשות, אתרוג מורכב",""]]},{"i":13837,"n":"דרוק, יעקב","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":13838,"n":"דרוק, משה עקיבא מירושלים","f":"מאיר","bt":"תרפג","b":"חתן ר יוסף דייטש. כותב בעתונים וברדיו. עורך המודיע."},{"i":13839,"n":"דרוקר, אליעזר הכהן מאליווער","b":"רב בארה\"ב. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":13840,"n":"דרוקר, דוד מבריסק","b":"גביר מחכמי בריסק-שנות ה-ש' בזמן המהרש\"ל. חתנו - השר שאול וייל."},{"i":13841,"n":"דרוקר, מרדכי מסטרי","f":"יהודה ליביש","k":"בעל תכלת מרדכי","bt":"תריד","bp":"סטרי","dt":"תרצה","b":"רב בסטרי. חיבר \"תכלת מרדכי\" למברג תרנד, ועוד."},{"i":13842,"n":"דרוקר, צבי הירש מיאס","b":"תשובה אליו - \"אורי וישעי\"-תרלז."},{"i":13843,"n":"דרוקשקוביץ, חיים","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":13844,"n":"דרושקוביץ, אברהם מולוזין ונ\"י","k":"בעל שערי הוראה","b":"משגיח בישיבת וולוזין, רב בשאט-תרנז, רב בניו יורק."},{"i":13845,"n":"דרזי, יצחק מירושלים","b":"מקובל מחכמי ירושלים והקים ישיבה למקובלים, ור יהודה פתייא לימד שם את תורת הסוד."},{"i":13846,"n":"דרזי, שמואל מבגדד","dt":"תשסו - כג כסלו","dp":"ירושלים","b":"תלמיד בישיבת \"בני ציון\" אצל ר בן ציון מוצפי בבגדד, ר\"מ בישיבה אצל ר בן ציון. עלה לארץ דרך פרס-תשיב, ופעל לחיזוק היהדות אצל העולים ברחבי הארץ. הקים את ועד הרבנים לעולי בבל ופעל להדפסת ספרי חכמי בבל. ממקובלי ירושלים ויסד מנין לגדולי המקובלים ובהם ר יעקב עדס, ר סלמן חוגי עבודי, ר סלמן מוצפי, ר אפרים אנקווה ועוד. הניח חבורים בכת\"י."},{"i":13847,"n":"דרזניץ, יהודה מהאליטש וסעניץ","b":"רב בהאליטש-תקכ\"ה,סעניץ-תקמ\"א"},{"i":13848,"n":"דרזנר, יהושע מקראקא","dt":"תרלג או תרנג","dp":"קראקא","b":"דיין בקראקא."},{"i":13849,"n":"דרזנר, ישראל ליב מלמברג","b":"שו\"ב בלמברג במינוי החוזה מלובלין. נכדו ר שמחה על מקומו."},{"i":13850,"n":"דרזנר, שמשון אלתר מקראקא","b":"סופר בקוסוב וקראקא. תשובה אליו - \"חזון נחום\"."},{"i":13851,"n":"דריבין, איסר מקובנא","b":"ר\"מ בישיבת \"אהל יצחק\" בקובנא-תרצה, יחד עם ר יצחק שטרשון."},{"i":13852,"n":"דריהם משה בן שמעון הכהן","f":"שמעון","k":"בעל ידי משה","bt":"תרסו","dt":"תשכו - י ניסן","b":"תלמיד ר מכלוף עידאן, רב בג'רבא בהדיג'ת על מקום רבו. עלה לארץ-תשיח והתישב בטבריה, כיהן כדיין, והיה ממקימי בית כנסת לעולי ג'רבא בטבריה - ונקרא על שמו \"אהל משה\".","bk":[["והשיב משה",""],["ידי משה",""]]},{"i":13853,"n":"דריהם, שמעון הכהן מג'רבה","k":"בעל שער שמעון","bt":"תרמה","bp":"ג'רבא","dt":"תשיט - ז אב","dp":"טבריה","b":"רב בתונס בכמה מקומות. עלה לארץ והתישב בטבריה. מחדושיו ב\"המאסף\", בנו ר משה הכהן דריהם."},{"i":13854,"n":"דריזינגר, חנניה יו\"ט ליפא מנ\"י","k":"בעל שפת חי\"ל","b":"רב בארה\"ב-תרצט. חיבר גם \"מקור חיים\". ?? לא באוצר ??"},{"i":13855,"n":"דרייפוס, וולף מלענגנויא","f":"ליב","bt":"תקמב","dt":"תרך - ט סיון","b":"תלמיד ר הירש שייאר ממגנצא. אב\"ד לענגנויא. נזכר בתשובת החת\"ס."},{"i":13856,"n":"דרייפוס, יעקב חנוך מפאריס","bt":"תרה","bp":"שיראף-גרמניה","b":"תלמיד ביהמ\"ד לרבנים בפאריס, בעל תואר ד\"ר, רב ראשי בפאריס וצרפת-תרסא."},{"i":13857,"n":"דרייפוס, שלמה זלמן מוינהיים","k":"זלמן וינהיים","bp":"וינהיים-אלזס","dt":"תרי - ד חשון","dp":"המבורג","b":"חתן ר זלגימן בן זלמן מהמבורג גבאי הקלויז. תלמיד ר משה טוביה זונטהיים בישיבת הנאו, הגיע להמבורג עם ר נח חיים צבי ברלין-תקס וכיהן כר\"מ לצעירים, מחכמי הקלויז וגבאי על מקום חותנו ודיין."},{"i":13858,"n":"דרייפוס, שמואל מלבוב","f":"משה","k":"בעל אגרת הפורים","bt":"תרי","dt":"תרס","b":"רב בלמברג. חיבר \"אגרת הפורים\" למברג תרנח. ?? לא באוצר ??"},{"i":13859,"n":"דרייר, זלמן","b":"פרסם מאמרים ב\"שמוש חכמים\" - בני ברק תשז."},{"i":13860,"n":"דריכס, חי מטריפולי","bt":"תרמט","bp":"טריפולי","dt":"תרפט","dp":"טריפולי","b":"רב בטריפולי. נזכר אצל גבריאל רוקח."},{"i":13861,"n":"דריכס, יוסף מטריפולי","bt":"תקס","dt":"תרל - בערך","b":"רב וסופר דווקני בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":13862,"n":"דריליך, נפתלי ממליץ","f":"דוד","b":"עסקן ואיש חסד במליץ."},{"i":13863,"n":"דריליך, שלמה מברנוב","f":"בצלאל","k":"בעל ילקוט שלמה","bt":"תרמד","bp":"ברנוב","dt":"תשלא","b":"מחכמי ברנוב, היגר לניו יורק-תרעג. עלה לארץ-תשיז. חיבר \"ילקוט שלמה\" ניו יורק תרצח, ועוד."},{"i":13864,"n":"דרילמן, יוסף דוד","f":"ישראל מנחם מלנצהוט","bt":"תרצה","dt":"תשנה","b":"ניצל מהשואה - גלה לסיביר. עלה לארץ-תשח ולמד בישיבה בבאר יעקב. חתן ר יצחק ויסקי - ר\"מ בתפארת צבי. סופר סתם מומחה."},{"i":13865,"n":"דרילמן, פנחס מנחם מליזנסק","b":"פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":13866,"n":"דרימר, אברהם מלמברג","f":"אליעזר","bt":"תרעד","bp":"למברג","dt":"תשלה","b":"עלה לארץ-תרצד. עורך במוסד הרב קוק."},{"i":13867,"n":"דרימר, אברהם מסקאלא","f":"שלמה","bt":"תר","dt":"תרעה","b":"חסיד ויזניץ. רב בסקאלא-תרלג על מקום אביו, אב\"ד פרוביזנא על מקום אביו. בנו ר נתן נטע על מקומו אחריו."},{"i":13868,"n":"דרימר, אפרים ממנוסטרישץ","dt":"תש..","b":"שו\"ב במנוסטרישץ. נספה בשואה."},{"i":13869,"n":"דרימר, דב בר מבוצאץ ודארהוי","f":"ירוחם","k":"בעל ארונו של יוסף","bt":"תריב","b":"נכד ותלמיד ר שלמה דרימר בעל \"ישרש יעקב\". חתן ר יוסף אהרן מארילס מבוצאץ בעל \"יד יוסף\". מו\"צ בביטשעטשי(בוצאץ)-תרלה, ברדושן(=בארדוזשען)-תרמ, הערץ-תרמב ,דרוהוי(=דארהוי)-רומניה-תרן. נסמך מאת: ר יוסף שאול נתנזון מלבוב, מהרש\"ם מברעזן. חיבר \"ארונו של יוסף\" הוסיאטין תרעג. בניו ר שלמה מפיאטרא, ר ישעיה מבוטושאן - נולד תרלו, ר ישראל בבאקוי, ר חיים ביאס - הוא הסופר קרול יליד תרמו שחתם על מאמריו - \"איש יהודי\" - נספה בשואה, ר לוי יצחק מבאקוי, ירוחם."},{"i":13870,"n":"דרימר, דוד שלמה מטרמבובלה","b":"אב\"ד טבמבובלה-תרלג."},{"i":13871,"n":"דרימר, יהודה ליב","f":"שלמה מסקאלא","b":"תשובה אליו ב\"שבעה עינים\""},{"i":13872,"n":"דרימר, יהודה מסקאלא","f":"נתן נטע מסקאלא","bt":"תרסח","bp":"סקאלא","b":"חסיד ויזניץ. רב בסקאלא על מקום אביו. נספה בשואה."},{"i":13873,"n":"דרימר, יוחנן אליעזר לזיל","f":"משה אריה מסקאלא","bt":"תרי","dt":"תרף","b":"מחכמי סקאלא, ויזניץ, בזמן מלחמת העולם הראשונה בוינה."},{"i":13874,"n":"דרימר, יוסף","f":"שלמה מסקאלא","b":"תשובות אליו ב\"בית שלמה\" - תריב-תרכא."},{"i":13875,"n":"דרימר, יחיאל מיכל","b":"מחכמי זביא (ליד קוסוב). תלמיד ר יהודה גרשון פיקהולץ שהשיב לו ב\"מנחת יהודה\"-תרלז."},{"i":13876,"n":"דרימר, יעקב","f":"שלמה מסקאלא","b":"רב בסטרוזיניץ (בוקובינה)-תרלח."},{"i":13877,"n":"דרימר, יעקב","b":"חתן ר שלמה סגל לנדא מדולינא (נפטר-תקנט). אביו של ר שלמה מסקאלא בעל \"בית שלמה\"."},{"i":13878,"n":"דרימר, ירוחם","f":"שלמה מסקאלא","dt":"תרפט","b":"תלמיד ה\"ישמח משה\". אב\"ד בוצ'ץ'-תרלח, בורדוזען-תרם, הערצה-תרמב, דורוהוי-תרן."},{"i":13879,"n":"דרימר, ישראל מנדבורנה","dt":"תרלא","b":"רב בנדבורנה-תרלא. מכתב ממנו בענין עגונה - המגיד-תרלב."},{"i":13880,"n":"דרימר, לאזיל מויזניץ-בוקובינה","b":"רב בויזניץ-בוקובינה. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד, \"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":13881,"n":"דרימר, נתן נטע מסקאלא","f":"אברהם","bt":"תרם","dt":"תרץ","b":"אב\"ד סקאלא על מקום אביו, בנו ר יהודה על מקומו אחריו. בנו ר שלמה היה סגן הרב הראשי בצבא הפולני."},{"i":13882,"n":"דרימר, שלמה מסקאלא","f":"יעקב פולק","k":"בעל ישרש יעקב","r":"רב בסקולא","bt":"תקס","bp":"נדבורנא","dt":"תרלג - כב תשרי","b":"בזיוו\"ש חתן ר צבי גרוסמן מדלטין. מגדולי חסידי ר חיים מקוסוב. תלמיד ר אהרן משה טויביש מיאס, ר אברהם דוד מבוצאץ, ור נתן נטע קליצר מפודהייץ. אב\"ד סקאלא-תקצג כ-40 שנה בהשפעת אחיו הגביר ר יהושע. מחסידי רוזין ומשיב לשאלות החצר. חיבר \"ישרש יעקב\" למברג תרכג, ועוד. (כשהאדמור מרוזין הגיע לגליציה וראה את ר שלמה אמר כי הוא הרב הראשון באוסטריה שנראה עליו צלם אלוקים בשלימות). נספד בספר \"נחלה לישראל\".","bk":[["ישרש יעקב","מפרשי ש\"ס - אחרונים"],["בית שלמה – שו\"ת",""],["ישרש יעקב – יבמות",""],["בית שלמה",""],["ישרש יעקב [עמ\"ס יבמות]",""],["בית שלמה","שו\"ת - אחרונים"]]},{"i":13883,"n":"דרימר, שמואל מלודמיר וסווידניק","b":"מו\"צ בלאדמיר,רב בסווידניק-תר\"ע"},{"i":13884,"n":"דרישער, צבי מירושלים","f":"יצחק","dt":"תקצא - כו אייר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":13885,"n":"דרכסלר, מרדכי מטימישואר","f":"יהודה","k":"בעל מקונן אבלנו","bt":"תרמג","b":"בעל תואר דוקטור. תלמיד הסמינר לרבנים בבודפשט. רב הקהלה הניאולוגית בטימישואר-1910. חיבר \"מקונן אבלנו - רבי יצחק בן חיים הכהן\" (על חכם מספרד שכתב יד ממנו בספריה המוזיאון הבריטי). חיבר גם ספרים ומאמרים בהונגרית. ההדיר \"מקונן אבלנו\" לר יצחק בן חיים הכהן-1923."},{"i":13886,"n":"דרכסלר, מרדכי מיקשה","b":"רבה הניאולוגי של טימישואר-תרע-תשכו."},{"i":13887,"n":"דרכסלר, שמעיה","b":"רב בפעצעל-תרכ\"ו"},{"i":13888,"n":"דרליך, יחיאל מיכל זאב מטיטשין","bt":"תקע","dt":"תרמח","b":"אב\"ד טיטשין. בנו ר ישראל מילא את מקומו אחריו."},{"i":13889,"n":"דרליך, יעקב יצחק מטיטשין","f":"ישראל","bt":"תרן","dt":"תשג","b":"אב\"ד טיטשין, על מקום אביו."},{"i":13890,"n":"דרליך, ישראל מטיטשין","f":"יחיאל מיכל זאב","bt":"תרי","dt":"תרעה","b":"חתן ר אריה ליב הרושובסקי אב\"ד אוהנוב. אב\"ד טיטשין, על מקום אביו. בנו ר יעקב יצחק על מקומו אחריו."},{"i":13891,"n":"דרמון, יהודה מאלגיר","bt":"תקך","dt":"תר - בערך","b":"רב בווהראן ומלמד תורה. חתם ראשון על תקנות בווהראן ונזכר ב\"גושפנקא דמלכא\". בניו: ר מסעוד, ר עמרם. הסכים על \"מאמר מרדכי\" לדודו ר מרדכי דרמון, ועל \"גושפנקא דמלכא\"."},{"i":13892,"n":"דרמון, יהודה מאלגיר","dt":"תרמג","b":"דיין בווהראן, רב זמני של הקהלה-תרלז-תרם. דרשן, תרגם ספרים לערבית יהודית. הו\"ל \"רנה וישועה\" - ליוורנו תרלז, גושפנקא דמלכא\" לר פארוז קרסיינטי."},{"i":13893,"n":"דרמון, יהודה מטריפולי - א","bt":"תי","dt":"תף - בערך","b":"מקובל מחכמי טריפולי. נזכר אצל ר אברהם חלפון שראה הגהות ממנו על הזהר. אחיו של ר יצחק ודודו של ר נהוראי."},{"i":13894,"n":"דרמון, יהודה מטריפולי - ב","bt":"תף","dt":"תקס - בערך","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":13895,"n":"דרמון, יהודה מתונס","k":"בעל שובה ישראל","bt":"תקסח-פח","dt":"תרעא","b":"רב ואב\"ד בתוניס מגיל 24 במשך 80 שנה, מקובל, בקי, חיבר \"גור אריה\" חידושים על הש\"ס, \"שובה ישראל\", \"נחלת אבות\", ועוד. (באוצר הרבנים כתוב רב בטריפולי?)"},{"i":13896,"n":"דרמון, יעקב מאלגיר","f":"יצחק בן סוסו","bt":"קפ - בערך","dt":"רן - בערך","b":"רב בלמדייא(=מידיאה). שאלות ממנו לרשב\"ש, מקורב לר צמח דוראן בן הרשב\"ש - כ-30 תשובות אליו ב\"יכין ובועז\"."},{"i":13897,"n":"דרמון, יעקב מאלגיר","f":"מסעוד","dt":"תרסז","b":"רב ודיין בווהראן-תרמב, ור\"מ-תרן. הסכים על \"פתשגן הכתב\" אלגיר תרמו, ועוד. ערך קובץ תשובות חכמי הדור ובהם גם פסקים ממנו - חתם עם ר אברהם הסבעוני על פסק בענין המאבד עצמו לדעת והיה מחלוקת בינו ושאר רבני ווהראן לבין ר חיים בלייח מתלמסאן."},{"i":13898,"n":"דרמון, יצחק מטריפולי","dt":"תקיב","b":"מצאצאי ר יהודה ג'רמון. רב בטריפולי-לוב. בנו ר נהוראי בעל יתר הבז. נהרג עק\"ה."},{"i":13899,"n":"דרמון, יצחק מטריפולי - רם","bp":"ג'בל-יפרן-לוב","dt":"תעא","b":"רב דיין ונשיא קהלת טריפולי. נזכר ב\"זרע יצחק\" לר יצחק לומברזו, וב\"שובה ישראל\" תונס תרמג - שם מסופר שנהרג עק\"ה."},{"i":13900,"n":"דרמון, ישעיה מטריפולי","f":"אברהם","bt":"תם","dt":"תקי","b":"רב וסופר קהלת טריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":13901,"n":"דרמון, כליפא מטריפולי","bt":"תק","dt":"תקע","dp":"טריפולי","b":"רב וחסיד בלוב. נטמן בחלקת אבותיו בבית העלמין בטריפולי הנקראת \"הג'רמנה\". נזכר בחוברת \"עדות\"-1 - בת ים."},{"i":13902,"n":"דרמון, מסעוד מאלגיר","f":"יהודה","k":"בעל גור אריה","dt":"תרכו","b":"רב ור\"מ בווהראן, התכתב עם ר שלמה זוראפה ב\"שער שלמה\". חיבר פיוט על הצלת יהודי והראן מידי הערבים, בזמן הכבוש הצרפתי, ונהגו לאמרו בשבת חזון. חיבר \"גור אריה\" ליוורנו תרה."},{"i":13903,"n":"דרמון, מרדכי מאלגיר","f":"יהודה","k":"בעל מאמר מרדכי","bt":"תק","dt":"תקע","b":"רב באלמעסכר(=מסכארא)-אלגיר, בזמן ר יעקב ן נאים בעל \"זרע יעקב\". חיבר \"מאמר מרדכי\" ליוורנו תקמז. מקורב לשליט העיר ונשלח מטעמו לתורכיה והצליח בשליחותו - חיבר שיר לזכר נס הצלתו בדרכו, לאחר כיבוש ווהראן מדי הספרדים-תקנב נקרא ע\"י שליט העיר ופעל לחדוש הקהלה שם וכיהן כרבה הראשון של הקהלה המחודשת (לאחר שבמשך שלטון הספרדים לא היו שם יהודים), ובנה ביכ\"נ בכספו ונקרא על שמו ביהכ\"נ דרמון."},{"i":13904,"n":"דרמון, משה מתונס","dt":"תקד","b":"תלמיד עם ר יוסף בשמוט (ביסמוט). רב בקהילת ליגורניזיס בתונס. חתם בשנת תפה אחרי ר שמואל הכהן, ר אברהם טייב, ר יצחק לומברוזו ור משה נג'אר. בנו ר שמואל דיין בתונס."},{"i":13905,"n":"דרמון, נהוראי מטריפולי ותונס","f":"יצחק","k":"בעל יתר הבז","bp":"טריפולי או כפר ג'בל-יפרן","dt":"תקמג - טו ניסן","dp":"תונס","b":"מקובל ומשורר מחכמי תונס (במקור מלוב), למד בישיבת ר יצחק לומברוזו בתונס, ואף התגורר אצלו (נתייתם בילדותו). עלה לארץ והיה בשליחות. כל רכושו וספריו נשדדו וכתבם מחדש מזכרונו. חיבר \"יתר הבז\" ליוורנו תקמז בסוף ספר בנו ר חיים גרמון - \"צדקה לחיים\", בנו גם - ר פנחס","bk":[["יתר הבז",""]]},{"i":13906,"n":"דרמון, סעדיה מאלגיר","bt":"קי - בערך","dt":"קץ - לג בעומר","b":"רב בלמדייא(=מדיאה)-אלגיר. התכתב עם הריב\"ש והרשב\"ץ. ציון קברו היה מקודש. עליו בספר \"זכ\"ר לרב\" לר אברהם מאיר - אלגיר תרסב."},{"i":13907,"n":"דרמון, עמרם מאלגיר","f":"יהודה","dt":"תרכז","b":"רב ודיין בווהראן. היה עשיר כאחיו ר מסעוד - וכיהנו שלא על מנת לקבל פרס. נזכר ב\"מלל לאברהם\"."},{"i":13908,"n":"דרמון, צרמון - משפחה","b":"משפחה עתיקה בצפון אפריקה, נקראה דרמונא. לדעת דוד קורקוס (אנציקלופדיה גודאייקה) מקור המשפחה באלמהדייא-תונס בניגוד לדעת שמקורם בלמדייא-אלגיר, וראיה לדבריו מ\"יכין ובועז\"."},{"i":13909,"n":"דרמון, שלום מלוב","bt":"תק","dt":"תקס","b":"רב בג'ריאן-לוב. עליו ב\"מחניים\"-צג."},{"i":13910,"n":"דרמשטט, יהודה מפפד\"מ","f":"מנחם","dt":"תעט - טו אלול","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ."},{"i":13911,"n":"דרמשטט, יוסף מדרמשטט","k":"בעל עץ יוסף","b":"רב בדרמשטט-ת\"ק"},{"i":13912,"n":"דרמשטט, מאנס מפפד\"מ","dt":"תמד - א אייר","dp":"פפד\"מ","b":"גביר בפפד\"מ שבכספו נבנה בימ\"ד גדול - ובו לימד ר שמואל שאטין-מהרשש\"ך-תע. בנו - ר ליב."},{"i":13913,"n":"דרנבורג, צבי הירש","k":"בעל יושבי תבל","b":"חכם וסופר. חיבר \"יושבי תבל\" - אופיבאך תקמט."},{"i":13914,"n":"דרנברג, יעקב מלאס","f":"משה דרנברג","dt":"תקס - ג שבט","b":"רב בלאס"},{"i":13915,"n":"דרנברג, משה מהלברשטט","b":"מו\"צ בהלברשטט-תק\"ל"},{"i":13916,"n":"דרעא - אזור במרוקו","b":"אזור במרוקו שהיה במשך תקופה ארוכה בשליטת היהודים."},{"i":13917,"n":"דרעא ן, יהודה מדרעא-מרוקו","f":"שמואל","b":"פייטן בדרעא(מרוקו)"},{"i":13918,"n":"דרעזשער, חיים יעקב מפיאסק","dt":"תשג","b":"רב בפיאסק"},{"i":13919,"n":"דרעי, אברהם ממרוקו ומצרים","b":"דרע\"א(מרוקו)-ד'תתס\"ג, רב ראשי בפורסטט(מצרים)"},{"i":13920,"n":"דרעי, אברהם ממרוקו וספרד","dp":"אימין תאנות(מרוקו)","b":"חכם קדמון ממרוקו מחכמי ספרד, תוכן"},{"i":13921,"n":"דרעי, אהרן מאלגיר","dt":"תרך - בערך","b":"רב בתלמסאן-תקף. נזכר ברשימת ר יצחק רוש."},{"i":13922,"n":"דרעי, ברוך ממרוקו","dt":"תרס - ל אדר","b":"מעיין גדול מחכמי מרוקו"},{"i":13923,"n":"דרעי, ברוך ממרוקו","dt":"תרפח - ב שבט","b":"אב\"ד במראקש"},{"i":13924,"n":"דרעי, חנניה מיפו","f":"יעיש","k":"בעל חדר בריוח","bp":"מרוקו","b":"מקובל,עלה לא\"י,רבה של יפו,חיבר \"חדר בריוח\""},{"i":13925,"n":"דרעי, יוסף ממרוקו","b":"מחכמי מרוקו-תיז, מתורתו בכת\"י של ר אלעזר בהלול."},{"i":13926,"n":"דרעי, יעקב מאלגיר","bt":"רף","dt":"שן - בערך","b":"רב באלגיר. שאלות ממנו לר יוסף ששפורטש, ונזכר ב\"ר יוסף שפפורטש וספר תשובותיו לר נח עמינח."},{"i":13927,"n":"דרעי, יצחק חי מאלגיר","bt":"תרלב","dt":"תרפז","dp":"אלגיר - ירושים","b":"רב בסטיף-אלגיר. החזיק בכתב יד בקבלה ממקובלים קדמונים ממרוקו ובהם ר דוד הלוי המכונה \"דרע\", ור פרח שושן. מכתביו נדפסו בתוך \"חדר בריח\"ו\" - יפו תשנה לר\"ח דרעי."},{"i":13928,"n":"דרעי, משה ממרוקו","f":"יקותיאל","b":"רב בדברו-מרוקו-תקסז."},{"i":13929,"n":"דרעי, משה מספרד ומרוקו","bp":"דרעא-מרוקו","b":"עבר לספרד והיה מחכמי ספרד בדור שלפני הרמב\"ם, חזר למרוקו והתישב בפאס. ניבא את הגאולה בפסח הקרוב ושכנע את העם שהשתכנע כנגד התנגדותו של ר מימון אבי הרמב\"ם, והדבר נגמר במפח נפש ובנזק רב לקהלה, כמתואר באגרת תימן לרמב\"ם. עלה לארץ ועמד בראש ישיבה. יש הסוברים שהיה חי במאה התשיעית והיה מורו של סלמון בן ירוחם הקראי."},{"i":13930,"n":"דרעי, שלמה ממראקש","b":"דיין במראקש. חתם על פסק דין-תרמא עם רבני עירו."},{"i":13931,"n":"דרצנסקי, שמואל אביגדור","f":"משה הלוי","k":"בעל אהל משה","bt":"תרכח","bp":"סלונים","dt":"תשד - יב שבט","dp":"ירושלים","b":"תלמיד ר מאיר שמחה בעל \"אור שמח\". חתן ר חיים הלל מוולוזין ועבר לשם. ברח למינסק במלחה\"ע ה-I ואחריה רב בוולוזין-תרפ, עלה לארץ-תרצד וכיהן כרב ביבנאל, וקרית משה-ירושלים. בנו פרופ' חיים הלל בן ששון מירושלים."},{"i":13932,"n":"דרשביץ, אשר","dt":"תשג","b":"רב במישלניצא"},{"i":13933,"n":"דרשביץ, דב בר","dt":"תשג","b":"רב במישליניצא"},{"i":13934,"n":"דרשביץ, חיים ישעיה מקולבסוב","b":"חתן ר יצחק אליעזר גרהר מקולבסוב. והיה רב בקולבסוב אחריו."},{"i":13935,"n":"דרשביץ, יעקב אלימלך מטיליטש","b":"נכד אדמורי רופשיץ. מחכמי טיליטש."},{"i":13936,"n":"דרשביץ, ישכר בריש מטרנוב","b":"מחכמי טרנוב. בנו ר שמעון מאיר ממישלניץ."},{"i":13937,"n":"דרשביץ, ישכר בריש ממישלניץ","f":"שמעון מאיר ממישלניץ","bt":"תרם","dt":"תשג","b":"חסיד בובוב. רב במישלניץ על מקום אביו. נספה בשואה."},{"i":13938,"n":"דרשביץ, מאיר ממישלניץ","f":"בריש","bt":"תרך","dt":"תרעח","b":"חתן ר יוסף שמואל פרלמן אב\"ד מישלניץ, רב במישלניץ על מקום חותנו. במלחמת העולם הראשונה נאסר על כי חליק אישורי רבנות כדי לפטור בחורי ישראל מהצבא."},{"i":13939,"n":"דרשביץ, משה חיים ממישלניץ","b":"רב במישלניץ-תרצט"},{"i":13940,"n":"דרשביץ, שמעון מאיר מטרנוב","f":"ישכר מאיר","b":"רב במישלניץ. חתנו - ר אהרן וולמוט ממישלניץ."},{"i":13941,"n":"דרשן, אלעזר מוירצבורג","f":"משה בן אלעזר","k":"בעל ספר גימטריאות","b":"נכד-אבי אמו ר שמואל בן ר יהודה החסיד. בנו ר משה עזריאל הדרשן, ונכדו ר ישעיה מוויילא. רב בוירצבורג. חיבר ספר הגימטריאות, פירוש לספר יצירה, ועוד. אחיו של ר מאיר-נהרג עק\"ה. חיבר קינה \"ציון עטרת צבי\"."}];
